-- AP&E glossary — Machine B batch 1 — PASTE FILE 06a (replaces the oversized APPLY_06)
-- Paste into Supabase SQL editor and Run. Idempotent; safe to re-run.
BEGIN;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"735a44f0-73df-4eec-9f1d-66db4c74974f": {"definition": "The deliberate buzzing, overtone-rich, long-sustaining timbre produced by the sawari mechanism on Japanese lutes such as the shamisen and biwa, in which the lowest string (and, on the biwa, others) makes light grazing contact with a ridge or shaped surface near the nut instead of clearing it cleanly. This nonlinear string-surface contact adds bright upper harmonics and a singing sustain that is prized as an essential aesthetic feature, not a fault.", "plain_english": "A buzzing, humming tone that some Japanese string instruments like the shamisen and biwa make on purpose. The lowest string lightly touches a small ridge near the top, so it buzzes and rings for a long time. Players want this sound. It is not a fault.", "purpose_function": "The sawari buzz adds extra high overtones and long sustain, giving the shamisen and biwa their singing, buzzing voice, which is why builders shape the ridge to create it on purpose.", "practical_application": "When recording a shamisen or biwa a technician expects a bright, buzzy sustain and places mics and sets EQ to keep that ringing overtone character rather than treating it as a fault to remove.", "category": "Instrument timbre", "related_terms": ["Sitar jawari", "Sympathetic resonance", "Sustain", "Timbre", "Overtones", "Plucked string"], "common_mistakes": ["Treating the sawari buzz as a defect or setup fault and trying to remove it; on a shamisen or biwa it is a wanted part of the tone.", "Confusing sawari with an accidental fret or bridge buzz on a Western instrument, which usually is a genuine fault.", "Miking too close and capturing only the harsh buzz instead of the full body and singing sustain."], "scenario_contexts": ["Recording a solo shamisen for a traditional Japanese music session.", "Amplifying a biwa on stage while preserving its buzzing sustain.", "Blending a shamisen into a fusion track where its bright buzz must sit in the mix."]}, "182cfb90-c2c0-4309-9ac9-b4b9f2cd473e": {"definition": "The wide, gently curved (near-parabolic) main bridge of the sitar, and by extension the buzzing, harmonically rich, long-sustaining timbre it creates. Because each string grazes along the curved bridge surface rather than terminating at a sharp edge, the effective contact point shifts nonlinearly through every vibration cycle, generating strong high harmonics and the sitar's characteristic shimmering buzz; the bridge is periodically re-filed ('doing the jawari') to maintain the tone.", "plain_english": "The curved bridge on a sitar, and the buzzing, ringing sound it gives. The string lightly grazes the curve instead of sitting on a sharp edge, so it makes many bright overtones and a long shimmer. Craftsmen reshape the bridge to keep this sound right.", "purpose_function": "The jawari bridge shapes the sitar's signature bright, buzzing, long-sustaining tone by adding high harmonics, which is why its exact curve is carefully filed and maintained.", "practical_application": "A technician recording a sitar captures the shimmering, harmonically dense buzz with careful mic placement, and knows a dull or over-buzzy instrument may need its jawari re-cut by a specialist rather than fixing it with EQ.", "category": "Instrument timbre", "related_terms": ["Sawari buzz", "Sitar sympathetic strings", "Overtones", "Sustain", "Timbre", "Plucked string"], "common_mistakes": ["Thinking the sitar's buzz is a fault; the jawari bridge is designed to buzz.", "Assuming EQ can replace a properly cut jawari; the timbre comes from the physical bridge curve.", "Confusing the main playing-string bridge (jawari) with the separate smaller bridge that carries the sympathetic strings."], "scenario_contexts": ["Recording a sitar for a film score and capturing its shimmering buzz.", "Diagnosing a dull-sounding sitar that needs its jawari re-shaped by a maker.", "Amplifying a sitar live and keeping the bright overtones without harshness."]}, "646c0bba-3bec-484a-a1e3-410ae2d54537": {"definition": "A set of thin, undamped resonating strings on the sitar (the tarab strings, typically eleven to thirteen) tuned to the notes of the raga and running beneath the frets to their own small bridge and tuning pegs. They are not normally plucked; instead they vibrate by sympathetic resonance whenever the played strings sound a matching pitch, producing a continuous shimmering halo of resonance behind the melody.", "plain_english": "A group of thin extra strings on a sitar that the player usually does not pluck. They are tuned to the notes of the piece, and they ring on their own whenever a matching note is played. This adds a soft, shimmering echo behind the main melody.", "purpose_function": "The sympathetic strings enrich and extend the sitar's sound with a resonant shimmer tuned to the raga, giving the instrument its floating, echoing quality without the player touching them.", "practical_application": "When miking a sitar a technician places mics to capture both the played strings and the ringing sympathetic strings, and knows these resonances continue after each note and can build up in a mix.", "category": "Instrument component", "related_terms": ["Sympathetic resonance", "Sitar jawari", "Resonance", "Sustain", "Drone string", "Sawari buzz"], "common_mistakes": ["Assuming the sympathetic strings are played directly; they are normally left alone and ring on their own.", "Forgetting to tune the sympathetic strings to the raga, so their resonance clashes with the melody.", "Gating or muting a sitar recording so hard that the natural sympathetic ring is cut off."], "scenario_contexts": ["Recording a raga performance and capturing the shimmering sympathetic resonance.", "Tuning a sitar's sympathetic strings to a specific raga before a session.", "Managing the build-up of sympathetic ring when mixing a dense sitar track."]}, "6d592ae6-f536-4d5f-806c-d0911808ff52": {"definition": "The sharp, high-amplitude attack spike produced when a bass string is struck (slapped) by the side of the thumb or snapped (popped) by a finger against the fingerboard, giving a percussive, click-like onset with strong high-frequency content. Because this transient peaks well above the note's sustained level, it is a central concern in gain-staging, compression and limiting when recording or mixing slap bass.", "plain_english": "The quick, loud spike of sound at the very start of a slapped or popped bass note. Hitting the string with your thumb or snapping it makes a sharp, clicky attack that is much louder than the rest of the note. Engineers watch this spike so it does not overload the recording.", "purpose_function": "The bright transient gives slap bass its punchy, percussive funk character, but it also warns the engineer that peak level far exceeds the average, so gain and dynamics must be set to control it.", "practical_application": "A technician recording slap bass sets converter levels with headroom for the peaks and often uses a compressor with a slower attack plus a fast limiter, so the transient's punch survives while clipping is prevented.", "category": "Attack transient", "related_terms": ["Transient", "Compression", "Limiter", "DI box", "Attack time", "Headroom"], "common_mistakes": ["Setting record levels by the average meter reading and letting the sharp transient clip the converter.", "Using a fast compressor attack that flattens the transient and kills the slap's percussive punch.", "Assuming the click is a fault; the bright transient is the whole point of the slap sound."], "scenario_contexts": ["Tracking a funk slap-bass part through a DI and leaving headroom for peaks.", "Setting compressor attack and a limiter to tame slap transients without losing punch.", "Mixing slap bass so the attack cuts through without overloading the bus."]}, "f251787b-1a1c-4f17-b0f4-0b1b4af64a68": {"definition": "An unwanted buzzing or rattling produced when a vibrating string contacts something it should clear, most often a fret (fret buzz), but also the nut, fingerboard or a loose component. It occurs when the string's vibrating arc runs too close to the obstruction, typically from low action, insufficient neck relief, uneven or worn frets, or a poorly cut nut.", "plain_english": "A buzzing or rattling from a guitar or bass string hitting something it should not touch, usually a fret. It happens when the strings sit too low or the frets are uneven, so the vibrating string slaps against them. It is normally a fault to fix in the setup.", "purpose_function": "Naming this fault helps a technician trace an unwanted rattle to its real cause, the action, relief, frets or nut, so it can be corrected at the instrument instead of masked with EQ.", "practical_application": "A technician diagnoses string buzz by checking string height, neck relief and fret level, then adjusts the truss rod, raises the saddle, or dresses the frets to clear it.", "category": "Mechanical noise", "related_terms": ["Fret buzz", "Action", "Neck relief", "Truss rod", "Nut", "Fret dressing"], "common_mistakes": ["Lowering the action for easier playing until the strings buzz on the frets, then blaming the strings.", "Ignoring neck relief and trying to cure buzz only by raising the saddle.", "Confusing light fret contact from very hard playing with a genuine setup fault."], "scenario_contexts": ["Setting up a guitar and chasing buzz that appears only on certain frets.", "Adjusting a truss rod to add relief and stop open-string buzz.", "Isolating whether a rattle comes from the nut, the frets, or a loose part."]}, "7c5d614b-1031-4b73-b4a4-327aace881c9": {"definition": "In bowed-string playing, the movement of the bow from one string to an adjacent or non-adjacent string, requiring a change in the bow arm's plane so the hair cleanly contacts the new string. Coordinated at the shoulder, elbow and wrist, clean string crossing underpins smooth passages, arpeggios and bariolage; awkward crossings cause scratchy tone or an accidental double-stop.", "plain_english": "Moving the bow from one string to the next on a violin, viola, cello or bass. The player raises or lowers the bow arm to reach the new string cleanly. Doing it smoothly is key to fast passages, and doing it clumsily makes scratchy or doubled notes.", "purpose_function": "String crossing lets a player move between the pitches on different strings while keeping a smooth bow stroke, and mastering it avoids the scratches and accidental extra notes that spoil arpeggios and fast runs.", "practical_application": "A technician recording strings expects slight bow noise at crossings and chooses mic placement and edits phrasing so these natural moments stay musical, while the player practices arm-level control to keep crossings clean.", "category": "Bowing technique", "related_terms": ["Bowing", "Arco", "Bariolage", "Détaché", "Double stop", "Legato"], "common_mistakes": ["Moving only the wrist for wide crossings, which causes scratchy tone or catches the wrong string.", "Crossing too early or too late and sounding an accidental double-stop between the two strings.", "Assuming crossing noise is a microphone problem when it comes from the bowing itself."], "scenario_contexts": ["Recording a violinist's arpeggios where smooth string crossings matter.", "Coaching cleaner crossings in a fast passage during a session.", "Editing a string take to smooth an awkward audible crossing."]}, "f474a887-2358-46ea-9edf-a373213c31d5": {"definition": "The scraping, rasping sound made when a hand or pick slides lengthwise along the wound (wrapped) surface of a string, dragging across the ridges of the winding. It occurs incidentally when shifting position on wound strings, and is also produced deliberately as an effect (for example a pick scrape) for a dramatic descending or ascending rasp.", "plain_english": "The rough, scratchy sound made by sliding a finger or pick along the length of a wound string. The wrapped ridges of the string catch and rasp as you move. It can be an accident when shifting the hand, or done on purpose as a special effect.", "purpose_function": "As a noise the scrape signals that a hand slid along a wound string; as an effect it adds a dramatic rasping swoop, so a technician must tell wanted scrapes from unwanted ones.", "practical_application": "A technician decides case by case whether a string scrape is an intended effect to keep or an unwanted noise to reduce through cleaner shifting, flatwound or coated strings, or editing.", "category": "Performance noise", "related_terms": ["String squeak", "Pick scrape", "Wound string", "Flatwound string", "Finger noise", "Position shift"], "common_mistakes": ["Confusing a lengthwise string scrape with fret buzz; the scrape comes from sliding along the winding.", "Trying to EQ out every scrape and dulling the whole track instead of adjusting technique or strings.", "Assuming all scrapes are mistakes, when a pick scrape may be a deliberate effect."], "scenario_contexts": ["Cleaning up incidental scrape noise on a recorded bass shift.", "Adding a deliberate pick scrape for effect in a rock track.", "Switching to flatwound or coated strings to cut scrape on a session."]}, "ab6ee4d1-7600-4345-b08e-3d5dd783114c": {"definition": "The short, high-pitched squeak produced when a fingertip slides along a round-wound string while shifting position or changing chords, as skin drags over the string's spiral winding. Most audible on acoustic and electric guitar and bass fitted with wound strings, it is generally an unwanted artifact in recordings.", "plain_english": "The quick, high squeak you hear when a finger slides along a wound guitar or bass string to change notes. The skin drags over the string's ridges and squeaks. It is usually an unwanted sound in a recording.", "purpose_function": "The term names a common finger-noise artifact so technicians and players can target its cause, the technique, string type or dry skin, rather than blaming the microphone or the mix.", "practical_application": "A technician reduces string squeak by advising lighter, lifted shifts and by using flatwound or coated strings, and can soften any remaining squeaks with careful editing.", "category": "Performance noise", "related_terms": ["String scrape", "Finger noise", "Wound string", "Flatwound string", "Roundwound string", "Position shift"], "common_mistakes": ["Blaming the microphone for squeaks that come from the player's hand sliding on wound strings.", "Gating a track hard to kill squeaks and cutting off the start of real notes.", "Ignoring string type when coated or flatwound strings would greatly reduce the squeak."], "scenario_contexts": ["Recording a fingerstyle acoustic part and reducing position-shift squeaks.", "Choosing coated strings to cut squeak on a close-miked guitar.", "Editing out distracting squeaks between phrases in a quiet passage."]}, "1cd45c79-5605-4b5b-a2f2-48e25223f682": {"definition": "The excitation of a string by striking (hitting) it, with a hammer, mallet, stick or the fingers (as in fret-hand hammer-ons and two-hand tapping), rather than plucking or bowing, producing a sharp percussive attack. Struck-string excitation defines instruments such as the piano and hammered dulcimer and gives techniques like slapping and tapping their percussive onset.", "plain_english": "Making a string sound by hitting it instead of plucking or bowing it. A piano hammer, a dulcimer beater, or a finger tapping the fretboard all strike the string. This gives a sharp, percussive start to the note.", "purpose_function": "Striking a string sets it moving with a fast, percussive attack and a distinct tone, which is why struck-string instruments and techniques exist alongside plucked and bowed ones.", "practical_application": "A technician recording struck-string sounds, such as piano, hammered dulcimer or tapped guitar, expects a sharp attack transient and sets levels and mic placement to capture the percussive onset cleanly.", "category": "Playing technique", "related_terms": ["Attack transient", "Hammer-on", "Tapping", "Plucked string", "Bowing", "Slap bass transient"], "common_mistakes": ["Confusing striking a string (hitting it) with plucking it; the attack and tone differ.", "Setting a conservative-only level and clipping the sharp strike transient.", "Miking only for sustain and missing the percussive attack of a struck note."], "scenario_contexts": ["Recording a hammered dulcimer and capturing its percussive attack.", "Tracking two-hand tapping on electric guitar.", "Close-miking piano hammers for a bright, percussive attack."]}, "90fedc3e-3d8b-42ec-a9b1-67730d4de7eb": {"definition": "A sustained, self-oscillating tone that arises when the amplified sound of a string instrument re-excites its own strings, hollow body, or pickup/microphone, forming a closed acoustic loop between the loudspeaker and the instrument. It is most common with acoustic-electric guitars, violins, mandolins and other resonant-bodied instruments whose air cavity and top plate readily couple to loud stage sound.", "plain_english": "A loud howl or ring that happens when a string instrument's amplified sound feeds back into it and keeps building. The speaker shakes the guitar's body and strings, and they push the sound back to the speaker in a loop.", "purpose_function": "It is not a designed function but an unwanted feedback phenomenon of amplifying a resonant acoustic body at high volume; recognizing that the loop rides on the instrument's body and string resonances is what lets a technician raise the usable gain before feedback.", "practical_application": "On stage a technician fights it by lowering stage volume, fitting a feedback-suppressing soundhole cover on guitars, notching the offending resonant frequency with a parametric EQ, and repositioning the player away from monitors and mains.", "category": "Live sound", "related_terms": ["Upright-bass feedback", "Gain before feedback", "Notch filter", "Piezo pickup", "Soundhole cover", "Monitor wedge"], "common_mistakes": ["Cranking the channel gain for more level, which only pushes the system past gain-before-feedback sooner.", "Blaming the main PA when the real loop is a monitor wedge exciting the instrument body right in front of it.", "Permanently stuffing the soundhole and killing the instrument's natural tone instead of notching the single problem frequency.", "UNSAFE: Letting sustained feedback ring at high SPL, which can overheat and destroy compression drivers and exposes everyone nearby to hearing-damaging sound levels."], "scenario_contexts": ["A singer-songwriter's acoustic-electric guitar starts howling on a low note as the band's stage volume rises.", "A miked mandolin feeds back every time the player steps toward the front-fill speakers.", "Sound check where the engineer rings out an acoustic guitar channel to find its feedback frequencies before the show."]}, "2591bd30-5035-440b-953e-c3ca1d96941c": {"definition": "The thin, brittle, silvery timbre produced when a bowed string is played sul ponticello (very close to the bridge), a bow position that suppresses the fundamental and lower partials while emphasizing high harmonics. The resulting color is commonly described as glassy, metallic, or eerie.", "plain_english": "The cold, glassy sound a bowed string makes when the player bows right next to the bridge. Bowing there brings out the high, thin overtones and holds back the warm low ones, so the note sounds like glass or metal.", "purpose_function": "It is a tone color composers and players call for to add a fragile, otherworldly quality; the extreme near-bridge bow position is what shifts the harmonic balance toward the shimmering upper partials.", "practical_application": "A recording engineer expects sul ponticello passages to be bright and hiss-like, so they leave headroom for the extra high-frequency energy and may ease off bright room mics or HF EQ so the glassy overtones do not turn harsh.", "category": "Timbre", "related_terms": ["Sul ponticello tone", "Sul tasto", "Harmonics", "Bow position", "Tremolo", "Overtones"], "common_mistakes": ["Confusing sul ponticello (near the bridge, glassy and bright) with sul tasto (over the fingerboard, soft and flute-like).", "Thinking the effect comes from bow pressure when it actually comes from the bowing point being close to the bridge.", "Adding a mute to 'clean up' the sound, which removes the very upper harmonics that create the glassy character."], "scenario_contexts": ["Scoring a horror cue where the string section plays sul ponticello tremolo for an unsettling shimmer.", "A cellist bows near the bridge to give a sustained note a cold, metallic edge.", "Micing a quartet and hearing the timbre turn thin and bright when players shift to ponticello."]}, "5e255dc0-dd65-4fa6-993a-31b8afa02966": {"definition": "The characteristic tone of bowing sul ponticello (close to or on the bridge), in which the bow excites high partials disproportionately to give a bright, nasal, glassy or scratchy sound weak in fundamental. It is notated 'sul pont.' and cancelled by 'ordinario' ('ord.').", "plain_english": "The bright, thin sound a string makes when the bow is drawn close to the bridge. The bow wakes up the high overtones more than the main note, so the tone is glassy and a little scratchy.", "purpose_function": "It gives arrangers a distinct string color for eerie or tense moments; the near-bridge bow point is the mechanism that rebalances the sound toward its upper harmonics.", "practical_application": "Players switch to it on the 'sul pont.' marking and return to normal on 'ord.'; an engineer capturing it keeps headroom for the extra high-frequency energy so the bright transients do not distort.", "category": "Timbre", "related_terms": ["Sul ponticello glassiness", "Sul tasto", "Ordinario", "Bow position", "Flautando", "Harmonics"], "common_mistakes": ["Reading 'sul pont.' as a dynamic instead of a bowing-position change.", "Forgetting to cancel it with 'ord.', leaving the whole passage glassy.", "Assuming louder bowing makes the effect; the timbre depends on where the bow contacts the string, not how hard."], "scenario_contexts": ["A film composer marks 'sul pont.' over a violin tremolo for a suspense scene.", "A violist practices the near-bridge contact point to get an even ponticello tone.", "An engineer notices extra bow noise and brightness when the section plays sul ponticello."]}, "d96eb056-14ee-4e0e-b0d8-4b5db37d7add": {"definition": "The audible resonance of a string set into vibration not by direct playing but by acoustic or mechanical coupling to another sounding string at a matching frequency or harmonic. The undamped string 'rings' sympathetically, adding a soft halo of related pitches to the played note.", "plain_english": "When one string rings on its own because another string is playing a note it shares. The played note's vibrations travel through the instrument and set the quiet string humming along.", "purpose_function": "It enriches an instrument's tone with a lingering, shimmering resonance; on instruments with dedicated sympathetic strings it is a designed feature, while on guitars and pianos it is a natural side effect of open, undamped strings.", "practical_application": "A guitarist or engineer controls unwanted sympathetic ringing with palm muting or light finger damping during quiet passages, while a sitar or Hardanger player relies on it for the instrument's signature wash.", "category": "Acoustic resonance", "related_terms": ["Sympathetic string", "Tarab (sympathetic resonance)", "Understring ring (Hardanger)", "Resonance", "Open string", "Damping"], "common_mistakes": ["Mistaking sympathetic ringing for a tuning problem or a buzz when it is the instrument resonating normally.", "Trying to EQ it out instead of muting the offending open strings at the source.", "Assuming only special instruments do it; any undamped string on a guitar or piano can ring sympathetically."], "scenario_contexts": ["Recording fingerstyle guitar where open bass strings ring under a melody and blur the mix.", "A piano's undamped strings resonate when the sustain pedal is held.", "A sitar's sympathetic strings shimmer beneath the melody line."]}, "5487ccc6-3ea0-43e8-a8b7-5abf405a0054": {"definition": "In organology, tarab (also taraf) strings are the sympathetic strings fitted to instruments such as the sitar, sarangi and sarod; here 'tarab' denotes the resonant shimmer these undamped strings add when they vibrate in sympathy with the played strings. The word derives from the Arabic ṭarab, the state of musical ecstasy the effect evokes.", "plain_english": "Tarab strings are extra strings on some instruments that are never plucked directly. They ring on their own when the main strings are played, adding a shimmering, dreamy halo of sound.", "purpose_function": "These sympathetic strings exist to surround each melody note with a soft cloud of resonance that sustains and colors the tone; the effect is prized in South Asian and Middle Eastern music for its emotional, hypnotic quality.", "practical_application": "When recording a sitar or sarangi, an engineer positions a mic to catch the whole body's tarab resonance and expects a long, ringing decay that must not be over-compressed or gated.", "category": "Acoustic resonance", "related_terms": ["Sympathetic string", "Sympathetic string ringing", "Understring ring (Hardanger)", "Resonance", "Sitar", "Drone"], "common_mistakes": ["Thinking tarab strings are played directly; they are only ever excited sympathetically by the main strings.", "Gating or heavy compression that chokes the long sympathetic decay that gives the sound its character.", "Confusing the tarab strings with the melody or drone strings when tuning the instrument."], "scenario_contexts": ["Micing a sitar for a fusion session and preserving its shimmering sympathetic wash.", "A sarangi's many sympathetic strings ring under a vocal accompaniment.", "Tuning the tarab strings of a sitar to the notes of the chosen raga before a recording."]}, "39cc9486-4ec5-40dc-b7e3-fbe94b246406": {"definition": "A percussive right-hand technique on Turkish plucked lutes such as the bağlama (saz), in which the plectrum or fingers strike the strings to produce a sharp, rhythmic, largely unpitched attack (literally a 'string strike' or slap) that drives the rhythm rather than sounding a clear pitch.", "plain_english": "A drum-like slap of the strings on a Turkish saz, made by striking them sharply with the pick or hand. It gives a punchy, percussive beat instead of a clear note, which helps keep the rhythm.", "purpose_function": "It adds a built-in percussive pulse to a single melodic instrument, letting a lone player supply both tune and rhythm; the sharp strike briefly turns the strings and body into a drum.", "practical_application": "A player mixes these percussive strikes between plucked notes for groove, and a recording engineer leaves extra transient headroom so the loud slap attacks stay clean and punchy.", "category": "Playing technique", "related_terms": ["Bağlama", "Plectrum", "Percussive strike", "Pizzicato", "Palm mute", "Tremolo"], "common_mistakes": ["Treating the strike as a pitched note; its purpose is rhythmic attack, not a defined pitch.", "Striking too hard and knocking the instrument out of tune or stressing a thin top over time.", "Gating the recorded track so tightly that the natural percussive body sound is lost."], "scenario_contexts": ["A solo bağlama player drives a dance rhythm with string strikes between melody notes.", "Recording Turkish folk music where the saz's percussive slaps punctuate each phrase.", "A player practices even, controlled strikes so the rhythm stays steady."]}, "68315f7a-6ddb-4113-898b-73cc448ac622": {"definition": "On the hurdy-gurdy, the rhythmic buzzing of the trompette (a drone/melody string) whose loose bridge, the chien ('dog'), rattles against the soundboard. The buzz is triggered by a coup de poignet, a sharp wrist jolt that briefly accelerates the wheel so the player can articulate percussive rhythms on demand.", "plain_english": "The buzzing, rasping beat a hurdy-gurdy makes with its special 'dog' bridge. The player gives the crank a quick flick of the wrist, which makes the loose bridge rattle against the top and mark the rhythm.", "purpose_function": "It turns the hurdy-gurdy's drone into a rhythmic engine: the wrist-driven buzz lets one player lay down percussive accents while the wheel keeps sounding the melody and drones.", "practical_application": "A player sets buzz sensitivity with the tension thread (tirant) and shapes rhythm with wrist strokes, and an engineer miking the instrument positions a mic to catch both the melody and the sharp buzz transients without overload.", "category": "Playing technique", "related_terms": ["Hurdy-gurdy", "Buzzing bridge", "Chien", "Drone", "Rhythmic articulation", "Wheel"], "common_mistakes": ["Thinking the buzz comes from a mechanical fault instead of the deliberately loose chien bridge.", "Setting the tirant so tight the bridge cannot buzz, or so loose it rattles uncontrollably.", "Turning the crank at a steady speed and expecting rhythm; the buzz needs the sudden wrist accelerations."], "scenario_contexts": ["A hurdy-gurdy player drives a dance tune with steady wrist-stroke buzzing.", "Setting up the chien and tirant before a performance to dial in buzz response.", "Micing a hurdy-gurdy so its percussive trompette buzz cuts through an ensemble."]}, "a9c3c3db-f738-46cd-ab06-29af3049c772": {"definition": "The sympathetic ringing of the Hardanger fiddle's understrings, the four or five extra strings running beneath the fingerboard that are never bowed directly but resonate in sympathy with the four bowed top strings. Their shimmering, drone-like undertone is a defining feature of the instrument's sound.", "plain_english": "The soft, ringing hum from the hidden strings under a Hardanger fiddle. These strings are never bowed, but they buzz along on their own when the top strings are played, giving the fiddle its shimmering glow.", "purpose_function": "The understrings exist to wrap each bowed note in a resonant halo that gives the Hardanger fiddle its rich, echoing tone; tuning them to the tune's key strengthens the sympathetic response.", "practical_application": "A player tunes the understrings to match the tune's key for maximum ring, and an engineer mics the fiddle to capture the resonance while keeping the bowed melody clear.", "category": "Acoustic resonance", "related_terms": ["Hardanger fiddle", "Sympathetic string", "Sympathetic string ringing", "Tarab (sympathetic resonance)", "Resonance", "Scordatura"], "common_mistakes": ["Mistaking the understring ring for unwanted noise or a buzzing fault.", "Leaving the understrings tuned to the wrong key, which weakens the sympathetic resonance.", "Damping the strings to 'clean up' the sound and losing the instrument's signature shimmer."], "scenario_contexts": ["Recording Norwegian folk music where the Hardanger fiddle's understrings glow beneath the melody.", "Retuning the understrings between tunes to match each key.", "Micing a Hardanger fiddle to balance its bowed lines against the sympathetic ring."]}, "52c5e132-b53f-40e5-ade8-d11c4ba2a934": {"definition": "Acoustic feedback specific to the amplified double bass (upright bass), in which the instrument's large hollow body and low-frequency pickup couple with stage sound to produce a sustained low-frequency howl or boom. It typically centers on the body's main air (Helmholtz) and top-plate resonances.", "plain_english": "A low, booming howl an amplified upright bass makes when its big hollow body feeds its own sound back through the pickup and speaker. The loop builds on the bass's strongest low notes until it roars.", "purpose_function": "It is an unwanted resonance problem, not a feature; knowing it centers on the bass's body resonances lets a technician notch those frequencies and keep usable volume before feedback.", "practical_application": "Engineers tame it with a high-pass filter, a narrow notch at the boom frequency, a body-mounted pickup rather than an open mic, foam or a feedback-buster in the body, and by keeping the bass away from monitors and subs.", "category": "Live sound", "related_terms": ["String-instrument feedback", "Gain before feedback", "Helmholtz resonance", "Notch filter", "High-pass filter", "Piezo pickup"], "common_mistakes": ["Boosting low EQ for more 'body', which feeds the exact resonance that howls.", "Standing the bass right in front of a wedge or sub and then blaming the pickup.", "UNSAFE: Leaving a low-frequency feedback loop running at high level, which can drive subwoofers and amplifiers past their limits and expose the crew to harmful sound levels."], "scenario_contexts": ["A jazz trio's upright bass booms uncontrollably as stage volume climbs in a small club.", "Sound check where the engineer high-passes and notches the bass to raise its gain before feedback.", "An outdoor gig where the bass sits near the subs and starts a low-frequency howl."]}, "fb18f517-a235-47f6-bd01-e9c4830afa2e": {"definition": "Audible hum or buzz introduced into an audio signal when a USB link (typically between a computer and a bus-powered audio interface or other gear) bonds two devices' grounds together, forming a ground loop through which small power-related currents flow across the audio signal ground. It usually appears as low-frequency mains hum (50/60 Hz and its harmonics) or a digital whine that changes with computer activity.", "plain_english": "This is the hum or buzz you hear when a computer and an audio device share more than one ground path through a USB cable. The extra loop lets stray electrical current leak into the sound. It is a bit like two sinks joined by two pipes, so water sneaks around a loop instead of draining cleanly.", "purpose_function": "The term names a specific noise fault so a technician can diagnose and cure it rather than mask it; the noise exists because USB carries a shared ground reference that can close a loop with other grounded gear and let power-line currents modulate the audio ground.", "practical_application": "A technician who hears hum from a laptop-fed USB interface confirms USB ground noise by unplugging other grounded connections, then cures it with a USB isolator, an audio isolation transformer, correct balanced wiring, or by running the computer on battery.", "category": "Noise & Grounding", "related_terms": ["Ground loop", "Hum", "Balanced connection", "Isolation transformer", "Pin 1 problem", "Shield grounding"], "common_mistakes": ["Assuming the interface is defective when the hum is really a ground loop that disappears once the loop is broken.", "Chasing the noise with EQ or a noise gate instead of removing the ground loop at its source.", "Blaming USB cable quality when the problem is the shared ground path, not the data connection.", "UNSAFE: Lifting the equipment's mains safety/earth ground with a cheater plug or ground-lift adapter to silence the hum, which defeats protective earthing and creates a shock hazard; use a proper audio isolation transformer or USB isolator instead."], "scenario_contexts": ["A laptop on its charger feeds a bus-powered USB interface and a steady hum appears that vanishes when the charger is unplugged.", "A desktop PC connected to powered monitors and a USB interface produces buzz that shifts as CPU load changes.", "A guitarist recording direct into a USB interface hears mains hum only when the amp and interface plug into different outlets."]}, "3da3b9a1-d4c7-4980-aef2-e267a4d31142": {"definition": "A performance technique on steel guitar (pedal or lap steel) in which the player keeps the note attenuated at the moment of the pick attack and then raises the level, usually with a foot-operated volume pedal, so the note fades in smoothly with no audible pick transient. The result is a soft, vocal or bowed-string-like swell that is a signature of the pedal-steel sound.", "plain_english": "This is a way of playing steel guitar where you hide the pluck and let each note fade in gently. You keep the volume down as you pick, then push a foot pedal to bring the sound up. It ends up smooth and singing, a bit like a bowed violin.", "purpose_function": "It removes the percussive pick attack and reshapes the note's volume envelope, letting a plucked string imitate sustained, bowed or vocal phrasing and blend smoothly into pads and chords.", "practical_application": "A steel player rocks the volume pedal from heel-down (silent) toward toe-down (full) just after picking so each note or chord blooms in; guitarists use the same move with a volume pedal or the guitar's volume knob to emulate the steel sound.", "category": "Performance Technique", "related_terms": ["Volume pedal", "Pedal steel guitar", "Attack transient", "Envelope", "Sustain", "Lap steel"], "common_mistakes": ["Starting the swell too late so the pick attack is still heard, defeating the smooth fade-in.", "Placing the volume pedal after time-based effects so reverb or delay tails get choked off during the swell.", "Confusing volume swell with a tremolo effect; a swell shapes each note's attack, while tremolo repeatedly modulates volume."], "scenario_contexts": ["A country pedal-steel part where every chord blooms in behind the vocal.", "An ambient guitarist using a volume pedal to create pad-like swells under a song.", "A session player emulating pedal steel on a Telecaster by swelling notes with the volume knob."]}, "851a6440-c616-41cf-af12-5c36e6665b68": {"definition": "A guitar technique that uses the tremolo (vibrato) arm, the \"whammy bar,\" to lower the pitch of a note or chord by pushing the arm toward the body; this rotates the bridge, slackens the strings and drops the pitch. An extreme version, the \"dive bomb,\" is pushed until the strings go nearly slack for a dramatic downward glide.", "plain_english": "A whammy-bar dive is when a guitarist pushes the metal bar on the bridge to make the notes drop in pitch. Pressing the bar loosens the strings, so the sound slides downward. Pushed all the way, it can drop into a deep growl, like a plane diving.", "purpose_function": "The tremolo arm lets a player bend pitch smoothly and in real time; the dive is used for expressive downward glides, dramatic effects and dive-bomb accents that a fixed bridge cannot produce.", "practical_application": "On a guitar fitted with a Fender-style synchronized tremolo or a locking Floyd Rose, the player presses the bar after striking a note to swoop the pitch down; a Floyd Rose's locking nut and fine tuners keep the guitar in tune after deep dives.", "category": "Performance Technique", "related_terms": ["Tremolo arm", "Floyd Rose", "Vibrato", "Locking nut", "String tension", "Pitch bend"], "common_mistakes": ["Calling the arm a 'tremolo' when it actually produces vibrato/pitch change; true tremolo is volume modulation.", "Using deep dives on a non-locking tremolo without a well-set-up nut and springs, causing the guitar to go out of tune.", "Mismatching spring and string tension so a floating bridge will not return to pitch after a dive."], "scenario_contexts": ["A metal solo ending with a screaming dive bomb into slack strings.", "Adding subtle downward dips to sustained notes for expression.", "Setting up a Floyd Rose so it returns to pitch after repeated dives."]}, "e076f868-0482-4d15-a2d1-7306329dca92": {"definition": "A playing technique on the yangqin (Chinese hammered dulcimer) in which the performer lightly touches or presses the ringing strings with a hand or finger to damp their resonance and stop the note. Because the instrument has no mechanical dampers and its struck strings otherwise ring until they decay, this hand damping is used to shorten notes and produce staccato or percussive articulation.", "plain_english": "The yangqin is a Chinese instrument whose strings are hit with small hammers, and the strings keep ringing on their own. A damped stop is when the player touches the strings with a hand or finger to quiet them and cut the note short. It works like resting your hand on a bell to stop it humming.", "purpose_function": "Because the yangqin lacks dampers, hand damping gives the player control over note length and clarity, keeping notes from blurring together and allowing crisp, staccato phrasing.", "practical_application": "A yangqin player mutes strings with the side of the hand or the fingertips right after striking to end a note cleanly, to keep fast passages from ringing into one another, or to add percussive, staccato accents.", "category": "Performance Technique", "related_terms": ["Yangqin", "Damping", "Staccato", "Sustain", "Hammered dulcimer", "Muting"], "common_mistakes": ["Letting all struck notes ring, so rapid passages smear into a muddy blur instead of sounding clear.", "Damping too hard or too slowly, which adds an unwanted thud or buzz instead of a clean stop.", "Assuming the yangqin has built-in dampers like a piano; sustain must be controlled by hand."], "scenario_contexts": ["Stopping a chord cleanly at the end of a phrase so it does not ring over the next one.", "Playing a crisp staccato passage that would otherwise blur because the strings sustain.", "Muting sympathetic ringing from nearby courses during a quiet solo passage."]}, "d0a76f2e-e6a6-4b0d-b531-92259aa1f81b": {"definition": "A combined guzheng (Chinese zither) technique in which the right hand plays yaozhi (摇指), a rapid, repeated in-and-out plucking of a single string that produces a continuous, sustained tone, while the left hand presses and rocks the same string on the far side of the movable bridge to add vibrato and bend the pitch. The tremolo supplies sustain and the left-hand press supplies expressive pitch inflection.", "plain_english": "On the guzheng, a Chinese string instrument, yaozhi means plucking one string very fast so the note sounds long and steady. In a yaozhi vibrato-press, the other hand presses and wiggles that same string to add a wavering pitch. Together they make a held note that also bends and shivers.", "purpose_function": "Yaozhi overcomes the quick decay of a plucked string by sustaining the tone, and the left-hand vibrato-press adds the pitch shaping and vibrato that give guzheng melodies their vocal, speech-like quality.", "practical_application": "A guzheng player holds a long melody note with a right-hand yaozhi tremolo and, at the same time, uses the left hand behind the bridge to add vibrato or slide the pitch up and down for emotional emphasis.", "category": "Performance Technique", "related_terms": ["Guzheng", "Yaozhi", "Vibrato", "Tremolo", "Pitch bend", "Portamento"], "common_mistakes": ["Pressing the string with the left hand before the tremolo has spoken, so a pitch bend is heard without a clear sustained tone.", "Using stiff fingers or a locked wrist for yaozhi, which makes the tremolo uneven instead of smooth and continuous.", "Confusing yaozhi (a right-hand tremolo for sustain) with the left-hand vibrato press; they are different roles that combine here."], "scenario_contexts": ["Sustaining a long, expressive melody note that also needs vibrato and pitch inflection.", "Imitating a singing voice or a bowed string on a plucked guzheng.", "A slow, emotional passage where held notes rise and fall in pitch while ringing continuously."]}, "5b97cdfc-491c-4de7-815c-fb88162d009a": {"definition": "A timbales flourish, its name Spanish for 'fan,' used to announce a change of section in Afro-Cuban dance music. It typically opens with an accented rimshot on the paila, continues with a short buzz (press) roll, and ends with another accent, cueing the band into the next passage such as the montuno or mambo.", "plain_english": "A quick timbales fill that tells the band a new part is coming. The player hits a sharp rim shot, adds a short buzzing roll, then a final hit, like waving everyone into the next section.", "purpose_function": "It serves as an audible cue that leads the ensemble from one section of an arrangement into the next, giving the band a clear, rhythmic hand-off.", "practical_application": "A timbalero plays an abanico to launch the montuno or to mark the top of a chorus, and a live engineer learns to expect a loud rimshot-plus-roll transient at those moments.", "category": "Playing technique", "related_terms": ["Timbales", "Rimshot", "Buzz roll", "Cascara", "Montuno", "Paila"], "common_mistakes": ["Playing the abanico as a long solo instead of a short, clear cue that leads into the next section.", "Burying the opening rimshot so the band cannot hear the signal.", "Rushing the buzz roll so it loses its even, sustained sound."], "scenario_contexts": ["A timbalero cueing a salsa band from the verse into the montuno section.", "Marking the entrance of the horn mambo in a live dance set.", "Signalling the top of a coro (call-and-response chorus) so singers enter together."]}, "ad0720e9-f1e8-4b3d-ac43-424921ccf133": {"definition": "The short, dry clicking sound produced on an agogô (a joined pair of pitched metal bells) by squeezing the two bells together with their springy connecting handle, rather than striking them with the beater. It gives a percussive, unpitched accent between the bells' struck tones in samba and other Afro-Brazilian rhythms.", "plain_english": "A quick tapping sound made by pressing the two joined bells of an agogo together instead of hitting them. It adds a light click between the ringing bell notes, like tapping two spoons together.", "purpose_function": "The click adds an extra rhythmic layer and subtle syncopation to an agogô pattern without introducing another pitch, filling the gaps between the struck bell tones.", "practical_application": "A samba percussionist works clicks into the agogô part to keep the pattern lively, and an engineer capturing the agogô allows for these soft, transient clicks alongside the brighter struck notes.", "category": "Playing technique", "related_terms": ["Agogô", "Samba", "Idiophone", "Caixa", "Ganzá", "Repinique"], "common_mistakes": ["Squeezing so hard that the bells ring rather than give a clean, muted click.", "Confusing the click with a struck bell tone; the click has no clear pitch.", "Playing only struck notes and dropping the click, losing the pattern's inner rhythm."], "scenario_contexts": ["Adding clicks between bell tones in a samba bateria agogô part.", "Playing a maracatu or capoeira groove where the agogô drives the pulse.", "Micing an agogô in the studio and balancing soft clicks against loud struck notes."]}, "d4374381-ee49-48a6-9f46-c133edf90fa5": {"definition": "The vibration of a tuned bar (as in a marimba, xylophone, vibraphone, or glockenspiel) in its transverse flexural (bending) modes, which set the instrument's pitch and timbre. Makers undercut the underside of the bar to shift its naturally inharmonic overtones toward musical ratios such as the twelfth (xylophone) or the double octave (marimba and vibraphone), and a tuned tube beneath the bar resonates to reinforce the fundamental.", "plain_english": "The way a tuned bar on a marimba or xylophone shakes and rings when you hit it, which sets its note. Makers carve the underside to fix the overtones, and a tube under the bar makes the note louder.", "purpose_function": "Bar resonance is what turns a struck bar into a definite musical note; shaping the bar and adding tube resonators controls its pitch, sustain, and characteristic warm tone.", "practical_application": "A technician tuning or repairing mallet bars checks that undercut bars sound their intended pitch and that resonator tubes are the right length and aligned under each bar for full tone.", "category": "Acoustics", "related_terms": ["Marimba", "Xylophone", "Vibraphone", "Resonator", "Fundamental frequency", "Overtone"], "common_mistakes": ["Thinking a bar makes only one pure pitch, when it also produces inharmonic overtones that must be tuned.", "Sanding the top of a bar to tune it, which lowers pitch and thins the bar, instead of undercutting the underside.", "Assuming resonator length does not matter, when a mistuned tube weakens the note."], "scenario_contexts": ["Tuning marimba bars so their overtones line up with the fundamental.", "Aligning and adjusting resonator tubes under a vibraphone.", "Diagnosing a dull-sounding bar that has cracked or lost its tuning."]}, "2a1e5d92-f605-4141-92ec-9dfdf4c00a76": {"definition": "The low, full-bodied stroke on a hand drum such as a conga or djembe, produced by striking near the center of the head with the flat hand or palm and letting it rebound so the whole head resonates. It is the deepest of the basic hand-drum sounds, contrasting with the higher open tone and the sharp slap.", "plain_english": "The deep, booming sound of a hand drum, made by hitting the middle of the head with a flat hand and lifting off so it rings. It is the lowest of the drum's basic sounds, like a thump you feel in your chest.", "purpose_function": "The bass tone supplies the low end and underlying pulse of a hand-drum part, anchoring the rhythm beneath the brighter open tones and slaps.", "practical_application": "A conga or djembe player uses bass tones to mark the main beats of a groove, and an engineer mics the drum to capture that low thump without losing the higher strokes.", "category": "Drum stroke", "related_terms": ["Open tone", "Slap", "Conga", "Djembe", "Bongo slap", "Tumbao"], "common_mistakes": ["Leaving the hand pressed on the head after the strike, which deadens the low ring.", "Striking too close to the rim, which thins the bass instead of hitting near the center.", "Playing bass tones too hard, which chokes the tone and tires the hand."], "scenario_contexts": ["Marking the downbeats of a djembe groove with deep bass tones.", "Playing tumbao on congas where bass tones anchor the pattern.", "Recording a hand drum and balancing bass thump against slaps and open tones."]}, "8a7e7384-ad75-46e8-86e0-2f55786a10e0": {"definition": "The buzzing, rattling timbre of a bendir, a North African frame drum, produced by one or more gut or nylon snares stretched across the inside of the drumhead that vibrate against it when the head is struck. The snares add a sustained sizzle to each stroke, much like the snares on a snare drum.", "plain_english": "The buzzing rattle of a bendir frame drum. Strings stretched under the skin shake against it when you hit the drum, adding a fuzzy sizzle to each beat, like the snare wires on a snare drum.", "purpose_function": "The snare buzz gives the bendir its characteristic voice, blending pitch and noise so a single frame drum can carry a rhythm with a rich, sustaining texture.", "practical_application": "A player adjusts how the snares sit and where the head is struck to control how much buzz sounds, and an engineer positions a mic to balance the drum's low tone against that sizzle.", "category": "Instrument timbre", "related_terms": ["Bendir", "Frame drum", "Snare", "Riq", "Membranophone", "Daf"], "common_mistakes": ["Assuming the buzz is a defect or loose fitting rather than the drum's intended snare sound.", "Over-tightening or muting the snares so the drum loses its signature buzz.", "Gating the buzz away in a mix and stripping the drum of its natural character."], "scenario_contexts": ["Playing North African or Sufi rhythms where the bendir's buzz drives the groove.", "Recording a frame drum and deciding how much snare sizzle to capture.", "Comparing a bendir with a plain frame drum such as a daf to hear the added buzz."]}, "57f5e976-7e5e-47e6-95e5-d13279d074df": {"definition": "A nonpitched, rattling sound on the berimbau (a Brazilian musical bow), produced by letting the dobrão, a coin or stone, rest lightly against the wire as it is struck so the wire buzzes rather than ringing to a clear pitch. It is one of the instrument's basic sounds, alongside the open low tone and the pressed higher tone.", "plain_english": "A buzzy sound on the berimbau with no clear note. The player lets the coin barely touch the wire as they hit it, so the string rattles instead of ringing, a bit like a lightly muted guitar string.", "purpose_function": "The buzz adds rhythmic color and a percussive, unpitched accent to berimbau patterns, expanding the bow's small set of sounds beyond its two main pitches.", "practical_application": "A capoeira musician weaves buzz strokes into a toque (rhythm) for variety, and anyone recording the berimbau captures this soft, noisy sound as part of its full character.", "category": "Playing technique", "related_terms": ["Berimbau", "Dobrão", "Berimbau open tone", "Berimbau muted (dobrão)", "Caxixi", "Capoeira"], "common_mistakes": ["Pressing the coin too hard, which gives the pressed pitched tone instead of a buzz.", "Pulling the coin fully off the wire, which gives the open tone with no buzz.", "Expecting a clear note from the buzz, when it is meant to be unpitched."], "scenario_contexts": ["Adding buzz strokes to a capoeira berimbau toque for rhythmic variety.", "Teaching a beginner the three basic berimbau sounds side by side.", "Recording a berimbau and balancing the soft buzz against its ringing tones."]}, "7561d0c2-abab-4bb8-b262-f2c134c99e90": {"definition": "The pressed, higher-pitched tone of the berimbau, produced by pressing the dobrão (a coin or stone) firmly against the wire while striking it. Stopping the wire this way raises the pitch roughly a step above the open tone and shortens its ring, making it the 'closed' counterpart to the open sound.", "plain_english": "A higher, shorter note on the berimbau made by pressing the coin firmly onto the wire as you strike it. Pressing down raises the pitch and cuts the ring short, like pressing a guitar string against a fret.", "purpose_function": "The pressed tone gives the berimbau a second, higher pitch, so the single-string bow can play the two-note melodic patterns that define the capoeira rhythms it accompanies.", "practical_application": "A capoeira musician alternates open and pressed tones to play a toque, and a recordist notes that pressed strokes sound higher and shorter than open ones when setting levels.", "category": "Playing technique", "related_terms": ["Berimbau", "Dobrão", "Berimbau open tone", "Berimbau buzz", "Cabaça", "Capoeira"], "common_mistakes": ["Pressing the coin only lightly, which gives a buzz instead of a clear pressed pitch.", "Expecting a large pitch jump, when the pressed tone rises only about a step above the open tone.", "Confusing 'muted' with silencing the string, when it actually sounds a higher, shorter note."], "scenario_contexts": ["Alternating open and pressed tones to play the São Bento Grande toque.", "Teaching the two main berimbau pitches to a new capoeira student.", "Recording a berimbau and tracking the pitch change between open and pressed strokes."]}, "cc198314-dad0-4c3a-b68f-e20777273b3e": {"definition": "The low, open, ringing tone of the berimbau, sounded by striking the wire while the dobrão is held away from it so the full length of the wire vibrates freely. It is the instrument's lowest and most resonant basic sound, contrasting with the higher pressed tone and the nonpitched buzz.", "plain_english": "The low, ringing note of the berimbau, played by hitting the wire while the coin is held off it so the string rings freely. It is the deepest of the bow's sounds, like an open guitar string left to ring.", "purpose_function": "The open tone provides the berimbau's fundamental low pitch, forming the base against which the higher pressed tone and the buzz are heard within a rhythm.", "practical_application": "A capoeira musician uses open tones as the low note of a two-tone pattern, and an engineer treats them as the loudest, most sustained sound the bow produces.", "category": "Playing technique", "related_terms": ["Berimbau", "Dobrão", "Berimbau muted (dobrão)", "Berimbau buzz", "Cabaça", "Capoeira"], "common_mistakes": ["Letting the coin touch the wire, which turns the open tone into a buzz or pressed note.", "Damping the wire or gourd too soon, which cuts the natural ring short.", "Assuming the open tone can be pitched at will, when it is fixed by the wire's full length."], "scenario_contexts": ["Sounding the low note of a berimbau toque in a capoeira roda.", "Demonstrating the lowest of the three basic berimbau sounds.", "Recording the berimbau and capturing the long ring of the open tone."]}, "81e0a538-3000-44b4-a031-6e727681a454": {"definition": "A sharp, high-pitched, cracking stroke on the bongos, produced by striking the head with a relaxed, slightly cupped hand so the fingertips snap against it, usually on the larger drum (hembra). It is the accented sound that punctuates the steady martillo pattern in Afro-Cuban music.", "plain_english": "A sharp, cracking hit on the bongos made with a loose, slightly cupped hand so the fingers snap the head. It is the loud accent that pops out of the steady bongo pattern, like a hand clap.", "purpose_function": "The slap provides a bright, cutting accent that marks key points in a bongo pattern, adding contrast and drive above the softer heel-and-finger strokes of the martillo.", "practical_application": "A bongocero drops slaps into the martillo to accent the groove, and a live engineer expects these sharp transients to peak louder than the surrounding strokes when setting the bongo mic.", "category": "Drum stroke", "related_terms": ["Bongos", "Martillo", "Slap", "Open tone", "Hembra", "Bongocero"], "common_mistakes": ["UNSAFE: Playing loud slaps close to the head over long sets without hearing protection; sustained percussion transients can exceed safe exposure levels (OSHA 29 CFR 1910.95), so use earplugs.", "Tensing the hand, which bruises the fingers and gives a dull, weak slap.", "Slapping the center instead of near the edge, which muddies the sharp crack.", "Playing every stroke as a slap, burying the accent it is meant to provide."], "scenario_contexts": ["Accenting a salsa groove with slaps over the martillo pattern.", "Trading loud slaps in a percussion solo or descarga.", "Micing bongos live and taming the loud slap transients in the mix."]}, "9dde47a2-4644-4722-bef4-c19260e205eb": {"definition": "The dry, continuous rasping tone produced by the modern cabasa (afuché-cabasa), a shaker idiophone in which loops of steel ball-chain are wrapped around a ridged metal or wooden cylinder fitted with a handle. Holding the beads in one hand and twisting the cylinder with the other drags the chain over the ridges, generating the instrument's characteristic sustained, sizzling rasp.", "plain_english": "A cabasa is a hand percussion instrument with metal beads wrapped around a ridged cylinder. The rasp is the dry, scratchy rattle you hear when you twist those beads against the metal. It sounds a bit like shaking gravel in a can.", "purpose_function": "The rasp gives the cabasa its signature sizzling, high-frequency texture, adding sustained rhythmic motion that fills the space between accents in a groove.", "practical_application": "A percussionist produces the rasp by rotating the beaded cylinder back and forth; an engineer captures it with a small-diaphragm condenser and often high-passes the low end, since most of its energy sits in the high frequencies.", "category": "Percussion technique", "related_terms": ["Cabasa scrape", "Shaker", "Idiophone", "Güiro", "Afoxé", "Sizzle"], "common_mistakes": ["Twisting the cylinder too aggressively, which strains the wrist and can loosen or wear out the beaded chain.", "Confusing the modern cabasa with the traditional gourd afoxé; the cabasa uses a steel ball-chain on a metal or wood cylinder, not beads strung over a gourd.", "Gripping the beads too loosely, so the rasp turns weak and uneven instead of a full, even sizzle."], "scenario_contexts": ["Adding a steady sixteenth-note rasp over a Latin or pop groove.", "Recording a cabasa rasp with a condenser mic for a percussion overdub.", "Layering the rasp under a chorus to add rhythmic energy without adding pitch."]}, "403f69c1-6c7c-4ac2-8ebf-18a32478575a": {"definition": "A stroke on the cabasa in which the steel ball-chain is dragged in a single sweeping direction across the ridged cylinder, rather than twisted back and forth, producing a short scraping articulation. It is used as an accent or transition within the cabasa's continuous rasping patterns.", "plain_english": "This is the sound made by dragging the cabasa's metal beads across its ridged cylinder. You get a short, scratchy sweep, like running a stick along a fence. Players use it to add a swishy accent to a groove.", "purpose_function": "The scrape provides a distinct swept accent or fill that contrasts with the cabasa's steady rasp, marking transitions or adding expression to a percussion part.", "practical_application": "A player executes a scrape by pulling the beads along the cylinder in one direction on a chosen beat; in a mix it is treated like the rasp, sitting in the high frequencies and often panned for width.", "category": "Percussion technique", "related_terms": ["Cabasa rasp", "Güiro scrape", "Shaker", "Idiophone", "Accent", "Afoxé"], "common_mistakes": ["Scraping so hard the chain skips or the handle twists, giving an uneven, noisy sweep.", "Using the scrape continuously so it blurs into the steady rasp and loses its value as an accent.", "Assuming the scrape is a separate instrument; it is simply a different way of moving the same cabasa beads."], "scenario_contexts": ["Marking the end of a phrase with a single cabasa scrape.", "Adding swept accents to a busy percussion arrangement.", "Overdubbing occasional scrapes to break up a steady cabasa rasp."]}, "9aacb631-6057-4eda-b5d5-75fab5f1a011": {"definition": "The low-pitched, resonant tone of a cajón, produced by striking the centre of the front playing plate (tapa) with the flat of the hand. This central region flexes most freely and drives the enclosed air of the box, giving a deep note analogous to a bass or kick drum.", "plain_english": "A cajón is a wooden box drum you sit on and hit with your hands. The bass is the deep, low boom you get by hitting the middle of the front face. It works like the kick drum of the box.", "purpose_function": "The bass tone supplies the low-end foundation of a cajón groove, working like the kick drum of a kit so a single player can imply a full rhythm section.", "practical_application": "A player strikes the tapa's centre for bass notes and the top edges for higher tones; when miking, an engineer often places a mic at the rear sound hole or inside the box to reinforce the low bass.", "category": "Percussion tone", "related_terms": ["Cajón front plate", "Cajón snare", "Tapa", "Kick drum", "Sound hole", "Bass tone"], "common_mistakes": ["Hitting the centre with fingertips instead of the flat palm, which thins the bass and adds unwanted slap.", "Striking too high on the plate for bass notes, so the tone loses depth.", "Over-tightening the internal snares, which masks the pure bass tone with buzz."], "scenario_contexts": ["Playing the down-beat bass tone in an acoustic singer-songwriter set.", "Miking a cajón's rear port to capture more bass for a live show.", "Layering cajón bass with a bass guitar in a stripped-back arrangement."]}, "2e499604-095f-4f57-97a0-78ba6bb1ac99": {"definition": "The thin, resonant wooden sheet forming the front face of a cajón, also called the tapa, which the player strikes with the hands. Usually thin plywood, it is commonly screwed firmly at the top while the lower corners are left free to flex, giving brighter, snappier tones near the edges and deeper bass toward the centre.", "plain_english": "The front plate is the thin wooden sheet on the face of a cajón that you strike. It is often called the tapa. Where and how hard you hit it changes the sound from a deep boom to a sharp snap.", "purpose_function": "The front plate is the cajón's playing surface and main sound source; its flexibility and where it is struck set the whole range of bass and slap tones the instrument can make.", "practical_application": "A player tunes response by adjusting the top screws, tightening for a crisper attack or loosening the corners for more slap; a technician replacing a cracked tapa matches wood type and thickness to preserve the tone.", "category": "Instrument part", "related_terms": ["Cajón bass", "Cajón snare", "Tapa", "Soundboard", "Resonance", "Plywood"], "common_mistakes": ["Over-tightening every screw on the tapa, which kills the corner slap and flattens the tone.", "Confusing the front plate (tapa) with the whole box; only the front face is the struck playing surface.", "Replacing a broken tapa with thick, stiff wood that dulls the bass and slap response."], "scenario_contexts": ["Adjusting the top screws of the tapa to fine-tune slap response before a gig.", "Replacing a cracked cajón front plate on the workbench.", "Explaining to a student why hitting different spots on the tapa changes the tone."]}, "09bed24b-3ebe-4bf4-9f65-bba9d25ad868": {"definition": "The buzzing, snare-like effect built into most modern flamenco-style cajóns, created by snare wires or tensioned guitar strings mounted against the inside of the front plate. When the tapa is struck, especially near the top edge, the wires or strings vibrate against it, adding a bright buzz reminiscent of a snare drum.", "plain_english": "This is the buzzy, rattly sound built into many cajóns. Snare wires or guitar strings sit just behind the front plate and rattle when you hit it. It makes the box sound a bit like a real snare drum.", "purpose_function": "The internal snare lets a single cajón imitate both the kick and snare of a drum kit, giving the crisp backbeat crack that defines the flamenco cajón's sound.", "practical_application": "Many cajóns include a lever or adjustable strings to raise or lower the snare buzz; a player dials in more buzz for pop or less for a cleaner box tone, and can partly mute the strings for a drier sound.", "category": "Percussion tone", "related_terms": ["Cajón bass", "Cajón front plate", "Snare wires", "Tapa", "Buzz", "Snare drum"], "common_mistakes": ["Blaming a rattling cajón on a fault when the buzz is the intended snare effect.", "Leaving snare strings so loose they rattle on every bass note and muddy the low tones.", "Assuming all cajóns have snares; traditional Peruvian cajóns have no internal wires or strings."], "scenario_contexts": ["Adjusting the snare strings for a tighter backbeat crack in a pop set.", "Choosing between a snare cajón and a plain Peruvian cajón for a recording.", "Muting the internal snares for a drier, more traditional cajón tone."]}, "a38d1c6d-2907-4973-b543-d5a5c869d6e7": {"definition": "A slap stroke on the mridangam, the double-headed South Indian barrel drum, played with the hand on the right (valanthalai) treble head. Common forms include the ara chapu, a full open slap of the palm and fingers, and the muru (maru) chapu, which damps the head with the little finger to bring out a ringing harmonic; the stroke is represented in Carnatic drum syllables (solkattu) such as \"cha\".", "plain_english": "The mridangam is a two-headed drum from South India. A chapu is a slapping stroke played with the hand on the higher-pitched right head. It gives a sharp, ringing slap that helps drive the rhythm.", "purpose_function": "The chapu adds a sharp, accented slap to a mridangam phrase, giving rhythmic drive and a bright ringing accent that contrasts with the drum's clear tuned tones.", "practical_application": "A mridangam player uses chapu strokes as accents within rhythmic phrases and cadences; a recording engineer close-mics the treble head to capture the crisp attack and ring of these slaps.", "category": "Drum stroke", "related_terms": ["Mridangam", "Valanthalai", "Solkattu", "Konnakol", "Slap stroke", "Tabla bol"], "common_mistakes": ["Thinking chapu is played on the left bass head (thoppi); the slap is struck on the right treble head.", "Playing it with a stiff, flat hand that chokes the head and loses the ringing harmonic.", "Confusing the different chapu forms; the open ara chapu and the damped muru chapu produce distinct tones."], "scenario_contexts": ["Accenting a Carnatic rhythmic phrase with sharp chapu slaps.", "Learning the solkattu syllables that correspond to chapu strokes.", "Close-miking the treble head of a mridangam to record its slap strokes."]}, "772afcf9-0a95-46e9-9622-d020052bb99b": {"definition": "The sustained ringing vibration of chimes, such as orchestral tubular bells, bar chimes (mark tree), or tuned wind chimes, that continues after the instrument is struck. The long decay arises from the low internal damping of the metal tubes or bars, which vibrate in a set of partials that give chimes their shimmering, bell-like sustain.", "plain_english": "Chimes are metal tubes or bars that ring when you tap them. Chime resonance is that long, shimmering ring that keeps sounding after the hit. It is like the way a bell keeps humming once you strike it.", "purpose_function": "This long resonance gives chimes their shimmering, sustaining character, letting a single strike ring out as a wash of tone used for colour, accents, and transitions.", "practical_application": "A percussionist damps tubular bells with a foot pedal or hand to control how long they ring, while an engineer captures the full decay with condenser mics and watches for the long sustain overlapping other parts.", "category": "Acoustic property", "related_terms": ["Tubular bells", "Mark tree", "Sustain", "Decay", "Partials", "Idiophone"], "common_mistakes": ["Assuming chimes ring at one clean pitch; their many inharmonic partials give a complex, bell-like tone rather than a single note.", "Cutting off the natural decay too early with heavy damping and losing the shimmering tail.", "Miking chimes too close, so the strike is loud but the blooming resonance is under-captured."], "scenario_contexts": ["Letting orchestral tubular bells ring to add a bright accent in a film score.", "Recording a mark tree sweep and preserving its long shimmering decay.", "Damping chimes with a pedal so the resonance does not clash with the next chord."]}, "2aa7e728-5984-4bfd-8459-8a7e93d875e4": {"definition": "A tom-tom that is muted immediately after it is struck, typically by pressing a hand or fingers onto the drumhead, so its natural resonance is cut short and it produces a brief, staccato dead note. The term can also describe a tom heavily over-damped with muffling so that it lacks sustain.", "plain_english": "A tom is one of the round drums on a drum kit. A choked tom is one you mute right after hitting it, so the sound stops fast. Instead of ringing out, it gives a short, dead thud.", "purpose_function": "Choking a tom shortens its ring for rhythmic, staccato effects or to keep a resonant drum from clashing with the rest of the kit, giving the player control over sustain.", "practical_application": "A drummer chokes a tom by striking it and quickly laying a hand on the head; in the studio an engineer may add muffling or gating to get a similarly short, controlled tom sound.", "category": "Percussion technique", "related_terms": ["Tom-tom", "Damping", "Muffling", "Choke (cymbal)", "Sustain", "Noise gate"], "common_mistakes": ["Confusing choking (muting after the hit) with tuning the tom lower; choking shortens sustain, it does not change pitch.", "Over-muffling a tom permanently when only an occasional choked note was wanted.", "Applying a heavy noise gate to fake a choke and accidentally chopping off the note's attack."], "scenario_contexts": ["Choking a floor tom by hand for a short, punchy accent.", "Adding tape or a muffling ring to get a controlled, choked tom tone.", "Gating toms in a mix to tighten an overly long sustain."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"95959cd5-a731-4be7-bfa9-a0650cb80322": {"definition": "The sharp, bright transient produced at the instant two claves, short thick hardwood dowels, are struck together. The hard, dense wood combined with a cupped resonating hand gives the strike a fast rise time and a penetrating, high-pitched click that cuts through dense ensembles.", "plain_english": "Claves are two short wooden sticks you strike together. The attack is the sharp, bright click you hear the instant they meet. That crisp tock cuts through even a loud band.", "purpose_function": "The strong, clean attack makes the clave's timeline pattern audible over a full band, letting it act as the rhythmic reference that other parts lock to.", "practical_application": "A player forms a resonating cup with one hand and strikes it with the other clave for maximum tone; an engineer captures the sharp attack with a condenser mic and avoids heavy compression that would dull the transient.", "category": "Percussion tone", "related_terms": ["Claves", "Clave (rhythm)", "Transient", "Attack", "Idiophone", "Woodblock"], "common_mistakes": ["Holding both claves tightly in solid fists, which damps the resonance and gives a dull, weak attack.", "Confusing the clave attack (the sound's sharp onset) with clave the rhythmic pattern.", "Compressing the claves so hard in a mix that the crisp attack is squashed and lost."], "scenario_contexts": ["Cutting through a loud salsa band with a bright clave attack.", "Recording claves with a condenser mic to keep the sharp transient.", "Teaching a student to cup one hand so the clave rings instead of clicking dully."]}, "040b8c0f-47e1-42b9-881d-3fb35e50dd32": {"definition": "The low, deep tone of the conga, produced by striking the center of the head with the flat palm or heel of the hand and letting it rest briefly to damp the ring. It is the darkest, lowest-pitched of the basic conga strokes; in the heel-tip (heel-toe) rocking motion the heel of the palm supplies this bass pulse.", "plain_english": "The deep, low sound of a conga drum. You make it by pushing the flat of your hand into the middle of the head. It gives a soft, heavy thud that sits under the beat like a heartbeat.", "purpose_function": "It gives the conga part its low-end foundation and marks the pulse, so the higher open and slap tones have a deep note to lock against.", "practical_application": "A player sounds the bass tone on strong beats as part of the heel-tip rocking motion; when miking congas, an engineer positions the mic to capture this low thump without excessive boom.", "category": "Conga technique", "related_terms": ["Conga open tone", "Conga slap (seco)", "Conga muff (mute tone)", "Heel-tip stroke", "Tumbao", "Tumbadora"], "common_mistakes": ["Striking the center with a stiff, flat hand and leaving it there so long the note sounds dead instead of a round, deep bass.", "Confusing the bass tone with the quiet heel of the heel-tip motion; the bass is a distinct deep note, not just filler.", "Hitting harder for a lower sound, when relaxed weight from the palm gives a fuller bass than force does."], "scenario_contexts": ["Laying down the low pulse of a salsa tumbao on the downbeats.", "Anchoring a Latin-jazz groove so the open and slap tones have a deep note to sit over.", "Setting a mic on the conga to capture a full bass thump without boom."]}, "5e570438-954b-4f55-bc15-d4e11dca7b15": {"definition": "A muted conga stroke played like an open tone near the rim, but with the fingers left pressed on the head so the note is stopped short. It produces a short, dry, dead-sounding tone with little ring, used as soft filler between the ringing strokes.", "plain_english": "A short, dull conga note. You strike near the edge but keep your fingers on the head so it does not ring. It sounds soft and quiet, like a quick tap that gets muffled right away.", "purpose_function": "Muted tones fill the quiet spaces in a conga pattern with soft, non-ringing notes, adding motion and swing without competing with the loud open and slap accents.", "practical_application": "A player uses muff tones as low-volume filler within the heel-tip motion; an engineer keeps them just audible in a mix so the groove's inner rhythm is not lost under the louder strokes.", "category": "Conga technique", "related_terms": ["Conga open tone", "Conga bass (heel)", "Conga slap (seco)", "Muffled tone", "Heel-tip stroke", "Damping"], "common_mistakes": ["Playing muff tones too loud so they compete with the open and slap accents instead of sitting underneath them.", "Lifting the fingers after the strike, which turns the intended muted note into an open, ringing tone.", "Skipping muted filler notes entirely, leaving the pattern stiff and losing its swing."], "scenario_contexts": ["Filling the gaps of a tumbao with quiet, non-ringing notes to keep the groove moving.", "Using the heel-tip rocking motion where muted taps link the louder accents.", "Mixing a busy percussion track and keeping the soft muted notes just audible under the accents."]}, "ad32da57-edc6-4c66-87d2-3cad8d86def6": {"definition": "The clear, ringing conga tone produced by striking the edge of the head with the fingers held together and flat, then letting the hand bounce straight off so the head rings freely. It is the fundamental sustained, pitched sound of the drum.", "plain_english": "The clear, ringing sound of a conga. You hit the edge with flat fingers and let your hand bounce right off. Because you do not hold the head down, the drum rings out with a bright, singing note.", "purpose_function": "The open tone is the conga's main melodic, pitched voice; drums tuned to different pitches use open tones to carry the tune and the main accents of a pattern.", "practical_application": "Players sound open tones for the ringing accents in a tumbao; when tuning a set of congas, a player or engineer checks that each drum's open tone gives a clear, distinct pitch.", "category": "Conga technique", "related_terms": ["Conga slap (seco)", "Conga bass (heel)", "Conga muff (mute tone)", "Tumbao", "Drum tuning", "Sustain"], "common_mistakes": ["Leaving the fingers on the head after striking, which mutes the tone and kills the ring.", "Striking too far from the edge or over the center, giving a dull, pitchless thud instead of a clear tone.", "Using too much arm force so tones sound harsh and the hand tires, when a loose wrist gives a cleaner ring."], "scenario_contexts": ["Sounding the ringing melodic accents of a salsa or rumba pattern.", "Tuning a set of two or three congas so each open tone gives a clear, separate pitch.", "Recording a solo where the open tones carry the main melody of the phrase."]}, "6d7f19c9-21ba-42b1-ab02-2ddbca7c4642": {"definition": "A sharp, loud, high-pitched conga accent produced with a quick whip of the cupped fingers at the head. In the closed or 'seco' (dry) slap the hand stays on the head after striking, muting the ring to leave a short, cracking pop; an open slap instead lets the head ring.", "plain_english": "A loud, sharp 'crack' on the conga. You snap your cupped fingers onto the head with a fast whip of the hand. The dry, or 'seco', slap keeps the hand down so the sound is short and pops like a clap.", "purpose_function": "The slap is the loudest, most cutting conga stroke; it provides the bright accents that punch through a band and mark key points in a rhythm.", "practical_application": "Players place slaps on offbeats for drive and cut; because slaps are much louder than other strokes, an engineer watches for level spikes and may use light compression to control them.", "category": "Conga technique", "related_terms": ["Conga open tone", "Conga bass (heel)", "Conga muff (mute tone)", "Accent", "Transient", "Dynamic range"], "common_mistakes": ["Trying to make the slap loud with brute force, which strains the hand; the crack comes from a relaxed whip of the fingers.", "Confusing the closed (seco) slap with the open slap; the seco slap keeps the hand on the head to stop the ring.", "UNSAFE: Practicing hard slaps for long stretches without rest, risking bruising and repetitive-strain injury to the hand and wrist."], "scenario_contexts": ["Cutting sharp accents through a full band on the offbeats.", "Trading loud slaps in a rumba or conga solo for excitement.", "Controlling level spikes when recording, since slaps are far louder than open tones."]}, "c68030e8-f44a-4448-91a9-2485863f2201": {"definition": "A high, sharp slapping tone on a cajón, produced by striking the top corner or upper edge of the front playing surface (the tapa), where the panel is loosest. It contrasts with the deep bass tone struck in the center and functions like a snare-style accent.", "plain_english": "The high, snappy sound of a cajon. You get it by hitting the top corner of the front playing face, not the middle. It cracks like a snare drum, while the center gives the deep bass note.", "purpose_function": "Corner tones give the cajon its treble, snare-like accents; playing corners versus center lets one box drum imitate both the snare and the bass drum of a kit.", "practical_application": "A player strikes the top corners for backbeats and the center for bass notes; when miking a cajon, an engineer aims to capture both the corner slap and the internal snare buzz.", "category": "Cajon technique", "related_terms": ["Cajon", "Bass tone", "Slap tone", "Snare wires", "Backbeat", "Close miking"], "common_mistakes": ["Hitting the center for every note, so the playing has no high, snare-like accents and sounds flat.", "Striking the wooden frame instead of the loose top corner of the tapa, giving a hard knock instead of a ringing slap.", "Forgetting that corner and center tones need different hand angles, leading to weak, uneven sounds."], "scenario_contexts": ["Playing the backbeat 'snare' hits on an acoustic pop gig with just a cajon.", "Switching between corner slaps and center bass to imitate a full drum kit.", "Miking a cajon for a live set to capture both the corner slap and the internal snare buzz."]}, "d893acdd-4544-4083-abd0-4269f1f31ffc": {"definition": "The sharp initial transient of a cowbell strike: the loud, bright metallic onset heard the instant the beater hits the bell, before the tone settles. A cowbell has a very fast, pronounced attack and short sustain, giving it a hard, cutting sound.", "plain_english": "The hard, bright 'clank' at the very start of a cowbell hit. That sudden burst of sound is the attack. A cowbell's attack is fast and loud, so it cuts through a band even when other things are playing.", "purpose_function": "The strong attack is what makes the cowbell so easy to hear in a busy mix; its sharp onset marks time clearly and adds a driving accent to a groove.", "practical_application": "A player varies where and how hard the bell is struck to shape the attack; an engineer may use a fast transient or compression setting so the cowbell's onset stays punchy without turning harsh.", "category": "Cowbell sound", "related_terms": ["Attack", "Transient", "Sustain", "Cowbell", "Clave", "Compression"], "common_mistakes": ["Choking the bell by gripping it tightly, which deadens both the attack and the sustain.", "Striking only one spot; the open mouth and the closed end give very different attack and pitch.", "Turning the cowbell up too loud in a mix because its sharp attack already cuts through easily."], "scenario_contexts": ["Marking the clave or timeline in a Latin band with a bright, cutting cowbell.", "Adding a driving accent to a rock or funk groove that needs to punch through.", "Dialing a fast transient or compression setting so the cowbell stays punchy in a dense mix."]}, "13277150-6502-4291-944a-8325f0e71291": {"definition": "The characteristic high, vocal-like cry of the cuica, a Brazilian friction drum. It is made by rubbing a damp cloth along a stick fixed inside and perpendicular to the head; the friction drives the head into vibration, while a finger pressing the head from outside slides the pitch up and down to create the squeaking, moaning or laughing sound.", "plain_english": "The squeaky, moaning cry of the cuica, a Brazilian drum. Inside is a stick joined to the head. You rub the stick with a wet cloth to make it sing, and press the head with a finger to slide the pitch, so it sounds like a voice.", "purpose_function": "The squeak-and-moan is the cuica's whole voice; its rising and falling cry adds a talking, call-and-response feel that drives samba and carnival grooves.", "practical_application": "A player rubs and presses to bend the pitch in time with the music; an engineer close-mics the drum to catch its quiet, high squeak without picking up too much surrounding percussion.", "category": "Cuica technique", "related_terms": ["Friction drum", "Membrane", "Pitch bend", "Samba", "Timbre", "Close miking"], "common_mistakes": ["Rubbing with a dry cloth or too little rosin, so the stick slips and squeals unevenly instead of singing.", "Forgetting to press the head with the other hand, losing the pitch changes that make the moaning voice.", "Rubbing too fast or hard, which produces a harsh screech rather than a controlled cry."], "scenario_contexts": ["Adding the talking, call-and-response cries to a samba bateria at carnival.", "Coloring a percussion track with a vocal-like moaning effect.", "Close-miking the drum in the studio to catch its quiet, high squeak."]}, "c2ff5775-6ceb-42ee-b798-0137f96c929f": {"definition": "A loud, dense, sustained wash of cymbal sound, built by striking a cymbal hard or rolling on it until its many closely spaced vibration modes blend into a full, roaring surge of noise. It is most often produced on a crash, ride or suspended cymbal with mallets or fast repeated strokes.", "plain_english": "A big, loud swell of cymbal sound, like a wave of noise growing louder. A cymbal makes so many tones at once that a hard hit or fast roll blends them into a roar. Drummers use it to build up to a big moment.", "purpose_function": "A cymbal roar adds power and tension, filling the top end of the sound to lift a climax or mark a dramatic transition in a piece.", "practical_application": "A drummer rolls with mallets to swell a roar into a chorus or downbeat; an engineer manages overhead mic levels and possible limiting so the roar's peak stays loud but does not distort.", "category": "Cymbal sound", "related_terms": ["Cymbal shimmer", "Cymbal wash", "Crash cymbal", "Suspended cymbal", "Cymbal roll", "Overhead miking"], "common_mistakes": ["Crashing at full force to get a roar, which can crack a thin cymbal; a mallet roll builds the same swell more safely.", "Rolling with sticks too slowly, so the sound stays as separate hits instead of blending into a wash.", "UNSAFE: Standing close to loud, sustained cymbal washes without hearing protection, risking noise-induced hearing loss."], "scenario_contexts": ["Building a mallet roll into a huge wash to launch a chorus or final section.", "Marking a dramatic transition in an orchestral or film score with a suspended-cymbal swell.", "Riding overhead levels and limiting so the roar's peak stays loud but clean."]}, "850b0b3d-0f26-45bc-970e-d1228088b60d": {"definition": "The bright, sparkling, sustained high-frequency component of a cymbal's sound: the soft, glistening ring produced by its high vibration modes, especially from a light touch, soft roll or gentle wash on a thin cymbal. It is a delicate, airy sustain rather than a loud attack.", "plain_english": "The soft, sparkly ring of a cymbal that hangs in the air. It is the bright, glittery part of the sound, not a loud crash. A light tap or gentle roll brings it out, adding a shiny sheen on top of the music.", "purpose_function": "Shimmer adds air, sparkle and a sense of space at the top of a mix, giving music a bright, glossy finish without heavy volume.", "practical_application": "A drummer coaxes shimmer with soft rolls or light ride playing under a quiet passage; an engineer captures it with well-placed overhead or room mics and gentle high-end EQ rather than boosting harsh frequencies.", "category": "Cymbal sound", "related_terms": ["Cymbal roar", "Cymbal wash", "Ride cymbal", "Sustain", "Overhead miking", "High frequency"], "common_mistakes": ["Playing too hard, which turns the soft shimmer into a loud crash and loses the delicate sheen.", "Boosting harsh high frequencies to add sparkle, when gentle, well-placed miking captures shimmer more naturally.", "Choosing a thick, heavy cymbal and expecting shimmer; thinner cymbals give the airy, sustained ring more easily."], "scenario_contexts": ["Adding soft, sparkling sustain under a quiet ballad verse.", "Coaxing an airy sheen from a light ride pattern in a jazz brush groove.", "Capturing the delicate high-end ring with overhead or room mics in a session."]}, "cafdd815-5567-4b16-bafe-06ca21240abd": {"definition": "The sustained, shimmering blend of overtones and decaying sustain produced when cymbals, especially crash and ride cymbals, are struck firmly or played continuously, so their sound builds up and blurs together rather than reading as distinct hits. In recording, the term also describes this broadband cymbal sustain as it bleeds into overhead and room microphones.", "plain_english": "Cymbal wash is the loud, shimmery haze a cymbal makes when it keeps ringing. The separate hits blur into one bright sound. It is like the long hiss you hear after crashing a cymbal hard.", "purpose_function": "It adds energy, sustain, and a sense of size to drum parts, filling space during loud sections and swells, and it matters to engineers because it dominates the high end of overhead and room mics.", "practical_application": "A technician manages cymbal wash by choosing and placing overhead mics, applying high-pass filtering and EQ, and controlling decay so the cymbals add excitement without masking vocals or smearing the mix.", "category": "Cymbal technique", "related_terms": ["Ride cymbal", "Crash cymbal", "Overhead microphone", "Decay", "Bleed", "Hi-hat"], "common_mistakes": ["Letting cymbal wash swamp the overheads so it buries the snare and vocals in the mix.", "Assuming louder crashing sounds better, when excessive wash just adds harsh, fatiguing high end.", "Trying to fix a washy mix with EQ alone instead of addressing cymbal choice, playing, and mic placement at the source."], "scenario_contexts": ["Miking a drum kit and hearing cymbal wash dominate the overhead channels.", "Taming a bright, washy chorus where crash cymbals cover the lead vocal.", "A drummer using rapid ride patterns to build a wash of sound into a song's climax."]}, "b9cf1c8d-ab08-4f8f-bd3f-5d962cb79fb2": {"definition": "A steady, syncopated ostinato in Afro-Cuban music played with sticks on a hard surface, traditionally the metal shell (side) of the timbales or a woodblock, that outlines and locks with the clave. Played in continuous eighth- and sixteenth-note figures, it serves as a quieter timekeeping pattern, often in son and montuno sections, before the player moves to the bell or drum heads.", "plain_english": "Cascara is a repeating stick pattern played on the metal side of the timbale drums. It keeps steady time and lines up with the clave beat. The word means \"shell\" in Spanish, which is the part of the drum you hit.", "purpose_function": "It gives a driving but low-volume timekeeping groove that supports the clave and singer during softer sections, providing a rhythmic backbone without the loudness of the bell or drum heads.", "practical_application": "A percussionist plays cascara on the timbale shells during verses and quiet passages, then switches to the mambo bell or drum heads to raise intensity for choruses and solos.", "category": "Rhythmic pattern", "related_terms": ["Clave", "Timbales", "Cencerro (bell)", "Montuno", "Paila", "Abanico"], "common_mistakes": ["Playing cascara out of alignment with the clave, so the pattern fights the song's rhythmic feel.", "Confusing the 3-2 and 2-3 directions and starting the pattern on the wrong side of the clave.", "Playing it too loudly on the shells, defeating its purpose as a softer, supportive timekeeper."], "scenario_contexts": ["A timbalero playing cascara on the shells through a salsa verse.", "Switching from cascara to the mambo bell to lift a chorus.", "Programming a realistic timbale part in a DAW using a cascara pattern locked to clave."]}, "238a48bc-f345-4864-96c6-0e08ad369a4d": {"definition": "The small metal rings (jingles) fastened to the inner side of the wooden frame of the daf, a large Persian and Kurdish frame drum. When the head is struck or the drum is shaken and tilted, the rings strike the frame and one another, adding a bright, shimmering, sustained jingle to the drum's tone.", "plain_english": "Daf rings are little metal rings hung inside the frame of the daf drum. When you hit or shake the drum, the rings rattle and add a bright, shimmery sound. They work a bit like the jingles on a tambourine.", "purpose_function": "The rings give the daf its signature sizzling shimmer, extending the sustain of each stroke and adding rhythmic sparkle, especially during shakes and rolls.", "practical_application": "A player uses wrist shakes and finger rolls to make the rings ring out, and a recording engineer positions mics to balance the bright jingle against the deeper head tone.", "category": "Instrument component", "related_terms": ["Daf", "Frame drum", "Riq", "Jingles", "Bendir", "Roll"], "common_mistakes": ["Thinking the rings are decorative rather than a functional part of the instrument's sound.", "Miking only the head and missing the bright ring shimmer that defines the daf.", "Confusing the daf's hanging internal rings with the paired metal jingles slotted into a tambourine or riq frame."], "scenario_contexts": ["Recording a daf and balancing the metallic ring shimmer against the low head tone.", "A player producing a sustained shimmer with rapid shakes during a Sufi music piece.", "Distinguishing a daf from a plain frame drum (bendir) by the sound of its internal rings."]}, "d9420167-7e48-4f1d-a7d8-5616cd2ad0d5": {"definition": "The two contrasting basic strokes of the davul, a large double-headed cylindrical bass drum of Turkey and the Balkans: the deep, low \"dum\" produced by a heavy wooden beater on the larger, thicker head, and the sharp, high \"tek\" produced by a thin switch or stick on the opposite, thinner head. Their alternation forms the basic rhythmic drive of Anatolian and Balkan dance music.", "plain_english": "On the davul drum, \"dum\" is the deep low hit and \"tek\" is the sharp high hit. A big beater makes the low sound on one side, and a thin stick makes the high sound on the other. Switching between them gives dance music its bounce.", "purpose_function": "The low-high contrast lets one drummer state both the strong bass pulse and the lighter offbeats, driving folk-dance rhythms and outdoor processional music.", "practical_application": "A davul player alternates the beater-hand \"dum\" and the stick-hand \"tek\" to lay down dance grooves, and an engineer mics both heads to capture the low body and the sharp high stroke.", "category": "Playing technique", "related_terms": ["Davul", "Dum and tek", "Darbuka", "Bass drum", "Beater", "Zurna"], "common_mistakes": ["Assuming both strokes come from the same head, when dum and tek are played on opposite heads with different sticks.", "Playing dum and tek at equal volume, losing the low-high contrast that defines the groove.", "Confusing the davul's stick-and-beater dum-tek with the hand-played dum and tek of the goblet drum (darbuka)."], "scenario_contexts": ["A davul-and-zurna duo driving a Turkish wedding dance.", "Learning a 9/8 Balkan rhythm by counting the dum and tek strokes.", "Miking a davul for a folk recording to capture both the low dum and the crisp tek."]}, "e3d73b90-a5dd-4281-982e-703ff91376c5": {"definition": "A resonant composite stroke (bol) on the tabla in which a treble stroke on the right-hand drum (dayan), typically \"na\" or \"ta\" on the rim, is played together with the open bass stroke \"ge/ghe\" on the left-hand drum (bayan). The two fuse into one full, ringing syllable, \"dha\", one of the most common bols in tabla rhythmic cycles (tala).", "plain_english": "\"Dha\" is a tabla sound made by hitting both drums at once. You play a ringing high note on the small drum and a deep bass note on the big drum together. The two blend into one full, open sound.", "purpose_function": "Combining treble and bass in a single stroke gives a strong, resonant accent, so \"dha\" often marks important beats, such as sam (the first beat), in a rhythmic cycle.", "practical_application": "A tabla player uses \"dha\" as a full-sounding downbeat within spoken and played rhythm patterns, and it appears constantly in the recited bols of common talas such as teental.", "category": "Drum stroke", "related_terms": ["Tabla", "Bayan", "Dayan", "Bol", "Tala", "Dhin"], "common_mistakes": ["Striking the two drums slightly out of sync so the bass and treble do not fuse into one \"dha\".", "Damping the bayan bass stroke, which turns the open \"dha\" into a closed, dead sound.", "Confusing \"dha\" with \"dhin\", which pairs a different, more sustained treble stroke with the same bass."], "scenario_contexts": ["Reciting and playing teental, where \"dha\" opens the cycle on sam.", "A student learning to land both hands together to produce a clean \"dha\".", "Notating a tabla groove and marking the \"dha\" strokes on the accented beats."]}, "ea4d7791-2227-4616-acc9-52df59151063": {"definition": "The two contrasting striking sides of the dhol, a double-headed barrel drum of the Indian subcontinent: the higher-pitched treble side (thali, also tili/tihli), struck with a thin cane stick, and the lower-pitched bass side (dagga, also dhamma), struck with a heavier curved wooden stick. Playing the two together produces the drum's characteristic layered bass-and-treble rhythm.", "plain_english": "A dhol has two heads. The \"thali\" side is the high side, hit with a thin stick, and the \"dagga\" side is the low bass side, hit with a thick curved stick. Playing both sides makes the big, punchy dhol beat.", "purpose_function": "Splitting the drum into a bass side and a treble side lets one player produce a full low-and-high groove, the driving rhythmic engine of bhangra and folk processions.", "practical_application": "A dhol player strikes the dagga side for deep downbeats and the thali side for fast, high offbeats, while an engineer mics both heads to catch the bass thump and the sharp treble crack.", "category": "Playing technique", "related_terms": ["Dhol", "Dagga", "Bhangra", "Barrel drum", "Dholak", "Beater"], "common_mistakes": ["Swapping the sticks, using the light treble stick on the bass side or the heavy stick on the treble side, and losing each side's proper tone.", "Playing both sides at one volume, so the bass-treble contrast that drives the groove disappears.", "Confusing the large two-stick dhol with the smaller, hand-played dholak."], "scenario_contexts": ["A dhol player driving a bhangra dance with alternating dagga and thali strokes.", "Miking a dhol for a wedding-procession recording to balance both heads.", "Learning a folk rhythm by separating the bass (dagga) and treble (thali) parts."]}, "bf5736e0-9854-42fc-819f-19eab027b332": {"definition": "The central, deep note of a handpan (and the earlier Hang): a hammered elliptical dome in the middle of the top shell, tuned to the instrument's lowest fundamental with harmonic partials (typically an octave and a fifth) and surrounded by a ring of higher tone fields. Struck near its center, the ding also helps excite the Helmholtz air resonance of the enclosed shell.", "plain_english": "The ding is the big center note of a handpan. It is a small raised dome in the middle that plays the lowest, deepest note. All the other notes sit in a ring around it.", "purpose_function": "The ding anchors the instrument as its lowest, most resonant note and, by exciting the enclosed air resonance, gives the handpan its warm, singing body of sound.", "practical_application": "A player uses the ding as the tonic or bass note of a scale, returning to it for grounding, while an engineer mics near it to capture the instrument's deep low end.", "category": "Instrument component", "related_terms": ["Handpan", "Hang", "Tone field", "Gu (bottom port)", "Helmholtz resonance", "Fundamental"], "common_mistakes": ["Striking the ding too hard or off-center, which chokes the note instead of letting the dome ring.", "Assuming the ding is just another note, rather than the tuned central tonic that anchors the whole layout.", "Confusing the top-shell ding with the \"gu\", the sound port in the bottom shell."], "scenario_contexts": ["Playing a melody and using the ding as the home/bass note.", "Miking a handpan close to the ding to capture its deep fundamental.", "Tuning or checking a handpan by testing the ding's fundamental with its octave and fifth partials."]}, "f977c20a-baf3-4ea5-8cf5-875fb5f9a357": {"definition": "The lowest of the three fundamental djembe tones, produced by striking the center of the drumhead with the flat palm and fingers together and letting the hand rebound, releasing a deep, round bass note. In West African drum language it is commonly vocalized \"gun\" (or \"dun\"), and it anchors djembe rhythms alongside the tone and slap.", "plain_english": "The bass is the deep, low sound of a djembe. You hit the middle of the drum with your whole flat hand and let it bounce off. Drummers often sing this stroke as \"gun\".", "purpose_function": "The bass provides the low, grounding pulse of a djembe pattern, marking the main beats and giving the rhythm its foundation beneath the brighter tone and slap.", "practical_application": "A djembe player strikes the head's center for bass downbeats within a rhythm, and teachers use the spoken \"gun dun\" to teach where the bass falls in a pattern.", "category": "Drum stroke", "related_terms": ["Djembe", "Open tone", "Djembe slap (pa)", "Dundun", "Kenken (bell)", "Hand drumming"], "common_mistakes": ["Leaving the hand resting on the head after the bass stroke, damping the note instead of letting it resonate.", "Hitting the bass off-center toward the rim, which thins out the deep low tone.", "Confusing the bass (gun) with the open tone, which is played nearer the edge and sounds higher."], "scenario_contexts": ["Playing a djembe accompaniment part built on steady bass strokes.", "A teacher using the spoken \"gun dun\" to place the bass notes in a rhythm.", "Miking a djembe to capture both the deep bass and the sharp slap."]}, "d8b0fd31-dfee-4b66-a7b2-31b732c71746": {"definition": "The highest and sharpest of the three fundamental djembe tones, produced by striking near the rim with a relaxed, slightly cupped hand so the fingers snap against the head, giving a bright, cracking, high-pitched sound with little sustain. In West African drum language it is commonly vocalized \"pa\" (or \"ta\").", "plain_english": "The slap is the sharp, high crack of a djembe. You hit near the edge with loose fingers so they snap on the skin. Drummers often sing this stroke as \"pa\".", "purpose_function": "The slap adds bright, cutting accents that sit above the bass and tone, giving djembe rhythms their punch, sparkle, and rhythmic detail.", "practical_application": "A djembe player uses slaps for accents and lead phrases, especially when soloing, and teachers use the spoken \"pa ta\" to mark where slaps fall in a pattern.", "category": "Drum stroke", "related_terms": ["Djembe", "Djembe bass (gun)", "Open tone", "Accent", "Rim shot", "Hand drumming"], "common_mistakes": ["Tensing the hand and hitting flat, which produces a dull thud instead of a sharp, ringing slap.", "UNSAFE: Playing hard slaps for long stretches without rest or proper technique, which can bruise or injure the hands and wrists; build up gradually and stop if pain develops.", "Confusing the slap with the open tone; the slap is sharper and higher, played with snapping fingertips near the rim."], "scenario_contexts": ["A lead djembe player using slaps to accent a solo.", "Learning the three djembe voices by contrasting bass, tone, and slap.", "Placing bright slap accents in a rhythm to make it cut through an ensemble."]}, "93cea788-cdd5-4358-a81a-cbb02443df2a": {"definition": "One of the three basic djembe sounds — bass, tone, and slap — the tone is a clear, ringing note produced by striking the edge of the goatskin head with the flat fingers held together and letting them rebound. In the West African oral drum language used to teach djembe, this stroke is vocalized 'go' (or 'do' for the non-dominant hand).", "plain_english": "The clear, ringing note a djembe makes when you hit the edge of the head with flat fingers and let them bounce off. Teachers say the sound 'go' out loud so you can learn the pattern by voice.", "purpose_function": "The tone gives the djembe its clear, pitched middle voice, sitting between the deep bass and the sharp slap so drummers can build layered patterns and melodies from the three sounds.", "practical_application": "A player produces the tone by hitting the rim area with relaxed, closed fingers and lifting off quickly; when miking a djembe, an engineer positions a mic to catch this ringing edge tone as well as the low bass from the center.", "category": "Hand drum stroke", "related_terms": ["Bass stroke", "Slap stroke", "Open tone", "Doum", "Frame drum resonance", "Talking drum"], "common_mistakes": ["Hitting the drum with tense, spread fingers, which muddies the tone and can bruise the hand.", "Striking too far toward the center, which turns the clear tone into a boomy bass sound.", "Leaving the fingers resting on the head after the strike, which damps the ring and kills the tone.", "UNSAFE: Playing hard for long stretches with tense, poor technique can bruise fingers and strain the wrist; warm up and keep strokes relaxed."], "scenario_contexts": ["Playing a West African rhythm where tone and slap alternate to form the melody.", "Learning a new pattern by first singing the 'go / do / pa / ta' syllables.", "Miking a djembe for a live world-music set to capture both edge tone and center bass."]}, "1c8725db-a761-4705-aebb-1ce62d24baea": {"definition": "The deep, low bass sound of a goblet drum (darbuka/doumbek), produced by striking near the center of the head, usually with the dominant hand, and letting the head resonate. It is the drum's fundamental voice, contrasted with the sharp, high 'tek' (or 'tak') played at the rim.", "plain_english": "The deep, booming low note of a darbuka or doumbek drum. You make it by hitting near the middle of the head and letting it ring, the opposite of the sharp 'tek' tap at the edge.", "purpose_function": "The doum marks the strong downbeats of Middle Eastern rhythms, giving the groove its low anchor while the higher tek strokes fill in the offbeats.", "practical_application": "A player strikes the center with the fingers or palm and lifts off to let the low tone ring; in Middle Eastern rhythm notation 'D' marks a doum and 'T' a tek, so a technician reads a pattern as a string of doums and teks.", "category": "Hand drum stroke", "related_terms": ["Tek", "Darbuka", "Finger roll (darbuka)", "Bass stroke", "Goblet drum", "Djembe tone (go)"], "common_mistakes": ["Confusing the doum with the tek; the doum is the low center note, the tek the high rim note.", "Pressing the hand into the head after the strike and choking the low resonance.", "Hitting dead center too hard, which slaps rather than producing a full, round bass."], "scenario_contexts": ["Playing a maqsum or baladi rhythm where doum-tek-tek sets the basic pattern.", "Reading a darbuka chart marked with D and T symbols.", "Miking a darbuka so the center doum stays full without booming."]}, "c57141f1-7fec-4183-9508-bd0012a43b56": {"definition": "The use of felt — strips, pads, or mutes placed against a drumhead — to absorb vibration, shorten sustain, and reduce unwanted overtones or ring. On a drum kit it commonly means a felt strip run under the bass-drum head; the same principle appears in timpani mutes and under piano and mallet dampers.", "plain_english": "Using a soft felt pad or strip that touches the drumhead to soak up vibration, so the drum rings less and sounds tighter. It works like resting your hand on a struck drum to stop it humming.", "purpose_function": "Felt damping controls how long a drum rings and tames boomy or clashing overtones, letting a player or engineer get a focused, controlled sound instead of a long, ringing one.", "practical_application": "A technician weaves a felt strip under the bass-drum batter or resonant head to cut sustain, or lays felt on a drum to tame ring, adjusting how much the felt touches the head to fine-tune the amount of damping.", "category": "Damping technique", "related_terms": ["Muffling", "Dampening", "Overtones", "Sustain", "Bass drum", "Gel damper"], "common_mistakes": ["Adding too much felt and deadening the drum completely, losing tone and projection.", "Assuming felt tunes the drum; it only shortens ring and does not really change the fundamental pitch.", "Letting a felt strip sit unevenly, so it buzzes or mutes the head in only one spot."], "scenario_contexts": ["Weaving a felt strip into a bass drum for a tight, punchy studio kick.", "Taming a ringy tom with a small felt pad before tracking.", "Placing felt on a snare to reduce ring for a close-miked recording."]}, "4bc68f13-8003-45b6-9570-e637f1f5e7b9": {"definition": "A sustained, continuous sound on the darbuka (goblet drum) produced by striking the head with the fingers in rapid succession — often rolling the fingers of one or both hands across the edge — so the individual strokes blur into a smooth roll or buzz. It ornaments a rhythm and sustains sound between the louder doum and tek accents.", "plain_english": "A fast flutter of the fingers on a darbuka that runs the taps together into one smooth, rolling sound. It is like drumming your fingers quickly on a table so the taps blur into a buzz.", "purpose_function": "The finger roll lets a goblet-drum player sustain sound and add decoration on an instrument whose single strokes die away fast, filling gaps and building tension between the main beats.", "practical_application": "A player rolls the fingers of one or both hands near the rim to make a continuous ripple, using it for fills, endings, and ornamented passages in Middle Eastern solos.", "category": "Hand drum technique", "related_terms": ["Doum", "Tek", "Darbuka", "Roll", "Buzz roll", "Ornamentation"], "common_mistakes": ["Tensing the hand, which makes the roll uneven and stops it sounding smooth.", "Rolling too far toward the center, where the head is looser and the roll loses clarity.", "Playing the roll so loud it covers the main doum and tek accents instead of supporting them."], "scenario_contexts": ["Adding a finger roll as a fill at the end of a darbuka phrase.", "Ornamenting a slow section of a Middle Eastern solo with rolling fingers.", "Building tension with a rising finger roll before the rhythm drops back in."]}, "b79aba78-ff0c-4b25-819c-31fd6503e7db": {"definition": "The tonal and acoustic response of a frame drum — a shallow, single-headed drum whose diameter is much greater than its depth (e.g., tar, bendir, riq, bodhrán, daf). With little enclosed air volume, its sound is dominated by the membrane's vibrational modes and by hand position: striking near the center gives lower, fuller tones and striking near the rim gives higher, sharper ones.", "plain_english": "How a frame drum rings and colors its sound. Because these drums are wide but very shallow, the tightness of the skin and where you hit it matter most. Hit the middle for a low note, hit near the edge for a higher, snappier one.", "purpose_function": "A frame drum's resonance is what gives it a range of pitches and tone colors from a single head, letting one player draw out bass notes, edge tones, and ringing sustain to shape a rhythm.", "practical_application": "A player varies where and how the head is struck, and may press a finger on the skin to raise pitch or damp it; when recording, an engineer places the mic to balance the low center resonance against the brighter rim tones.", "category": "Percussion acoustics", "related_terms": ["Frame drum", "Membrane", "Head tension", "Djembe tone (go)", "Damping", "Overtones"], "common_mistakes": ["Thinking a frame drum has one fixed sound; hand position and pressure change its pitch and tone a lot.", "Over-tightening the head chasing volume, which can raise pitch too far and stress the skin or frame.", "Miking only the center and missing the bright rim tones that give the drum its character."], "scenario_contexts": ["Playing a bodhrán where moving the back hand on the skin bends the drum's pitch.", "Recording a tar and choosing mic placement to catch both low and edge tones.", "Tuning a frame drum head so its resonance suits the key of a song."]}, "62df420f-188e-4786-8b70-4e45cfe85f58": {"definition": "The pitch-bending technique of the West African hourglass 'talking drum' (Yoruba gángán, of the dùndún family), in which the player presses the drum under the arm to squeeze the leather tension cords that run between its two heads. Squeezing tightens the heads and raises the pitch, so the drum can 'talk' by sliding between tones to imitate the rise and fall of speech.", "plain_english": "On a talking drum, you tuck it under your arm and squeeze the cords along its side to change the pitch while you play. Squeeze harder and the note slides up, like a voice going higher, which is how the drum seems to 'talk.'", "purpose_function": "The squeeze is what makes the talking drum melodic and speech-like; by changing pitch on the fly it lets the drum imitate the tones of West African languages and carry messages or melodies.", "practical_application": "A player holds the drum under the arm and varies arm pressure while striking the head with a curved beater, gliding the pitch up and down; a sound engineer expects a wide, sliding pitch range and mics for it.", "category": "Hand drum technique", "related_terms": ["Talking drum", "Dundun", "Pitch bend", "Membrane", "Head tension", "Djembe tone (go)"], "common_mistakes": ["Thinking the drum is tuned to fixed notes; its pitch is changed live by arm pressure.", "Squeezing so hard the heads or cords are over-stressed, risking a torn head or snapped cord.", "Striking with a flat hand instead of the curved stick, which weakens the clear, pitched tone."], "scenario_contexts": ["Playing a talking-drum phrase that mimics a spoken proverb in a Yoruba language.", "Sliding the pitch up under a lead line in an Afrobeat or highlife groove.", "Miking a talking drum for stage, allowing for its sliding pitch and wide dynamics."]}, "5d4d0e72-c7df-46a0-b885-efbacba2f4df": {"definition": "A continuous, driving shaker pattern played on the ganzá — a Brazilian tubular shaker (metal or woven) filled with beads or shot — using rapid back-and-forth arm motion so both the forward and return strokes sound. In samba and related styles it lays down a steady stream of sixteenth-note subdivisions, often with a slight swing, that propels the groove.", "plain_english": "A steady shaking pattern on the ganzá, a tube-shaped shaker used in Brazilian music. You shake it forward and back so it makes sound both ways, giving a fast, non-stop rustle that drives the beat.", "purpose_function": "The pattern fills in the fast subdivisions of a samba groove, acting like a hi-hat by keeping continuous time and adding forward motion under the louder drums.", "practical_application": "A percussionist keeps the wrist and forearm moving evenly so the shaker sounds on each stroke, adding accents to match the rhythm; on stage the ganzá is usually close to a mic because it is quieter than the surdos and snares.", "category": "Shaker technique", "related_terms": ["Ganzá", "Shaker", "Samba", "Caixa", "Surdo", "Subdivision"], "common_mistakes": ["Shaking only on the forward stroke, which loses the steady, even stream the pattern needs.", "Letting the tempo drift, since the ganzá, not the loud drums, is holding the fast subdivisions.", "Overfilling the tube or shaking unevenly, so the accents blur and the groove loses its swing."], "scenario_contexts": ["Playing continuous sixteenths on a ganzá in a samba bateria.", "Using the ganzá like a hi-hat to keep time in a Brazilian percussion section.", "Recording a ganzá close to the mic so its quiet, fast pattern sits in the mix."]}, "f013b9af-e0de-4496-9506-e00a202ea1de": {"definition": "A bol (spoken stroke-name) of the tabla, and specifically the open, resonant bass stroke played on the bayan, the larger left-hand drum. It is produced by striking the head with the fingers while the heel of the hand rests on the skin and can slide to bend the pitch, leaving the stroke undamped so it rings. It contrasts with the closed, damped bass stroke 'ke/kat.'", "plain_english": "A named tabla stroke that makes the deep, ringing bass note on the big left-hand drum. You strike with your fingers and let it sing, and by sliding the heel of your hand you can bend the pitch up or down.", "purpose_function": "Ge provides the tabla's resonant low voice and its signature sliding bass, giving weight and pitch movement to rhythmic patterns and letting the drummer shade the low tone within a phrase.", "practical_application": "A player sounds ge by striking the bayan with relaxed fingers while pressing and gliding the wrist to bend the note; students learn it by name as part of reciting bols before playing them.", "category": "Drum stroke", "related_terms": ["Bol", "Bayan", "Tabla", "Dha", "Na", "Pitch bend"], "common_mistakes": ["Damping the head right after the strike, which turns the ringing 'ge' into a closed, dead 'ke.'", "Keeping the wrist stiff, losing the sliding pitch bend that gives ge its voice.", "Treating 'ge' as just a sound; it names a specific stroke and hand action, not only a syllable."], "scenario_contexts": ["Reciting a tabla composition's bols, where 'dha' combines ge with a treble stroke.", "Bending the bayan's pitch on a ge stroke to follow a melody.", "Learning left-hand technique by isolating the ge stroke."]}, "5f25517b-36c8-452e-8b5e-9dd16412bc88": {"definition": "The relatively long ring, or decay time, of a glockenspiel's tone. Because its bars are hard steel — a material with very low internal damping — a struck bar keeps vibrating and sounds a bright, bell-like note that rings on far longer than the short decay of a wooden-barred xylophone or marimba. Orchestral glockenspiels usually have no resonators, so the sustain comes from the bars themselves.", "plain_english": "How long a glockenspiel keeps ringing after you strike a bar. Its metal bars hold their vibration for a long time, so each note has a bright, bell-like ring, unlike a wooden xylophone that stops almost at once.", "purpose_function": "The long metallic sustain gives the glockenspiel its shimmering, bell-like character and lets its high notes cut through and hang over an ensemble.", "practical_application": "A player controls the ring with mallet choice and, when needed, by damping bars with the hand, since most glockenspiels have no pedal; when recording, an engineer captures the bright attack while managing the long, ringing tail.", "category": "Mallet percussion", "related_terms": ["Glockenspiel", "Xylophone", "Vibraphone", "Sustain", "Decay", "Mallet"], "common_mistakes": ["Expecting a glockenspiel to stop like a xylophone; its steel bars ring on and can blur fast passages.", "Using very hard mallets carelessly, which can dent bars and give a harsh, clangy sustain.", "Forgetting the ring builds up in fast runs, muddying the line because the notes overlap."], "scenario_contexts": ["Playing a slow melody where each glockenspiel note rings into the next.", "Hand-damping bars to stop the ring in a passage that needs clarity.", "Miking a glockenspiel to catch its bright attack without an overly long, harsh tail."]}, "a31941e0-3a9e-4081-a32c-df843e0b7bbc": {"definition": "A dynamic effect in which a tam-tam or gong is rolled with two mallets, building smoothly from near silence to a loud peak and often back down. The player begins with a soft priming stroke so the metal is already vibrating, then increases stroke frequency and force so successive tones merge into one continuously growing sound.", "plain_english": "A gong sound that grows slowly from very soft to very loud. The player taps the gong so it is already humming, then hits it faster and harder so the sound swells like a rising wave.", "purpose_function": "It lets a single indefinite-pitch instrument add a long, dramatic rise or fall in loudness, shaping tension and release without a sharp initial attack.", "practical_application": "A percussionist primes the tam-tam with light strokes, then rolls with soft mallets to grow the swell on cue; live engineers ride the fader and anticipate the peak because a full gong swell is extremely loud.", "category": "Playing Technique", "related_terms": ["Tam-tam", "Roll", "Crescendo", "Soft mallet", "Suspended cymbal roll", "Mallet"], "common_mistakes": ["Striking too hard or in one spot, which chokes the bloom instead of letting the tones merge", "Starting the roll too fast so individual strikes are heard instead of a smooth swell", "UNSAFE: Standing close to a large tam-tam at full swell without hearing protection; peak levels can reach hearing-damaging SPLs"], "scenario_contexts": ["Orchestral or film-score climax where a slow gong crescendo underlines a dramatic moment", "Live sound reinforcement where the engineer must capture and control a wide dynamic swell", "Studio recording of a tam-tam swell for a cinematic riser or transition effect"]}, "8f33ea2f-1b50-4881-92ba-5ad2cf84465f": {"definition": "The buzzing timbre produced by a mirliton — a thin membrane stretched over a small hole in a gourd resonator on instruments such as African xylophones (balafon) and gourd-resonated lamellophones (mbira). When a bar or lamella sounds, the membrane vibrates sympathetically and adds a characteristic rasp or buzz to the tone.", "plain_english": "A raspy buzz added to a note by a thin skin stretched over a hole in a gourd. When the instrument plays, the skin shivers and gives the sound a fuzzy edge, a bit like a kazoo.", "purpose_function": "The mirliton enriches an otherwise plain wooden or metallic tone with extra buzzing overtones, giving the instrument its traditional voice and helping it carry and sustain.", "practical_application": "A player or maker tunes the buzz by choosing the membrane material and hole size; when recording these instruments, engineers place mics to capture the buzz without letting it turn harsh.", "category": "Timbre Effect", "related_terms": ["Mirliton", "Balafon", "Mbira", "Gourd resonator", "Marimba", "Sympathetic resonance"], "common_mistakes": ["Assuming the buzz is a defect to be silenced, when it is a deliberate, traditional feature of the instrument", "Confusing a mirliton buzz with snare buzz or a rattling part that actually needs repair", "Over-tightening or over-damping the membrane so the characteristic buzz is lost"], "scenario_contexts": ["Recording a West African balafon and deciding how much membrane buzz to keep", "Building or restoring a gourd-resonated marimba or mbira and fitting new mirliton membranes", "Live miking of a traditional percussion ensemble where the buzz is part of the intended sound"]}, "2f59170c-c414-4c05-8d74-c6a69f744e1c": {"definition": "The low bass tone of a handpan (Hang) associated with the Gu — the circular opening in the bottom shell. The enclosed air cavity behaves as a Helmholtz resonator, so striking near or modulating the Gu port produces a deep bass note below the tuned tone fields on the top shell.", "plain_english": "The deep low note of a handpan that comes from the hole in the bottom. The air inside the shell acts like the air in a bottle you blow across, so the player can shape the bass by covering the hole with a hand.", "purpose_function": "The Gu adds a low foundation and resonant body to the handpan's tuned notes, so one player can sound both bass and melody at the same time.", "practical_application": "Players strike near the bottom port or pulse a hand over it (like an udu) to bring out or bend the bass; recording engineers often add a mic under the Gu to capture this low end.", "category": "Instrument Feature", "related_terms": ["Hang drum", "Handpan", "Helmholtz resonator", "Ding", "Tone field", "Steelpan"], "common_mistakes": ["Thinking the Gu is just a sound hole with no pitch, when it forms a tuned Helmholtz bass resonance", "Blocking the bottom port while holding the instrument, which muffles the bass and shortens sustain", "Striking the thin bottom shell hard with mallets, which can dent or detune the instrument"], "scenario_contexts": ["A solo handpan player using Gu bass pulses to underpin a melody", "Close-miking a handpan top and bottom to capture both the tone field and the Gu bass", "Explaining to a student why cupping the bottom port changes the low-end resonance"]}, "59110bae-4738-4ffd-92cd-b0f999571a4c": {"definition": "The primary playing technique of the guiro: dragging a stick or scraper (pua) across the parallel notches cut into the hollow gourd (or wood/fiberglass) body, producing a rasping, ratchet-like sound. Long strokes give sustained rasps and short strokes give clipped articulations, and the notches may also be tapped for shorter accents.", "plain_english": "The main way to play a guiro: sliding a stick across the ridges cut into a hollow gourd to make a raspy, scratchy sound. Long slides make long rasps and short slides make short clicks, a bit like running a stick along a fence.", "purpose_function": "The scrape gives Latin and orchestral music a dry, rhythmic rasp that marks the beat and adds texture without a definite pitch.", "practical_application": "A percussionist holds the guiro loosely and works long and short scrapes to lock into a clave or dance pattern; engineers mic it close and watch for harsh high-frequency spikes.", "category": "Playing Technique", "related_terms": ["Guiro", "Pua (scraper)", "Idiophone", "Clave", "Cabasa", "Ratchet"], "common_mistakes": ["Scraping every stroke at the same length and force, losing the long/short contrast that shapes the pattern", "Muting the sound holes with the holding hand and choking the instrument's resonance", "Treating the guiro as struck-only and missing the sustained rasp that defines it"], "scenario_contexts": ["Playing a guiro scrape pattern in a salsa or cumbia arrangement", "Orchestral or film percussion needing a Latin-flavored scraping texture", "Overdubbing guiro in the studio and matching the scrape rhythm to the clave"]}, "4c40a7fc-c160-41b6-a983-fc271a45a1a2": {"definition": "The primary playing technique of the güiro: dragging a stick or scraper (pua) across the parallel notches cut into the hollow gourd (or wood/fiberglass) body, producing a rasping, ratchet-like sound. Long strokes give sustained rasps and short strokes give clipped articulations, and the notches may also be tapped for shorter accents.", "plain_english": "The main way to play a güiro: sliding a stick across the ridges cut into a hollow gourd to make a raspy, scratchy sound. Long slides make long rasps and short slides make short clicks, a bit like running a stick along a fence.", "purpose_function": "The scrape gives Latin and orchestral music a dry, rhythmic rasp that marks the beat and adds texture without a definite pitch.", "practical_application": "A percussionist holds the güiro loosely and works long and short scrapes to lock into a clave or dance pattern; engineers mic it close and watch for harsh high-frequency spikes.", "category": "Playing Technique", "related_terms": ["Güiro", "Pua (scraper)", "Idiophone", "Clave", "Cabasa", "Ratchet"], "common_mistakes": ["Scraping every stroke at the same length and force, losing the long/short contrast that shapes the pattern", "Muting the sound holes with the holding hand and choking the instrument's resonance", "Treating the güiro as struck-only and missing the sustained rasp that defines it"], "scenario_contexts": ["Playing a güiro scrape pattern in a salsa or cumbia arrangement", "Orchestral or film percussion needing a Latin-flavored scraping texture", "Overdubbing güiro in the studio and matching the scrape rhythm to the clave"]}, "1418b038-3eb8-49e1-a6c7-264283ffe8a5": {"definition": "Muting a drum or other percussion instrument by resting a hand or palm on the vibrating surface to shorten its sustain and tame overtones. On hand drums it produces the muffled or 'mute' stroke; on the drum kit or timpani a hand laid on the head damps the ring and can raise the apparent pitch.", "plain_english": "Quieting a drum by laying a hand or palm on the head so it stops ringing. It works like pressing your hand on a struck bell to cut the sound short and make it drier.", "purpose_function": "Hand-damping controls how long a note rings, so the player can make tight, dry sounds, stop unwanted ring, and add rhythmic shape between open hits.", "practical_application": "A conga or drum-kit player rests fingers or palm on the head to mute individual notes for a tighter groove; engineers rely on this when they want players to control sustain live rather than adding tape.", "category": "Playing Technique", "related_terms": ["Muffling", "Open tone", "Mute stroke", "Sustain", "Palm mute", "Timpani"], "common_mistakes": ["Confusing hand-damping, which is played live and variable, with permanent muffling using tape, gel, or cloth", "Pressing too hard and choking the note completely instead of shaping its decay", "Forgetting that a hand on the head raises apparent pitch, which can throw off tuned drums"], "scenario_contexts": ["A conguero muting strokes to create the muffled tone in a tumbao pattern", "A kit drummer palm-muting the snare or toms for a dry, controlled sound", "A timpanist damping heads by hand to stop the ring between notes"]}, "6ff1aae0-94aa-454c-b068-20a704c232b1": {"definition": "A handpan — a convex, gong-like steel percussion instrument played with the hands, first made in 2000 by Felix Rohner and Sabina Schärer of PANArt in Bern, Switzerland. It has a central bass note (Ding) surrounded by a ring of tuned tone fields on the top shell and a bottom port (Gu); 'Hang' is PANArt's trademark, while 'handpan' is the generic term for the wider family.", "plain_english": "A steel instrument shaped like two joined woks that you play with your hands. It has a low center note ringed by tuned dents and gives soft, bell-like tones. Hang drum is a common nickname, but the makers say it is not really a drum.", "purpose_function": "It puts melody, harmony, and bass under one player's hands with a warm, sustaining tone, so a single musician can play complete, meditative pieces.", "practical_application": "Players rest it on their lap and strike the tuned fields with fingers and thumbs; engineers close-mic the top and often the Gu and use gentle compression to even out its wide dynamics.", "category": "Instrument", "related_terms": ["Handpan", "Gu bass (handpan)", "Ding", "Steelpan", "Tone field", "Idiophone"], "common_mistakes": ["Calling every handpan a 'Hang'; 'Hang' is one maker's (PANArt) trademarked instrument, while 'handpan' is the general term", "Playing it with drumsticks or hard mallets, which dents and detunes the soft steel", "Storing it in a hot car or damp bag, which can rust or detune the instrument"], "scenario_contexts": ["Recording a solo handpan piece for ambient or meditation music", "Miking a handpan for a live acoustic set", "Advising a student on the difference between a PANArt Hang and a generic handpan"]}, "1530bda2-3a00-4f6e-8e6f-8263dc5ab6d8": {"definition": "A mallet with a hard head — typically wood, plastic/acrylic, phenolic, or hard rubber — that emphasizes the attack and upper partials, producing a bright, sharp, articulate tone. Hard mallets are used on high, bright instruments such as the xylophone, glockenspiel, and bells, and wherever clear articulation is wanted on marimba or vibraphone.", "plain_english": "A beater with a hard tip that makes a bright, clicky sound. Because the tip does not give, it brings out the attack and the high overtones, like tapping glass instead of a pillow.", "purpose_function": "Hard mallets bring out clarity and cut, so fast, high, or exposed passages speak clearly and project through an ensemble.", "practical_application": "A percussionist matches mallet hardness to the instrument and passage, choosing hard mallets on xylophone or glockenspiel for bright articulation and softer ones when a warmer, rounder tone is needed.", "category": "Mallet / Beater", "related_terms": ["Soft mallet", "Yarn mallet", "Xylophone", "Glockenspiel", "Marimba", "Vibraphone"], "common_mistakes": ["Using hard mallets too forcefully on glockenspiel or bells, which can chip or damage the bars and produce a harsh clang", "Assuming one mallet suits every instrument instead of matching hardness to the instrument and passage", "Confusing 'hard' with 'loud'; mallet hardness changes tone color and attack, not just volume"], "scenario_contexts": ["Choosing hard mallets for a bright xylophone solo that must cut through the band", "Selecting glockenspiel mallets in the studio to control brightness and attack", "A student learning why the same marimba sounds different with hard versus soft mallets"]}, "4330cbcb-8994-48c4-b523-5d4755349d09": {"definition": "A conga (and bongo) hand technique in which the hand rocks back and forth between the heel (the base of the palm) and the toe (the fingertips), producing a soft, steady stream of low, muffled sounds. It fills the spaces between the louder open and slap tones to maintain a continuous underlying pulse.", "plain_english": "A hand-drum move where you rock your hand like a seesaw, tapping first the base of your palm, then your fingertips. It makes a quiet, steady pulse that fills the gaps between the louder hits and keeps time under the beat.", "purpose_function": "The heel-toe motion keeps a constant flow of soft strokes so the player holds a steady groove and time while saving the loud open tones and slaps for accents.", "practical_application": "A conguero uses the heel-toe rock to fill the subdivisions of a tumbao or marcha; it is felt more than heard, giving the pattern its drive without adding loud notes.", "category": "Playing Technique", "related_terms": ["Conga", "Open tone", "Slap", "Bass tone", "Tumbao", "Bongo"], "common_mistakes": ["Playing the heel and toe too loudly so they compete with the accented open tones instead of sitting underneath them", "Stiffening the wrist instead of letting the hand rock freely, which breaks the smooth flow", "Treating the heel-toe as decoration rather than the timekeeping backbone of the pattern"], "scenario_contexts": ["Holding a tumbao groove on congas in a salsa band", "Teaching a beginner to keep time between open tones and slaps", "Recording congas where the soft heel-toe pulse must be captured without excess low-end rumble"]}, "b768d0fc-ab56-4f36-8c9e-3fa4c26f602e": {"definition": "A bass drum pedal technique in which a drummer sounds two strokes with one foot in a single rocking motion: the first driven with the heel down (using the heel or ball of the foot), the second by the toe as the heel lifts and the foot rocks forward. It lets a single pedal produce fast double strokes without a double pedal.", "plain_english": "A way to hit the bass drum twice with one foot in one smooth rock. You play the first note with your heel down. Then you tip forward onto your toes for the second note. It gives you fast doubles from a single pedal.", "purpose_function": "Enables rapid double strokes and steady fast patterns from one foot and one pedal, improving speed and endurance without adding a second bass drum or a double pedal.", "practical_application": "Drummers use it for fast bass-drum figures and rolls in rock, metal, and fusion; when miked, each of the two beats should read as an even, separately audible hit.", "category": "Playing technique", "related_terms": ["Double bass drumming", "Bass drum pedal", "Beater", "Slide technique", "Kick click", "Kick thump"], "common_mistakes": ["Letting the two strokes come out uneven, so the second (toe) note is weak or lost", "Tensing the leg and ankle instead of relaxing to let the foot rock, which kills speed and causes fatigue", "Burying the beater into the head on both strokes, choking the tone instead of letting it rebound"], "scenario_contexts": ["Playing fast double-kick sixteenth notes with only a single pedal", "Adding quick bass drum doubles under a groove", "An engineer setting a gate so both closely spaced beats trigger cleanly"]}, "e637e2c5-25d7-43f4-b7cd-128301a5574b": {"definition": "A microphone placed inside the cajón, usually reaching in through the rear sound hole, to capture the box's low-frequency body and the rattle of the internal snares. It is commonly paired with an external front mic that captures the slap and attack of the front playing plate (tapa).", "plain_english": "A mic put inside the cajon box, usually through the round hole in the back. It picks up the deep bass boom and the buzzy snare rattle from inside. Players often add a second mic in front for the sharp slap sound.", "purpose_function": "Captures the deep bass and internal snare buzz that a front mic misses, giving a fuller and more controllable low end for live reinforcement or recording.", "practical_application": "A tech clips or tapes a small mic (or uses a cajón with a built-in mic) inside the box, checks polarity against any front mic, and blends the two so bass and slap sit together.", "category": "Microphone technique", "related_terms": ["Cajón", "Kick drum microphone", "Boundary microphone", "Polarity inversion", "Close miking", "Phase cancellation"], "common_mistakes": ["Combining the inside mic with a front mic without checking polarity, so the low end thins out from phase cancellation", "Placing the mic where the player's hand or the internal snares slap it, causing thumps and rattles", "Boosting inside-mic low end so much that the sound becomes boomy and undefined"], "scenario_contexts": ["Miking a cajón for a singer-songwriter set in a small club", "Recording an acoustic session and blending inside and front mics", "Using a cajón with a built-in mic plugged into a DI or mixer"]}, "16ffd74f-ad1c-453f-8657-f4ee044351a4": {"definition": "In darbuka (goblet drum) technique, the 'ka' is a sharp, high-pitched stroke played at the edge of the head with the secondary (usually non-dominant) hand. It produces the same crisp rim tone as a 'tek' but with the other hand, so alternating tek and ka yields fast, even patterns.", "plain_english": "A short, high tap sound on the darbuka, played at the rim with your weaker hand. It matches the sharp tap your strong hand makes, called a tek. Swapping between the two hands lets you play fast, even rolls.", "purpose_function": "Gives the drummer an opposite-hand rim stroke so tek-ka alternation can produce quick, smooth runs and fills that one hand alone could not play evenly.", "practical_application": "A player uses ka as the off-hand fill-in between dum and tek strokes when reading or teaching Middle Eastern rhythms such as maqsum or baladi.", "category": "Drum stroke", "related_terms": ["Dum", "Tek", "Darbuka", "Doumbek", "Maqsum", "Finger technique"], "common_mistakes": ["Striking too far toward the center, so the ka sounds dull instead of sharp and high", "Letting the weaker-hand ka come out quieter than the tek, making patterns sound uneven", "Confusing ka with dum; ka is a thin rim tone, not the deep center bass"], "scenario_contexts": ["Learning the maqsum rhythm where tek and ka alternate", "A percussionist filling fast passages by trading tek and ka hands", "Notating a darbuka part that marks D, T, and K strokes"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"6fb33b57-7b46-4f4d-81bd-2354cd99a81e": {"definition": "The buzzing or rattling timbre added to the sustained tone of a plucked lamellophone tine. On traditional African instruments (mbira, likembe) it is produced deliberately with attached shells, bottle caps, beads, or a mirliton sleeve and is musically prized; on modern melodic kalimbas an unintended buzz can also arise from a loose tine, debris, or a tine vibrating against its bridge.", "plain_english": "A rattly, buzzing sound layered onto a kalimba or mbira note. On many African instruments this buzz is added on purpose with beads, shells, or bottle caps, and it is wanted. On a modern kalimba, a buzz can also be a fault from a loose or dirty key.", "purpose_function": "Adds a shimmering, sustaining buzz that thickens each note and helps it carry; traditionally it also holds cultural and ritual meaning, while an unwanted buzz signals a setup problem to fix.", "practical_application": "A player adds or removes buzzers (rings, beads, shells) to taste, while a tech traces an unwanted buzz by reseating the tine, cleaning under it, or adjusting where it clamps.", "category": "Sound characteristic", "related_terms": ["Kalimba", "Mbira", "Tine", "Mirliton", "Sympathetic resonance", "Sustain"], "common_mistakes": ["Assuming every buzz is a fault; on the mbira and many kalimbas the buzz is added deliberately and desired", "Bending or forcing a tine to silence a buzz, which pushes the note out of tune", "Ignoring debris or a loose tine base, so an unwanted rattle keeps returning"], "scenario_contexts": ["Adding a buzzer ring to a tine for more sustain and shimmer", "A traditional mbira with bottle caps producing its characteristic buzz", "Troubleshooting a new kalimba that rattles on one note"]}, "38c83af4-acd8-44e6-b1be-31505b1b233c": {"definition": "The sharp, high-frequency attack of a bass (kick) drum produced by the beater striking the batter head, dominated by energy roughly in the 2-5 kHz range. Engineers emphasize it so the kick's beater 'click' cuts through a dense mix, especially in rock and metal.", "plain_english": "The short, clicky tick you hear when the kick drum beater hits the head. It lives in the higher frequencies, around a few kHz. Engineers boost it so the kick stays clear even in a loud, busy mix.", "purpose_function": "Gives the kick definition and attack so each hit is clearly heard through guitars, bass, and cymbals, and so reinforced kicks translate on small speakers.", "practical_application": "A mixer boosts around 2-5 kHz, uses a harder or plastic beater, adds a patch to the head, or blends a sample to bring out the click when the kick is getting lost.", "category": "Frequency character", "related_terms": ["Kick thump", "Beater", "Attack transient", "EQ", "Kick drum microphone", "Transient"], "common_mistakes": ["Boosting click so hard the kick sounds thin and clicky with no weight behind it", "Confusing click (beater attack, high frequencies) with thump (body, low frequencies)", "Chasing click with EQ when the real fix is a harder beater or a patch on the head"], "scenario_contexts": ["Cutting a metal kick through a wall of distorted guitars", "Adding click so the kick shows up on phone and laptop speakers", "Blending a click-heavy sample under a soft acoustic kick"]}, "256dd2d4-7f6a-43e4-9ce8-30afd04b2709": {"definition": "The deep, low-frequency body and weight of a bass (kick) drum, centered roughly in the 50-100 Hz region around its fundamental. It provides the felt 'thump' and power of the kick, as distinct from the higher-frequency beater 'click.'", "plain_english": "The deep, punchy low end of the kick drum that you feel in your chest. It sits down around 50 to 100 Hz. This is the thump part, separate from the higher clicky attack.", "purpose_function": "Delivers the low-end power and rhythmic foundation of a track, giving the kick its size and weight in a mix or through a PA.", "practical_application": "An engineer shapes thump with EQ around 50-100 Hz and by controlling resonance and decay, balancing it against the bass guitar so the low end stays tight, not muddy.", "category": "Frequency character", "related_terms": ["Kick click", "Sub bass", "Fundamental frequency", "EQ", "Muffling", "Bass management"], "common_mistakes": ["Piling on low end until the kick booms and masks the bass guitar", "Confusing thump (low-frequency body) with click (high-frequency attack)", "Boosting thump on speakers that cannot reproduce it, so the change is inaudible and only wastes headroom"], "scenario_contexts": ["Tuning kick low end so it locks with the bass guitar", "Dialing chest-thump for a live PA with subwoofers", "Taming an overly boomy kick in a small room"]}, "9446efa5-3543-41b9-a06f-5374f1edc2ea": {"definition": "The relative firmness of a percussion mallet's head, ranging from soft yarn or cord through medium rubber to hard plastic, acrylic, or brass, which sets how it excites a bar or drum. Harder heads have shorter contact time and excite more high partials for a brighter, more articulate attack; softer heads emphasize the fundamental for a rounder, darker tone.", "plain_english": "How hard or soft the head of a percussion mallet is, from soft yarn to hard plastic. A hard mallet gives a bright, sharp sound with lots of attack. A soft mallet gives a warm, round tone that brings out the low notes.", "purpose_function": "Lets a player match tone, attack, and volume to the instrument, register, and music, since the same bar can sound bright or mellow depending on the mallet.", "practical_application": "A percussionist picks harder mallets for xylophone, the high register, or bright loud passages, and softer mallets for marimba, the low bars, or warm blended playing.", "category": "Mallet property", "related_terms": ["Marimba", "Xylophone", "Vibraphone", "Marimba resonators", "Attack transient", "Timbre"], "common_mistakes": ["Using very hard mallets on the low marimba bars, which sounds harsh and can crack the bars", "Assuming harder always means louder; past a point it just adds click and noise, not musical volume", "Ignoring how hardness must change across the range, so low bars sound weak or high bars sound harsh"], "scenario_contexts": ["Choosing yarn mallets for a warm marimba solo", "Switching to hard plastic mallets for a bright, cutting xylophone part", "Selecting graded mallet sets so each register speaks evenly"]}, "a4b06ab0-2855-4767-b08b-934839fbb0f2": {"definition": "The tuned tubes (traditionally gourds or wood, now usually aluminum) suspended below each marimba bar, each acting as a closed pipe whose air column is tuned to the bar's fundamental frequency (about a quarter wavelength). When the bar vibrates, the matched resonator reinforces the fundamental, making the note louder and fuller while shortening its decay.", "plain_english": "The tubes hanging under each marimba bar. Each tube is tuned so the air inside rings at the same pitch as the bar above it. This makes each note louder and richer, though it also fades a bit faster.", "purpose_function": "Amplify and enrich each bar's fundamental so the marimba projects with a full, warm tone rather than the thin, quiet sound of an unmounted bar.", "practical_application": "A tech keeps resonators aligned and dent-free and may adjust tuning stops or end caps to compensate for temperature and humidity so notes stay at full resonance.", "category": "Instrument component", "related_terms": ["Marimba", "Xylophone", "Vibraphone", "Fundamental frequency", "Helmholtz resonance", "Mallet hardness"], "common_mistakes": ["Thinking resonators change a note's pitch; they reinforce the bar's fundamental, they do not tune the bar", "Denting, clogging, or misaligning tubes, which weakens resonance and volume", "Ignoring temperature and humidity, so bars and resonators drift out of match and lose fullness"], "scenario_contexts": ["Setting up a marimba and aligning bars over their resonators", "Adjusting resonator tuning stops for a hot, humid venue", "Explaining why an unmounted bar sounds thin without its tube"]}, "962c83cd-a684-497e-9f8a-1b64130be867": {"definition": "The basic, steady bongó pattern of Cuban son and salsa, whose name means 'hammer.' It is a continuous eighth-note ostinato played with fingers and thumbs across the two bongo drums (macho and hembra), anchoring the groove while the player also adds improvised fills.", "plain_english": "The main hammer pattern a bongo player keeps going in salsa and Cuban son. It is a steady stream of even notes played across the two little drums. It holds the groove while the player throws in extra fills on top.", "purpose_function": "Provides a constant timekeeping pulse and rhythmic anchor for the ensemble, tying the percussion section to the clave and the rest of the band.", "practical_application": "A bongocero plays martillo through the verse/son sections, breaks from it for fills, and typically switches to the bell (cencerro) in the montuno.", "category": "Rhythm pattern", "related_terms": ["Bongo", "Clave", "Montuno", "Cencerro", "Tumbao", "Son"], "common_mistakes": ["Rushing or letting the eighth notes get uneven, so the martillo loses its steady drive", "Playing it too loud or too busy so it fights the clave and the rest of the rhythm section", "Never leaving the pattern; martillo should breathe with occasional fills, not run mechanically nonstop"], "scenario_contexts": ["Holding the groove during the verses of a salsa tune", "A bongo player switching from martillo to the bell at the montuno", "Teaching a beginner the basic bongo timekeeping pattern"]}, "8864f8f0-2f55-4414-8bec-e6883e0b40bf": {"definition": "The plucking of a single tuned metal tongue (lamella or key) of an mbira, an African lamellophone or 'thumb piano', to sound a note; the player depresses and releases the free end of the tine with the thumb or forefinger, setting it vibrating to produce a soft, bell-like pitched tone that decays gradually, often colored by buzzing rattles attached to the instrument.", "plain_english": "It is plucking one metal key of an mbira, an African thumb piano, to play a note. You press the free end of the key with your thumb and let it spring back. The key then rings out like a tiny bell.", "purpose_function": "It is how sound is made on an mbira, since each pluck sets one tuned tongue vibrating, so the length and stiffness of each key fix its pitch and how long the note rings.", "practical_application": "When recording an mbira, engineers close-mic it to capture the quiet pluck and its bell-like decay, add enough gain because each note is low in level, and expect buzzy overtones from the instrument's rattlers.", "category": "Lamellophone technique", "related_terms": ["Kalimba", "Lamellophone", "Thumb piano", "Pluck transient", "Sustain"], "common_mistakes": ["Treating the mbira as a struck idiophone when its notes are plucked, not hit", "Setting record gain too low, so the soft pluck and its bell-like tail get lost in noise", "Trying to filter out the buzzing rattles, which are part of the instrument's intended sound"], "scenario_contexts": ["Close-miking a solo mbira for a world-music recording", "Blending an mbira into a pop arrangement so its quiet plucks sit forward", "Sampling individual mbira notes for a virtual instrument"]}, "603acfa6-1488-43fe-83d9-d76ff3c1fbb1": {"definition": "A percussion beater of medium hardness whose head — typically yarn or cord wound over a rubber or synthetic core, or a medium-density rubber or felt head — falls between soft and hard mallets, giving a balanced blend of fundamental tone and attack across an instrument's range.", "plain_english": "It is a percussion beater that is neither soft nor hard, but in between. It gives a middle-of-the-road sound, with a good deal of note tone and some attack. That makes it a safe choice for many parts.", "purpose_function": "It offers an all-purpose balance of warmth and clarity, so it serves as a default when a part needs neither the deep tone of a soft mallet nor the bright attack of a hard one.", "practical_application": "A percussionist reaches for medium mallets as a starting point on marimba, vibraphone or timpani, then switches softer or harder if the passage needs more warmth or more articulation.", "category": "Percussion mallet", "related_terms": ["Soft mallet", "Hard mallet", "Yarn mallet", "Timpani mallet", "Marimba"], "common_mistakes": ["Assuming one medium mallet suits every instrument, when the hardness that balances a marimba may be wrong for a xylophone or timpani", "Choosing mallet hardness by how it looks instead of by the tone and attack the music needs", "Reaching for a mallet harder than the bars can take, which can dent or crack rosewood marimba bars"], "scenario_contexts": ["Playing a concert-band mallet part that specifies no particular mallet", "Starting a marimba passage with mediums before deciding on softer or harder sticks", "Covering a range of dynamics on vibraphone where mediums balance tone and attack"]}, "1f692303-f2e9-4031-84b4-b28e4e339ce0": {"definition": "A friction-based percussion sound effect — a small friction (string) drum in which a rosined cord passes through a resonating cup or tube; drawing rosined fingers or a cloth along the cord sets it vibrating, and varying its tension produces a continuous roaring or bellowing glissando that imitates the call of a moose or similar animal.", "plain_english": "It is a noisemaker that growls and slides in pitch, like a moose call. You rub a sticky string that runs through a small drum or cup. The pitch then swoops up or down in one smooth glide.", "purpose_function": "It exists to add an animal-like roaring glissando to a piece or sound cue, giving players a controllable voice that slides smoothly in pitch rather than sounding fixed notes.", "practical_application": "A percussionist or foley artist makes the call by drawing rosined fingers or a cloth along the cord, controlling tension for the pitch sweep, and mics it closely because the sound is soft and detailed.", "category": "Friction drum effect", "related_terms": ["Friction drum", "Lion's roar", "Cuica", "Glissando", "Waterphone"], "common_mistakes": ["Expecting fixed pitches, when the moose call is a glissando effect rather than a tuned instrument", "Using too little rosin, so the cord slips and the roar will not speak", "Miking too far away, so the quiet friction sound is lost"], "scenario_contexts": ["Adding an animal-call effect to a film or theatre score", "A percussionist covering a sound-effect part in a contemporary piece", "Foley work needing a controllable roaring glissando"]}, "7a635427-6a90-459c-ab91-5a98543f4aa0": {"definition": "Unwanted sound generated by an electric motor and captured by microphones — mechanical hum, bearing rattle, or brush-and-commutator buzz, plus any radiated electrical interference; in percussion it most often refers to the audible noise of a vibraphone's motor, which spins the fans that create the instrument's vibrato.", "plain_english": "It is the extra humming or whirring a motor makes that a mic can pick up by mistake. On a vibraphone, it is the whir of the small motor that spins the fans for the wobble effect.", "purpose_function": "Naming it helps technicians spot and control it, because motor noise is a fault to be minimized, not a wanted sound, and it muddies quiet passages and reveals that a motor is running.", "practical_application": "When close-miking a vibraphone, engineers aim mics away from the motor housing, may run the motor slower or switch it off for still passages, and service worn bearings that rattle.", "category": "Noise source", "related_terms": ["Vibraphone motor", "Vibrato", "Signal-to-noise ratio", "Mechanical noise", "Hum"], "common_mistakes": ["Blaming electrical hum for a whir that is really the vibraphone's mechanical motor noise", "Leaving the motor running during quiet passages where its noise is exposed", "Placing the mic right by the motor housing instead of over the bars"], "scenario_contexts": ["Recording a soft solo vibraphone passage where the motor whir becomes audible", "Troubleshooting a rattle traced to worn motor bearings", "Deciding whether to run the vibraphone motor for a given track"]}, "e38f2742-b6a3-4dd3-9947-a48379e6c4ec": {"definition": "A tabla bol (stroke-syllable) played on the dayan, the smaller right-hand treble drum: the index finger strikes the kinar (outer rim) while another finger rests lightly on the syahi to suppress the fundamental, producing a clear, ringing, resonant tone at the drum's tuned pitch.", "plain_english": "It is one of the named strokes on the tabla, the small right-hand drum. You tap the outer edge with a finger while another finger touches the black spot. The drum then rings with a clear, bell-like note.", "purpose_function": "It gives the player a bright, ringing open sound at the drum's pitch, and it is a basic building block of tabla rhythmic patterns and the spoken drum language.", "practical_application": "A player produces Na by striking the rim with the index finger, and an engineer mics the dayan to catch this stroke's ringing, pitched sustain while keeping finger noise low.", "category": "Tabla stroke", "related_terms": ["Tabla", "Dayan", "Syahi", "Bol", "Bayan"], "common_mistakes": ["Damping the whole head, which kills the ring that defines Na", "Confusing Na with the damped, non-ringing strokes such as Te or Ka", "Striking the center instead of the rim, which loses the clear pitched tone"], "scenario_contexts": ["Learning tabla bols and reciting rhythmic compositions", "Miking a tabla so the dayan's ringing strokes come through", "Building a tabla sample library with correct open-stroke articulations"]}, "5290fd2c-070c-4ebb-93c3-b7dea1c394b8": {"definition": "A fundamental hand-drum stroke on instruments such as conga, djembe and bongo in which the fingers strike the head near the edge and rebound off immediately, letting the head ring freely to produce a clear, resonant, pitched tone that is the drum's characteristic 'singing' note.", "plain_english": "It is the clear, ringing note you get on a hand drum like a conga or djembe. You hit near the edge with your fingers and let your hand bounce right off. The drumhead then sings out its pitch.", "purpose_function": "It provides the drum's main resonant, pitched voice, contrasting with the sharp slap and the deep bass tone, so a single drum can carry singing lines within a rhythm.", "practical_application": "A player gets a good open tone by striking at the edge and lifting off cleanly, and an engineer mics a conga or djembe to capture the open tone's ring while balancing the slap and bass strokes.", "category": "Hand-drum stroke", "related_terms": ["Slap tone", "Bass tone", "Conga", "Djembe", "Muted tone"], "common_mistakes": ["Leaving the hand on the head after the strike, which chokes the ring and dulls the tone", "Striking too far toward the center, which gives a dead thud instead of a clear open tone", "Confusing the open tone with the slap, when the slap is sharp and high and the open tone is round and pitched"], "scenario_contexts": ["Playing a conga tumbao where open tones carry the melodic line", "Miking a djembe so open tones ring without excess low thump", "Teaching the three basic hand-drum sounds: bass, open tone and slap"]}, "675be25f-644f-4da4-aa0d-a4baf06b9663": {"definition": "A Spanish term (literally a metal pan or kettle) for the Cuban timbales — the pair of shallow, single-headed, metal-shelled drums, also called 'pailas criollas', played with sticks and mounted on a stand; by extension it also names the metal shell of the drum, the surface struck for the sharp 'cascara' shell pattern.", "plain_english": "It is another name for timbales, the shallow metal Cuban drums played with sticks. The word means a metal pan. Players also use it for the metal side of the drum that they tap for the clicky shell pattern.", "purpose_function": "The metal-shelled paila gives timbales their bright, cutting tone and lets the player switch between ringing head strokes and the sharp cascara pattern on the shell, driving Latin dance rhythms.", "practical_application": "A timbalero plays both heads and shells with sticks, and an engineer mics the timbales to catch the head tone and the bright cascara on the shell, watching levels because shell strokes are sharp and loud.", "category": "Latin percussion", "related_terms": ["Timbales", "Cascara", "Cowbell", "Bongos", "Conga"], "common_mistakes": ["Thinking paila is a different instrument from timbales, when it is the Cuban name for them", "Miking only the heads and missing the bright cascara played on the metal shell", "Setting one gain for the heads and forgetting that shell strokes peak much louder"], "scenario_contexts": ["Recording a salsa band's timbales section", "A timbalero switching between head tones and shell (cascara) patterns", "Balancing bright shell strokes against the rest of a Latin percussion mix"]}, "ece2316e-2edc-4d66-b050-94804a61ec1b": {"definition": "On the vibraphone, the use of the foot pedal to operate a felt-covered damper bar running beneath the tone bars: with the pedal released a spring holds the damper against the bars so notes sound short and damped, and pressing the pedal lowers the damper away so notes ring and sustain, giving control of note length much like a piano's sustain pedal.", "plain_english": "It is using a foot pedal on a vibraphone to control how long the notes ring. A soft bar presses the metal keys to stop them. Pressing the pedal lifts that bar away so the notes sustain, just like a piano's sustain pedal.", "purpose_function": "It gives the vibraphonist control over note length and legato — sustaining, connecting or cutting off notes — since the metal bars would otherwise ring on for a long time by themselves.", "practical_application": "A vibraphonist works the pedal together with hand and mallet dampening to phrase lines cleanly and avoid a blur of overlapping notes, and engineers place mics to keep the pedal mechanism's thump low.", "category": "Damping technique", "related_terms": ["Vibraphone", "Damper bar", "Sustain pedal", "Mallet dampening", "Motor noise"], "common_mistakes": ["Leaving the pedal down constantly, so notes pile up into a muddy wash", "Relying only on the pedal and neglecting hand or mallet dampening for single-note control", "Lifting the damper too slowly between chords, which smears one harmony into the next"], "scenario_contexts": ["Playing a legato vibraphone ballad that needs pedaling for smooth phrasing", "Cutting off a chord cleanly on a rhythmic figure with the pedal", "Combining pedal and mallet dampening to control which notes ring"]}, "dd63fd9f-909b-4bc8-b1ad-ff1bae85999b": {"definition": "The soft, continuous, rushing and rattling sound produced by a rainstick — a sealed tube fitted with internal pins or thorns and filled with small beads, seeds or pebbles — when it is slowly tilted so the contents cascade down past the pins, imitating the sound of falling rain.", "plain_english": "It is the gentle, rushing 'shhh' a rainstick makes, like rain falling. When you tip the tube, little beads trickle down past pins inside and hiss softly.", "purpose_function": "This hiss is the rainstick's whole purpose — a soft, pitchless wash of sound used for atmosphere, texture and gentle transitions rather than a definite rhythm or pitch.", "practical_application": "A player tilts the rainstick at different angles to speed up or slow down the hiss, and an engineer close-mics it, adds gain because the sound is quiet and broadband, and keeps handling noise in check.", "category": "Shaken idiophone", "related_terms": ["Shaker", "Cabasa", "Ocean drum", "Maraca", "Idiophone"], "common_mistakes": ["Tilting too fast, which turns the gentle hiss into a rattly dump of beads", "Under-gaining the quiet, broadband hiss so it disappears in the mix", "Treating the rainstick as a rhythmic instrument rather than a sustained texture"], "scenario_contexts": ["Adding a rainfall-like texture to an ambient or film cue", "Close-miking a rainstick for a nature-sound recording", "Using the hiss as a soft transition between song sections"]}, "1a458d08-69eb-4d57-9e5e-12345f575a77": {"definition": "The tuned, usually metal, tubes suspended beneath the bars of a marimba, xylophone, vibraphone or similar mallet instrument, each acting as a quarter-wavelength air column tuned to the fundamental of the bar above it. By resonating in sympathy with the struck bar, the tube reinforces and radiates the fundamental, increasing loudness and sustain while shaping timbre.", "plain_english": "Hollow tubes that hang under each bar of a marimba or vibraphone. Each tube is tuned to match its bar, so it makes that note louder and fuller. It works a bit like blowing across a bottle to get a tone.", "purpose_function": "They exist to amplify and prolong the relatively weak sound of a struck bar by resonating at the bar's pitch, giving mallet instruments their full, singing tone rather than a short, thin click.", "practical_application": "A technician keeps the tubes clear, correctly aligned under the bars and at the right length, and when miking checks that the pickup captures the tubes' radiated fundamental as well as the attack from the bars.", "category": "Instrument anatomy", "related_terms": ["Marimba", "Vibraphone", "Tone bar", "Fundamental", "Sustain", "Soft mallet"], "common_mistakes": ["Thinking the tube changes the note's pitch; it only reinforces the pitch already set by the bar's length and tuning.", "Letting debris or a misaligned tube sit under a bar, which weakens and dulls that note's resonance.", "Miking only the bars from above and missing the fuller fundamental radiated from the open tube ends."], "scenario_contexts": ["Setting up a marimba and aligning each resonator under its bar before a session.", "Miking a vibraphone to capture both the bar attack and the sustained tone from the tubes.", "Diagnosing a weak, thin note traced to a blocked or misaligned resonator tube."]}, "f0525177-2532-4537-a15f-3532f0ef39ef": {"definition": "A rapid, continuous roll produced on the riq (a small Middle Eastern frame drum with jingles) by fast finger or wrist motion, or by shaking the frame, so the pairs of jingles and the head sound in quick succession to create a sustained shimmering effect. It is the frame drum's equivalent of a sustained roll, used to fill and color a rhythmic line.", "plain_english": "A fast roll on the riq, a small Arabic tambourine with jingles. The quick motion blurs the jingles into a smooth, steady shimmer. It works much like a drum roll that holds a sound out.", "purpose_function": "It lets a frame-drum player sustain sound and add a shimmering wash beneath or between accented strokes, since a single struck note decays almost instantly.", "practical_application": "A player produces it with rapid alternating fingers or a shaking wrist, and an engineer recording it uses a mic and any gentle compression that keeps the fast jingle detail without smearing the transients.", "category": "Playing technique", "related_terms": ["Riq", "Frame drum", "Jingles", "Tremolo", "Roll", "Tambourine"], "common_mistakes": ["Confusing the tremolo with a single accented strike; the tremolo is a fast, sustained succession of sounds, not one hit.", "Gripping the frame too tightly, which chokes the jingles and stops the shimmer from ringing evenly.", "Recording it with heavy compression or a slow attack setting that smears the fast jingle detail into mush."], "scenario_contexts": ["Sustaining energy under a vocal phrase in Arabic or Turkish classical music.", "Filling the space between accented dum and tak strokes in a rhythmic cycle.", "Recording a riq part where the engineer must preserve the fine jingle shimmer."]}, "d3097352-db7b-41d5-92ea-bd482df996db": {"definition": "The bright, bell-like metallic attack and ring of a struck saron bar, the saron being a bronze-keyed metallophone of the Indonesian gamelan. The 'ping' is the clear, high partial-rich tone that sounds the instant the bar is hit and before the player's free hand damps it.", "plain_english": "The bright, ringing sound a saron bar makes the moment it is struck. The saron is a metal-bar instrument from Indonesian gamelan music. Its bronze bars ring out clearly, a little like small bells.", "purpose_function": "This ringing attack carries the saron's melodic line and gives the gamelan its shimmering metallic character; the free hand damps each bar so the ring does not blur into the next note.", "practical_application": "When recording gamelan a technician places mics to capture the bright bar attack without harshness and expects each ping to be cut short by the player's damping hand.", "category": "Timbre", "related_terms": ["Saron", "Gamelan", "Metallophone", "Damping", "Attack", "Tabuh"], "common_mistakes": ["Assuming the bars ring on indefinitely; in correct playing each ping is quickly damped by the free hand.", "Miking too close and exaggerating a harsh, clangy attack instead of the balanced bell-like tone.", "Confusing the saron's ping with a struck cymbal's wash; the saron sounds a definite pitch, not a spread of noise."], "scenario_contexts": ["Recording a Javanese gamelan where the saron carries the core melody.", "Placing mics to capture the saron's bright attack while keeping it musical.", "Balancing the saron ping against softer gong and drum voices in a mix."]}, "2e79d209-7011-442d-8870-b65aebd603bd": {"definition": "The brief, sharp burst of energy at the onset of each shaker stroke, produced as the beads, seeds or shot inside strike the shell before the sound quickly decays. This fast, high-frequency transient defines the shaker's rhythmic articulation and its ability to sit at the top of a mix.", "plain_english": "The quick burst of sound at the start of each shaker shake. It is the sharp 'chh' you hear before the sound fades away. This crisp start is what makes a shaker cut through a mix.", "purpose_function": "The transient carries the shaker's timing and crispness; because the sound is mostly high frequency and short, the sharp onset is what the ear locks onto for groove and placement.", "practical_application": "An engineer preserves the shaker transient by choosing a fast, detailed mic and avoiding slow compressor attack times or heavy limiting that would round off and dull the leading edge.", "category": "Sound property", "related_terms": ["Shaker", "Transient", "Attack", "Compression", "Transient shaping", "High frequency"], "common_mistakes": ["Using a slow compressor attack that clamps down after the transient, flattening the shaker's crisp leading edge.", "Rolling off too much high frequency, which buries the transient and makes the shaker sound dull and distant.", "Over-quantizing a live shaker part and losing the subtle transient timing that gave it feel."], "scenario_contexts": ["Recording an overdubbed shaker to add high-end drive to a pop groove.", "Setting compressor attack and release so the shaker stays crisp and controlled.", "Using a transient shaper to bring a buried shaker forward without raising overall level."]}, "a0a9b67a-9a6c-4d89-a327-8c224e5dd5b0": {"definition": "A stroke on the shekere (a West African beaded gourd rattle) in which the open bottom of the gourd is struck against the palm or heel of the hand, producing a deep, low-pitched 'boom' beneath the rattle of the beaded net. It is one of the instrument's core strokes, contrasted with the sharper sound of shaking or slapping the beads.", "plain_english": "A slap on the bottom of a shekere, which is a beaded gourd rattle from West Africa. The palm hits the open end of the gourd to make a deep, low 'boom.' That boom sits under the beady, shaking sound.", "purpose_function": "The slap adds a low, resonant accent that anchors the shekere's rhythm, giving the instrument a bass note to balance the bright rattle of the surrounding beads.", "practical_application": "A player alternates the palm slap with bead shakes to build a pattern, and when miking a technician positions the mic to capture both the low gourd 'boom' and the higher bead rattle.", "category": "Playing technique", "related_terms": ["Shekere", "Gourd", "Rattle", "Slap", "Low frequency", "Groove"], "common_mistakes": ["Striking the gourd too hard on a bony part of the hand, which risks cracking a dried gourd shell.", "Miking only for the bright bead rattle and missing the low 'boom' of the slapped gourd body.", "Confusing the gourd-body slap with the bead sound; the slap is the low accent, the beads are the bright rattle."], "scenario_contexts": ["Playing a shekere in an Afro-Cuban or West African percussion ensemble.", "Recording a shekere so both the low body slap and bead rattle are captured.", "Using the slap to place a low accent on the downbeat of a groove."]}, "bc7d12c7-0c9c-414b-a5aa-c310b3845600": {"definition": "The buzzing, sizzling component of a snare drum's sound, created when the metal snare wires (snares) stretched across the bottom head vibrate against that head as the drum is struck. The same mechanism produces sympathetic buzz when the snares are excited by other instruments or by resonances in the room.", "plain_english": "The buzzy sizzle a snare drum makes. It comes from the metal wires stretched under the drum. Each time the drum is hit, those wires rattle against the skin and add the buzz.", "purpose_function": "The buzz is what distinguishes a snare drum from a plain tom; the snares' response gives the backbeat its bright, cutting sizzle and its characteristic sharp decay.", "practical_application": "A technician tunes the resonant head and sets the snare-wire tension so the buzz is crisp and quick, and adjusts throw-off tension or damping to control excess sympathetic buzz picked up by nearby mics.", "category": "Sound property", "related_terms": ["Snare wires", "Snare rattle", "Resonant head", "Backbeat", "Sympathetic vibration", "Snare tuning"], "common_mistakes": ["Over-tightening the snare wires to kill buzz, which chokes the drum and removes its characteristic sizzle.", "Gating the snare so hard that the natural buzz tail is cut off and the drum sounds abrupt and dead.", "Blaming the snare wires for a rattly sound when the resonant head tuning is the real cause."], "scenario_contexts": ["Tuning a snare drum so the wire buzz is tight and cuts through the mix.", "Managing sympathetic snare buzz that leaks into tom and vocal mics.", "Setting snare-wire tension to balance sizzle against a clean, controlled decay."]}, "385ffeff-bba6-48ae-b0f7-511683d7f106": {"definition": "The unwanted rattling or buzzing of a snare drum's wires when they vibrate sympathetically in response to other instruments (bass, toms, low brass) or stage energy rather than a direct strike. It is heard as extraneous noise and is controlled through snare tension, drum tuning, muffling, or gating.", "plain_english": "An unwanted rattle from a snare drum's wires when other loud instruments play nearby. The wires shake on their own and add noise, even when no one hits the snare. It is usually treated as a problem to tame.", "purpose_function": "Recognizing sympathetic snare rattle matters because it adds noise and buzz to a recording or live mix; identifying it lets a technician tame it without dulling the drum's intended sound.", "practical_application": "A technician reduces rattle by adjusting snare-wire tension, retuning the offending drum or resonant head, or using light muffling, and on the desk may gate the snare mic to reject the buzz between hits.", "category": "Sound property", "related_terms": ["Snare wires", "Snare buzz", "Sympathetic vibration", "Resonant head", "Gate", "Muffling"], "common_mistakes": ["Over-tightening the snares to stop rattle, which strangles the drum's natural sizzle and response.", "Ignoring the true source; the rattle often comes from a tom or bass frequency exciting the snares, not the snare itself.", "Reaching for heavy gating first instead of fixing the tuning or wire tension that causes the rattle."], "scenario_contexts": ["Chasing a rattle that appears on the snare only when the bass guitar plays a certain note.", "Retuning a floor tom whose resonance is setting off the snare wires.", "Gating a snare mic to reject sympathetic rattle between backbeats."]}, "3ac9cd1e-d49b-4ae8-bac9-f78dfa740e2e": {"definition": "A percussion beater whose head is wound with soft yarn, cord or a soft rubber core, giving a low striking hardness. The soft head lengthens the contact time with the bar, cymbal or drumhead, which suppresses high harmonics and the sharp attack to produce a warm, rounded, fundamental-rich tone.", "plain_english": "A stick with a soft, padded head used to hit tuned percussion. The soft tip gives a warm, mellow sound with less click at the start. It is like tapping something with a cushioned end instead of a hard one.", "purpose_function": "Soft mallets exist to bring out an instrument's warm fundamental and reduce hard attack, used to swell suspended cymbals, play smooth marimba lines, or roll timpani without a harsh edge.", "practical_application": "A player chooses mallet hardness to suit the passage, and a technician expects a softer mallet to give a duller attack and stronger low end, adjusting mic placement or EQ accordingly.", "category": "Beaters & mallets", "related_terms": ["Mallet", "Hard mallet", "Marimba", "Suspended cymbal", "Attack", "Timbre"], "common_mistakes": ["Assuming mallet hardness only changes volume; it mainly changes attack sharpness and brightness of tone.", "Using a very soft mallet for fast passages where the soft head blurs note definition and articulation.", "Playing hard bars or bells with a soft mallet and losing the clear attack the part needs."], "scenario_contexts": ["Swelling a suspended cymbal roll smoothly with a pair of soft yarn mallets.", "Choosing soft mallets for a warm, singing marimba melody.", "Rolling timpani with softer mallets to avoid a harsh, clacky attack."]}, "1f797ff8-5ec9-472d-a86d-01b4463e842f": {"definition": "A steelpan accompaniment technique in which the player sounds chord tones in rapid, repeated strokes to sustain harmony and rhythm, imitating a strummed or comped chordal instrument. It is the characteristic role of the lower 'strumming' pans (guitar and cello pans) in a steelband, whose fast repeated notes fill the texture between melody and bass.", "plain_english": "A way of playing chords on a steel pan by tapping the notes fast, one right after another. It fills in the rhythm and harmony under the tune. It does much the same job as strumming a guitar.", "purpose_function": "Strumming provides the harmonic and rhythmic middle layer of a steelband, keeping chords sounding between the sharp attacks of the melody pans and the bass, so the ensemble sounds full.", "practical_application": "A background or guitar-pan player uses fast repeated strokes to comp chords, and an engineer miking a steelband captures these strumming pans as the harmonic bed beneath the lead pans.", "category": "Playing technique", "related_terms": ["Steelpan", "Guitar pan", "Cello pan", "Steelband", "Comping", "Roll"], "common_mistakes": ["Thinking a strum sounds all chord notes at once; on a pan it is a fast series of repeated strokes, not a single sweep.", "Striking too hard while strumming, which overwhelms the melody pans and muddies the ensemble balance.", "Miking only the lead pans and losing the strumming pans that carry the harmony."], "scenario_contexts": ["A guitar-pan section comping chords behind the melody in a steelband arrangement.", "Recording a steelband and balancing the strumming pans under the lead pans.", "Learning the strumming role to fill the harmonic middle of an ensemble."]}, "fead459c-31c2-4b79-9e3e-903dcad644d1": {"definition": "A steel tongue drum is a struck idiophone made from a hollow steel shell (often two welded domes) with a set of radial slots cut into one face to form tongues of differing length. Each tongue is tuned to a specific pitch and sounds when struck with fingers or soft mallets. It descends from the slit drum and hand-built 'tank' drums.", "plain_english": "A steel tongue drum is a rounded metal instrument with slots cut into its top. Each cut piece of metal, called a tongue, rings a different note when you tap it. It sounds soft and bell-like, a bit like a music box you play with your hands.", "purpose_function": "It produces a set of clear, sustained, tuned pitches from a single portable resonating body, letting one player sound melodies and simple chords without separate bars or drumheads.", "practical_application": "A technician close-mics or records one to capture its long ringing sustain, managing the strong fundamental and slow decay so the instrument sits in a mix without dominating it.", "category": "Percussion instrument", "related_terms": ["Idiophone", "Slit drum", "Handpan", "Overtone", "Sustain"], "common_mistakes": ["Confusing a steel tongue drum with a steel pan (steelpan), which is played on concave note areas hammered into a drum, not on cut tongues", "Assuming any striking point works, when the sweet spot near a tongue's tip gives the cleanest pitch", "Over-damping the shell when miking, which kills the instrument's defining long sustain"], "scenario_contexts": ["Recording an ambient or meditation track that needs a soft bell-like melodic layer", "Adding a tuned percussion texture to a live acoustic set", "Teaching beginners simple melodies, since the tuned tongues make wrong notes hard to play"]}, "f531f21c-250f-4be8-86f0-1d5866506ebc": {"definition": "On the tabla, sur is the tuning of the drums, principally setting the dayan (treble drum) to the tonic (sa) of the raga, while meend is a continuous glide in pitch. Meend is produced on the bayan (bass drum) by pressing and sliding the heel of the hand across the head to change skin tension during or after a stroke.", "plain_english": "On the tabla, sur means tuning the drum to the right note. Meend is a slide in pitch. The player presses and drags the heel of the hand on the big bass drum to bend the tone up or down, like a singer sliding between notes.", "purpose_function": "Sur locks the drums to the piece's key so the tabla blends with the melody, and meend lets the bass drum bend its pitch expressively to echo the vocal or instrumental line.", "practical_application": "A player tunes the dayan to the soloist's sa before performing and uses heel-pressure meend on strokes like 'ghe' to sweep the bass pitch, an effect an engineer should preserve rather than gate away.", "category": "Hand-drum technique", "related_terms": ["Tabla", "Bayan", "Dayan", "Syahi", "Pitch bend", "Raga"], "common_mistakes": ["Thinking the bass drum has one fixed pitch, when heel pressure deliberately changes it", "Confusing sur (the tuning) with meend (the glide itself)", "Tuning the dayan by ear to the wrong octave of sa"], "scenario_contexts": ["Tuning the dayan to a singer's tonic before a Hindustani concert", "Performing a 'ghe' stroke with a rising heel-pressure glide", "Close-miking the bayan and hearing the pitch sweep on sustained strokes"]}, "bf7dda00-e10e-451e-94bc-a3f87a8a4a24": {"definition": "On the surdo, the large Brazilian samba bass drum, an open stroke lets the head ring freely for a full, sustained boom, while a muffled (stopped) stroke damps the head, typically by pressing the free hand or the beater onto the skin, cutting the ring into a short, dead thud. Alternating the two shapes the samba's low pulse.", "plain_english": "The surdo is a big Brazilian bass drum. An open hit is left to ring out and boom. A muffled hit is stopped short by pressing a hand or the beater onto the head, so the note is short and dead. Players mix the two to make the beat bounce.", "purpose_function": "The contrast between ringing open notes and choked muffled notes gives the surdo its swing and marks the strong and weak beats that anchor a samba bateria.", "practical_application": "A player damps with the non-striking hand on the offbeat and releases for the accented open hit, while an engineer captures both with a dynamic mic and watches for the long open-note decay.", "category": "Drum stroke", "related_terms": ["Surdo", "Samba", "Bateria", "Muffling", "Bass drum", "Damping"], "common_mistakes": ["Muffling with the striking hand instead of the free hand, which breaks the groove", "Leaving every note open, so the pattern loses its accent and swing", "UNSAFE: hanging a heavy surdo from a worn or poorly adjusted shoulder strap, which can slip and drop the drum onto the player or bystanders"], "scenario_contexts": ["Playing a first-surdo part with alternating open and muffled beats", "Damping the head to tighten an overly boomy drum in a live samba set", "Miking a surdo section and balancing sustain against the mix"]}, "69a047a5-d4f2-4e43-830c-ad380f64e399": {"definition": "Sympathetic snare buzz is the unwanted rattle of a snare drum's snare wires when they vibrate in sympathy with sound from another source, such as a tom, a bass note, a vocal, or stage sound, rather than from a direct strike. It occurs when that excitation carries energy near the resonant frequency of the snare-side head.", "plain_english": "A snare drum has metal wires under its bottom head. These wires can rattle on their own when a nearby loud note hits the right pitch, even if no one touches the drum. It is like how a glass can hum when you sing the right tone near it. This stray buzz can sneak into recordings.", "purpose_function": "It is a natural coupling effect that shows how freely the snares respond; recognizing it lets a technician control unwanted noise while keeping the snare's intended sensitivity and sound.", "practical_application": "When recording or mixing, an engineer reduces sympathetic buzz by tuning the resonant head, adjusting snare tension, gating the snare track, or repositioning drums and monitors.", "category": "Drum acoustics", "related_terms": ["Snare wires", "Resonant head", "Sympathetic resonance", "Noise gate", "Crosstalk", "Sustain"], "common_mistakes": ["Blaming a rattling snare on broken wires when the real cause is sympathetic vibration", "Cranking snare tension extremely tight to stop buzz, which chokes the drum's tone", "Ignoring the buzz while tracking and only noticing it in the final mix"], "scenario_contexts": ["Hearing the snare rattle every time the bass guitar hits a certain note", "Buzz bleeding into tom or vocal mics during a quiet passage", "Setting a noise gate on the snare channel to tame stray buzz"]}, "bcc732d4-36d1-4e92-9f5f-96f51b95e030": {"definition": "In taiko (Japanese drum) playing, 'don' is the vocable and stroke for a full, resonant hit struck near the center of the drumhead, producing the instrument's deep, open fundamental tone. It is one of the core sounds in kuchi shoga, the spoken drum-syllable system used to teach and remember patterns.", "plain_english": "Don is the deep, ringing hit in the middle of a taiko drum. Players say the word out loud to learn the beat, like singing boom for a big hit. It gives the drum its full, open sound.", "purpose_function": "Don provides the drum's loudest, most sustaining note and usually falls on strong beats, giving a taiko piece its weight and drive; as a spoken syllable it also lets players learn rhythms by voice.", "practical_application": "A player aims for the head's center to get a clean 'don', and an engineer mics the batter side and often the shell to capture both the attack and the long low resonance.", "category": "Drum stroke", "related_terms": ["Taiko", "Kuchi shoga", "Ka (katsu)", "Fundamental", "Bachi"], "common_mistakes": ["Striking off-center and getting a weaker, less resonant tone than a true 'don'", "Treating kuchi shoga syllables as exact pitches rather than sound-and-stroke cues", "Gripping the bachi too tightly, which deadens the open ring"], "scenario_contexts": ["Learning a new pattern by chanting 'don' and 'ka' before playing it", "Placing accented center hits on the downbeats of an ensemble piece", "Miking a large nagado-daiko to capture the deep 'don' resonance"]}, "bc943e2c-4bd9-4674-91a0-2ebf3b154e5c": {"definition": "In taiko, 'ka' (also 'katsu') is the vocable and stroke for a light, dry hit on the wooden rim or edge of the drum, giving a high, clicking sound that contrasts the deep center 'don'. It is a core syllable in kuchi shoga and is often used to keep time and fill the space between accents.", "plain_english": "Ka is a light, clicky hit on the wooden rim of a taiko drum. It sounds dry and high next to the deep center hit. Players use it to keep time and fill the small gaps in a rhythm.", "purpose_function": "Ka supplies a soft, sharp timekeeping sound that marks subdivisions and rests between the loud 'don' hits, letting a player hold the pulse and the ensemble stay together.", "practical_application": "A player taps the fuchi (rim) for 'ka' to hold the tempo quietly, and an engineer keeps the rim detail audible without letting the higher click overpower the low drum tone.", "category": "Drum stroke", "related_terms": ["Taiko", "Kuchi shoga", "Don", "Fuchi", "Bachi"], "common_mistakes": ["Hitting the rim too hard so 'ka' overpowers the musical 'don' accents", "Confusing 'ka' (a rim stroke) with a center-head stroke", "Losing the steady 'ka' timekeeping and drifting off tempo"], "scenario_contexts": ["Keeping a quiet rim pulse under a soloist's phrases", "Chanting 'don ka' patterns to teach a rhythm by voice", "Balancing rim clicks and center booms when miking a taiko"]}, "de68c985-d9cf-4685-8181-5980b76812ba": {"definition": "On the tambora, the two-headed drum of Dominican merengue, one hand plays a stick that strikes the head and the wooden shell or rim while the other bare hand works the opposite head, slapping it for a muted, sharp tone or leaving it open to ring. Combining slapped (muffled) and open strokes creates the drum's characteristic driving pattern.", "plain_english": "The tambora is a two-headed drum used in merengue music. One hand holds a stick that taps the head and the wood side. The other hand slaps the head to mute it or lets it ring open. Switching between these gives the fast, swinging groove.", "purpose_function": "The interplay of muted slaps, open tones, and stick rim strokes gives merengue its fast, syncopated bass-and-accent groove and drives the dance rhythm.", "practical_application": "The player rests the drum across the lap and works the stick and hand in tandem, while an engineer mics both heads or the shell to catch the stick clicks, slaps, and open tones.", "category": "Drum stroke", "related_terms": ["Tambora", "Merengue", "Open tone", "Slap", "Muffling"], "common_mistakes": ["Playing every stroke open, which muddies the fast merengue pattern", "Using two sticks or two bare hands instead of the stick-and-hand combination", "Damping the ringing head when an open tone is wanted"], "scenario_contexts": ["Laying down a merengue groove with stick rim clicks and hand slaps", "Alternating slapped and open tones to accent the beat", "Miking both heads of a tambora in a tipico ensemble"]}, "73a0536c-2ecd-44df-8cad-6d9f2c3765ac": {"definition": "Tambourine jingles (also called zils or platinelas) are the small, thin metal discs mounted in pairs within slots around a tambourine's frame. When the instrument is shaken, struck, or thumbed, the loosely fitted pairs clash and ring against each other to produce the tambourine's bright, sustained jingling sound.", "plain_english": "Jingles are the little metal discs set into the frame of a tambourine. They come in pairs that clash together and ring when you shake or tap the drum. They give the tambourine its bright, shiny sound.", "purpose_function": "The jingles turn the player's shakes and hits into a shimmering metallic sustain, which is the tambourine's defining voice and its role as a high-frequency rhythmic accent.", "practical_application": "A player controls jingle sound through shake, thumb roll, or strike, and an engineer captures the bright transient with a small-diaphragm condenser while guarding against harsh high-frequency peaks.", "category": "Instrument component", "related_terms": ["Tambourine", "Zils", "Frame drum", "Idiophone", "Thumb roll"], "common_mistakes": ["Calling the whole tambourine a 'jingle', when the jingles are only the metal discs", "Mounting jingles too tightly so they cannot ring freely", "Recording jingles too close and too hot, producing harsh, spiky highs"], "scenario_contexts": ["Overdubbing a tambourine backbeat with bright jingle accents", "Performing a thumb roll to sustain the jingles across a phrase", "EQing harsh jingle peaks out of a percussion track"]}, "ed89f559-ade3-440d-a91d-e8472889ce01": {"definition": "Tek is a stroke on goblet drums such as the darbuka/doumbek: a sharp, high-pitched sound made by striking the edge of the drumhead near the rim with the fingers, usually of the dominant hand. It contrasts with 'dum', the deep bass stroke played in the center, and the two form the backbone of Middle Eastern drum rhythms.", "plain_english": "Tek is a sharp, high tap on the edge of a hand drum like the darbuka. You make it with your fingertips near the rim. It answers the deep center hit called dum, so the two trade off to build a rhythm.", "purpose_function": "Tek supplies the crisp, high accents that answer the low 'dum' hits, so alternating them builds the rhythmic patterns, such as maqsum or baladi, that define darbuka playing.", "practical_application": "A player uses the fingertips at the rim for a ringing tek, often with a matching 'ka' from the other hand, while an engineer captures the sharp edge transient without losing the drum's low body.", "category": "Hand-drum stroke", "related_terms": ["Darbuka", "Dum", "Ka", "Goblet drum", "Slap"], "common_mistakes": ["Striking too far toward the center, turning a crisp tek into a dull thud", "Using flat fingers instead of the fingertips at the rim", "Confusing 'tek' (the dominant-hand edge stroke) with 'ka' (the other-hand edge stroke)"], "scenario_contexts": ["Playing a maqsum pattern of dum and tek strokes", "Adding tek accents on the offbeats of a baladi rhythm", "Close-miking a darbuka to capture bright tek transients"]}, "53ff2b52-9eeb-439c-a220-2d2d534838c3": {"definition": "Temple blocks are a graduated set of hollow, rounded wooden slit-idiophones (descended from the Chinese muyu/mokugyo) struck with mallets; the 'cluck' is their characteristic dry, hollow, mellow, clop-like tone, sounded by striking the block over its slit. It is rounder and softer than the sharp crack of a woodblock.", "plain_english": "A temple block is a hollow, round wooden block you hit with a mallet. The 'cluck' is its soft, hollow, knocking sound, like a gentle wooden clop.", "purpose_function": "The hollow slit lets the block ring with a warm, semi-pitched cluck, giving players a mellow wooden tone for melodic runs, comic effects, and rhythmic color that stands apart from metal or skin percussion.", "practical_application": "A percussionist mounts a set of graduated temple blocks and plays them with medium mallets for galloping, cartoon-style figures or simple pentatonic melodies in orchestral, band, and studio work.", "category": "Percussion articulation", "related_terms": ["Woodblock", "Slit drum", "Idiophone", "Mallet selection", "Claves"], "common_mistakes": ["Confusing temple blocks with the harder, sharper-sounding woodblock", "Using hard plastic or metal mallets that can crack or dent the wood instead of soft or medium mallets", "Striking the solid top of the block rather than over the slit, which chokes the tone"], "scenario_contexts": ["Playing a galloping horse-hoof figure in a cartoon or film score", "Adding pentatonic melodic color in a percussion ensemble piece", "Layering a warm wooden tick in a studio percussion overdub"]}, "1a589374-15a5-4284-9792-178c16ce81cb": {"definition": "Thom is the open, resonant bass stroke of the South Indian mridangam, produced by striking the center of the larger left-hand (bass) head with the flat palm and fingers and letting it ring freely, giving a deep, sustained low tone.", "plain_english": "Thom is the deep, booming bass note of the mridangam drum. You hit the middle of the big left drumhead and let it ring, like a low 'boom'.", "purpose_function": "Thom supplies the drum's low-frequency foundation and resonance, anchoring the rhythm and balancing the sharp treble strokes so a phrase has both weight and clarity.", "practical_application": "A mridangam player uses thom for downbeats and cadences, often pairing it with a treble stroke so the low syllable marks the start or close of a rhythmic cycle in Carnatic music.", "category": "Drum stroke", "related_terms": ["Mridangam", "Tabla bol", "Sollukattu", "Konnakol", "Bayan"], "common_mistakes": ["Damping the left head right after striking, which kills the intended open ring", "Confusing thom (open bass) with a closed, muted bass stroke", "Striking off-center and losing the deep fundamental tone"], "scenario_contexts": ["Marking the first beat (sam) of a rhythmic cycle in a Carnatic performance", "Recording the low end of a mridangam for a fusion track", "Teaching konnakol, where 'thom' names the bass syllable"]}, "0e4f6b04-cf65-4063-b2d4-b89687d80bd1": {"definition": "Ti is a closed, non-resonant (damped) tabla stroke played on the right-hand drum (dayan), struck at the center of the black syahi so the fundamental is suppressed, giving a short, dry sound used mainly in rapid figures.", "plain_english": "Ti is a short, dry tap on the small right tabla drum. You strike the black center so it does not ring, making a quick, muffled 'ti' click.", "purpose_function": "Because it is damped and quick, Ti fills fast rhythmic subdivisions and word-like patterns (such as 'tirakita') where a ringing tone would blur the notes together.", "practical_application": "A tabla player uses Ti inside rapid combination strokes and fillers, keeping the finger on the drum to mute the sound and articulate clean, even fast runs.", "category": "Drum stroke", "related_terms": ["Tabla bol", "Tin/Tun (tabla)", "Na (tabla)", "Bayan", "Dayan"], "common_mistakes": ["Letting the finger bounce off so the stroke rings instead of staying dry", "Confusing the damped Ti with the resonant Tin", "Striking too hard and losing the light, fast feel"], "scenario_contexts": ["Playing a fast 'tirakita' filler between theka strokes", "Practicing damped-stroke clarity at high tempo", "Notating a rela pattern that relies on closed strokes"]}, "09ecd520-9c5d-4c44-9631-50146d16f387": {"definition": "Tin and Tun are open, resonant strokes on the tabla's right-hand drum (dayan): Tin rings by striking the border between the syahi and the open skin (maidan) while two fingers rest on the syahi, while Tun excites the drum's fundamental by striking the center of the syahi, giving a deeper, sustained ring.", "plain_english": "Tin and Tun are ringing notes on the small right tabla drum. Tin is struck near the black patch's edge for a bright ring; Tun is struck in the middle for a deeper, longer ring.", "purpose_function": "These resonant strokes give the tabla its clear pitched tones, letting the drum sing a sustained note that carries melody-like accents within a rhythmic pattern.", "practical_application": "A tabla player tunes the dayan to the tonic of the melody, then uses Tin and Tun for open, ringing accents in the theka and in cadential phrases.", "category": "Drum stroke", "related_terms": ["Tabla bol", "Ti (tabla)", "Na (tabla)", "Dayan", "Syahi"], "common_mistakes": ["Muting the head after the strike, which kills the intended ring", "Failing to tune the dayan to the melody's tonic so the resonant strokes clash", "Confusing resonant Tin/Tun with the damped Ti and Te strokes"], "scenario_contexts": ["Tuning the right drum to the tonic (sur) before a performance", "Playing ringing accents in a teentaal theka", "Recording a clear pitched tabla tone for a film cue"]}, "12543219-484b-438d-aafc-f54934a17373": {"definition": "A triangle strike is the act of striking a suspended steel triangle with a metal beater to produce its characteristic bright, high, sustaining shimmer of indefinite pitch; single taps, or rapid trills inside a corner, are common articulations.", "plain_english": "A triangle strike is a hit on the metal triangle with a small metal rod. It makes a bright, ringing 'ting' that hangs in the air.", "purpose_function": "The strike sets the metal ringing across many high overtones, adding sparkle and accent that cut through an ensemble even at low volume.", "practical_application": "A percussionist hangs the triangle by its clip, strikes the base or a corner with a steel beater, and pinches the metal to damp the ring when the note should stop.", "category": "Percussion articulation", "related_terms": ["Idiophone", "Triangle beater", "Damping", "Sleigh bells", "Orchestral percussion"], "common_mistakes": ["Gripping the metal frame so it cannot ring freely", "Forgetting to damp, so the note sustains past its written length", "Using a beater far too heavy or light for the required dynamic"], "scenario_contexts": ["Playing a single bright accent in an orchestral tutti", "Executing a fast trill inside a corner for a crescendo", "Adding shimmer to a pop or film percussion track"]}, "2d15c907-dd02-4d64-9a80-8d2593ad2317": {"definition": "Tubular bell resonance is the long, bell-like ringing decay of a struck orchestral chime, a tuned metal tube sounded at its top cap; it is marked by strong sustain and a complex, inharmonic overtone spectrum whose perceived pitch (the 'strike note') is heard against those partials, and it is held or stopped with a foot damper.", "plain_english": "Tubular bells are long metal tubes you hit at the top to make a church-bell sound. Their 'resonance' is the long ringing that keeps sounding after the hit until a pedal stops it.", "purpose_function": "The long resonance imitates real church or clock bells and lets single notes ring through an ensemble, so composers use the sustain for chimes, tolling effects, and grand accents.", "practical_application": "A percussionist strikes the tube's top cap with a rawhide mallet and uses the foot-operated damper pedal to sustain or cut off the ring, matching the note lengths in the score.", "category": "Tuned percussion", "related_terms": ["Chimes", "Idiophone", "Damper pedal", "Strike note", "Glockenspiel"], "common_mistakes": ["Striking the body of the tube instead of the top cap, which weakens the tone", "Ignoring the damper pedal so successive notes ring into each other", "Assuming the pitch is pure when strong inharmonic partials color the sound"], "scenario_contexts": ["Playing tolling bell notes in a symphonic finale", "Sounding a clock-chime effect in a film score", "Sustaining a single chime accent with the damper pedal in a wind ensemble"]}, "4af17768-5faa-45ae-9e72-e467e264b6b5": {"definition": "The udu bass, or 'whoomp', is the deep, low-pitched tone of the Nigerian (Igbo) udu clay pot drum, produced by quickly striking or slapping the palm over the side hole so the sudden change in the enclosed air excites the vessel's air-cavity (Helmholtz) resonance.", "plain_english": "The udu is a clay pot drum with a hole in its side. Hitting or covering that hole with your palm makes a deep, hollow 'whoomp', a bit like blowing across a bottle but much lower.", "purpose_function": "The bass whoomp gives the udu its signature low pulse, letting a single clay pot supply a bass-drum-like foundation for grooves without any drumhead or skin.", "practical_application": "A percussionist seats the pot in the lap and pops the side hole with the palm on downbeats to lay a deep bass groove, nudging the pitch by how fully the hole is covered.", "category": "Drum stroke", "related_terms": ["Udu finger tone", "Helmholtz resonance", "Ghatam", "Idiophone", "Hand percussion"], "common_mistakes": ["Striking too softly to trigger the air-cavity whoomp", "Cupping the hand loosely so air leaks and the bass note weakens", "Confusing the side-hole bass tone with lighter finger tones on the body"], "scenario_contexts": ["Laying a bass pulse in a world or ambient percussion track", "Standing in for a kick drum in acoustic, unplugged settings", "Bending the bass pitch live by varying palm coverage of the hole"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"d5d9a5a4-3faa-43fd-a00c-a0b09b2c54e6": {"definition": "Udu finger tone refers to the higher, drier percussive sounds of the udu clay pot, produced by tapping the vessel's body, neck, and the rims of its openings with the fingertips, giving light clicks and pitched taps that contrast with the deep side-hole bass.", "plain_english": "Udu finger tones are the light, high taps you make by tapping the clay pot's body and rims with your fingers. They sound like quick, dry clicks and pings.", "purpose_function": "These finger sounds add rhythmic detail and higher-pitched color on top of the udu's bass, letting one pot cover both the low pulse and the busy top end of a groove.", "practical_application": "A player taps the pot's shoulder, neck, and hole rims with individual fingers for ghost notes and ornaments between the bass slaps, shaping a full rhythmic pattern on one instrument.", "category": "Drum stroke", "related_terms": ["Udu bass (whoomp)", "Ghatam", "Idiophone", "Ghost note", "Hand percussion"], "common_mistakes": ["Hitting too hard and cracking the fired clay", "Playing only finger tones and neglecting the contrasting bass", "Wearing rings or long nails that click harshly or scratch the surface"], "scenario_contexts": ["Adding ghost-note ornaments between bass slaps in a groove", "Playing intricate top-end patterns in a solo udu piece", "Layering dry clicks in a studio percussion overdub"]}, "bf5c389b-d083-4558-8689-7cf7669de3a4": {"definition": "The vibraphone motor is an electric motor mounted on the instrument that slowly rotates the fan-shaped discs (butterfly valves) seated in the tops of the resonator tubes; as the discs open and close the tube mouths, they periodically vary the coupling between bar and resonator, producing the vibraphone's signature pulsing vibrato (tremolo).", "plain_english": "The vibraphone motor is a small electric motor that spins little fans inside the metal tubes under the bars. The fans open and close the tubes. This makes the notes throb, giving the wobbly, shimmering vibraphone sound.", "purpose_function": "The motor exists to create the vibraphone's vibrato by rhythmically opening and closing the resonators; a speed control sets how fast the pulse is, and switching the motor off gives a plain, straight sustain.", "practical_application": "A vibraphonist plugs in the motor, sets its speed to taste (slow shimmer to fast tremolo) or turns it off for straight tones, and uses the damper pedal alongside it to shape sustain.", "category": "Instrument component", "related_terms": ["Vibraphone", "Resonator", "Tremolo", "Damper pedal", "Mallet percussion"], "common_mistakes": ["Thinking the motor changes pitch, when it only pulses the volume and timbre (vibrato)", "Leaving the motor running for passages meant to be played with it off", "UNSAFE: running the motor from a damaged mains cord or an ungrounded outlet instead of inspecting the cord and using a properly grounded supply"], "scenario_contexts": ["Setting a slow motor speed for a ballad's shimmer", "Turning the motor off for a dry, sustained chorale passage", "Matching motor speed to the tempo for a rhythmic tremolo effect"]}, "9316c34a-c340-4b58-bd6e-ce835e86d948": {"definition": "The pulsing tremolo effect produced by a vibraphone's motor-driven rotating discs (fans) fitted at the tops of its resonator tubes; as the discs spin they alternately open and close the resonators, cyclically varying the amplitude of each sustaining note. Motor speed sets the rate (roughly 1-12 Hz), and the motor can be switched off for a plain, steady tone.", "plain_english": "It is the wavering, pulsing sound of a vibraphone. A small motor spins discs inside the tubes under the bars. They open and close, so each note gets louder and softer over and over, like a slow shimmer.", "purpose_function": "It gives the vibraphone its signature shimmering sustain, adding motion to held notes, and the variable-speed motor lets a player match the vibrato rate to the music or switch it off entirely.", "practical_application": "A player sets the motor speed to taste while an engineer mikes the instrument; because the effect is acoustic amplitude modulation it must be captured at the source rather than added convincingly afterward.", "category": "Mallet Percussion", "related_terms": ["Vibraphone", "Tremolo", "Amplitude modulation", "Resonator", "Marimba", "Sustain pedal"], "common_mistakes": ["Calling the effect true vibrato when it is actually tremolo (amplitude modulation), not a change in pitch.", "Assuming the spinning discs change the pitch of the bars; they only vary how strongly the resonators reinforce each note.", "Setting the motor very fast and expecting a classic sound, when most classic parts use a slow rate or no motor at all."], "scenario_contexts": ["Recording a jazz vibraphone solo and choosing a slow motor speed for a warm, shimmering sustain.", "Performing a classical mallet part with the motor switched off for a clean, steady tone.", "Miking a vibraphone in a live band and blending both sides of the bars to capture the vibrato evenly."]}, "78e33f09-30f2-458c-a6ff-f25e5b439aba": {"definition": "The rattling, buzzing sustain of a vibraslap, a percussion instrument descended from the quijada (donkey jawbone). Striking the wooden ball on its bent metal rod jars a set of loose pins or rivets held in a hollow resonating box, which vibrate against the box to produce a sharp crack followed by a long, dry buzz.", "plain_english": "It is the loud, rattling sound a vibraslap makes. You hit the wooden ball, and loose metal pins inside a wooden box shake and buzz. It is like a fast wooden rattle that slowly fades.", "purpose_function": "The buzz delivers a sudden accent with a long, decaying rattle, used to punctuate hits and transitions where a plain, short strike would not carry enough character.", "practical_application": "A percussionist holds the metal rod loosely and slaps the ball with the palm, then lifts or damps the instrument to control how long the buzz rings; engineers pad the channel because the initial crack is very loud.", "category": "Auxiliary Percussion", "related_terms": ["Vibraslap", "Quijada", "Cabasa", "Guiro", "Rattle", "Auxiliary percussion"], "common_mistakes": ["Gripping the metal rod tightly, which chokes the buzz and shortens the sustain.", "Striking the wooden box instead of the ball, which produces a weak, uneven rattle.", "Forgetting that the initial crack is very loud, then clipping the channel or startling nearby microphones."], "scenario_contexts": ["Adding a rattling accent at the end of a phrase in a Latin or pop percussion arrangement.", "Using the vibraslap for a comedic or dramatic shudder effect in film or theatre sound.", "Layering a short buzzing hit into a drum track to mark a transition or fill."]}, "61accdd6-c06f-4d94-8932-cd7c8f917326": {"definition": "The sharp, dry transient that begins a wood block's sound. A wood block is a hollow, slotted hardwood block; struck with a stick or hard mallet it produces a bright, high click with a very fast onset and short decay, giving it one of the crispest attacks in the percussion section.", "plain_english": "It is the quick, hard knock you hear the instant a wood block is hit. The sound starts almost at once and dies away fast. Think of the sharp click of a clock tick, but louder and more woody.", "purpose_function": "The fast, clear attack lets a wood block cut through a mix and mark rhythm precisely, which is why it is used for clave patterns, sound effects, and tight rhythmic accents.", "practical_application": "Because the attack is so fast and loud, an engineer uses a microphone that tracks quick transients and may trim the fader or add light compression so the click sits in the mix without spiking the meters.", "category": "Auxiliary Percussion", "related_terms": ["Wood block", "Transient", "Attack", "Temple blocks", "Claves", "Auxiliary percussion"], "common_mistakes": ["Confusing the wood block's attack with its pitch; the sharp onset is a timing and transient feature, not the note's fundamental.", "Over-compressing the channel, which softens the very transient that makes the wood block useful.", "Miking too far away, so the crisp attack is lost and only a dull thud remains."], "scenario_contexts": ["Recording a clave or wood block part where the crisp attack must line up tightly with the beat.", "Reinforcing a percussion section live and keeping the wood block's click audible over a loud band.", "Using a wood block hit as a sharp sound effect, such as a knock or clock tick, in post production."]}, "b0ba911f-68fa-4666-ad5c-adfd0866bd19": {"definition": "The bright, sharp onset of a xylophone note. The xylophone's hard rosewood or synthetic bars, struck with hard mallets, produce a fast, percussive attack and short sustain; the bars are quint-tuned (the strong overtone a twelfth above the fundamental), reinforcing the brilliant, brittle character of the attack.", "plain_english": "It is the bright, hard ping at the start of each xylophone note. The wooden bars are hit with hard mallets, so the sound jumps out fast and fades quickly. It sounds sharper and drier than a marimba.", "purpose_function": "The strong attack makes the xylophone cut clearly through an ensemble and articulate fast passages, which is why it is chosen for crisp, bright melodic lines and rhythmic figures.", "practical_application": "An engineer mikes the xylophone to capture the bright transient without harshness, often adding distance or a slight high-frequency roll-off to tame the sharp attack in a dense mix.", "category": "Mallet Percussion", "related_terms": ["Xylophone", "Transient", "Marimba", "Glockenspiel", "Mallet", "Attack"], "common_mistakes": ["Confusing the xylophone with the marimba; the xylophone has a brighter, drier, sharper attack and a higher range.", "Using soft mallets and expecting the characteristic sharp attack, when hard mallets are what create it.", "Boosting high frequencies to add brightness, which can make the already sharp attack harsh and brittle."], "scenario_contexts": ["Recording a fast xylophone melody where each note's sharp attack must stay clean and distinct.", "Mixing a xylophone into an orchestral track and controlling its bright transient so it cuts without piercing.", "Reinforcing xylophone in live musical theatre so its articulation is heard over the pit."]}, "f629f1e4-b345-4e4d-b4ad-dfc90b458409": {"definition": "In wind and reed instruments and pipe organs, air leakage is the unintended escape of air through imperfect seals — such as woodwind key pads and joint corks, organ windchest and pipe-foot joints, or a bagpipe bag, valve, or stock — reducing air-supply efficiency and causing weak tone, unstable pitch, or notes that fail to speak.", "plain_english": "Air leakage is when air escapes from an instrument through a gap it should not, like a leaky pad or a loose joint. It is a bit like a bike tire with a slow leak, so the instrument loses power and notes may not sound right.", "purpose_function": "The concept names a common fault mode, so identifying air leakage lets a player or technician find why an instrument sounds weak or will not hold pitch and then restore an airtight air path.", "practical_application": "A repair technician checks for air leakage by feeling or listening for escaping air, using a leak light or feeler gauge on woodwind pads or soaping organ joints, then reseats pads or reseals joints.", "category": "Air-supply fault", "related_terms": ["Bellows air noise", "Air-button hiss", "Bagpipe moisture noise", "Reed", "Windchest"], "common_mistakes": ["Confusing intentional air sounds, like an accordion air button, with an actual leak.", "Blaming weak tone on the player's breath when a leaking pad or joint is the real cause.", "Overtightening joints or key screws to stop a leak, which can bend keys or crack wood."], "scenario_contexts": ["A saxophone's low notes will not speak because a pad is not sealing and air leaks past it.", "An organ rank sounds weak and breathy due to a leaking windchest joint.", "A bagpiper struggles to keep the bag inflated because a stock or valve is leaking."]}, "9870cc69-47f4-4aef-b454-13249016eb6f": {"definition": "The audible rush of air, heard as a hiss, produced when an accordion's air button (air-release valve) is pressed to move the bellows without sounding any reeds; on close-miked recordings it can appear as unwanted noise between or beneath notes.", "plain_english": "On an accordion, the air button lets the player open the bellows without playing a note. The air that escapes makes a soft hiss. Up close a mic can pick it up, like the sound of blowing gently across your hand.", "purpose_function": "Naming this hiss helps a recording engineer expect and manage the noise that comes from normal accordion bellows handling rather than mistaking it for a fault.", "practical_application": "An engineer recording accordion positions or angles the mic and may use gating or editing to reduce air-button hiss captured during bellows resets.", "category": "Recording artifact", "related_terms": ["Bellows air noise", "Air leakage", "Bagpipe moisture noise", "Noise gate", "Close miking"], "common_mistakes": ["Mistaking normal air-button hiss for a broken reed or an instrument leak.", "Gating too hard so quiet real notes are cut along with the hiss.", "Placing the mic right at the bellows seam, which exaggerates the hiss."], "scenario_contexts": ["A studio take of solo accordion shows a soft hiss each time the player resets the bellows.", "A live sound engineer hears hiss through a clip-on accordion mic during quiet passages.", "A composer asks for the air-button whoosh as an intentional effect, so the engineer keeps it."]}, "68e3d066-b705-45e6-bdbb-d93b38269791": {"definition": "The alphorn-fa is the note produced by the 11th harmonic (11th partial) of a natural, valveless labrosone such as the alphorn or natural horn; relative to the instrument's harmonic series it falls about a quarter-tone between F and F-sharp and sounds distinctly out of tune to ears expecting equal temperament.", "plain_english": "On an alphorn you can only play the notes of the natural harmonic series, and one of them, the 11th, sits halfway between F and F-sharp. This alphorn-fa sounds oddly out of tune to us, like a note stuck between two piano keys.", "purpose_function": "The term identifies a characteristic pitch of natural brass and alphorn music, explaining why some traditional melodies use a note that falls outside the standard scale.", "practical_application": "A player or arranger uses the alphorn-fa knowingly as part of the instrument's authentic sound, and a recording engineer or transcriber recognizes it as intended rather than a tuning error to correct.", "category": "Harmonics", "related_terms": ["Harmonic series", "Natural horn", "Partial", "Overblowing", "Just intonation"], "common_mistakes": ["Thinking the alphorn-fa is simply an F or F-sharp played out of tune by mistake.", "Trying to correct the note in tuning software when it is a genuine feature of the harmonic series.", "Confusing it with the flat 7th partial, which is a different out-of-tune harmonic."], "scenario_contexts": ["A folk melody for alphorn deliberately features the alphorn-fa as its signature color.", "An engineer transcribing a natural-horn part must decide how to notate the 11th-partial note.", "A student overblows a valveless horn and lands on the alphorn-fa between F and F-sharp."]}, "fafee9aa-5be9-42ac-8247-5e269a7cbe47": {"definition": "The chanter is the melody pipe of a bagpipe, fitted with fingerholes and driven by a reed (a double reed on Great Highland pipes), on which the player fingers the tune while the bag supplies a continuous air stream.", "plain_english": "The chanter is the part of the bagpipe you play the tune on, using finger holes like a recorder. A reed inside makes the sound, and the bag keeps feeding it air so the notes never stop for a breath.", "purpose_function": "The chanter carries the melody of the instrument, and its reed and fingerholes set the pitch range and scale of the bagpipe.", "practical_application": "A piper tunes and maintains the chanter reed and hole taping, and a sound engineer usually aims the main melody mic at the chanter.", "category": "Instrument component", "related_terms": ["Bagpipe drone", "Bagpipe drones", "Reed", "Double reed", "Blowpipe"], "common_mistakes": ["Confusing the chanter, which plays the melody, with a drone, which holds one fixed note.", "Assuming the chanter can be silenced on its own like a woodwind; it sounds whenever the bag has air.", "Aiming the microphone at the bag or drones instead of the chanter for the melody."], "scenario_contexts": ["A piper swaps to a softer chanter reed for indoor recording.", "A sound engineer close-mics the chanter to capture the melody clearly over the drones.", "A pipe band tunes each chanter to a common pitch before a performance."]}, "21a91736-3efe-4405-a273-53890c69a69b": {"definition": "A drone is a bagpipe pipe that sounds a single, fixed, continuous pitch and is not fingered, usually driven by a single reed and tuned to the tonic of the chanter to provide a constant harmonic backdrop to the melody.", "plain_english": "A drone is a bagpipe pipe that plays just one steady note the whole time, with no finger holes. It sits under the tune like a held bass note, giving that classic droning bagpipe sound.", "purpose_function": "The drone supplies a constant reference pitch and sustained harmony against which the chanter's melody is heard.", "practical_application": "A piper tunes each drone by sliding its joints so it matches the chanter's tonic, and an engineer may add a separate mic or accept spill to balance drones against the melody.", "category": "Instrument component", "related_terms": ["Bagpipe drones", "Bagpipe chanter", "Reed", "Tonic", "Blowpipe"], "common_mistakes": ["Thinking the drone can play a melody; it holds only one fixed pitch.", "Leaving a drone slightly out of tune with the chanter, which sounds sour.", "Corking off a drone but forgetting it changes the overall balance."], "scenario_contexts": ["A piper tunes the bass drone to the low A of the chanter before playing.", "An engineer notices one drone beating against the chanter and asks the piper to retune.", "A solo piper corks two drones to record with a single drone for a thinner texture."]}, "4d3e59e0-1272-4151-83f4-2b7b54b40d94": {"definition": "The drones are the set of fixed-pitch, non-fingered pipes on a bagpipe (typically two tenor and one bass on the Great Highland bagpipe), each driven by its own reed and tuned in octaves to the chanter's tonic so they sound together as a sustained chord beneath the melody.", "plain_english": "The drones are the group of pipes on a bagpipe that each hold one steady note. Together they add a full, humming background under the tune, usually tuned to the same note in different octaves.", "purpose_function": "As a group the drones create the bagpipe's signature sustained harmony and fix the tonal center of the music.", "practical_application": "A piper tunes all the drones to lock with the chanter and with each other, and a sound engineer balances the drones' low hum against the chanter melody in the mix.", "category": "Instrument component", "related_terms": ["Bagpipe drone", "Bagpipe chanter", "Reed", "Tonic", "Octave"], "common_mistakes": ["Tuning the drones to each other but not to the chanter.", "Assuming every bagpipe has three drones; the number varies by type.", "Miking only the drones and losing melody detail from the chanter."], "scenario_contexts": ["A pipe band lines up so all players' drones sound as one steady chord.", "An engineer sets a room mic to capture the blended drones of a full band.", "A piper corks one tenor drone to change the drone texture."]}, "99e4f7ab-0dd5-4a68-a9ce-7078c6ef793c": {"definition": "The gurgling, burbling, or unstable sounds caused by condensed moisture from the player's breath collecting in a bagpipe's bag, reeds, and bores, which disturbs reed vibration and can be captured as unwanted noise on close-miked recordings.", "plain_english": "When a piper blows into the bag, warm breath leaves moisture inside, and that wet build-up makes gurgling or crackly sounds. It can make reeds sound rough, a bit like blowing bubbles through a straw in a drink.", "purpose_function": "Naming this noise helps players and engineers spot moisture as the cause of gurgling or reed instability and take steps to control it.", "practical_application": "Pipers fit moisture traps or drying agents and let the instrument dry out, while engineers may edit or gate stray gurgles from a recording.", "category": "Recording artifact", "related_terms": ["Air leakage", "Bellows air noise", "Reed", "Bagpipe drone", "Close miking"], "common_mistakes": ["Blaming a rough reed when trapped moisture is the real cause.", "Ignoring moisture buildup until a reed stops speaking during a performance.", "Over-editing natural playing sounds while chasing every small gurgle."], "scenario_contexts": ["A long studio session leaves the bag damp, so gurgling appears in later takes.", "A piper's drone reed becomes unstable outdoors on a cold day from condensation.", "An engineer hears burbling under quiet passages and asks the piper to dry the reeds."]}, "8ce432fd-5899-448a-ab81-101913eae9cc": {"definition": "The brief, breathy transient heard at the onset of a note on a bansuri (a side-blown Indian bamboo flute), produced as the player's air jet first strikes the sharp edge of the blowing hole before a stable tone forms; \"chiff\" is a term borrowed from organ flue-pipe voicing for this attack noise.", "plain_english": "When a bansuri player starts a note, the breath hits the sharp edge of the blow hole and makes a soft puff before the clear note settles. This little breathy attack is called chiff, like the burst of air at the start of the word who.", "purpose_function": "The term describes a natural attack transient that gives the bansuri its breathy, expressive character and signals how a note begins.", "practical_application": "A recording engineer places and angles the mic to capture a pleasing amount of edge chiff without harsh wind blasts, and a player controls breath to shape it.", "category": "Attack transient", "related_terms": ["Chiff", "Edge tone", "Embouchure", "Attack transient", "Air jet"], "common_mistakes": ["Treating all chiff as a flaw and gating it away, which removes natural expression.", "Confusing chiff with wind pops that come from breath hitting the mic.", "Blowing too hard so the chiff turns into harsh wind noise."], "scenario_contexts": ["A film composer wants an intimate bansuri with just a touch of edge chiff.", "An engineer moves the mic off-axis to soften strong chiff on loud attacks.", "A student learns to control breath so each note's chiff is even."]}, "3c6780dd-919f-450a-b025-0ee96db9c3cb": {"definition": "The broadband rushing or whooshing sound produced by air moving through and around the bellows and wind path of a bellows-driven instrument (accordion, concertina, harmonium or reed organ, or an organ blower system), heard separately from the musical tone and often captured as noise on close-miked recordings.", "plain_english": "Instruments like accordions and reed organs push air with bellows, and that moving air makes a soft rushing sound of its own. Up close a mic can pick it up, a bit like the hiss you hear when you squeeze an air pump.", "purpose_function": "Naming this noise helps engineers separate normal air-handling sound from musical tone and manage it during recording.", "practical_application": "An engineer chooses mic placement and may use gating or editing to control bellows air noise, or keeps it when a natural, intimate sound is wanted.", "category": "Recording artifact", "related_terms": ["Air-button hiss", "Air leakage", "Bagpipe moisture noise", "Reed", "Close miking"], "common_mistakes": ["Mistaking normal bellows air noise for an air leak or fault.", "Placing the mic directly at the bellows fold, which exaggerates the noise.", "Gating so aggressively that soft note tails are lost with the noise."], "scenario_contexts": ["A close-miked accordion recording shows steady air rush under sustained chords.", "A harmonium track in a quiet mix reveals bellows noise that needs gentle editing.", "An engineer keeps some bellows noise on a folk recording for a natural feel."]}, "2525ea55-186a-433d-9482-27703aaffcc1": {"definition": "The mechanical and air-related sound produced by the bellows of a free-reed instrument (accordion, concertina, bandoneon) or the wind-raising bellows of an organ or harmonium, including the hiss of escaping air, valve clatter, and the creak or thump of the folds as they open and close. It is an incidental noise, distinct from the musical tone, and is most noticeable at direction changes and under close microphone placement.", "plain_english": "This is the puffing, hissing, or creaking sound a bellows makes as it pushes air, apart from the notes themselves. It is like the whoosh you hear when you squeeze a fireplace bellows.", "purpose_function": "It is an unwanted byproduct of moving air through a bellows; recognizing it helps a technician judge instrument condition and control how much of it reaches a recording.", "practical_application": "When close-miking an accordion, concertina, or chamber organ, a technician positions and angles microphones to capture the reeds or pipes while minimizing bellows hiss and mechanical thumps.", "category": "Instrument noise", "related_terms": ["Bellows shake (rale)", "Blower rumble", "Free reed", "Reed valve", "Wind noise", "Close miking"], "common_mistakes": ["Assuming all bellows noise is a fault when some is normal to the instrument", "Placing a microphone right at the bellows seam, which exaggerates air hiss and valve clatter", "Confusing bellows air hiss with reed or pipe speech noise"], "scenario_contexts": ["Close-miking an accordion for a studio folk session", "Recording a chamber organ or harmonium where the hand-pumped bellows is audible", "Editing out bellows thumps at direction changes in a solo recording"]}, "9c9b30a5-a7b1-46ee-9a85-3e6e97140ddb": {"definition": "An accordion (and concertina/bandoneon) technique in which the player rapidly reverses the direction of the bellows while holding one or more keys, rearticulating the sustained note into a fast, even tremolo or rhythmic pulsation. The pitch stays constant while the bellows motion supplies repeated attacks, producing a shimmering or driving rhythmic effect.", "plain_english": "The player wiggles the bellows quickly back and forth while holding a note, so the note pulses fast instead of staying flat. It works a bit like flicking a light on and off fast to make one steady light seem to flutter.", "purpose_function": "It lets a bellows-driven instrument, which cannot re-strike a note from the keys alone, add rhythmic drive and a tremolo-like accent to a held chord.", "practical_application": "A player uses the bellows shake for energetic passages in forro, musette, and folk styles; a technician recording it watches levels because each shake adds a burst of transient energy and bellows noise.", "category": "Bellows technique", "related_terms": ["Bellows noise", "Tremolo", "Free reed", "Accordion", "Articulation", "Circular-breathing drone"], "common_mistakes": ["Thinking the shake changes pitch when only the attack pattern changes", "Confusing the bellows shake with keyboard tremolo, which the accordion cannot produce", "Shaking so hard the reeds choke or the pitch bends from pressure spikes"], "scenario_contexts": ["A forro accordionist driving a fast dance groove", "A French musette waltz adding rhythmic shimmer to a held chord", "Miking an accordion solo where bellows-shake transients must not clip"]}, "933c1a24-ea14-4cb9-89d1-e928b76f0895": {"definition": "A harp technique (Italian for 'whispering') in which a note or chord is repeated very softly and rapidly, usually by alternating the fingers of both hands near the soundboard, to create a delicate, murmuring tremolo. It is marked with the word 'bisbigliando' (often abbreviated 'bisb.') and a wavy line, and is played at a low dynamic.", "plain_english": "On the harp, this is a soft, fast fluttering of a note or chord that sounds like a whisper. The player gently trades the strings between both hands to make it shimmer quietly.", "purpose_function": "It gives the harp a sustained, veiled shimmer on a held note, since a plucked string quickly fades; it exists to add quiet color and atmosphere.", "practical_application": "An arranger writes bisbigliando for a hushed background wash, and an engineer captures it with a sensitive, low-noise microphone setup because the effect lives at very low levels.", "category": "Harp technique", "related_terms": ["Tremolo", "Harp harmonics", "Glissando", "Arpeggio", "Pres de la table", "Dynamics"], "common_mistakes": ["Playing it too loudly, which destroys the whispered character", "Treating it as a strict measured tremolo instead of a free, rapid shimmer", "Assuming it is a wind or organ effect because of the topic label, when it is a harp technique"], "scenario_contexts": ["Orchestrating a quiet, atmospheric harp background", "A harpist sustaining a soft chord under a solo melody", "Recording delicate harp textures at very low dynamic levels"]}, "d328e202-d189-40d3-8972-b57837a85eae": {"definition": "A low-frequency noise in a pipe organ (or other blown instrument) caused by the electric wind blower and its motor, transmitted through the wind trunks, reservoir, and building structure into the pipe chamber or room. It appears as a steady low hum or rumble beneath the musical sound, separate from the pipe tone itself.", "plain_english": "This is the low humming or rumbling sound an organ air blower makes, heard under the music. It is like the background drone of a fan or furnace running in another room.", "purpose_function": "It is unwanted mechanical and airflow noise from the blower that supplies the organ's wind; identifying it helps a technician keep it out of recordings and diagnose wind-system problems.", "practical_application": "When recording a pipe organ, an engineer uses high-pass filtering and careful microphone placement to reduce blower rumble, and a technician may check for loose ducting or a failing motor bearing if it grows louder.", "category": "Wind-supply noise", "related_terms": ["Bellows noise", "Wind supply", "Reservoir", "Rumble", "High-pass filter", "Pipe organ"], "common_mistakes": ["UNSAFE: Opening or servicing a running blower or its electrical motor without locking out and tagging out power, risking shock or injury from live parts and moving blades", "Mistaking blower rumble for a low pedal pipe or room HVAC noise", "Trying to fix rumble only with EQ when the microphone is placed too near the blower or wind trunks"], "scenario_contexts": ["Recording a church pipe organ where blower rumble intrudes on quiet passages", "Diagnosing a new low-frequency hum after blower maintenance", "Setting up microphones in an organ loft to avoid the blower and wind trunks"]}, "e9b87b2c-4460-4c85-8df7-bd79ccf40fce": {"definition": "A raspy, buzzing 'raspberry' used as a comic or derisive effect, produced on a brass instrument by buzzing the lips very loosely and slackly into the mouthpiece so the tone breaks up into a flabby, uncontrolled buzz rather than a clear pitch. Vocally it is the familiar lip 'raspberry'; on brass it is the deliberately unfocused, sputtering counterpart.", "plain_english": "This is the rude raspberry buzzing sound, like a fake fart noise. On a brass instrument the player makes it by letting the lips flap loosely into the mouthpiece instead of buzzing a clean note.", "purpose_function": "It provides a humorous, rude, or gritty special effect, and a loose-lip 'free buzz' that brass players also use to relax and warm up the embouchure.", "practical_application": "A composer may call for a Bronx cheer in a novelty or cartoon-style passage, and brass players also free-buzz a raspberry as a warm-up to loosen the lips.", "category": "Brass technique", "related_terms": ["Flutter tonguing", "Growl", "Lip buzz", "Embouchure", "Mute", "Conch blast"], "common_mistakes": ["Trying to force a clear pitch, which the effect deliberately avoids", "Confusing it with flutter tonguing, which uses a rolled tongue rather than loose lips", "Over-relying on loose free-buzzing so the working embouchure weakens"], "scenario_contexts": ["A novelty or comedic brass passage calling for a rude effect", "A brass player free-buzzing a raspberry during warm-up", "A jazz or theatrical setting adding a derisive 'razz'"]}, "c591e0c8-71b4-48ba-9d6f-56ad86e2d587": {"definition": "On a bagpipe chanter, the brief, breathy 'chiff' - a short transient of noise at the very start of a note - created when a grace note (a fast finger movement, or 'gracing') articulates and separates otherwise continuous notes. Because the chanter sounds without pause, gracings inject these tiny chiffs to mark note beginnings, functioning like tonguing on other wind instruments.", "plain_english": "On bagpipes the notes never stop, so players flick quick grace notes to separate them. Each flick makes a tiny puff at the note start, called a chiff, a bit like the little t sound of tonguing a flute.", "purpose_function": "The chiff from gracing gives note definition and rhythm on an instrument that cannot stop or tongue, so listeners hear separate, articulated notes instead of one smeared drone.", "practical_application": "A piper practices crisp gracings so each chiff is clean, and an engineer close-miking a chanter captures these transients, which carry the tune's rhythmic clarity.", "category": "Bagpipe articulation", "related_terms": ["Grace note", "Chanter", "Drone", "Articulation", "Embellishment", "Circular-breathing drone"], "common_mistakes": ["Playing gracings too slowly so they sound like real melody notes instead of quick chiffs", "Thinking the chanter can be tongued or stopped like a flute", "Miking only the drones and missing the chanter chiffs that carry the rhythm"], "scenario_contexts": ["A Highland piper articulating a fast reel with crisp gracings", "Teaching a beginner why grace notes replace tonguing", "Close-miking a solo chanter so its gracing chiffs stay clear"]}, "2320559d-1d89-4cd1-b111-2937e18c915c": {"definition": "A continuous, unbroken sustained tone (drone) produced on a wind instrument by circular breathing: the player pushes stored air from the puffed cheeks to keep the instrument sounding while quickly inhaling through the nose, so the note never stops. It is central to instruments such as the didgeridoo, launeddas, and zurna, and to drone accompaniments on double reeds.", "plain_english": "This is a wind note that goes on and on with no break, because the player breathes in through the nose while pushing air out from the cheeks. It works like a bagpipe bag holding air, but the cheeks do the storing.", "purpose_function": "It lets a single player hold an endless drone or line without pausing to breathe, providing a steady harmonic foundation under a melody.", "practical_application": "A didgeridoo or duduk player circular-breathes to hold a drone for minutes, and a technician records it knowing there is no natural breath gap to edit or punch in at.", "category": "Breathing technique", "related_terms": ["Circular breathing", "Drone", "Dam drone (duduk)", "Didgeridoo", "Embouchure", "Double reed"], "common_mistakes": ["Believing the player never inhales, when they inhale through the nose during the cheek push", "Letting the tone dip or waver at the cheek-to-lung switch", "Expecting a breath gap to edit at, when the drone is deliberately seamless"], "scenario_contexts": ["A didgeridoo player holding a long continuous drone", "A duduk 'dam' player sustaining an accompaniment", "Recording a seamless drone with no breath points for edits"]}, "ff04cceb-c4bc-434f-b208-a377a1bab663": {"definition": "The loud, sustained tone sounded on a conch-shell (or other shell) trumpet, produced by buzzing the lips into a hole cut at the shell's apex or side, exactly as on a natural brass horn. The shell's conical cavity fixes the pitch, and players typically sound one strong note used for signaling or ceremony.", "plain_english": "This is the deep, powerful note made by blowing into a large seashell like a horn. The player buzzes their lips into a hole in the shell, and it rings out one loud tone, often used to call people together.", "purpose_function": "It turns a shell into a natural lip-blown horn for signaling, ceremony, or ritual, carrying a strong tone over long distances.", "practical_application": "In ceremonial or world-music recordings, a technician captures the conch blast knowing it is a loud natural horn tone with a strong attack and a very limited pitch range.", "category": "Shell-trumpet sound", "related_terms": ["Shell trumpet", "Natural horn", "Embouchure", "Lip buzz", "Harmonic series", "Bronx cheer/raspberry"], "common_mistakes": ["Thinking the conch has valves or holes to change pitch, when it plays essentially one natural tone", "Blowing without a firm lip buzz, which produces only breathy air", "Underestimating its loudness and overloading a close microphone"], "scenario_contexts": ["A ceremonial conch call in ritual or theatrical music", "A world-music session featuring a shell trumpet", "Herald or signal effects requiring a natural horn blast"]}, "8742c63d-e031-4915-9afb-69be04dcc36e": {"definition": "The sustained drone ('dam') that underlies Armenian duduk music, held continuously on a second duduk by an accompanist using circular breathing while the lead player performs the melody. The dam is usually the tonic and sometimes shifts pitch to follow the mode, giving the music its steady harmonic ground.", "plain_english": "In Armenian duduk music, a second player holds one long, unbroken note called the dam while the first plays the tune over it. The dam is the steady background hum that the melody floats on top of.", "purpose_function": "The dam supplies a constant tonal center and drone, anchoring the melody's mode and creating the duduk's deep, sustained atmosphere.", "practical_application": "In an ensemble recording, the dam player is often given a separate microphone and holds the drone by circular breathing, so the engineer balances a steady low line against the moving melody duduk.", "category": "Drone technique", "related_terms": ["Circular-breathing drone", "Drone", "Duduk", "Tonic", "Double reed", "Chanter gracing chiff"], "common_mistakes": ["Assuming the dam is a machine or bag drone, when a live player holds it by circular breathing", "Thinking the dam is always a fixed pitch, when it can shift to follow the mode", "Miking only the melody duduk and losing the dam's supporting drone"], "scenario_contexts": ["A traditional Armenian duduk duo with lead and dam players", "Film-score sessions using duduk for a mournful, drone-based mood", "Balancing a sustained dam under an expressive melody line in a mix"]}, "152229c8-c776-4ef0-839d-06c3f269fa32": {"definition": "The continuous low fundamental tone of the didgeridoo, a lip-blown Australian Aboriginal wooden or bamboo tube sounded by loosely buzzing the lips into one end. The player sustains it indefinitely by circular breathing, and the tube's length fixes the drone's pitch while the vocal tract shapes its timbre.", "plain_english": "This is the deep, steady humming note that a didgeridoo makes without stopping. The player buzzes their lips into the long tube, and the same low tone rings out over and over, like a constant hum.", "purpose_function": "It provides the sustained tonal and rhythmic foundation of didgeridoo playing, over which the player layers overtone, vocal, and rhythmic effects.", "practical_application": "When recording a didgeridoo, a technician expects a strong, sustained low fundamental with heavy low-frequency energy and no natural breath gaps, and places and equalizes microphones accordingly.", "category": "Instrument sound", "related_terms": ["Didgeridoo wobble (vocalized overtone)", "Circular-breathing drone", "Drone", "Embouchure", "Lip buzz", "Fundamental frequency"], "common_mistakes": ["Thinking the drone stops for breaths, when circular breathing keeps it seamless", "Under-powering the low end so the deep fundamental is lost in a recording", "Confusing the steady fundamental drone with the overlaid vocal and overtone effects"], "scenario_contexts": ["Recording a solo didgeridoo drone for a world-music or film session", "Layering a sustained didgeridoo drone under an ambient mix", "Explaining to a student why there are no breath points to edit at"]}, "e09b0ff8-0160-4b8e-bc7d-648f5edc18d6": {"definition": "The characteristic rhythmic, wah-like timbral modulation of a didgeridoo, produced by the player altering the vocal-tract shape (tongue, jaw, cheeks) and adding vocalizations such as hums, calls, or vowel sounds over the sustained drone. These changes shift the vocal-tract resonances, emphasizing different overtones of the fundamental so the drone's tone color pulses and 'wobbles' without the pitch itself changing.", "plain_english": "This is the wobbly, wah-wah change in a didgeridoo sound. The player moves the tongue and cheeks and adds voice sounds. That makes different overtones ring out over the steady drone. It is like changing your mouth shape while you hum.", "purpose_function": "It turns a single unchanging drone into a rich, evolving, rhythmic texture, which is the core expressive resource of didgeridoo playing.", "practical_application": "A player shapes the mouth and adds vocal sounds to create rhythmic wobble patterns, and an engineer captures the resulting shifting overtones and formants without smoothing them away with heavy processing.", "category": "Instrument technique", "related_terms": ["Didgeridoo drone", "Circular-breathing drone", "Overtone", "Formant", "Timbre", "Embouchure"], "common_mistakes": ["Thinking the wobble changes the pitch, when only the overtone balance and timbre change", "Assuming it is added electronically, when it comes from vocal-tract movement and vocalizations", "Over-compressing or heavily filtering the signal so the moving overtones are flattened out"], "scenario_contexts": ["Recording rhythmic didgeridoo patterns for a fusion track", "Capturing vocalized overtone effects over a sustained drone", "Teaching how tongue and vocal sounds shape the didgeridoo's tone"]}, "ced94709-9ea1-4739-ac06-67a8422b4944": {"definition": "The bright, buzzing, reedy resonance added to the tone of the Chinese dizi (bamboo transverse flute) by the dimo, a thin membrane taken from the inner skin of reed or bamboo and glued over a dedicated hole (mokong) between the embouchure and finger holes. The membrane vibrates sympathetically with the air column, enriching the sound with a nasal, penetrating buzz that is essential to the dizi's characteristic timbre.", "plain_english": "On a Chinese dizi flute, a thin skin is glued over one hole. It buzzes along with the notes and gives the flute a bright, reedy, humming edge. It works a little like the paper buzz on a kazoo.", "purpose_function": "The membrane buzz gives the dizi its distinctive bright, carrying, reedy voice; without a properly tensioned dimo the flute sounds dull and muffled.", "practical_application": "A player tunes the buzz by adjusting the membrane's tension with garlic juice or e'jiao glue, and an engineer miking a dizi captures the strong high-frequency buzz, which can sound harsh if the microphone is placed too close.", "category": "Instrument sound", "related_terms": ["Dizi", "Membrane", "Timbre", "Overtone", "Sympathetic resonance", "Embouchure"], "common_mistakes": ["Assuming the buzz is a defect or a bad reed, when it is the intended sound of the dimo membrane", "Tensioning the membrane too tightly, which kills the buzz and dulls the tone", "Miking too closely so the membrane buzz becomes harsh and shrill"], "scenario_contexts": ["Recording a solo dizi where the membrane buzz must stay bright but not harsh", "Diagnosing a dull dizi tone traced to a loose or damaged dimo", "Balancing the buzzy high end of a dizi in a traditional ensemble mix"]}, "a4f28f68-b3c1-4b53-adbe-ec3138bb802e": {"definition": "A soft, breathy, low-dynamic tone on the Armenian duduk, produced by relaxing the embouchure and using gentle breath pressure on the large double reed so that audible air blends with the pitch. As with subtone playing on other wind and reed instruments, it yields a warm, veiled, intimate sound especially in the instrument's low register, rather than a full, focused tone.", "plain_english": "This is a soft, breathy low note on the duduk, played gently so air blends with the tone. It sounds warm and hushed, like speaking in a low, airy whisper.", "purpose_function": "It gives the duduk its mournful, intimate, close-up quality at quiet dynamics, extending the instrument's expressive range downward toward near-whisper.", "practical_application": "A player uses subtone for hushed, plaintive phrases, and an engineer records it with a sensitive, low-noise microphone chain because the breathy tone sits at low level and is easily buried.", "category": "Playing technique", "related_terms": ["Dam drone (duduk)", "Duduk", "Double reed", "Embouchure", "Dynamics", "Circular-breathing drone"], "common_mistakes": ["Pushing too much breath, which turns the intimate subtone into audible hiss with little pitch", "Assuming subtone is only a saxophone term and not applicable to double-reed instruments", "Recording it too far back so the quiet, breathy detail is lost under room noise"], "scenario_contexts": ["A film-score duduk part calling for a hushed, mournful low phrase", "Close-miking a soft, breathy duduk melody in the studio", "Balancing a whisper-quiet subtone passage against a louder accompaniment"]}, "f6d445d0-1327-49e2-905f-f6cc93c63c0f": {"definition": "Incidental sound generated at the player's mouth-to-instrument interface, distinct from the musical tone, including breath hiss, air escaping around the lips or embouchure hole, lip smacks, and reed or mouthpiece contact noises. It is most audible on breathy or low-dynamic wind playing and under close microphone placement.", "plain_english": "This is the extra breath, hiss, or lip sounds a wind player makes at the mouthpiece, apart from the real notes. It is like hearing someone puff air when they blow across a bottle top.", "purpose_function": "It is an unwanted byproduct of how a wind player forms the tone; recognizing it helps a technician judge technique and control how much of it reaches a recording.", "practical_application": "When close-miking flutes, reeds, or brass, a technician angles and distances the microphone to capture the tone while minimizing breath hiss and lip noise, and may use a small amount of high-frequency control if needed.", "category": "Instrument noise", "related_terms": ["Embouchure", "Flute key noise", "Breath noise", "Close miking", "Windscreen", "Duduk subtone"], "common_mistakes": ["Placing the microphone directly in the breath stream, which exaggerates hiss and pops", "Assuming all embouchure noise is a player fault when some is normal to the instrument", "Trying to remove it entirely with EQ instead of fixing microphone placement first"], "scenario_contexts": ["Close-miking a flute where breath hiss competes with the tone", "Recording a soft, breathy reed passage in a quiet studio", "Choosing microphone angle to reduce lip and air noise on a brass solo"]}, "2d2e3b11-4b61-4ae2-a363-9e823952a5cd": {"definition": "A jazz brass and wind articulation in which the pitch drops and slides downward at the release of a note. A 'fall-off' (or 'fall') is a longer descending smear off the end of the note, produced by relaxing the embouchure, dropping valves/slide, or a chromatic finger-fall; a 'doink' is a short, quick downward drop of the same kind. The pitch trails off rather than ending cleanly.", "plain_english": "This is a jazz brass sound where a note drops and slides down as it ends. A long slide down is a fall-off, and a short quick drop is a doink. It is like your voice sliding down at the end of a word.", "purpose_function": "It adds expressive, vocal-like shaping and stylistic punctuation to the end of a note, a staple of jazz and big-band phrasing.", "practical_application": "A player reads fall-off and doink symbols in a big-band chart and executes them by lip, slide, or finger, and an engineer captures the trailing downward pitch without gating it off too early.", "category": "Brass technique", "related_terms": ["Glissando smear (trombone)", "Doit", "Scoop", "Embouchure", "Articulation", "Bend"], "common_mistakes": ["Confusing a fall-off (downward) with a doit or scoop, which move upward", "Ending the fall on a definite pitch instead of letting it trail off", "Setting a noise gate to close too fast, cutting off the tail of the fall-off"], "scenario_contexts": ["Playing a big-band shout chorus with fall-offs on accented notes", "A jazz brass section adding doinks for punctuation", "Editing a horn track so fall-off tails are not clipped by gating"]}, "670f1ed5-7333-4dab-a727-3b048b255764": {"definition": "The percussive mechanical noise made by a flute's keys and pads as they close against the tone holes, heard as clicks or thumps separate from the musical tone. It arises from the metal keywork and pad seating of a Boehm-system flute and is most noticeable in fast passages, at low dynamics, and under close microphone placement; it is sometimes used deliberately as a percussive extended technique.", "plain_english": "These are the small clicks and thumps a flute's keys and pads make as fingers press them. A close microphone can pick them up along with the music, like hearing key clicks under a voice.", "purpose_function": "It is normally an incidental byproduct of the keywork; recognizing it lets a technician control how much reaches a recording, or capture it on purpose when a composer calls for percussive key clicks.", "practical_application": "When close-miking a flute, a technician chooses microphone position and distance to keep key clacks in balance, and checks a player's pads and mechanism if the noise is unusually loud.", "category": "Instrument noise", "related_terms": ["Embouchure noise", "Flute", "Close miking", "Extended technique", "Pad", "Key click"], "common_mistakes": ["Placing the microphone right over the keywork, which exaggerates clicks and thumps", "Assuming all key noise is a fault when some is inherent to the mechanism", "Confusing normal key noise with worn pads or loose keywork that actually need service"], "scenario_contexts": ["Close-miking a flute solo where key clicks intrude on quiet passages", "Recording deliberate percussive key-click effects in contemporary music", "Diagnosing unusually loud key noise traced to worn pads"]}, "136230b8-cbed-430b-9915-88b3e732f556": {"definition": "The high, breathy overtones sounded on the fujara, a very large three-holed Slovak overtone shepherd's fipple flute, produced mainly by overblowing to jump the air column up through its natural harmonic series. Melodies are formed largely from these overblown partials above the low fundamental, and each overtone typically speaks with a soft, airy whistle at its onset.", "plain_english": "The fujara is a very long Slovak shepherd's flute. The player blows harder to jump up to high, whistling notes above the low base note. Each jump starts with an airy whistle sound.", "purpose_function": "Overblowing the harmonic series is how the fujara produces its melodic range from only three finger holes, giving it its distinctive high, whistling overtone voice over a deep drone-like fundamental.", "practical_application": "A player controls breath pressure to select and cleanly speak each overtone, and an engineer records both the deep fundamental and the airy high overtones, mindful of the breathy onset transients.", "category": "Instrument technique", "related_terms": ["Overtone", "Harmonic series", "Overblowing", "Fujara", "Fipple", "Fundamental frequency"], "common_mistakes": ["Thinking pitches come mainly from the three finger holes rather than from overblowing the harmonic series", "Using too little breath support so the overtone cracks or drops back to the fundamental", "Miking only the fipple end and missing the breathy overtone character"], "scenario_contexts": ["Recording a solo fujara featuring its overblown overtone melody", "Capturing the airy whistle onsets of each overtone in a folk session", "Explaining how a three-hole flute plays full melodies via overblowing"]}, "27ef794e-8b88-4b3f-91b0-c66b481c68c8": {"definition": "A continuous slide in pitch on the trombone (also called a 'smear'), produced by moving the slide while sustaining the tone so the pitch glides smoothly between notes with no discrete steps. A true glissando is limited to the range covered within a single harmonic (up to about a tritone across the slide positions); wider slides require a change of partial and are not fully continuous.", "plain_english": "This is the smooth slide between two notes on a trombone. The player keeps blowing and moves the slide, so the pitch glides with no gaps, like a siren swooping up or down.", "purpose_function": "It exploits the trombone's continuously variable slide to produce a smooth pitch glide for expressive, comic, or dramatic effect, something valved brass cannot do as seamlessly.", "practical_application": "A player executes a smear by moving the slide steadily while keeping the same partial, and an arranger keeps written glissandos within the roughly tritone span playable without switching harmonics.", "category": "Brass technique", "related_terms": ["Fall-off/doink", "Glissando", "Portamento", "Slide", "Harmonic series", "Trombone"], "common_mistakes": ["Writing a continuous glissando wider than one harmonic allows, which forces an audible partial change", "Confusing a smooth slide smear with a stepped chromatic run", "Moving the slide unevenly so the smear speeds up or stalls instead of gliding smoothly"], "scenario_contexts": ["A big-band or Dixieland trombone smear for comic or bluesy effect", "Notating a playable trombone glissando within one harmonic", "Recording a dramatic trombone slide in a film-score cue"]}, "2a4d6774-76d7-4c41-a670-7971442b18a1": {"definition": "A rough, gravelly tone effect on a brass or reed instrument produced when the player vocalizes (hums, sings, or growls in the throat) while blowing, so the sung pitch and the played pitch beat against each other and roughen the sound. It is common on saxophone, trumpet, and trombone in jazz, blues, and rhythm and blues, and is sometimes reinforced with flutter tonguing.", "plain_english": "The player hums or growls in the throat while blowing the note. The two sounds clash and make the tone rough and dirty, like a singer adding rasp to their voice.", "purpose_function": "It adds a gritty, vocal, aggressive color to a sustained note, giving brass and reed lines an expressive, human, dirty edge.", "practical_application": "A saxophone or trumpet player growls on a held note for a bluesy or funky solo, and an engineer capturing it notes that the added harshness broadens the harmonic content and can peak harder than a clean note.", "category": "Brass/reed technique", "related_terms": ["Flutter tonguing", "Bronx cheer/raspberry", "Multiphonics", "Overblowing", "Embouchure", "Subtone"], "common_mistakes": ["Thinking growl comes only from the lips or reed, when it is the vocalized throat tone beating against the played note", "Confusing growl with flutter tonguing, which rolls the tongue instead of using the voice", "Pushing so hard that pitch and intonation become unstable"], "scenario_contexts": ["A tenor saxophonist growling through a blues or rhythm and blues solo", "A trumpet or trombone adding a dirty growl in a big-band shout chorus", "Recording a growled line and watching for extra peak level and harshness"]}, "ad75ac0e-a510-4a53-b6d2-12c76f2094d9": {"definition": "An expressive pitch slide (portamento) on the guanzi, a Chinese cylindrical double-reed pipe (also called bili), produced by continuously varying lip and jaw pressure on the large reed and by sliding or gradually uncovering the finger holes so the pitch bends smoothly between notes. Wide, vocal glides are a hallmark of guanzi style and can span a large interval.", "plain_english": "On the guanzi, a Chinese double-reed pipe, the player slides smoothly from one note to another. They squeeze the reed with the lips and roll the fingers off the holes, bending the pitch like a voice sliding up or down.", "purpose_function": "The glide gives the guanzi its crying, vocal, speech-like quality, connecting notes expressively and imitating the human voice.", "practical_application": "A guanzi player uses wide glides for mournful or dramatic passages, and an engineer records the instrument close enough to catch these continuous pitch slides and its strong, reedy tone.", "category": "Wind technique", "related_terms": ["Double reed", "Portamento", "Kari (head-raise pitch bend)", "Embouchure", "Overblowing", "Suona"], "common_mistakes": ["Assuming pitch changes only by lifting fingers, when lip and jaw pressure on the reed do much of the bending", "Treating the glide as a fast slur rather than a smooth continuous slide", "Confusing the guanzi with the suona, a conical double-reed with a brighter, louder tone"], "scenario_contexts": ["A guanzi solo in Chinese traditional or folk music using wide expressive glides", "A film or world-music session wanting a crying double-reed line", "Close-miking a guanzi to capture its glides and reedy timbre"]}, "12a6765e-7073-4e55-a053-ef91a87ced91": {"definition": "A brass technique (trumpet, cornet, and other valved brass) in which one or more valves are pressed only partway down, partially restricting the airway so the instrument produces a stuffy, muffled, indeterminate pitch. Moving the valves and adjusting the lip while half-valved lets the player slide or smear between pitches, producing a lazy glissando or a muted, choked color.", "plain_english": "The player presses a valve only halfway, which chokes the air and blurs the note. Sliding the valve and lips this way smears smoothly between pitches, a bit like a slow scoop up to a note.", "purpose_function": "It lets a valved brass instrument, which normally jumps between fixed notes, slide smoothly between pitches and add a muffled, expressive effect.", "practical_application": "A trumpeter uses a half-valve smear to scoop into a note or add a jazzy, choked effect, and an engineer notes that the tone is softer and less focused than a normal note.", "category": "Brass technique", "related_terms": ["Glissando", "Growl (vocalized brass/reed)", "Lip bend", "Embouchure", "Valve", "Portamento"], "common_mistakes": ["Pressing the valve fully instead of halfway, which produces a normal clear note rather than a smear", "Expecting a loud, focused tone when the half-valve sound is deliberately stuffy and quiet", "Confusing a half-valve smear with a lip glissando that follows the harmonic series"], "scenario_contexts": ["A jazz trumpeter scooping into a phrase with a half-valve smear", "A brass effect calling for a lazy, muffled glissando", "Recording a soloist whose half-valve notes sit lower in level than clean notes"]}, "9dd4bce3-a429-496e-aa33-72aea0b16c6f": {"definition": "A pitch-altering technique on the harmonica in which the player changes the shape and resonance of the mouth and throat, along with breath pressure, to lower a note's pitch (a draw bend or blow bend) or, with overblowing and overdrawing, to raise it. Bending works because the two reeds sharing a channel interact, and the vocal-tract resonance forces them to sound at a pitch between or above their natural notes.", "plain_english": "The player changes the shape of the mouth and throat to slide a note down in pitch, or up with a harder trick. It works like whistling lower by changing your mouth. This lets a simple harmonica reach the blue notes between the built-in ones.", "purpose_function": "Bending fills in notes missing from the harmonica's fixed layout and adds the expressive, vocal, blue inflections central to blues and folk playing.", "practical_application": "A blues harmonica player bends draw notes to reach missing pitches and add feeling, and a technician recording it hears smooth pitch dips that need clean, low-noise capture.", "category": "Free-reed technique", "related_terms": ["Free reed", "Overblowing", "Harmonica feedback", "Embouchure", "Reed", "Portamento"], "common_mistakes": ["Thinking bending comes from breathing harder, when it is the mouth and throat shape (resonance) that bends the pitch", "Biting or clamping the harmonica instead of shaping the oral cavity", "Assuming every hole bends the same amount, when the bend range differs by hole"], "scenario_contexts": ["A blues player bending draw notes in second position (cross harp)", "Reaching a missing scale note by bending rather than switching harmonicas", "Recording expressive pitch dips in a folk or blues harmonica part"]}, "a40654fd-d76c-4bbd-bf50-b3e6eeb2b76f": {"definition": "Acoustic feedback in amplified harmonica playing, which occurs when sound from the amplifier's loudspeaker re-enters the closely cupped microphone and the loop gain reaches unity, causing a sustained howl or squeal. Chicago-blues players deliberately court controlled feedback and mild distortion by cupping a bullet microphone tightly against a small tube amplifier, using it as part of the raw, saturated tone.", "plain_english": "This is the squeal that starts when a harmonica mic picks up its own sound from the amp in a loop. Blues players learn to ride a little of it on purpose for a gritty sound. It is like standing just close enough to a speaker to make it buzz.", "purpose_function": "As a fault it is unwanted howl to be controlled; as a stylistic tool it adds sustain, grit, and saturation to amplified blues harmonica tone.", "practical_application": "A player cups a bullet microphone to a tube amp and manages gain and position to get grit without a runaway squeal, while the sound technician sets levels and placement to keep feedback under control.", "category": "Amplified sound", "related_terms": ["Acoustic feedback", "Gain before feedback", "Bullet microphone", "Harmonica bend", "Monitor wedge", "Distortion"], "common_mistakes": ["UNSAFE: Driving an amp into sustained feedback at high level near the ears without hearing protection or level limits, risking noise-induced hearing loss", "Blaming the harmonica when a too-loud amp or poor microphone placement is causing the feedback loop", "Trying to cure feedback only with EQ instead of reducing gain or moving the microphone away from the speaker"], "scenario_contexts": ["A Chicago-blues harp player cupping a bullet microphone into a small tube amp for grit", "A sound technician chasing runaway harmonica feedback on a loud stage", "Setting monitor and amp levels so the player gets tone without a howl"]}, "ef18157e-21a4-430e-9b39-69e93aef5fcb": {"definition": "A sustained, unchanging tone (or pair of tones, typically tonic and fifth) held on the harmonium, a hand-pumped free-reed keyboard instrument, to provide a constant pitch reference beneath a melody. On many South Asian harmoniums it is produced by pulling drone stops or by wedging or holding specific keys while the bellows keep the reeds sounding.", "plain_english": "On the harmonium, a pumped reed keyboard, the player holds one or two notes that never change under the tune. This steady background hum gives singers a fixed pitch to sing against, like a tuning note that stays on.", "purpose_function": "The drone anchors the tonal center (the key note) so melody and singing stay in tune with a constant reference, which is central to Indian classical and devotional music.", "practical_application": "A singer or player sets harmonium drone reeds for a raga or bhajan and pumps steadily, and an engineer records a continuous low sustain that has no natural breaks to edit at.", "category": "Free-reed technique", "related_terms": ["Drone", "Free reed", "Harmonium", "Tonic", "Circular-breathing drone", "Reed"], "common_mistakes": ["Letting the bellows pressure sag so the drone wavers in pitch and volume", "Confusing the harmonium drone with an electronic tanpura or shruti box, which serve the same role differently", "Choosing drone notes that do not match the piece's key or mode"], "scenario_contexts": ["A harmonium holding a tonic-and-fifth drone under a raga or bhajan", "Accompanying qawwali or kirtan singing with a steady pitch reference", "Recording a continuous harmonium drone with no breath gaps to edit"]}, "1c7a3ce3-7c49-49b7-b410-6303ce1037fb": {"definition": "A shakuhachi (Japanese end-blown bamboo flute) technique in which the player raises the head and tilts the flute outward, moving the blowing edge away from the lips to raise a note's pitch and brighten its tone. It is the opposite of meri (head lowered, blowing edge partly covered, pitch lowered and tone darkened), and the two are used together to bend pitch and shade color expressively.", "plain_english": "On the shakuhachi, a Japanese bamboo flute, the player lifts the head and tilts the flute out to push a note higher and brighter. It is the opposite of meri, where dropping the head makes the note lower and darker.", "purpose_function": "Kari lets the player raise pitch and brighten tone without changing fingering, giving fine control over intonation and expressive color on a flute with few holes.", "practical_application": "A shakuhachi player uses kari and meri to bend between pitches and shade tone within a phrase, and an engineer close-miking the flute captures these subtle pitch and timbre shifts and the instrument's breathy attack.", "category": "Wind technique", "related_terms": ["Meri", "Embouchure", "Portamento", "Overblowing", "Guanzi glide", "End-blown flute"], "common_mistakes": ["Thinking pitch changes only by fingering, when head angle (kari and meri) bends it too", "Overshooting the head raise so the note breaks or the tone thins out", "Confusing kari (raise, brighter) with meri (lower, darker)"], "scenario_contexts": ["A shakuhachi player using kari to raise pitch and brighten a sustained note", "Bending expressively between meri and kari within a honkyoku phrase", "Close-miking a shakuhachi to capture head-motion pitch and timbre changes"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"bbfdd0f3-bc6f-436e-b583-25f5faf8f27c": {"definition": "On the kaval, an end-blown rim flute of the Balkans and Anatolia, the point at which increasing breath pressure overblows the tube into a higher register, jumping to the next note of the harmonic series rather than rising smoothly. Around this break the tone can crack or split, and skilled players control the transition to move cleanly between the low and upper registers.", "plain_english": "On the kaval, a Balkan rim-blown flute, blowing harder makes the note jump up to a higher register instead of rising smoothly. That jump point is the break, where the tone can crack if the player is not careful.", "purpose_function": "Overblowing past the break extends the kaval's range across several registers from a single tube, and controlling it cleanly is a mark of skilled playing.", "practical_application": "A kaval player manages breath and embouchure through the break to keep register changes clean, and an engineer records the instrument knowing upper-register notes are louder and brighter than low ones.", "category": "Wind technique", "related_terms": ["Overblowing", "Register break", "Embouchure", "Harmonic series", "End-blown flute", "Breath support"], "common_mistakes": ["Blowing too softly or too hard at the break, causing the note to crack or split", "Thinking the register jump comes from fingering alone rather than breath pressure and embouchure", "Expecting even loudness across registers when the upper register is naturally louder and brighter"], "scenario_contexts": ["A kaval player moving cleanly across the register break in a fast tune", "A beginner whose notes crack at the overblow transition", "Recording a kaval where upper-register phrases sit louder than low ones"]}, "51aaa45b-caee-4bdd-b8a4-97a73d3bcfc7": {"definition": "A sustained cluster of notes sounded together on the khaen (also khene), a free-reed bamboo mouth organ of Laos and northeastern Thailand, produced when the player holds several pipes open at once so their reeds drone continuously beneath or around the melody. Certain pipes are held with the fingers or stopped with wax to sound constantly, giving the instrument its characteristic thick, sustained harmony.", "plain_english": "The khaen is a bamboo mouth organ from Laos and Thailand. The player sounds several pipes at once to make a thick, held chord. This steady bundle of notes hums under the tune, like both hands playing an accordion.", "purpose_function": "The drone chord gives the khaen a full, continuous harmonic backing under the melody, so a single player can supply both tune and accompaniment.", "practical_application": "A khaen player holds drone pipes open with the fingers or wax stops while playing the melody, and an engineer records a dense, sustained free-reed sound with no natural breath gaps to edit at.", "category": "Free-reed technique", "related_terms": ["Free reed", "Drone", "Harmonium drone", "Circular-breathing drone", "Reed", "Mouth organ"], "common_mistakes": ["Assuming the khaen plays single lines, when it typically sounds drone chords under the melody", "Confusing the khaen with the Chinese sheng, a related but differently built free-reed mouth organ", "Expecting breath gaps to edit at, when the drone is held nearly continuously"], "scenario_contexts": ["A khaen player backing a molam singer with a sustained drone chord", "A Lao or Isan folk performance featuring continuous free-reed harmony", "Recording a dense, sustained khaen part with few natural breaks"]}, "b71afdcf-b32f-4141-bb1c-1c3db27ab7e9": {"definition": "The audible clicking, tapping, or thudding produced by a woodwind instrument's key mechanism as it is worked, such as pads seating on tone holes and keys striking their posts, felt, or cork bumpers; it is a mechanical byproduct distinct from the instrument's musical tone.", "plain_english": "The clicking and tapping sound a flute, clarinet, or sax makes as its keys and pads open and close. It is a bit like the click of a keyboard as you type.", "purpose_function": "It is an unavoidable byproduct of a padded key mechanism; identifying it lets players and engineers manage it so it does not distract from the musical sound of the instrument.", "practical_application": "A recording engineer positions and angles the microphone away from the keywork and may service or lubricate the mechanism to reduce the amount of key clatter captured in a close-miked take.", "category": "Instrument Noise", "related_terms": ["Tone hole", "Pad", "Embouchure", "Spot microphone", "Transient"], "common_mistakes": ["Assuming key noise means the instrument is broken; some mechanism noise is normal on any padded woodwind.", "Placing a microphone directly over the keywork, which exaggerates clicks and pad slap.", "Trying to remove all key noise with heavy gating or EQ, which also damages the natural tone."], "scenario_contexts": ["Close-miking a flute or clarinet in a quiet studio, where key clicks become obvious in the recording.", "A classical solo or chamber session where the producer wants minimal mechanism noise.", "Live orchestral pickup where a poorly adjusted key mechanism adds distracting clatter."]}, "6fb0d3c3-7b44-41ad-b67d-f4e116d75296": {"definition": "A dynamic-shaping technique on the melodica in which the player varies breath pressure to raise and lower the loudness of a sustained note, producing a crescendo and decrescendo; because the melodica sounds free reeds, breath pressure mainly changes volume rather than pitch.", "plain_english": "On a melodica, blowing harder makes a held note grow louder and easing off makes it fade. Doing this smoothly gives the note a rising and falling swell, like slowly turning a volume knob up and down.", "purpose_function": "It gives the melodica expressive dynamic control for shape, phrasing, and emphasis, since the player's breath rather than a fixed mechanism sets each note's loudness.", "practical_application": "A player uses steady, controlled breath to fade notes in and out for expressive lines, and an engineer recording it may apply gentle compression to keep the swells within a usable level range.", "category": "Breath Dynamics", "related_terms": ["Free reed", "Crescendo", "Breath control", "Embouchure", "Dynamics"], "common_mistakes": ["Blowing too hard for a swell, which can make a free reed sound harsh or bend the pitch slightly flat.", "Confusing a breath swell with a pitch bend; a swell changes loudness, not the note.", "Letting breath run out mid-phrase so the swell collapses unevenly."], "scenario_contexts": ["A studio overdub where a melodica adds a swelling, pad-like line under a song.", "A live performance where the player fades a chord in for atmosphere.", "Reggae or dub recordings where melodica swells are a signature texture."]}, "965531bb-9e2c-44c7-b20d-d7527c92cf2c": {"definition": "A shakuhachi (Japanese end-blown bamboo flute) technique in which the player lowers the chin and head, decreasing the blowing angle across the mouthpiece edge and often partly shading a finger hole, to flatten the pitch and darken the tone; its opposite, raising pitch by lifting the chin, is called kari.", "plain_english": "On the shakuhachi flute, the player tips the chin down to make a note go flat and sound darker. It is like aiming your breath lower across a bottle top to drop the pitch.", "purpose_function": "It lets the player reach the in-between pitches and subtle tone colors the finger holes alone cannot give, which is central to the instrument's expressive, speech-like style.", "practical_application": "A player rocks the head down for meri or up for kari while holding a fingering, bending pitch and shading timbre within a phrase to match the melody or another instrument.", "category": "Pitch Bending", "related_terms": ["Kari", "Embouchure", "Overblowing", "Muraiki (overblown air-blast)", "Pitch bend"], "common_mistakes": ["Thinking meri is only a fingering; it depends mainly on head angle and blowing, not just covering holes.", "Dropping the chin so far the note weakens or cracks instead of bending cleanly.", "Confusing meri, which lowers pitch, with kari, which raises it."], "scenario_contexts": ["Playing traditional honkyoku pieces that call for meri notes and sliding pitch.", "Tuning a shakuhachi line to a shamisen or koto in an ensemble.", "Recording where meri's darker, breathier tone needs careful microphone placement."]}, "f9d377e2-3d6a-48d8-ba68-d3581c2041d6": {"definition": "The bright, sparkling brilliance added to an organ's tone by a Mixture, a compound stop that sounds several high-pitched ranks per note tuned to upper octaves and fifths of the harmonic series; drawn on top of the diapason chorus, these ranks crown the sound with high-frequency reinforcement.", "plain_english": "A pipe organ mixture stop adds several tiny high pipes to every note, giving the sound a bright, sparkling top. That extra sparkle on top of the main tone is the shimmer.", "purpose_function": "The mixture reinforces the upper harmonics of the foundation stops, adding brightness and clarity so the full chorus sounds brilliant and carries in a large room.", "practical_application": "An organist draws mixtures on top of principals to build the full plein jeu chorus for hymns and climaxes, blending them so the shimmer adds brilliance without harshness.", "category": "Organ Registration", "related_terms": ["Rank", "Stop", "Principal chorus", "Harmonic series", "Diapason"], "common_mistakes": ["Drawing a mixture by itself; it is meant to sit on top of foundation stops, not stand alone.", "Assuming a mixture plays one pitch per key; each note sounds several pipes at different pitches.", "Forgetting that mixtures break back down in pitch up the keyboard, so the top does not scream."], "scenario_contexts": ["Registering a hymn's final verse where full organ with mixtures is wanted.", "Recording a large pipe organ where the bright mixture ranks can sound harsh if the mic is too close.", "Balancing a Baroque plein jeu registration for clarity in counterpoint."]}, "1a221b67-b344-45f7-a5e1-0d1c28c53075": {"definition": "An articulation technique on wind and brass instruments in which the player alternates a front-of-tongue stroke (such as \"tu\") with a back-of-tongue stroke (such as \"ku\") to articulate rapid passages faster than single tonguing allows; two-stroke patterns are double tonguing and three-stroke patterns are triple tonguing.", "plain_english": "To play fast repeated notes, wind and brass players use two tongue actions, one at the front and one at the back of the mouth, saying something like tu-ku, tu-ku. It lets the tongue keep up when single tonguing is too slow.", "purpose_function": "It lets players articulate very fast passages cleanly, since a single tongue stroke cannot repeat quickly enough for rapid runs and fanfares.", "practical_application": "A trumpet or flute player uses double or triple tonguing for fast staccato runs, working to make the front and back strokes sound equally strong so every note is even.", "category": "Articulation", "related_terms": ["Single tonguing", "Flutter tonguing", "Staccato", "Articulation", "Embouchure"], "common_mistakes": ["Letting the back stroke sound weaker or duller than the front stroke, giving uneven notes.", "Pushing the speed up before the tongue coordination is secure.", "Using a double-tonguing pattern for triple-meter groups, which throws off the accents."], "scenario_contexts": ["Playing a fast trumpet fanfare or a flute's rapid staccato passage.", "Orchestral excerpts that demand rapid repeated articulation.", "Close-miking where uneven tonguing strokes are clearly audible."]}, "83adadd5-7617-42cf-9ba3-3b4ee45ecb27": {"definition": "A shakuhachi technique in which the player forcefully overblows to produce a loud, breath-heavy attack, an explosive burst of air noise mixed with the tone, used as an expressive percussive color rather than a clean sustained pitch.", "plain_english": "On the shakuhachi, the player blows a hard, noisy blast of air so the note bursts out with a rush of breath. It sounds stormy and rough, like a strong gust of wind.", "purpose_function": "It adds dramatic, breathy, noise-based color to the music, extending the flute's expressive range beyond clean sustained tones.", "practical_application": "A player uses muraiki at key moments in traditional honkyoku for a stormy, forceful effect, and an engineer leaves extra headroom because the air-blast attack is much louder and noisier than normal notes.", "category": "Extended Technique", "related_terms": ["Overblowing", "Meri (chin-lower pitch bend)", "Ney breath tone", "Embouchure", "Transient"], "common_mistakes": ["Treating muraiki as an accident; it is a controlled, intentional effect, not a failed note.", "Overblowing so hard the pitch jumps to the wrong overtone.", "Recording with too little headroom, so the loud air-blast clips."], "scenario_contexts": ["Performing traditional honkyoku pieces that call for a stormy muraiki attack.", "A film or game score wanting a raw, breathy shakuhachi effect.", "Setting record levels so the sudden air-blast does not distort."]}, "6771cccb-cee7-4c2e-b188-1a364d133982": {"definition": "Playing melodies on a valveless bugle or natural brass instrument using only the notes of its harmonic series, selecting pitches solely by changing lip tension and air, since there are no valves or slides to alter the tube length.", "plain_english": "A bugle has no valves, so the player changes notes only by tightening or loosening the lips. This limits it to a handful of harmonic notes, which is why bugle calls use just a few pitches.", "purpose_function": "It reflects how a natural brass instrument works: with a fixed tube length, only the harmonic (overtone) series is available, which is why traditional calls and fanfares are built from those few notes.", "practical_application": "A player selects each note by adjusting embouchure and breath alone, which is the basis of military and camp bugle calls and of period natural-trumpet playing.", "category": "Brass Technique", "related_terms": ["Harmonic series", "Embouchure", "Natural trumpet", "Overtone", "Lip slur"], "common_mistakes": ["Expecting a bugle to play a full scale; only the harmonic-series notes are available without valves.", "Blaming missed notes on the instrument when a secure embouchure is what selects the right harmonic.", "Confusing lipping between harmonics with changing notes by valves."], "scenario_contexts": ["Playing standard bugle calls such as reveille or taps.", "Historically informed performance on a valveless natural trumpet.", "Teaching the harmonic series by demonstrating which notes a bugle can sound."]}, "9522ca3d-5310-4e91-bcc2-fbc17af0273a": {"definition": "The characteristic breathy, airy timbre of the ney, an end-blown reed flute of Middle Eastern music, in which audible breath noise blends with the pitched tone because the player directs the airstream obliquely across the open end of the tube; this breathiness is a prized expressive feature, not a flaw.", "plain_english": "The ney is a reed flute you blow across the end, and its sound always carries a soft rush of breath mixed with the note. That airy, whispery quality is its signature voice.", "purpose_function": "The breathy tone gives the ney its warm, human, voice-like expressiveness, which is central to its role in Middle Eastern and Sufi music.", "practical_application": "A player shapes embouchure and breath to control how much air noise colors the tone, and an engineer mics it to capture that breathiness without harsh wind blasts hitting the capsule.", "category": "Timbre", "related_terms": ["Embouchure", "End-blown flute", "Overblowing", "Muraiki (overblown air-blast)", "Windscreen"], "common_mistakes": ["Treating the ney's breath noise as a defect to remove; it is an essential part of the sound.", "Blowing straight instead of obliquely across the edge, which kills the tone.", "Close-miking without a pop or wind screen, so breath blasts overload the microphone capsule."], "scenario_contexts": ["Recording a ney solo for Middle Eastern or world-music production.", "Live Sufi or classical ensemble where the ney's breathy line must sit in the mix.", "Sampling a ney and needing to preserve its breathy attack."]}, "06e97cbe-dc0a-4f36-82ff-e99a0dc8b016": {"definition": "A momentary missed or split note, most common on brass, in which the player's lip fails to lock cleanly onto the intended harmonic resonance at the attack, producing a wrong pitch, a brief split, or a noisy break; \"clam\" is the common musician's slang for such a flubbed note.", "plain_english": "A crack or clam is when a brass player's note comes out wrong for an instant. It splits or jumps to the wrong pitch on the attack. It happens because the lips did not quite lock onto the right note.", "purpose_function": "Naming it helps players and engineers identify and fix attack errors, since brass notes depend on the lips matching an exact resonance of the tube.", "practical_application": "In a session, a producer flags a cracked note for a retake or a punch-in, while players reduce clams by centering the pitch and supporting the air at the attack.", "category": "Performance Error", "related_terms": ["Harmonic series", "Embouchure", "Attack", "Punch-in", "Lip slur"], "common_mistakes": ["Blaming the instrument for clams that come from an unfocused embouchure or weak air.", "Punching in over a cracked note without matching tone and tuning, so the edit shows.", "Trying to fix an obvious clam with pitch software when a clean retake would sound better."], "scenario_contexts": ["A trumpet solo take where one high entrance cracks and needs a punch-in.", "Live broadcast where a prominent clam is audible and cannot be redone.", "Editing a horn section where one player's split note must be replaced."]}, "6c7957f7-014b-4cb6-a552-7eb6e8fc47c5": {"definition": "Low-frequency mechanical and aerodynamic sound produced by the electric blower (a rotary or centrifugal fan) that supplies pressurized wind to a pipe organ. It typically appears as a steady rumble, hum, or whir that can transmit through the wind system and building structure into the listening or recording space.", "plain_english": "The steady hum or rumble made by the fan that pushes air into a pipe organ. It sounds like the low whir of a furnace blower running in another room.", "purpose_function": "The blower exists to feed steady wind to the pipes, so its noise is an unwanted by-product that organ builders and recordists work to keep out of the music.", "practical_application": "When recording an organ, a technician locates the blower (often in a separate chamber or basement), checks whether its rumble reaches the mics, and uses distance, isolation, or high-pass filtering to reduce it.", "category": "Organ noise", "related_terms": ["Organ wind noise", "Pipe hiss", "Wind supply", "Windchest", "Low-frequency rumble", "High-pass filter"], "common_mistakes": ["Assuming all low rumble on an organ track is room noise rather than the blower itself.", "Placing mics near the blower chamber or wind trunk, capturing its rumble along with the pipes.", "Cutting blower rumble with a high-pass filter set so high it also thins out the pedal (low bass) pipes."], "scenario_contexts": ["Recording a church pipe organ where basement blower rumble leaks up into the room.", "A quiet solo passage where the blower whir becomes audible between phrases.", "Tracing a low hum on an organ stem to the blower rather than to electrical hum."]}, "4b7f75b2-0894-4224-96f6-a339ae8d3d55": {"definition": "A brief, noisy transient of higher partials heard at the onset (speech) of a flue organ pipe before its steady tone establishes, giving a percussive \"ch\" or spitting attack. Its strength depends on voicing and is prominent on lightly nicked or unnicked pipes and in many flute and principal stops.", "plain_english": "A short, breathy \"ch\" burst at the very start of an organ note before the clear tone settles in. It is like the little puff of air you hear when a flute player first tongues a note.", "purpose_function": "Chiff marks the attack of a pipe's speech and lends articulation and clarity to each note, so voicers deliberately keep, reduce, or add it to control how crisply a stop speaks.", "practical_application": "A voicer judges chiff by ear on note onset and adjusts nicking, windway, and languid position to tame excess chiff, while a recordist places mics to capture a natural rather than exaggerated attack.", "category": "Organ articulation", "related_terms": ["Flue pipe", "Pipe speech", "Nicking", "Attack transient", "Voicing", "Languid"], "common_mistakes": ["Confusing intentional voiced chiff with a speech fault or pipe defect.", "Close-miking flue pipes so tightly that the chiff is exaggerated and sounds unnatural.", "Voicing so much chiff into a rank that every note starts with a hard, exaggerated attack instead of a clean one."], "scenario_contexts": ["Recording a Baroque-style organ whose flute stops chiff strongly on each note.", "A voicer adjusting nicking to reduce harsh chiff on a newly made rank.", "Editing an organ track where prominent chiff makes fast passages sound articulate."]}, "fb081138-8e33-4e0d-8e63-f0cbd0e6b45e": {"definition": "Broadband rushing or hissing sound produced by air moving through an organ's wind system - trunks, windchests, pallets, and pipe feet - as distinct from the intended pipe tone. It can arise from leaks, high wind pressure, restricted passages, or the air jet at a flue pipe's mouth.", "plain_english": "The rushing, airy sound of wind moving through an organ's pipes and air paths, separate from the musical note. It is like the \"whoosh\" you hear when you blow across a bottle before a clear tone forms.", "purpose_function": "Some air noise is an unavoidable side effect of blowing pipes with wind, so knowing what is normal lets builders and recordists tell healthy speech from a leak or excess turbulence.", "practical_application": "A technician listens for wind noise rising above normal, which can signal a leak or a regulation problem, and positions mics to keep captured hiss low on quiet passages.", "category": "Organ noise", "related_terms": ["Organ blower noise", "Pipe hiss", "Windchest", "Wind pressure", "Flue pipe", "Pallet"], "common_mistakes": ["Treating all wind noise as a fault when a small amount is natural to pipe speech.", "Ignoring a rise in wind noise that actually signals an air leak in a chest or trunk.", "Boosting high frequencies in the mix and exaggerating the organ's wind hiss."], "scenario_contexts": ["A leaking pallet or gasket adding audible hiss under sustained chords.", "Recording a soft registration where wind noise competes with the quiet pipes.", "Servicing an organ and tracing excess wind noise to over-high wind pressure."]}, "069613e9-69a7-4942-b92e-35fd4ea01d9d": {"definition": "Extended diatonic-harmonica techniques in which precise embouchure and breath make the normally silent \"opening\" reed of a cell sound in place of the closing reed, producing a pitch roughly a semitone above that reed's normal note. Overblow is played on the exhale (blow), where the draw reed sounds in place of the choked blow reed; overdraw is played on the inhale (draw), where the blow reed sounds in place of the choked draw reed, together filling in notes missing from the standard diatonic layout.", "plain_english": "Special tricks for playing a blues (diatonic) harmonica. You use your breath and mouth shape to make a hidden higher note sound. They let a player reach notes the harmonica does not normally give.", "purpose_function": "Overblows and overdraws exist to complete the chromatic scale on a ten-hole diatonic harmonica, letting players hit notes that would otherwise need a chromatic harmonica or a different key.", "practical_application": "A player chokes the normal reed and coaxes the opposite reed to sound, usually on a harmonica whose reed gaps are set up for it, then bends the initially flat pitch up to true.", "category": "Extended technique", "related_terms": ["Bending", "Free reed", "Diatonic harmonica", "Reed plate", "Embouchure", "Chromatic scale"], "common_mistakes": ["Confusing overblowing with note bending; they use different reeds and a different mechanism.", "Expecting overblows to speak cleanly on a stock harmonica without adjusting the reed gaps.", "UNSAFE: Blowing very hard to force an overblow, which can overstress and break reeds."], "scenario_contexts": ["A blues player using overblows to play a full chromatic melody on one diatonic harp.", "Setting reed gaps on a harmonica so overblows and overdraws speak reliably.", "A studio session where a harmonica part needs a note reachable only by overdraw."]}, "9ad92a1c-e5a7-4c35-9561-130a7a91aba7": {"definition": "A family of vocal techniques in which a singer sustains a low fundamental drone and shapes the vocal tract to strengthen one upper harmonic sharply enough that it is heard as a separate whistling melody note. Tuvan khoomei and related styles do this by tuning the tract resonances (formants) to isolate successive partials of the voice.", "plain_english": "A way of singing that makes two notes at once: a low steady tone and a clear high whistle above it. The singer shapes the mouth and throat to pick out one high note from the voice's natural overtones.", "purpose_function": "The technique turns the voice's natural harmonics into an audible melody, a core musical practice in Central Asian and other traditions and a subject of voice-acoustics research.", "practical_application": "A recordist captures both the drone and the fragile overtone by choosing a mic and placement that preserve high-frequency detail, since the melody sits in a narrow, easily masked upper band.", "category": "Vocal technique", "related_terms": ["Formant", "Harmonic series", "Fundamental frequency", "Vocal tract", "Drone", "Partial"], "common_mistakes": ["Thinking the singer makes two separate pitches at the vocal cords rather than reinforcing one existing harmonic.", "Rolling off the highs in the mix and burying the whistling overtone melody.", "Assuming any mic captures the overtone equally; a dull or distant mic can lose it."], "scenario_contexts": ["Recording a Tuvan khoomei performance where the overtone melody must stay clearly audible.", "A voice-acoustics study measuring formant tuning during overtone singing.", "Mixing a world-music track so the reinforced harmonic sits above the drone."]}, "517d44f7-4d89-445f-a21a-755a703df952": {"definition": "The mechanical clicking, thumping, or slapping sound made by a woodwind instrument's key pads seating on or lifting off their tone holes, independent of the musical tone. It is most audible in close-miked recordings of flutes, clarinets, saxophones, and similar keyed instruments.", "plain_english": "The soft clicks and thumps a wind instrument's keys make as they open and close over the holes. It is like hearing the keys of a flute clack while the note plays.", "purpose_function": "Pad noise is a by-product of the key mechanism sealing tone holes, and recognizing it helps a technician decide when it is natural detail and when it distracts from the tone.", "practical_application": "A recordist reduces distracting pad noise by moving the mic off the key work (toward the bell or a little farther away) and may edit or gently reduce clicks in quiet passages.", "category": "Mechanical noise", "related_terms": ["Tone hole", "Key pad", "Close miking", "Woodwind", "Transient", "Spot mic"], "common_mistakes": ["Placing a spot mic right over the keys and capturing loud pad clicks.", "Trying to remove every click and stripping away natural, expected instrument detail.", "Blaming pad noise on the mic when a worn or loose pad is the real cause."], "scenario_contexts": ["Close-miking a flute where finger and pad clicks stand out in soft passages.", "A saxophone overdub where key noise sits too high against the tone.", "Servicing a clarinet whose worn pads slap loudly on closing."]}, "451840a7-9d8a-488f-b80d-ad983d602a2a": {"definition": "The breathy attack transient heard at the onset of a pan-flute (panpipe) note: a brief burst of air-jet noise as the edge tone starts, before the pipe's tone stabilizes. It comes from the player's breath striking the pipe's rim, and its strength varies with blowing angle and articulation.", "plain_english": "The airy \"puff\" you hear at the start of a pan-flute note before the clear tone comes in. It is the sound of breath hitting the pipe's edge as the note begins.", "purpose_function": "The chiff is a natural part of how an edge-blown pipe starts to speak, so players and recordists treat it as expressive attack rather than a fault.", "practical_application": "A recordist positions the mic to catch a natural amount of breath attack without exaggerating it, since a very close mic lets the chiff and breath noise dominate.", "category": "Attack transient", "related_terms": ["Edge tone", "Attack transient", "Breath noise", "Panpipe", "Air jet", "Organ chiff"], "common_mistakes": ["Miking the pan flute so closely that breath chiff overwhelms the tone.", "Treating the natural breath attack as a defect to be fully removed.", "Confusing player breath noise with mechanical or wind-system noise."], "scenario_contexts": ["Close-recording a panpipe solo where each note starts with an airy chiff.", "Balancing breath attack against tone in a folk-ensemble mix.", "A player adjusting blowing angle to control how much chiff each note has."]}, "7d9d74a5-9318-4ac8-b2c1-522a727b6cdc": {"definition": "On a brass (lip-reed) instrument, the unintended sounding of a neighboring partial of the harmonic series - the note momentarily \"pops\" to the harmonic above or below the intended one because the lips lock onto the wrong resonance. It produces a cracked or split note, most common in the upper register where partials sit close together.", "plain_english": "When a trumpet or horn player accidentally hits the wrong note in the natural series, so the note jumps or cracks. It happens because the nearby notes are easy to slip onto, especially up high.", "purpose_function": "Understanding partial popping helps players and techs know why brass notes crack and how lip tension and air support keep the intended harmonic locked in.", "practical_application": "A technician or player traces cracked notes to lip setup, air support, or mouthpiece and tuning issues rather than assuming the instrument is faulty.", "category": "Brass technique", "related_terms": ["Harmonic series", "Partial", "Embouchure", "Lip reed", "Cracked note", "Register"], "common_mistakes": ["Blaming the instrument for popped partials that come from embouchure or air support.", "Expecting clean upper-register notes without enough breath support.", "Confusing a popped partial with a valve or slide error."], "scenario_contexts": ["A trumpet player cracking a high note as it pops to the next partial.", "A horn section where closely spaced partials make entrances risky.", "Reviewing a brass take and hearing a note split to a neighboring harmonic."]}, "ed37c62f-f77e-4595-9a33-35799e8b830a": {"definition": "A steady, broadband high-frequency hiss radiated by an organ flue pipe, produced by turbulent air where the wind jet crosses the pipe's mouth and upper lip, accompanying its tone. Excess hiss can indicate over-high wind pressure, a maladjusted jet, or voicing that emphasizes air noise over harmonic tone.", "plain_english": "The airy, hissing sound that comes from an organ pipe along with its note, made by wind rushing across the pipe's mouth. It is like the breathy hiss you hear when blowing hard across a bottle top.", "purpose_function": "A little jet hiss is built into how a flue pipe makes sound, so judging it helps voicers and recordists tell healthy speech from noisy, poorly regulated pipes.", "practical_application": "A voicer adjusts wind pressure and the pipe's mouth (cut-up and jet) to balance tone against hiss, while a recordist places mics so as not to over-emphasize pipe hiss on soft stops.", "category": "Organ noise", "related_terms": ["Flue pipe", "Organ wind noise", "Air jet", "Cut-up", "Wind pressure", "Voicing"], "common_mistakes": ["Treating all pipe hiss as a fault when some jet noise is natural to flue speech.", "Raising wind pressure for more volume and adding harsh hiss.", "Boosting treble in the mix and exaggerating pipe hiss on quiet passages."], "scenario_contexts": ["A softly voiced flute stop whose jet hiss is audible up close.", "A voicer reducing hiss by refining the cut-up and wind pressure.", "Recording a quiet registration where pipe hiss competes with the tone."]}, "953941d1-79bd-4453-afbd-c0b63d01c9c4": {"definition": "The broadband, non-pitched turbulence and edge-tone hiss produced as pressurized air (organ \"wind\") passes through flue pipes, windways, and windchest components. It includes the breathy hiss at a pipe's mouth and the transient \"chiff\" or speech consonant at note onset, distinct from the sustained musical tone.", "plain_english": "The airy, hissing sound an organ makes as air rushes through its pipes, on top of the musical notes. Like the breathy sound you hear when you blow across a bottle top before the clear tone settles.", "purpose_function": "It is an unavoidable byproduct of exciting flue pipes with an air jet; a small amount of onset chiff gives a note a crisp, articulate start, while excessive hiss signals over-blowing, leaks, or a voicing fault.", "practical_application": "When recording or reinforcing a pipe organ, a technician places mics to balance musical tone against wind and chiff noise, and treats excessive hiss as an instrument voicing or wind-leak issue rather than a fault in the mic or chain.", "category": "Instrument noise", "related_terms": ["Organ wind noise", "Pipe hiss", "Chiff", "Flue pipe", "Wind pressure", "Voicing"], "common_mistakes": ["Mistaking the natural onset chiff of flue pipes for a defect and trying to EQ it all out, which strips the note's articulation.", "Assuming all organ hiss comes from the recording chain, when much of it is acoustic wind noise from the instrument itself.", "Confusing flue-pipe wind noise with reed-pipe buzz, which has a different cause and cure."], "scenario_contexts": ["Close-miking a pipe organ in a church and hearing breathy hiss at the start of each note.", "Diagnosing excessive hiss that traces to a leaking windchest pallet or too-high wind pressure.", "Balancing soft flue stops on a large organ where wind noise becomes audible in quiet passages."]}, "aae13383-2593-492c-bb7e-1d211f2ec3e0": {"definition": "An expressive brass articulation in which the player approaches the target note from below, bending the pitch upward with the embouchure, air, and (on valved or slide instruments) partial fingerings or slide position, so the note \"scoops\" into tune rather than starting cleanly on pitch. It is common in jazz and pop styles.", "plain_english": "When a brass player slides up into a note from underneath instead of hitting it dead-on. Like a singer swooping up to the right note rather than landing on it straight away.", "purpose_function": "It exists as a stylistic, vocal-sounding inflection that adds a bluesy, expressive lead-in to the start of a note.", "practical_application": "A technician tracking a horn section anticipates scoops on lead lines, avoids gating or transient shaping that would clip the rising pitch, and pitch-corrects only the landing note if any correction is needed at all.", "category": "Articulation", "related_terms": ["Portamento", "Glissando", "Fall-off", "Bend", "Embouchure", "Lip slur"], "common_mistakes": ["Treating a scoop as sloppy intonation and pitch-correcting it out, removing the intended expression.", "Confusing a scoop, which rises into a note, with a fall or doit that drops off the end of a note.", "Assuming every scoop is a wide glissando; many are quick inflections of a semitone or less."], "scenario_contexts": ["Recording a jazz trumpet lead that scoops into the first note of each phrase.", "A pop horn section adding scoops to accent the hits in a chart.", "Editing a comped horn take where scoops must line up rhythmically across the section."]}, "4a3f8368-2d28-463d-be50-46c57a554d6d": {"definition": "A continuous, sliding change of pitch between two notes on a wind instrument—a portamento or glissando—produced by gradually changing embouchure, air, and finger or key coverage so the pitch \"smears\" smoothly rather than moving in discrete steps. The clarinet glissando that opens Gershwin's Rhapsody in Blue is the classic example.", "plain_english": "A smooth slide from one note to another on a wind instrument, with no clear steps in between. Like sliding your finger up a slide whistle so the pitch glides instead of jumping.", "purpose_function": "It is an expressive device that connects two pitches with a continuous glide, giving a vocal or bluesy inflection between notes.", "practical_application": "A technician recording woodwinds keeps mic distance consistent so the glide's tone stays even, and avoids automation or gating that would interrupt the sliding pitch.", "category": "Articulation", "related_terms": ["Portamento", "Glissando", "Pitch scoop (brass)", "Embouchure", "Bend", "Legato"], "common_mistakes": ["Confusing portamento, a continuous slide, with legato, which connects discrete pitches smoothly but without a glide.", "Assuming any wind instrument can smear a full glissando; smooth slides are easiest on clarinet and saxophone and limited on others.", "Editing out the sliding pitch as if it were a tuning error."], "scenario_contexts": ["Recording the clarinet glissando that opens Rhapsody in Blue.", "A saxophonist smearing up into a note during a jazz solo.", "Comping wind takes where the start pitch of a smear must be timed to the beat."]}, "53bfe5d9-6229-4d1f-b171-095e48ed53c7": {"definition": "The characteristically breathy, wind-rich timbre of the quena, a traditional Andean end-blown notched flute. Because the player's air jet is split across an open notch, the sound carries a strong component of turbulent breath noise alongside the pitched tone, giving it an airy, exhaled quality.", "plain_english": "The breathy, whispery sound of the quena, an Andean flute you blow across a notch at the top. It always sounds a bit like someone breathing out, mixed with the melody.", "purpose_function": "The airy quality is inherent to the quena's notch and edge-tone excitation and is prized as an expressive, vocal characteristic of Andean flute music rather than treated as a fault.", "practical_application": "A technician recording a quena chooses a mic and distance that capture the breathy character without exaggerating wind blast, and avoids heavy de-noising that would strip the instrument's signature air.", "category": "Timbre", "related_terms": ["Breath noise", "Edge tone", "Notched flute", "Embouchure", "Overblowing", "Air jet"], "common_mistakes": ["Treating the quena's natural breathiness as a recording defect and gating or de-noising it away.", "Miking too close and on-axis to the notch, capturing wind blast and pops instead of a balanced tone.", "Confusing the airy tone with the sound of a leaky or poorly made instrument."], "scenario_contexts": ["Recording an Andean folk ensemble featuring a solo quena.", "Blending a breathy quena into a mix without losing its signature air.", "Choosing mic placement to tame wind noise on a close-miked quena."]}, "342381fe-ab75-4c2e-92c0-8fb325000473": {"definition": "The onset transient of a note on a reed instrument—the brief interval in which the reed begins vibrating and the air column builds to steady oscillation after the player tongues or starts the note. Its speed and character are shaped by tonguing, breath pressure, and reed response, and largely determine how crisp or soft the note's beginning sounds.", "plain_english": "The very start of a note on a reed instrument, when the reed first begins to buzz and the tone builds up. Like the difference between a sharp t and a soft d at the front of a word.", "purpose_function": "The attack sets articulation and clarity; a clean, well-defined onset lets notes speak precisely, which matters for ensemble timing and for the intelligibility of fast passages.", "practical_application": "A technician sets levels and transient handling with reed attacks in mind, avoiding compression or limiting that dulls the tongued onset, and mics the instrument to preserve articulation.", "category": "Reed acoustics", "related_terms": ["Reed vibration", "Attack transient", "Tonguing", "Articulation", "Embouchure", "Reed noise"], "common_mistakes": ["Over-compressing reed tracks so the tongued attack is squashed and the articulation blurs.", "Confusing a soft attack chosen by the player with a slow-speaking or damaged reed.", "Gating with too slow an attack setting, which clips the note's start."], "scenario_contexts": ["Recording a fast staccato clarinet passage where every attack must stay crisp.", "A saxophone lead where the engineer preserves tongued attacks under compression.", "Diagnosing whether a mushy note onset is caused by the player, the reed, or the processing."]}, "59651ad7-b364-4eaa-a8f1-7914c3eb27dc": {"definition": "The buzzing, harmonically rich sound produced by a musical reed as it beats against the mouthpiece or an opposing reed; more loosely, an unwanted rattling buzz from a chipped, warped, or improperly seated reed. The buzz reflects the reed's non-sinusoidal, valve-like opening and closing of the airflow.", "plain_english": "The buzzy sound a reed makes as it flaps very fast against the mouthpiece. A good buzz gives the tone its edge; a bad one is an unwanted rattle from a damaged reed.", "purpose_function": "The reed's buzzing action is how a reed instrument turns steady breath into a rich, harmonic tone; controlling that buzz shapes the note's brightness and edge.", "practical_application": "A technician distinguishes the musical buzz of a healthy reed from a rattling defect, and chooses mics and EQ that flatter the reed's edge without exaggerating harshness.", "category": "Reed acoustics", "related_terms": ["Reed vibration", "Reed crow", "Harmonics", "Timbre", "Embouchure", "Reed noise"], "common_mistakes": ["Mistaking the natural buzzy edge of a reed for distortion in the signal chain.", "Ignoring a rattling buzz that actually signals a chipped or warped reed.", "Boosting the upper mids so much that the reed buzz turns harsh and fatiguing."], "scenario_contexts": ["Miking a bassoon or oboe and capturing the reed's buzzy harmonics.", "Troubleshooting a rattle that turns out to be a damaged reed rather than the mic.", "Taming excessive reed buzz on a close-miked saxophone with gentle EQ."]}, "8fa81af0-4c3f-4618-ac89-41b57ac46d23": {"definition": "The raucous, rattling sound a double reed (oboe, bassoon, or similar) makes when blown by itself, away from the instrument, with the lips near the base of the reed. Reed makers and players judge a reed's response, pitch, and balance by the character and pitches of its \"crow.\"", "plain_english": "The harsh, crackly squawk a double reed makes when you blow it on its own, off the instrument. Reed makers listen to this crow to tell if a reed is ready to play.", "purpose_function": "The crow is a diagnostic test used in reed-making and setup; its pitch and rattle indicate whether a reed is too hard, too soft, or well balanced before it is played on the instrument.", "practical_application": "While not a performance sound, a technician may hear players crowing reeds during setup; recognizing it helps tell reed-testing sounds apart from instrument faults during a session.", "category": "Reed acoustics", "related_terms": ["Reed vibration", "Reed buzz", "Double reed", "Embouchure", "Reed noise", "Reed attack"], "common_mistakes": ["Thinking the crow is a performance technique rather than an off-instrument test of the reed.", "Assuming a good-sounding crow guarantees good intonation once the reed is on the instrument.", "Confusing a player's reed-crowing during setup with a squeak or fault in the recording."], "scenario_contexts": ["An oboist crowing a reed to check its pitch before a take.", "A bassoonist adjusting a reed until its crow sits at the expected pitches.", "An engineer recognizing crowing sounds during setup instead of flagging them as noise problems."]}, "6befba2e-d7f7-422a-9751-727e8441561a": {"definition": "The non-pitched, broadband noise that accompanies the musical tone of a reed instrument—chiefly turbulent breath noise passing the reed and mouthpiece, plus subtle reed rattle—audible especially at soft dynamics and note onsets, and distinct from the harmonic tone the reed produces.", "plain_english": "The airy, hissy sound mixed in with a reed instrument's notes, mostly from breath rushing past the reed. It is most noticeable on quiet notes and at the start of notes.", "purpose_function": "It is a natural byproduct of driving a reed with turbulent airflow; a little adds breathy realism, while too much (or added key and rattle noise) muddies close-miked recordings.", "practical_application": "A technician manages reed noise through mic choice, placement, and gentle high-frequency control, keeping enough for realism without excessive hiss on intimate recordings.", "category": "Reed acoustics", "related_terms": ["Reed buzz", "Reed vibration", "Breath noise", "Key noise", "Reed attack", "Timbre"], "common_mistakes": ["Aggressively de-noising or de-essing reed tracks until they sound lifeless and unnatural.", "Blaming the preamp or mic for hiss that is actually acoustic breath and reed noise.", "Close-miking directly at the mouthpiece so breath noise overwhelms the tone."], "scenario_contexts": ["An intimate close-miked clarinet where breath noise is audible on soft notes.", "Choosing mic distance on saxophone to balance body tone against reed and breath noise.", "Cleaning up a solo woodwind recording without stripping its natural air."]}, "f0405525-d323-4e15-8a9f-a1913400700b": {"definition": "The self-sustained oscillation of a cane or synthetic reed that drives a wind instrument's air column. Acting as a pressure-controlled valve, the reed opens and closes to modulate the airflow into the instrument at the resonance of the coupled air column, converting steady breath into a periodic acoustic tone.", "plain_english": "The fast flapping of a reed that makes a woodwind sound. Steady breath makes the reed open and shut many times a second, chopping the air into a musical note, a bit like a buzzing valve.", "purpose_function": "Reed vibration is the sound source of reed instruments; it turns constant breath pressure into the rapid pressure pulses that excite and sustain the air column's tone.", "practical_application": "Understanding that the reed and air column work together helps a technician interpret tone, tuning, and squeaks, and explains why reed condition and embouchure change the recorded sound so much.", "category": "Reed acoustics", "related_terms": ["Reed attack", "Reed buzz", "Air column", "Embouchure", "Single reed", "Double reed"], "common_mistakes": ["Thinking the reed vibrates at its own fixed pitch, when the coupled air column largely sets the sounding frequency.", "Assuming a stiffer reed always sounds better, ignoring how it changes response and attack.", "Overlooking that reed condition, such as moisture or chips, strongly affects the recorded tone."], "scenario_contexts": ["Explaining why a worn reed changes a saxophone's recorded tone mid-session.", "Understanding squeaks as disrupted reed vibration rather than a fault in the signal chain.", "Relating a player's embouchure changes to shifts in the tone captured by the mic."]}, "6538c72e-ff2e-4ef3-bbc7-22a2d5e79f27": {"definition": "The aggressive, buzzing, brassy timbre of a pipe organ's reed stops — ranks whose pipes sound by a vibrating brass tongue beating against a shallot rather than by an air jet — in which prominent upper harmonics give a raspy, snarling edge, most notably in chorus reeds such as the Trumpet, Bombarde or Trompeta.", "plain_english": "On a pipe organ, some pipes make sound with a small vibrating metal tongue instead of a plain jet of air. These reed pipes have a buzzy, brassy growl. That harsh edge is called the snarl.", "purpose_function": "Reed stops add power, bite and a brass-like voice to the organ chorus; the snarling edge lets them cut through full organ and carry solo lines over the smoother flue ranks.", "practical_application": "An organist hears reed snarl when drawing chorus reeds for a big tutti, and a voicer or tuner sets the tongue curvature and tuning wire to keep the snarl even across the rank without turning harsh or spitting.", "category": "Organ timbre", "related_terms": ["Reed stop", "Shallot", "Chorus reed", "Flue pipe", "Stop-change thunk", "Voicing"], "common_mistakes": ["Assuming every organ pipe is a reed; most stops are flue (labial) pipes that sound with an air jet, not a beating tongue.", "Mistaking a musical reed snarl for a fault, when a rough, spitting or uneven reed usually means the tongue, tuning wire or shallot needs regulating.", "Thinking the snarl comes from the resonator alone; the tongue and shallot set the buzz, and the resonator shapes and reinforces it."], "scenario_contexts": ["Drawing chorus reeds like the Trumpet and Bombarde for a full-organ climax and hearing them snarl above the flue chorus.", "A voicer regulating a new reed rank so the snarl is even from bass to treble.", "A tuner curving the tongue and setting the tuning wire on a Trompeta to control brightness and edge."]}, "4a683819-2393-48dd-b3a6-bd5d50931237": {"definition": "The loud, piercing, buzzy tone of the rhaita (Maghrebi ghaita) and mizmar — conical-bore double-reed shawms of North Africa and the Arab world, related to the zurna — whose wide, open reed and flaring bell produce a penetrating, blaring sound suited to outdoor and ceremonial playing.", "plain_english": "The rhaita and mizmar are loud folk oboes from North Africa and the Middle East. Their big double reed and open bell give a bright, buzzy blast that carries far outdoors. That piercing sound is the blare.", "purpose_function": "The blaring tone lets these shawms lead outdoor processions, weddings and dances without amplification; the double reed and conical bore make the instrument naturally loud and rich in high harmonics.", "practical_application": "An engineer capturing a rhaita or mizmar expects very high levels and sharp upper harmonics, so they pad the input, back the mic off and watch for harshness in the upper mids.", "category": "Instrument timbre", "related_terms": ["Zurna", "Shawm", "Double reed", "Circular breathing", "Conical bore", "Reed-stop snarl"], "common_mistakes": ["Calling the rhaita or mizmar a single-reed instrument; both are double-reed shawms like the zurna, not clarinet-type instruments.", "UNSAFE: Close-miking a rhaita or mizmar at full blare with no pad and no hearing protection; these shawms reach very high sound-pressure levels that risk hearing damage and input overload.", "Treating the buzzy blare as distortion to be equalized away, when the strong high harmonics are the instrument's real voice."], "scenario_contexts": ["Miking a mizmar in an Egyptian wedding band and adding a pad to handle the loud, piercing level.", "A world-music session where the rhaita must sit over drums without swamping the mix.", "An engineer gently taming harsh upper-mid blare while keeping the instrument's character."]}, "30a664c3-99b4-4446-9f21-b81b269a2c59": {"definition": "Two expressive brass approaches to a note: a rip is a fast, aggressive upward flourish that races through the harmonic series into a target pitch, while a smear is a slower slide or bend that glides into or between pitches using lip and partial-valve control.", "plain_english": "On brass instruments, a rip is a quick, rough slide up into a note. A smear is a slower slide or bend into it. Think of a trumpet player scooping up to a big note in a jazz band.", "purpose_function": "Rips and smears add jazz and blues expression, letting brass players attack notes with excitement or ease instead of hitting them cleanly; they shape phrasing and style in big-band and pop writing.", "practical_application": "An arranger notates a rip or smear so brass players know to slide into the note, and an engineer mixing the section leaves headroom for the loud, bright peak a rip lands on.", "category": "Brass technique", "related_terms": ["Glissando", "Fall (brass)", "Doit", "Scoop", "Harmonic series", "Half-valve"], "common_mistakes": ["Confusing a rip with a clean glissando; a rip is a fast, rough flourish through the harmonics, not a smooth continuous slide.", "Playing a smear as a hard, in-tune interval, when the effect depends on bending lazily into the pitch rather than snapping to it.", "Notating a rip with no target note, leaving the player unsure where the flourish should land."], "scenario_contexts": ["A big-band trumpet section ripping up to a shout-chorus hit.", "A trombonist smearing into a bluesy melody note.", "An arranger marking rips and smears in a horn chart for a pop record."]}, "b4daca01-1616-4199-80dc-e8b50c587897": {"definition": "The rough, buzzing, gravelly bass tone of the serpent — a curved, leather-covered wooden lip-reed instrument of the cornett family with open finger holes — and of the ophicleide, its 19th-century keyed-brass successor; both are blown with a cup mouthpiece and noted for a coarse, rasping voice that filled the bass before the tuba.", "plain_english": "The serpent and ophicleide are old bass horns you buzz your lips into, like a tuba's ancestors. Their sound is rough and buzzy. That gritty growl is called the rasp.", "purpose_function": "These instruments supplied the bass voice in early wind bands, churches and orchestras before the tuba; the rasp comes from wide finger or key holes and a large cup mouthpiece that make the low notes speak with a coarse edge.", "practical_application": "A player or engineer working with period instruments expects the serpent's and ophicleide's uneven, rasping low notes and mics them close to capture body without exaggerating the buzz.", "category": "Instrument timbre", "related_terms": ["Cornett", "Ophicleide", "Cup mouthpiece", "Lip reed", "Tuba", "Keyed bugle"], "common_mistakes": ["Classing the serpent as a woodwind because it is made of wood; it is sounded by buzzing the lips, so acoustically it belongs with the brass or lip-reed family.", "Treating the natural rasp as a defect, when the coarse tone is characteristic of these instruments rather than a fault.", "Assuming the ophicleide is valved like a modern tuba; it uses keys and tone holes, like a large keyed bugle."], "scenario_contexts": ["Recording a period-instrument ensemble where the serpent doubles the bass line in a church acoustic.", "An ophicleide standing in for a tuba in a historically informed performance of early Romantic music.", "An engineer choosing mic placement to capture the rasp without harshness."]}, "47d1b0de-f64e-428b-b64f-55b5f9bc9f46": {"definition": "The sheng's ability to sound several of its free-reed bamboo pipes at once, producing chords or intervals rather than a single line — traditionally parallel fourths and fifths and, on modern instruments, full harmonies — since each reed speaks only when its pipe's finger hole is covered and the player blows or draws air.", "plain_english": "The sheng is a Chinese mouth organ made of bamboo pipes. Each pipe has a small vibrating metal reed. Unlike a flute or trumpet, it can play several notes at once, so a player can hold a whole chord.", "purpose_function": "Chord playing lets the sheng provide harmony and sustained accompaniment within an ensemble, a rare trait among wind instruments; the free reeds give steady tone whether the player blows out or draws in.", "practical_application": "An arranger uses the sheng for held chords and clusters under a melody, and an engineer mics it to capture the blend of several pipes without favoring one reed.", "category": "Instrument technique", "related_terms": ["Free reed", "Mouth organ", "Sho", "Tone cluster", "Reed stop", "Harmony"], "common_mistakes": ["Thinking the sheng plays only one note at a time like a flute, when it is built to sound several pipes together for chords.", "Assuming a pipe sounds when its hole is open; a sheng reed speaks only when the finger hole is covered.", "Expecting sound on the out-breath only, when the free reeds sound on both blowing and drawing air."], "scenario_contexts": ["A sheng holding sustained chords beneath a dizi melody in a Chinese orchestra.", "A modern keyed sheng playing full harmonies in a contemporary work.", "Miking a sheng to blend its stacked pipe tones evenly."]}, "aee3bb6d-d78e-4ad5-affa-57e603a9de3a": {"definition": "A tone sounded on the shofar — an ancient natural horn made from a ram's or other kosher animal's horn and blown by buzzing the lips like a brass instrument — which, having no finger holes or valves, yields only two or three harmonic pitches; the ritual calls tekiah, shevarim and teruah are its prescribed blasts in Jewish liturgy.", "plain_english": "A shofar is a ram's horn you play by buzzing your lips, like a simple trumpet with no buttons. Because it has no finger holes, it makes just two or three notes. The loud calls it sounds are its blasts.", "purpose_function": "The shofar's blast serves as a ceremonial signal and call in Jewish worship, above all at Rosh Hashanah and Yom Kippur; with no valves or holes it relies on lip tension to reach its few available pitches.", "practical_application": "An engineer recording a shofar in a service expects a loud, buzzy, narrow-pitch tone and places the mic off the bell axis so the blasts do not overload the input.", "category": "Instrument timbre", "related_terms": ["Natural horn", "Lip reed", "Harmonic series", "Overblowing", "Embouchure", "Cup mouthpiece"], "common_mistakes": ["Thinking the shofar can play a melody, when with no holes or valves it sounds only two or three harmonics.", "Assuming it is a woodwind; the shofar is lip-blown, so acoustically it is a natural horn in the brass family.", "Expecting a smooth, refined tone, when the shofar's voice is meant to be raw and penetrating."], "scenario_contexts": ["Miking a shofar for a Rosh Hashanah service broadcast.", "Capturing the tekiah and teruah calls cleanly despite their loud, buzzy peaks.", "A sound designer using a shofar blast as a signal or dramatic effect."]}, "f73c62e4-0041-48f5-8011-a36ebe2c7918": {"definition": "A bubbling or crackling sound produced when condensation from the player's warm breath collects in the bore of a wind or brass instrument and disturbs the airflow, typically near valves, tone holes or tubing bends; it is cleared with a water key (spit valve), by emptying slides, or by swabbing.", "plain_english": "When you blow warm breath into a horn, tiny water drops form inside, like fog on a cold window. When that water pools in the tubing, air bubbling through it makes a gurgle. Players open a little water key to drain it.", "purpose_function": "The gurgle is a byproduct of condensation, not a musical feature; recognizing it tells the player to drain the instrument so notes speak cleanly instead of sputtering.", "practical_application": "A brass player empties the water key during a rest to stop gurgling, and a live engineer learns to expect the odd bubbling noise and may edit or ride around it on a recording.", "category": "Wind maintenance", "related_terms": ["Water key", "Spit valve", "Condensation", "Bore", "Swab", "Valve"], "common_mistakes": ["Thinking the water is mostly saliva, when it is mainly condensation from warm, moist breath cooling inside the metal tubing.", "Blaming a gurgle or airy note on the reed or embouchure when the bore simply needs draining.", "Forgetting to empty the water key or slides during rests, so notes sputter at the worst moment."], "scenario_contexts": ["A trumpet player draining the water key between phrases to stop a gurgle.", "An engineer hearing a bubbling noise on a trombone take and asking for another pass.", "A tuba player emptying condensation from the slides during a long rehearsal."]}, "3d55a63d-6e87-4412-bec5-7e7467bc69fb": {"definition": "The soft mechanical thump heard on a pipe organ when stops are drawn or retired — the drawknobs, sliders or combination-action pistons moving ranks into or out of play — an incidental noise of the stop action rather than a musical tone.", "plain_english": "A pipe organ turns sets of pipes on and off using stops. When the player changes stops, the mechanism moves. You can hear a soft thunk, most of all when the preset buttons switch many stops at once.", "purpose_function": "The thunk is a side effect of the stop or combination action engaging ranks; hearing it confirms the mechanism moved, though a well-regulated action keeps the noise low.", "practical_application": "An organist times stop changes to musical rests to hide the thunk, and a technician regulates the combination action or slider motors when the noise grows loud or the change is sluggish.", "category": "Organ mechanism", "related_terms": ["Stop (organ)", "Combination action", "Drawknob", "Slider chest", "Reed-stop snarl", "Registration"], "common_mistakes": ["Mistaking a normal stop-change thunk for a mechanical fault, when a light thump is inherent to slider and combination actions.", "Changing many stops during a quiet passage, letting the thunk intrude instead of hiding it in a louder moment or rest.", "Ignoring a thunk that grows louder or uneven, which can signal a combination action or slider motor needing service."], "scenario_contexts": ["An organist hitting a general piston mid-piece and hearing the stops thunk in.", "A technician regulating an electro-pneumatic combination action to quiet the change.", "A recording engineer placing mics to minimize audible stop-change noise during a broadcast."]}, "a68c16c2-098e-4954-9197-40894d527fdf": {"definition": "An unwanted squeal or squawk at the moment of strike-in — the start of the bagpipe, when the player fills the bag and strikes it to set the drone and chanter reeds sounding together — caused when the reeds fail to speak cleanly at once under uneven or insufficient bag pressure.", "plain_english": "A piper starts the pipes by filling the bag and giving it a firm squeeze, so all the reeds sound at once. If the pressure is uneven, a reed can squeak before it settles. That messy start is the strike-in squeal.", "purpose_function": "A clean strike-in is a mark of good piping; the squeal signals that bag pressure or reed setup is off, so removing it means the drones and chanter speak together crisply.", "practical_application": "A piper practices a firm, even strike-in to avoid the squeal, and adjusts reed strength or seating when a reed squawks at start-up every time.", "category": "Bagpipe technique", "related_terms": ["Chanter", "Drone", "Bag pressure", "Reed", "Cut-off", "Strike-in"], "common_mistakes": ["Filling the bag too slowly or with uneven pressure, so a reed squeals instead of the pipes striking in cleanly.", "Blaming the squeal on the chanter reed alone when a drone reed or the strike itself is at fault.", "Neglecting reed seating and strength, letting the same reed squawk at every start-up."], "scenario_contexts": ["A piper striking in before a competition and fighting a chanter squeal.", "A pipe band tuning up where uneven strike-ins cause squeals across the corps.", "An engineer recording pipes and editing out a squeal at the start of a take."]}, "78f5ae2e-4e29-4c58-9481-d16715a4ed33": {"definition": "The loud, bright, penetrating and vocal (\"crying\" or \"wailing\") tone characteristic of the suona (the Chinese conical double-reed shawm) and, more broadly, of the shawm family; a small exposed double reed drives a conical bore ending in a flaring bell, giving a strident, human-voice-like sound prized for outdoor processions, weddings, and funerals.", "plain_english": "The suona is a Chinese double-reed horn, and the shawm is its old European cousin. Both make a very loud, bright, wailing sound, almost like a human cry. This crying tone cuts through crowds, so they are played outdoors at weddings and funerals.", "purpose_function": "The term names the signature timbre of these instruments, explaining why they project so powerfully outdoors and why their tone is often described as vocal or crying rather than smooth.", "practical_application": "A recording or live-sound engineer expects a very high sound-pressure level and strong upper harmonics from a suona or shawm, so they choose a mic and gain structure that will not overload and position it slightly off-axis to tame the harsh top.", "category": "Instrument timbre", "related_terms": ["Double reed", "Reed", "Shawm", "Overblowing", "Conical bore"], "common_mistakes": ["Treating the loud, crying tone as a fault or a reed problem when it is the instrument's intended sound.", "Miking a suona or shawm as if it were a soft oboe, then overloading the input on loud passages.", "Confusing the suona (double reed) with a valved brass instrument because of its bell and volume."], "scenario_contexts": ["A folk ensemble features a suona whose piercing cry must be balanced against quieter instruments.", "An engineer records a Renaissance shawm consort outdoors and manages its strident, penetrating tone.", "A film composer wants the wailing suona sound for a funeral scene."]}, "5bd8f3da-977f-4c7f-a3b6-4d4d11fd49bb": {"definition": "A tongue-blocking harmonica technique in which the player, while covering several holes with the tongue to isolate a single reed, briefly lifts the tongue so a full chord sounds and then instantly re-blocks it, producing a short percussive chordal \"slap\" that accents the melody note.", "plain_english": "On a harmonica you can cover some holes with your tongue to play just one note. In a chord slap you lift your tongue for a split second so a full chord sounds, then put it back to leave the single note. It works like a quick drum hit before the melody note.", "purpose_function": "The technique adds rhythmic, percussive emphasis and a fuller chordal texture to single-note lines, a staple of blues and traditional harmonica phrasing.", "practical_application": "A blues harmonica player punches accents with chord slaps, and an engineer recording the part hears brief chordal transients ahead of notes and sets levels or compression so the percussive attack stays clear without clipping.", "category": "Playing technique", "related_terms": ["Tongue blocking", "Warble (harmonica)", "Draw note", "Blow note", "Reed"], "common_mistakes": ["Not fully re-blocking after the slap, so the chord keeps ringing instead of leaving a clean single note.", "Slapping with inconsistent timing so accents fall out of the groove.", "Confusing the chord slap with a warble, which is a shake between two holes rather than a percussive accent."], "scenario_contexts": ["A blues harmonica player uses chord slaps to drive the rhythm of a shuffle.", "A student learns to isolate one hole while adding slaps for accent.", "An engineer compresses a harmonica track to keep the slapped chords even in level."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"b4da2580-91d2-4cd3-a24f-d9a9da5423b3": {"definition": "An organ device, controlled by its own stop or lever, that introduces a regular periodic fluctuation into the wind supply of a division, causing the sounding pipes to waver periodically in both loudness and pitch to produce a tremolo/vibrato (undulating) effect.", "plain_english": "A tremulant is an organ control that makes the wind pulse in a steady beat. This makes the notes gently waver in loudness and pitch, like a singer's vibrato. It adds warmth to slow, singing stops.", "purpose_function": "The tremulant adds expressive warmth and an undulating, voice-like quality to a registration, and exists to give the organ's otherwise steady tone the life of a natural vibrato.", "practical_application": "An organist engages the tremulant for solo or string-toned stops in slow, lyrical passages, and an organ technician regulates its rate and depth (adjusting spring tension, weight, or valve) so the beat is even and not too fast or violent.", "category": "Organ device", "related_terms": ["Stop", "Windchest", "Celeste", "Vibrato", "Tremolo"], "common_mistakes": ["Confusing the tremulant, which pulses the wind of a whole division, with a celeste, which beats by tuning two ranks slightly apart.", "Setting the tremulant rate too fast or too deep so the tone sounds seasick rather than warm.", "Using the tremulant on full or loud registrations where its wavering muddies the sound."], "scenario_contexts": ["An organist adds the tremulant to a solo reed stop for an expressive melody.", "A technician adjusts a sluggish tremulant so its beat becomes steady and musical.", "A recording of a slow hymn shows the gentle wavering of a tremulant on the string stops."]}, "45b8788c-6c70-42ac-b339-dcf064d049a7": {"definition": "A harmonica ornament in which the player rapidly alternates between two adjacent holes—usually by shaking the instrument from side to side or moving the head—so the two notes sound in fast oscillation, creating a trill- or tremolo-like \"warbling\" effect; also called a shake or trill.", "plain_english": "A warble is when you quickly rock a harmonica between two side-by-side holes. The two notes trade back and forth so fast that they blur into a shimmering, wavy sound. It is also called a shake.", "purpose_function": "The warble adds a shimmering, sustained ornament and rhythmic energy to a held note, and is one of the harmonica's most recognizable expressive effects.", "practical_application": "A blues or folk harmonica player uses a warble to color a long note or build intensity, and an engineer captures the fast oscillation cleanly, avoiding heavy noise gating that could chop the alternating notes.", "category": "Playing technique", "related_terms": ["Tongue-block chord slap", "Vibrato", "Draw note", "Reed", "Trill"], "common_mistakes": ["Shaking too slowly, so the effect sounds like two separate notes rather than a smooth warble.", "Confusing a warble (a shake between two holes) with vibrato (a pulsing of a single note).", "Gating a warbled note so hard that the rapid note changes are clipped."], "scenario_contexts": ["A harmonica player warbles a high draw note to end a blues phrase.", "A student practices an even shake to turn two notes into a smooth warble.", "An engineer records a warble and keeps the gate gentle so the shimmer stays intact."]}, "b8566e4d-cf0c-4fb3-985b-09e35355cb4c": {"definition": "The low-frequency, broadband rumble, roar, or thumping generated when moving air—outdoor wind or gusts of breath—creates turbulence at a microphone's diaphragm and grille; it is unrelated to the desired signal and is controlled with foam windscreens, furry windshields (blimps), and high-pass filtering.", "plain_english": "Wind noise is the low rumble a mic makes when moving air hits it. It is not part of the real sound you want to record. A foam or furry cover over the mic blocks most of it, like a scarf over your face on a windy day.", "purpose_function": "The term names a common noise problem so technicians can recognize air turbulence at the mic as the cause of low-frequency rumble and take the right steps to prevent it.", "practical_application": "For outdoor or breezy work a technician fits a foam windscreen or furry windjammer, engages a high-pass filter, and positions or shields the mic so wind does not strike the diaphragm directly.", "category": "Recording artifact", "related_terms": ["Windscreen", "High-pass filter", "Rumble", "Proximity effect", "Plosive"], "common_mistakes": ["Relying on a thin foam windscreen in strong wind when a furry windshield is needed.", "Assuming a pop filter, which is made for plosives, will stop outdoor wind noise.", "Cutting so much low end with the high-pass filter that the wanted sound is thinned out."], "scenario_contexts": ["A location recordist fits a windjammer to a shotgun mic for an outdoor interview.", "A live-sound engineer hears rumble from wind on a stage mic and adds a high-pass filter.", "A boom operator shields the mic from a gust so wind noise does not ruin a take."]}, "537b7fdd-2646-4d05-952c-d4b5bf2ddb98": {"definition": "The characteristic buzzing, nasal, reedy timbre of wind-cap instruments (such as the crumhorn, cornamuse, and rauschpfeife), in which a double reed is fully enclosed in a perforated cap that the player blows into rather than lipping the reed directly; the freely vibrating, uncontrolled reed gives a strong buzzy quality and a narrow dynamic range.", "plain_english": "Some old reed instruments hide the reed inside a cap that you blow into, instead of putting the reed on your lips. Because you cannot control the reed, it buzzes freely and gives a strong, nasal, humming tone. That buzzy sound is normal, not a fault.", "purpose_function": "The term names the signature timbre of wind-cap instruments, explaining why they sound buzzy and constant in volume and why the player cannot shape the tone with the lips.", "practical_application": "A player or early-music engineer recognizes wind-cap buzz as the normal sound of these instruments, mics them to capture the reedy character, and does not expect the loud-soft dynamics or bending possible on lip-controlled reeds.", "category": "Instrument timbre", "related_terms": ["Double reed", "Crumhorn", "Reed", "Overblowing", "Nasal tone"], "common_mistakes": ["Trying to bend, overblow, or swell the volume as on a lipped reed, which the enclosed reed cannot do.", "Mistaking the normal buzz for a cracked or faulty reed.", "Blowing harder to get louder, which just chokes or overblows the reed instead of adding volume."], "scenario_contexts": ["An early-music consort records crumhorns whose steady buzz sits under the ensemble.", "A student is surprised that a wind-cap instrument has almost no loud-soft control.", "An engineer places a mic to capture the reedy buzz of a rauschpfeife without harshness."]}, "ffd63fa8-572e-4b28-ae82-7bb72c595ab1": {"definition": "The soft, airy, breath-rich timbre characteristic of the xiao (a Chinese end-blown notched bamboo flute), in which audible breath noise from the air jet striking the blowing edge blends with the fundamental to give a mellow, intimate, slightly hollow tone; it is cultivated as an expressive feature rather than treated as a flaw.", "plain_english": "The xiao is a Chinese bamboo flute you blow across the top edge. Some of your breath is heard as soft, airy sound mixed in with the note. This gives it a gentle, close, breathy tone that players use on purpose.", "purpose_function": "The term names an intended expressive quality of the xiao, distinguishing its deliberate breathy color from unwanted noise and describing how the instrument's intimate sound is produced.", "practical_application": "An engineer close-mics a xiao to capture its delicate breath tone, choosing placement that keeps the airy character without turning it into harsh wind blasts, and avoids gating that would strip the intended breathiness.", "category": "Instrument timbre", "related_terms": ["Edge tone", "Air jet", "Embouchure", "Bansuri edge chiff", "Breath noise"], "common_mistakes": ["Gating or de-noising away all the breath, which removes the xiao's intended character.", "Confusing the instrument's breath tone with wind noise hitting the microphone.", "Blowing too hard chasing volume, which turns the soft airy tone into a harsh, breathy blast."], "scenario_contexts": ["A film composer wants an intimate solo xiao with its natural breath tone up close.", "An engineer positions the mic to keep the airy quality without wind blasts.", "A player shapes the breath tone expressively in a slow, meditative piece."]}, "f58519f2-dfe7-49c6-939f-e8b447b9819a": {"definition": "A music mix created in Dolby Atmos, an object-based, three-dimensional audio format in which sounds are carried as a channel-based bed (typically up to 7.1.2) together with individual audio objects that hold positional metadata. A renderer interprets that metadata to reproduce the mix over a range of speaker layouts, including overhead speakers, or as a binaural headphone signal.", "plain_english": "A song mixed so sounds can sit all around and even above the listener, not just left and right. It works like moving each instrument to its own spot in a room, including the ceiling.", "purpose_function": "It lets an engineer position and move sounds in three dimensions so one mix can adapt to many speaker setups or headphones, giving music a more spacious, enveloping presentation than stereo.", "practical_application": "An engineer routes tracks as objects or into the bed, places them in a 3D space with spatial panners, monitors through the Dolby Atmos Renderer, and delivers an ADM BWF master for immersive streaming platforms.", "category": "Immersive format", "related_terms": ["Immersive music mix", "Immersive bus structure", "Immersive bass management", "Immersive mix session", "Front-wall placement", "Immersive depth"], "common_mistakes": ["Overusing overhead and surround speakers so the mix sounds gimmicky rather than musical", "Not checking the binaural or stereo fold-down, which is how most listeners actually hear it", "Assuming Atmos automatically improves a weak stereo mix instead of remixing thoughtfully", "Failing to deliver a correct ADM BWF master for the target platform"], "scenario_contexts": ["Mixing an album for delivery to an immersive music streaming service", "Re-mixing a stereo catalog track into Dolby Atmos", "Checking an Atmos mix on headphones through the binaural render"]}, "21512fbc-9c38-4a20-8ed1-fa137a95671c": {"definition": "The positioning of sound elements, or of the loudspeakers themselves, at the front plane of an immersive listening space, the wall carrying the left, center, and right (and any screen) channels. In an immersive music mix, front-wall placement anchors focal elements such as lead vocal, bass, and drums toward the front so they stay stable and easy to locate.", "plain_english": "Putting the main sounds, like the lead singer, at the front of the room where the big speakers are. It is like keeping the singer on a stage in front of you instead of behind you.", "purpose_function": "It keeps important, focal sounds anchored and easy to locate at the front, matching listener expectation and translating well when the mix folds down to stereo.", "practical_application": "When building an immersive mix, an engineer places lead vocal and core rhythm elements as front objects or in the front bed channels, reserving surrounds and overheads for space, effects, and ambience.", "category": "Object placement", "related_terms": ["Immersive depth", "Dolby Atmos music mix", "Immersive bus structure", "Immersive music mix", "Immersive channel verification", "Immersive bass management"], "common_mistakes": ["Placing the lead vocal overhead or in the surrounds, giving an unstable image and poor stereo fold-down", "Ignoring the center channel and losing a solid front anchor for the vocal", "Assuming the front wall is only the center speaker rather than the left, center, and right plane"], "scenario_contexts": ["Anchoring a lead vocal at the front of a Dolby Atmos pop mix", "Keeping kick, snare, and bass at the front for punch and focus", "Confirming front-placed elements survive the binaural and stereo fold-down"]}, "f927f6c4-5b9f-445a-98a6-238afa2a4ce6": {"definition": "In an immersive playback or monitoring system, the routing function that filters low-frequency content out of channels that cannot reproduce it and redirects that energy to one or more subwoofers, kept separate from the dedicated low-frequency effects (LFE) channel. A crossover, commonly around 80 to 120 Hz, splits the low band from the main channels so smaller speakers are protected and the low end is reproduced correctly.", "plain_english": "A way of sending the deep bass to a subwoofer when the other speakers are too small to play it. It is like giving the heavy lifting to one strong speaker so the little ones do not strain.", "purpose_function": "It gives consistent, full low-frequency reproduction and protects smaller monitors from overload, helping an immersive mix translate across systems with different speaker sizes.", "practical_application": "In the Dolby Atmos Renderer or an immersive monitor controller, a technician sets the bass-management crossover and confirms that low frequencies from full-range channels route to the subwoofer while the LFE channel stays separate.", "category": "Low-frequency management", "related_terms": ["Immersive bus structure", "Immersive channel verification", "Dolby Atmos music mix", "Immersive mix session", "Immersive music mix", "Immersive depth"], "common_mistakes": ["Confusing bass management, a playback redirection, with the LFE channel, which is a discrete content channel", "Routing musical low end into the LFE channel instead of leaving it in the full-range beds and objects", "Assuming every playback system applies the same crossover, so the low-end balance is misjudged"], "scenario_contexts": ["Monitoring an Atmos mix on a rig with small overhead speakers plus a subwoofer", "Setting the bass-management crossover in the renderer before a mix session", "Checking translation between a full-range room and a bass-managed one"]}, "ccbc7df4-0e2a-4ea6-8d3b-1821936bd10f": {"definition": "The routing architecture of an immersive mix session, meaning the arrangement of channel buses, group and aux buses, bed sub-mixes, and object outputs that feed audio to an immersive renderer. It defines how individual tracks are grouped and assigned either to a channel-based bed or to discrete objects carrying positional metadata.", "plain_english": "The plan for how all the tracks flow through the mixer and reach the immersive renderer. It is like a road map that decides which sounds travel together and which get their own lane.", "purpose_function": "It organizes a complex three-dimensional mix so each sound is correctly assigned to a bed channel or an object and reaches the renderer in an orderly, repeatable way.", "practical_application": "An engineer sets up group buses for drums or backing vocals, sends them to bed channels or object outputs, and routes everything to the renderer so panning and metadata are captured correctly.", "category": "Signal routing", "related_terms": ["Immersive mix session", "Immersive mix template", "Immersive channel verification", "Immersive bass management", "Dolby Atmos music mix", "Front-wall placement"], "common_mistakes": ["Routing the same source to both a bed channel and an object, causing doubled or phasey audio", "Assigning too many objects and running out of object outputs for the renderer", "Using disorganized bus names that make later channel verification slow and error-prone"], "scenario_contexts": ["Building the routing for a large multi-track Atmos session", "Deciding which stems go to the bed and which become objects", "Troubleshooting a signal that reaches the wrong renderer input"]}, "5f040606-dea6-4cf8-b11f-b41ce7a8027e": {"definition": "The process of confirming that every output of an immersive mix session maps to the correct renderer input, bed channel, or loudspeaker before and during mixing. It commonly uses test tones, noise, or solo checks to verify that each bed channel and object output plays from its intended location.", "plain_english": "Checking that every sound comes out of the right speaker before you start mixing. It is like a sound check where you make sure the left speaker really is the left one.", "purpose_function": "It catches wiring, routing, or assignment errors early so that objects and bed channels reproduce from their intended positions, keeping the spatial mix accurate.", "practical_application": "A technician sends a tone or noise to each bed channel and object in turn, then listens or watches meters to confirm it appears at the correct speaker and renderer input.", "category": "Verification", "related_terms": ["Immersive bus structure", "Immersive mix session", "Immersive bass management", "Dolby Atmos music mix", "Front-wall placement", "Immersive mix template"], "common_mistakes": ["Skipping verification and discovering swapped surround channels late in the mix", "Trusting channel labels instead of testing the actual speaker output", "Not re-checking routing after changing the monitor layout or re-patching outputs"], "scenario_contexts": ["Commissioning a new Dolby Atmos monitoring room", "Running a routing check before delivering a master", "Re-verifying outputs after re-patching the monitor controller"]}, "195e2004-2e64-4c78-8f82-758310286f0c": {"definition": "The perceived front-to-back dimension of an immersive sound field, the sense of distance and layering between sounds placed near the listener and those placed farther away. It is produced with front-to-rear speaker positioning combined with level, early-reflection, reverberation, and high-frequency cues.", "plain_english": "The feeling of some sounds being close and others far away in a mix. It is like looking down a street where near things seem big and far things seem small, but for your ears.", "purpose_function": "It adds realism and separation to an immersive mix, letting the listener sense space between elements instead of hearing everything at one distance.", "practical_application": "An engineer creates depth by panning elements toward the rear, lowering their level, rolling off highs, and adding reverberation so they sit behind the front-anchored sounds.", "category": "Spatial attribute", "related_terms": ["Front-wall placement", "Immersive music mix", "Dolby Atmos music mix", "Immersive bus structure", "Immersive mix session", "Immersive bass management"], "common_mistakes": ["Confusing depth, the front-to-back dimension, with mix width or height", "Using only level to imply distance while ignoring reflections and reverberation", "Adding so much reverberation for depth that the mix loses clarity"], "scenario_contexts": ["Placing background vocals behind the lead in an Atmos mix", "Creating a sense of a room around a live immersive recording", "Layering pads far back while keeping drums up front"]}, "3e885d0d-7334-4495-ae1f-c2c1e4101e43": {"definition": "A digital audio workstation session configured for immersive mixing, with tracks routed to bed channels and objects, spatial panners inserted, and outputs connected to an immersive renderer for monitoring and mastering. It holds the full arrangement, routing, automation, and metadata needed to produce an immersive mix.", "plain_english": "The project file in the mixing software set up to build a surround-and-height mix. It is like a workshop already laid out with the right tools before you start the job.", "purpose_function": "It provides the working environment where all tracks, routing, panning, and automation for an immersive mix live together and connect to the renderer.", "practical_application": "An engineer opens or builds the session, assigns tracks to beds or objects, automates 3D panning, and monitors through the renderer while mixing.", "category": "Session setup", "related_terms": ["Immersive mix template", "Immersive bus structure", "Immersive channel verification", "Dolby Atmos music mix", "Immersive music mix", "Immersive bass management"], "common_mistakes": ["Starting from a plain stereo session without proper immersive routing", "Not saving the setup as a reusable template for future projects", "Letting the DAW session and renderer settings fall out of sync"], "scenario_contexts": ["Setting up a new Dolby Atmos project", "Converting a stereo session for an immersive remix", "Recalling a saved session to revise an immersive mix"]}, "fa652a78-92e9-4b55-a6fb-e69e151cf89a": {"definition": "A pre-built, reusable DAW session file that contains the standard routing, bed and object output assignments, bus structure, and monitoring setup for an immersive mix. Loading it lets an engineer begin a new immersive project without rebuilding the signal flow each time.", "plain_english": "A ready-made starting file for immersive mixes with the wiring already done. It is like a blank form that already has all the boxes and lines in the right place.", "purpose_function": "It saves setup time and enforces a consistent, error-free routing structure across immersive projects.", "practical_application": "An engineer loads the template, imports or records tracks into its pre-routed beds and object slots, and begins mixing immediately.", "category": "Session setup", "related_terms": ["Immersive mix session", "Immersive bus structure", "Immersive channel verification", "Dolby Atmos music mix", "Immersive music mix", "Front-wall placement"], "common_mistakes": ["Using an outdated template whose routing no longer matches the current renderer setup", "Not adjusting the object count to suit the size of the project", "Assuming the template's monitor layout matches the actual room"], "scenario_contexts": ["Standardizing Atmos setups across a studio's engineers", "Quickly starting a new immersive project from a known-good file", "Onboarding an assistant with a consistent routing structure"]}, "6dce7214-9b3c-4810-9dcc-c2764a840e74": {"definition": "A music mix produced in an immersive, three-dimensional audio format such as Dolby Atmos, Sony 360 Reality Audio, or Auro-3D, that places sounds around and above the listener using surround and height channels or object-based positioning. It is monitored and delivered through a format-specific renderer or encoder rather than a two-channel stereo bus.", "plain_english": "A song mixed to surround the listener with sound from all sides and overhead. It is like sitting inside the band instead of hearing them from across the room.", "purpose_function": "It gives music a spacious, enveloping presentation and supports playback on immersive systems and headphones, going beyond the left-right limits of stereo.", "practical_application": "An engineer distributes vocals, instruments, and effects across the surround and height field, monitors on an immersive system, and exports a format-specific master for streaming.", "category": "Immersive format", "related_terms": ["Dolby Atmos music mix", "Immersive mix session", "Immersive depth", "Front-wall placement", "Immersive bus structure", "Immersive bass management"], "common_mistakes": ["Treating it as just a louder or wider stereo mix", "Ignoring how it folds down to stereo or binaural for most listeners", "Overusing height and surround so the result sounds unnatural"], "scenario_contexts": ["Delivering an album in both Dolby Atmos and 360 Reality Audio", "Remixing a catalog track for immersive streaming", "Checking the binaural headphone fold-down of an immersive mix"]}, "8748f017-be02-4357-8d72-82822ac4b846": {"definition": "The standardized, calibrated sound-pressure level at which an immersive (object-based) program is monitored, fixing the relationship between a given digital signal level and the acoustic level at the mix position. In Dolby Atmos cinema practice each full-range screen channel is aligned to 85 dB SPL (C-weighted, slow) using band-limited pink noise at -20 dBFS, while near-field and home or music rooms calibrate every speaker to a consistent, usually lower, per-speaker reference.", "plain_english": "This is the loudness a room is set to when mixing surround-with-height sound. The engineer plays a test noise and adjusts each speaker so a set signal makes a set volume. When every studio uses the same reference, a mix sounds the same everywhere. It is like tuning all the pianos to the same pitch.", "purpose_function": "It gives a fixed link between the signal level on the meters and real loudness in the room, so mixes made in different rooms match and translate to cinemas, home systems, and streaming.", "practical_application": "A technician calibrates the room with an SPL meter and -20 dBFS pink noise, setting each speaker to the target level before an immersive mix, and rechecks after any monitor or gain change.", "category": "Monitoring & calibration", "related_terms": ["Monitor calibration", "Pink noise", "SPL meter", "Loudness normalization", "Bass management", "Dolby Atmos"], "common_mistakes": ["Calibrating with A-weighting or fast metering instead of C-weighted, slow, which reports the wrong level", "Setting the reference by ear instead of using pink noise and an SPL meter", "Assuming the cinema 85 dB per-channel reference applies unchanged to a small near-field room", "UNSAFE: Monitoring for long sessions much above about 85 dBA risks hearing damage; follow OSHA and NIOSH exposure limits and take regular breaks"], "scenario_contexts": ["Calibrating a Dolby Atmos music room before a mix so it matches other studios", "Aligning a home theater's speakers to reference for accurate playback", "Troubleshooting why a mix plays too loud or too quiet on another system", "Setting monitoring level so metering lines up with delivery loudness targets"]}, "7e4611ed-2c30-4be9-903b-d1089f823b8f": {"definition": "The organized set of grouped submixes (stems) exported from an immersive project in a way that preserves its bed-and-object layout, so the program can be re-balanced, re-versioned, mastered, or archived without reopening the full session. In Dolby Atmos work these are typically object-audio stems or multichannel re-renders that retain the spatial layout, unlike flat stereo or 5.1 stems.", "plain_english": "A stem is a group of tracks bounced into one file, like all the drums together. In surround-with-height sound, the stems also keep where each sound sits in the room. This lets someone remix or fix the show later without opening the whole project. It is like keeping labeled boxes instead of one big pile.", "purpose_function": "It lets a mix be handed off, re-versioned for trailers, languages, or formats, mastered, or archived while keeping the immersive positioning intact.", "practical_application": "An engineer delivers dialogue, music, and effects as immersive re-renders or grouped object stems so a mastering house or another mixer can adjust balances and still output every required downmix.", "category": "Delivery & mastering", "related_terms": ["Bed (Dolby Atmos)", "Audio object", "Re-render", "Stem mastering", "ADM BWF", "Downmix"], "common_mistakes": ["Flattening immersive stems to stereo or 5.1 too early, losing the height and object placement", "Exporting stems without their spatial layout or metadata, so positions are lost on import", "Mismatched loudness or bus processing across stems, so the summed stems no longer equal the master", "Naming or grouping stems inconsistently, which makes clean re-assembly error-prone"], "scenario_contexts": ["Delivering dialogue, music, and effects stems for a Dolby Atmos film master", "Sending object stems to a mastering engineer for an immersive music release", "Creating trailer or foreign-language versions from immersive stems", "Archiving an immersive project for future re-versioning"]}, "a8b92ac4-2a6c-49d1-b917-330617dd3f7e": {"definition": "A quality-control step in which an immersive mix is auditioned through the various renderings it will produce - binaural headphone fold-down, stereo, and multichannel downmixes such as 5.1 and 7.1, plus different speaker layouts - to confirm that balance, dialogue intelligibility, and spatial intent hold up on each.", "plain_english": "This is a check to make sure a surround-with-height mix still sounds right on other systems. The engineer listens to the headphone, stereo, and smaller surround versions the format makes automatically. The goal is that nothing important gets lost or too loud on any of them. It is like checking a photo on both a phone and a laptop.", "purpose_function": "It catches cases where the automatic downmixes or binaural fold-downs bury dialogue, shift balance, or lose height content, so the program works for every listener.", "practical_application": "Before delivery, a technician switches the renderer through binaural, stereo, and 5.1 re-renders, checks on headphones and a soundbar, and adjusts object levels or downmix settings until each version translates.", "category": "Quality control", "related_terms": ["Downmix", "Binaural render", "Re-render", "Fold-down", "Dialogue intelligibility", "Loudness normalization"], "common_mistakes": ["Only checking the full immersive layout and never auditioning the stereo or binaural fold-down", "Ignoring downmix coefficients, so the 5.1 or stereo version clips or loses level", "Assuming height content survives a fold-down when it is usually attenuated", "Not checking dialogue level on small, mono, or phone playback"], "scenario_contexts": ["Final QC of a Dolby Atmos music track before a streaming release", "Checking a film mix's 5.1 and stereo downmixes for dialogue clarity", "Verifying a mix on headphones through the binaural render", "Testing playback on a consumer soundbar and TV speakers"]}, "3cd93ae4-9765-42db-897e-880dbad6f9b9": {"definition": "Positioning of sound sources defined relative to the listener's position and orientation (egocentric) rather than to fixed room coordinates, so a source keeps the same perceived direction as the layout, or the listener's head, changes. In object-based and VR/AR spatial audio this contrasts with allocentric, room-anchored placement.", "plain_english": "This means placing a sound based on where the listener is, not where the walls are. If the listener turns, or the speakers change, the sound stays in the same spot around them. Head-tracked headphone audio works this way. It is like a sign that always turns to face you.", "purpose_function": "It keeps spatial intent consistent across different speaker layouts and supports head-tracked and binaural playback, where sources must move relative to the listener.", "practical_application": "When mixing for headphones or VR, a technician places objects in listener-relative space so head-tracking rotates the scene correctly; in Atmos, room-relative object coordinates are rendered to whatever layout the listener actually has.", "category": "Spatial placement", "related_terms": ["Audio object", "Head tracking", "Binaural render", "Egocentric coordinates", "Allocentric coordinates", "Object panning"], "common_mistakes": ["Confusing listener-relative (egocentric) placement with room-relative (allocentric) placement", "Assuming head-locked and listener-relative are the same thing", "Placing critical sounds so head-tracking swings them behind the listener, where they are hard to locate", "Forgetting that speaker playback still renders positions to the actual room layout"], "scenario_contexts": ["Mixing head-tracked binaural audio for VR or spatial-audio earphones", "Deciding whether a sound should follow the listener or stay fixed to the scene", "Adapting a mix for many different consumer speaker layouts", "Keeping a narrator front-and-center as the viewer looks around"]}, "2c9f499a-df81-4fda-b88a-029bee334f4b": {"definition": "Positioning of sound in the height (top or ceiling) layer of an immersive layout - the overhead speakers above the listener - to place or move sources vertically, such as rain, aircraft, or open-air ambience. In Dolby Atmos these correspond to the top or height speakers (for example Top Front, Top Middle, and Top Rear).", "plain_english": "This means putting a sound above the listener, in the ceiling speakers. It suits things that belong overhead, like rain, a plane, or open-sky ambience. Height speakers are what make surround-with-height feel like a dome of sound. It is like hanging a speaker on the ceiling so sound comes from above.", "purpose_function": "The height layer adds the vertical dimension that separates immersive audio from flat surround, giving a sense of overhead space and elevation.", "practical_application": "A mixer pans ambience, weather, or fly-over effects into the top speakers, or raises an object's height coordinate, to lift them off the ear-level plane.", "category": "Spatial placement", "related_terms": ["Height channel", "Top speaker", "Audio object", "Elevation", "Ambience layer", "Bed (Dolby Atmos)"], "common_mistakes": ["Overusing the height layer so effects feel like a gimmick instead of natural", "Putting key elements only overhead, where localization is weaker for many listeners", "Assuming overhead content survives a stereo or 5.1 fold-down, when it is usually cut or lost", "Confusing overhead height speakers with rear surround speakers at ear level"], "scenario_contexts": ["Placing rain or open-air ambience in the top speakers of an Atmos mix", "Flying an effect from the front, up overhead, then to the rear", "Adding overhead reverb for the feel of a tall room", "Positioning a helicopter pass above the audience"]}, "e9aaa876-c20b-428c-847a-d36e5639f6f2": {"definition": "Positioning of a sound at the rear of the immersive listening space - the rear surround position behind the listener - either by panning to the rear surround speakers or by setting an object's coordinates to the back of the room. It completes the surround field behind the listener.", "plain_english": "This means placing a sound behind the listener, at the back of the room. The back speakers handle sounds coming from behind, like a crowd or a door shutting behind you. It helps wrap the sound all the way around. It is like someone speaking to you from the doorway at your back.", "purpose_function": "Rear placement completes the surround field behind the listener, supporting envelopment, off-screen effects, and front-to-back movement.", "practical_application": "A mixer sends ambience, off-screen effects, or trailing reverb to the rear surrounds, or sets an object to the rear, to build depth behind the audience.", "category": "Spatial placement", "related_terms": ["Surround channel", "Rear surround", "Audio object", "Envelopment", "Side-wall placement", "Object panning"], "common_mistakes": ["Placing dialogue or lead vocals in the rear, where they distract and pull focus off the screen", "Confusing rear surrounds with side surrounds when routing", "Overloading the rears so the image feels unbalanced front-to-back", "Assuming rear content translates to a stereo or soundbar downmix"], "scenario_contexts": ["Placing audience or crowd ambience behind the listener", "Moving an effect from front to back across the room", "Adding rear reverb returns for depth", "Positioning an off-screen sound behind the viewer"]}, "6e906398-1bc8-4d68-948b-1d0dbde78aa7": {"definition": "Positioning of a sound at the sides of the immersive listening space - the left and right side surround positions beside the listener - by panning to the side surround speakers or setting an object's coordinates to the side of the room. Side placement bridges the front and rear and supports lateral movement and width.", "plain_english": "This means placing a sound to the left or right of the listener, from the side speakers. It fills the space between the front and back so sounds can move smoothly around. It also widens the sound picture. It is like someone talking to you from the seat right next to you.", "purpose_function": "Side surrounds provide the lateral field that links front and rear, enabling smooth pans around the listener and a wider, more enveloping image.", "practical_application": "A mixer routes passing effects, width, and ambience to the side surrounds, or sets objects to the sides, to move sounds along the walls and broaden the stage.", "category": "Spatial placement", "related_terms": ["Surround channel", "Side surround", "Audio object", "Envelopment", "Rear-wall placement", "Object panning"], "common_mistakes": ["Confusing side surrounds with rear surrounds when assigning speakers", "Leaving a gap in a pan because side speakers are missing or misrouted in a smaller layout", "Placing lead elements at the sides, which hurts the front image and dialogue focus", "Assuming side content survives a fold-down to stereo"], "scenario_contexts": ["Panning a car or effect smoothly front to back along the side wall", "Adding lateral ambience for width", "Placing a sound beside the listener for a specific scene", "Widening a music mix using the side surrounds"]}, "96157096-60f7-4ebc-88dc-6dc338a45d95": {"definition": "A music mix produced and delivered in an immersive, spatial-audio format such as Dolby Atmos Music or Sony 360 Reality Audio, in which individual elements are placed in a three-dimensional field around and above the listener rather than only across a stereo pair. It is authored with beds and objects and rendered to the listener's playback layout or to a binaural headphone fold-down.", "plain_english": "This is a song mixed so the parts sit all around you, and even above you, not just left and right. On headphones or the right speakers it can feel like being inside the music. Formats like Dolby Atmos Music make this. It is like moving from a flat photo to standing inside the scene.", "purpose_function": "It gives listeners a more enveloping, three-dimensional music experience and lets artists place and move elements in space, delivered to many playback systems from one master.", "practical_application": "A mix engineer places vocals, instruments, and reverb as objects and beds in a spatial workspace, monitors on a calibrated immersive rig, and delivers a master that streaming services fold down to each listener's device.", "category": "Immersive format", "related_terms": ["Dolby Atmos", "Audio object", "Bed (Dolby Atmos)", "Binaural render", "Spatial audio", "Downmix"], "common_mistakes": ["Treating it as just a wider stereo mix instead of using the full 3D field with intent", "Placing lead vocals far from center or overhead, which hurts focus and translation", "Ignoring the binaural and stereo fold-downs that most listeners actually hear", "Not calibrating the room to reference before mixing"], "scenario_contexts": ["Producing a Dolby Atmos Music release for streaming platforms", "Remixing a legacy stereo album into spatial audio", "Mixing a live concert recording in an immersive format", "Preparing a binaural version for headphone listeners"]}, "393f3056-f2f1-4d6b-bf8b-70aab8634c45": {"definition": "The routing of an audio signal to a bed — the channel-based portion of an object-based mix that feeds fixed loudspeaker positions such as a 7.1.2 layout. Assigning a track to a bed makes it play back from set speaker channels rather than carrying dynamic 3D object metadata.", "plain_english": "Sending a sound to the bed, which is the set of fixed speakers in a surround mix. It is like telling a sound to always come from the left speaker, instead of moving around the room.", "purpose_function": "Beds provide a stable channel-based foundation for ambience, music and other content that does not need to move, so mixers do not have to author separate position data for every element.", "practical_application": "A technician assigns steady elements like room tone, reverb returns and music stems to the bed, reserving objects for sounds that must move or sit in a precise spot.", "category": "Signal routing", "related_terms": ["Object assignment", "Bed panning", "Bed-based music mix", "Bed monitoring mode", "Object-based audio", "7.1.2 bed"], "common_mistakes": ["Putting sounds that need to move or sit overhead in the bed, where they are locked to fixed speaker channels.", "Assuming a bed always has height channels; a 5.1 or 7.1 bed has no top layer.", "Duplicating the same signal in both a bed and an object, causing doubled level and comb filtering."], "scenario_contexts": ["Assigning music stems and ambience to a 7.1.2 bed in a Dolby Atmos music session.", "Routing reverb returns to the bed so they wrap around the room from fixed speakers.", "Building a broadcast mix where dialogue stays in the bed's center channel."]}, "382db387-e160-4403-9055-ebf2db7c8ab1": {"definition": "A monitoring mode that isolates the bed — the channel-based layer of an immersive mix — so the engineer hears only the content routed to fixed loudspeaker feeds, separate from the objects. It is used to check the balance and imaging of the bed on its own.", "plain_english": "A way to listen to just the fixed-speaker part of a surround mix by itself. It is like soloing one group of instruments so you can hear only them and check they sound right.", "purpose_function": "Monitoring the bed alone helps the engineer confirm the channel-based foundation is balanced and phase-correct before the moving object sounds are added back in.", "practical_application": "When a mix sounds cluttered, a technician switches to bed-only monitoring to hear whether the problem lives in the static bed content or in the objects.", "category": "Monitoring", "related_terms": ["Bed assignment", "Bed panning", "Object assignment", "Re-render", "Downmix", "Object-based audio"], "common_mistakes": ["Mistaking bed-only monitoring for the full mix and setting levels against an incomplete picture.", "Forgetting to return to full monitoring, then exporting while still soloed to the bed.", "Assuming the bed layer alone shows how the mix renders on smaller speaker layouts."], "scenario_contexts": ["Soloing the bed to check the surround balance of music stems in an Atmos session.", "Isolating the bed to trace an unwanted low-frequency buildup to the LFE channel.", "Comparing bed-only and full playback to judge how much of the mix relies on objects."]}, "270c7e35-5d5e-4286-90b1-db19351acbd1": {"definition": "The positioning of a source within a bed by distributing its level across the bed's fixed loudspeaker channels, as in traditional surround panning. Unlike object panning, the result is tied to the bed's discrete speaker feeds rather than a free 3D coordinate.", "plain_english": "Placing a sound among the fixed surround speakers by sending more of it to some speakers than others. It works like a normal surround pan knob, not a dot you drag anywhere in the room.", "purpose_function": "Bed panning lets an engineer place channel-based content in the surround field without turning it into an object, keeping the mix simple and predictable across playback systems.", "practical_application": "A technician uses bed panning to spread a stereo synth pad across the front and surround bed channels, or to seat a backing vocal slightly to one side.", "category": "Panning", "related_terms": ["Object panning", "Bed assignment", "Height panning", "Surround panning", "Bed-based music mix", "7.1.2 bed"], "common_mistakes": ["Expecting bed panning to place a sound overhead when the bed has no height channels.", "Confusing bed panning with object panning; bed pans snap to speaker feeds, not free positions.", "Hard-panning content fully into one surround channel so it vanishes on layouts missing that speaker."], "scenario_contexts": ["Panning a rhythm guitar into the left surround channels of a 7.1.2 bed.", "Spreading crowd ambience evenly across the bed's surround speakers.", "Seating a stereo keyboard part across the front bed channels of a music mix."]}, "5dcdf5c6-f7a6-431b-9571-837fac3780fc": {"definition": "An immersive music mix built mainly on the channel-based bed, with most elements placed in the bed layer (for example 7.1.2) and few or no discrete objects. It contrasts with an object-based approach that assigns many individual elements to moving objects.", "plain_english": "An immersive music mix where most sounds live in the fixed surround speakers. Few or none are separate moving objects. It is like seating a band in set spots, not letting each player roam the room.", "purpose_function": "A bed-based approach keeps sessions simple and translates predictably across playback systems, which suits music where instruments hold steady positions rather than moving.", "practical_application": "An engineer mixing an album in Atmos may keep drums, bass and pads in the bed and use objects only for lead vocals or special effects.", "category": "Mix approach", "related_terms": ["Bed assignment", "Object-based audio", "Bed panning", "7.1.2 bed", "Height panning", "Downmix"], "common_mistakes": ["Assuming a bed-based mix cannot use height; a 7.1.2 bed includes two overhead channels.", "Overusing the bed so nothing moves, wasting the format's ability to place discrete sounds.", "Ignoring how the bed folds down to stereo and surround, leading to poor translation on smaller systems."], "scenario_contexts": ["Mixing a jazz record in Atmos with the ensemble seated in a 7.1.2 bed.", "Delivering an immersive music master that must fold down cleanly to 5.1 and stereo.", "Choosing a bed-based workflow to speed up mixing a large back catalog."]}, "c7c96c95-21ce-4bab-bb28-f0d724e960cf": {"definition": "Panning that moves a source in the vertical dimension, raising or lowering its apparent elevation toward the overhead (height) loudspeakers. It controls the elevation component of a position, the axis that distinguishes immersive audio from horizontal-only surround.", "plain_english": "Moving a sound up or down so it seems to come from above you. It is like lifting a sound from ear level up to the ceiling.", "purpose_function": "Height panning adds the vertical dimension that makes a mix immersive, letting engineers place sounds overhead for effects, ambience or a sense of space that flat surround cannot give.", "practical_application": "A technician uses height panning to lift rain, applause or a synth wash into the top speakers, or to raise a helicopter as it flies overhead.", "category": "Panning", "related_terms": ["Object panning", "Bed panning", "Object azimuth", "Object distance", "Overhead speakers", "Elevation"], "common_mistakes": ["Pushing everything overhead, which tires listeners and weakens the main front image.", "Assuming height panning works on any system; playback with no top speakers folds the height content down.", "Confusing elevation (height) with azimuth (horizontal direction) when setting object position."], "scenario_contexts": ["Raising ambience and reverb into the overhead speakers of an Atmos music mix.", "Flying a sound effect from the floor to the ceiling in a film scene.", "Placing a backing choir slightly above the band to open up the vertical image."]}, "e2d1e31d-cd18-40df-9070-8968db5084c6": {"definition": "The routing of an audio track to an object input in an object-based renderer, so it is carried as an individual element with its own dynamic 3D position metadata rather than as fixed bed channels. In Dolby Atmos, inputs assigned as objects occupy the object slots above the bed channels.", "plain_english": "Turning a track into a movable object the system can place anywhere in the room. It is like giving one sound its own GPS so it can travel around the listener.", "purpose_function": "Object assignment lets a sound be positioned and moved freely in three dimensions and rendered to whatever speaker layout is present, which is the core advantage of object-based audio.", "practical_application": "A technician assigns a lead vocal, a flying effect or any element that must move or sit precisely to an object, then automates its position with a panner.", "category": "Signal routing", "related_terms": ["Bed assignment", "Object panning", "Object azimuth", "Object distance", "Object disable", "Object-based audio"], "common_mistakes": ["Assigning steady, non-moving content to objects and creating needless metadata and session complexity.", "Running out of object slots by making everything an object instead of using the bed.", "Forgetting to set a position, leaving a new object defaulted to the center of the room."], "scenario_contexts": ["Assigning a lead vocal to an object so it can be placed precisely in front.", "Making a sound effect an object so it can fly across and above the room.", "Converting a bed track to an object when a specific element needs to move."]}, "889f22e2-2857-47c2-bf8b-8e68b6de65b9": {"definition": "The horizontal angle of an audio object's position, describing its left-right and front-back direction around the listener in the horizontal plane. In the ADM (ITU-R BS.2076) polar coordinate system, azimuth is expressed in degrees with 0° at front center.", "plain_english": "The direction a sound comes from around you, like whether it is in front, to the side, or behind. Think of it as where the sound sits on a clock face drawn around your head.", "purpose_function": "Azimuth is one of the coordinates the renderer needs to place an object, fixing its horizontal direction so the sound images from the correct point around the listener.", "practical_application": "A technician sets or automates an object's azimuth to move a sound from front to side, for example sweeping an effect from center to the left surround.", "category": "Object metadata", "related_terms": ["Object distance", "Height panning", "Object assignment", "Object panning", "Elevation", "Object-based audio"], "common_mistakes": ["Confusing azimuth (horizontal angle) with elevation (height), so sounds end up in the wrong plane.", "Assuming every renderer uses the same zero point and sign for azimuth without checking the convention.", "Automating azimuth so fast that the sound jumps unnaturally between speakers."], "scenario_contexts": ["Setting an object's azimuth to seat a lead vocal at front center.", "Automating azimuth to pan a sound effect around the horizontal circle.", "Matching an object's azimuth to on-screen action in a film mix."]}, "7f530f80-064c-4be6-b463-5fb35e554542": {"definition": "Turning off an object so the renderer no longer reproduces it as an active positioned element; the object's audio and position metadata are made inactive. Disabling silences or bypasses an object without deleting its assignment or automation.", "plain_english": "Switching an object off so it stops playing and moving in the mix. It is like muting one moving sound while leaving its settings in place for later.", "purpose_function": "Disabling an object lets an engineer silence or bypass a single element, or free its slot, without losing its routing and position data.", "practical_application": "A technician disables an object to audition the mix without it, or to reclaim an object slot when the count runs high, then re-enables it later.", "category": "Signal routing", "related_terms": ["Object assignment", "Bed assignment", "Object panning", "Object azimuth", "Object distance", "Object-based audio"], "common_mistakes": ["Disabling an object instead of muting the source track, then forgetting it is off at export.", "Assuming a disabled object still contributes to downmixes and re-renders; it does not.", "Deleting an object when only a temporary disable was needed, losing its position automation."], "scenario_contexts": ["Disabling an effect object to A/B the mix with and without it.", "Turning off unused objects to stay within the renderer's object limit.", "Bypassing a problem object while troubleshooting a rendering error."]}, "d86db8cf-c23d-448b-80d4-f34ee497fe51": {"definition": "The distance (radius) component of an audio object's position, describing how far the object sits from the listening position alongside its azimuth and elevation. In the ADM (ITU-R BS.2076) polar model, distance is normalized, where 1 corresponds to the reference loudspeaker radius.", "plain_english": "How near or far a sound seems from the listener, on top of which direction it comes from. It is like saying a sound is right next to you versus far across the room.", "purpose_function": "Distance gives the renderer the depth coordinate, letting it push a sound toward or away from the listener so the mix has a sense of near and far, not just direction.", "practical_application": "A technician adjusts object distance to pull a whisper close to the listener or send a call far off, and may automate it to make a source approach or recede.", "category": "Object metadata", "related_terms": ["Object azimuth", "Height panning", "Object assignment", "Object panning", "Divergence", "Object-based audio"], "common_mistakes": ["Assuming every playback system reproduces distance the same way; renderers interpret it differently.", "Confusing distance with level; distance is a position coordinate, not just a volume change.", "Leaving distance at its default and losing the depth the format can provide."], "scenario_contexts": ["Pulling a narrator's voice close by setting a short object distance.", "Automating distance so a vehicle sounds like it approaches from far away.", "Placing crowd sounds at a greater distance to sit them behind the main action."]}, "e2451883-2106-4a57-b8c0-709b84e0f3f5": {"definition": "A per-object panner parameter that sets the attenuation curve used as an object is positioned along an axis (front x-axis, rear x-axis, front/rear y-axis, and height z-axis), governing how sharply the image collapses onto the nearest speaker versus spreading across neighboring speakers. Higher divergence widens and softens the source; lower divergence produces a tighter, more localized image.", "plain_english": "It controls how tightly a sound is focused on one speaker or spread across nearby ones. Low values keep the sound in a tight spot; high values let it bleed into the speakers around it.", "purpose_function": "It lets a mixer trade pinpoint localization for a wider, smoother spatial image and shape how an object blends into surrounding speakers as it moves through the room.", "practical_application": "A technician raises divergence to soften a hard-panned object so it does not jump speaker to speaker, or lowers it for a sharply localized effect such as a passing car.", "category": "Object Panning", "related_terms": ["Object size", "Object panning", "Object elevation", "Speaker snap", "Object linking"], "common_mistakes": ["Confusing divergence with object size; divergence shapes the attenuation/spread curve per axis while size sets the physical spread area of the object.", "Assuming maximum divergence always sounds better; too much spread smears localization and weakens the intended image.", "Forgetting that divergence is set independently per axis (front, rear, front/rear, height), so one axis can behave differently from another."], "scenario_contexts": ["Widening a synth pad object so it fills the room without collapsing onto the nearest speaker.", "Tightening divergence on a sound-effect object that must localize precisely to a screen position in a film mix.", "Adjusting height divergence so an overhead object spreads smoothly across the ceiling array."]}, "9dc00d52-99bf-4d96-a203-afd92a09176b": {"definition": "The vertical (z-axis / height) position of an audio object in the three-dimensional Dolby Atmos space, measured from the listener plane up toward the overhead speakers. In object panners it can be set manually or driven automatically by predefined elevation patterns (for example Wedge, Ceiling, Sphere, Cup, Tunnel, Half-Pipe, Ridge) that make height follow a fixed curve as the object moves in the horizontal plane.", "plain_english": "It is how high off the floor a sound sits, from ear level up to the ceiling speakers. You can set the height by hand or let a preset path raise and lower it as the sound moves.", "purpose_function": "It adds the vertical dimension that separates immersive object audio from flat surround, letting sounds be placed overhead or lifted off the listener plane.", "practical_application": "A mixer raises a helicopter object toward the ceiling speakers, or applies a Wedge or Ceiling elevation pattern so a panned object automatically rises as it moves to the sides.", "category": "Object Panning", "related_terms": ["Object panning", "Object size", "Object divergence", "Bed", "Overhead speakers"], "common_mistakes": ["Assuming every playback system has real height speakers; on many layouts elevation is virtualized, so extreme height cues may not translate.", "Confusing the manual height parameter with elevation patterns, which override manual height while active.", "Overusing height so the mix feels disconnected from the on-screen action."], "scenario_contexts": ["Placing ambience or rain in the overhead speakers of a cinema mix.", "Using an elevation pattern so a lead ad-lib lifts as it sweeps to the sides.", "Automating a rising riser effect from ear level to the ceiling in a music mix."]}, "c48a4163-7236-44b9-aec4-177052b927f4": {"definition": "The authoring action of designating a track's output as a Dolby Atmos object rather than part of a channel-based bed, routing it to an object bus/ID so its position is carried as dynamic metadata instead of being fixed to speaker channels.", "plain_english": "It is the switch that turns a normal track into a movable object. Once on, the track carries its own position that can travel anywhere in the room instead of staying locked to fixed speakers.", "purpose_function": "It exists so specific sounds can be panned freely in three dimensions and stay independent of the speaker layout, which is the core idea of object-based audio.", "practical_application": "A technician enables object mode on a lead-vocal or effect track and maps it to an object ID so the panner can move it in three dimensions.", "category": "Object Authoring", "related_terms": ["Object panning", "Object numbering", "Bed", "Object grouping", "Object monitoring mode"], "common_mistakes": ["Enabling more objects than the renderer supports (up to 118 object channel paths), which blocks additional assignments.", "Leaving sounds as objects when a static bed channel would be more appropriate, wasting object slots.", "Forgetting to map the enabled object track to an object ID, so its metadata never reaches the renderer."], "scenario_contexts": ["Turning a dialogue stem into an object so it can follow on-screen movement.", "Enabling a guitar track as an object for a wide, moving pan in a music mix.", "Deciding which stems become objects versus staying in the 7.1.2 bed during session setup."]}, "aa87ecce-80f8-43ec-9575-c53cca839c0d": {"definition": "The authoring practice of organizing multiple objects (and bed channels) into a named group so they can be managed and routed together, for example assigning them to a custom group in the Dolby Atmos Renderer to produce a combined re-render/stem output. It is distinct from spatial-coding clusters, which the encoder forms automatically by grouping nearby objects to fit the delivery bitstream.", "plain_english": "It means bundling several objects together so you can manage or route them as one. For example, you can group objects to bounce them out as a single stem.", "purpose_function": "Grouping keeps large object counts organized and lets a mixer output related sounds together, such as all dialogue or all effects, as one re-render.", "practical_application": "A technician assigns objects to custom groups in the renderer to create dialogue, music, and effects re-renders for delivery or archiving.", "category": "Object Authoring", "related_terms": ["Object enable", "Object numbering", "Bed", "Object linking", "Object panning"], "common_mistakes": ["Confusing custom re-render groups with spatial-coding clusters; the first is a mixer choice, the second is automatic during encoding.", "Assuming grouping merges objects into one; grouping organizes them, but each object keeps its own position metadata.", "Forgetting to update group assignments after adding new objects, so re-renders miss content."], "scenario_contexts": ["Grouping all dialogue objects to output a clean dialogue re-render.", "Organizing dozens of effect objects into groups for easier management in a large film session.", "Creating music-and-effects (M&E) stems from grouped objects for international delivery."]}, "5fa29eaf-47a7-4d3f-bd84-2b44a30939bb": {"definition": "Tying two or more object panner instances (or the channels of a multichannel object) together so their positions move in a fixed relationship, with one channel copying the other or mirroring it across the X, Y, or both axes, rather than being automated independently.", "plain_english": "It connects objects so they move together. For example, the right side of a stereo object can mirror the left, so one move controls both.", "purpose_function": "Linking keeps related objects in a consistent spatial relationship and saves the mixer from automating each one separately.", "practical_application": "A mixer links the left and right halves of a stereo object with a mirror mode so a single pan gesture spreads and moves both sides symmetrically.", "category": "Object Panning", "related_terms": ["Object panning", "Object grouping", "Object size", "Object divergence", "Object enable"], "common_mistakes": ["Confusing linking with grouping; linking ties positions together, while grouping bundles objects for management or output.", "Forgetting a link is active and wondering why a second object moves when only one is edited.", "Choosing the wrong mirror axis (X versus Y), which places the partner object in an unintended location."], "scenario_contexts": ["Mirroring the two channels of a stereo object so it stays symmetrical while panning.", "Linking a pair of effect objects so they move through the room in lockstep.", "Copying one object's motion to another to build a widened, coherent image."]}, "77693cdd-edc0-44bb-bd01-4b52dc1f1dec": {"definition": "The setting or approach that governs how an individual object is auditioned during authoring, including the per-object binaural render mode in the Dolby Atmos Renderer (Off, Near, Mid, or Far) that determines how much perceived distance and space is applied to that object when the mix is monitored over headphones.", "plain_english": "It is how you listen to a single object while you work. On headphones, each object can be set to sound close, mid, or far, or to have no added distance and space at all (Off).", "purpose_function": "It lets a mixer check how each object translates on different outputs, especially headphones, and control the perceived distance of each object in the binaural render.", "practical_application": "A technician sets a lead-vocal object to Near and a reverb object to Far so the headphone (binaural) mix has clear depth, then compares it against speaker monitoring.", "category": "Object Authoring", "related_terms": ["Object enable", "Object panning", "Object elevation", "Binaural rendering", "Bed"], "common_mistakes": ["Assuming binaural render mode changes the speaker mix; it only affects the binaural/headphone render.", "Setting every object to Far, which pushes the whole headphone mix back and muddies it.", "Forgetting that these per-object choices are written as metadata and affect consumer headphone playback, not just the studio."], "scenario_contexts": ["Assigning Near/Mid/Far binaural render modes per object before a headphone-focused music release.", "Soloing an individual object to check its placement and level.", "Comparing an object's sound on speakers versus binaural headphones during quality control."]}, "e1713fbd-28f5-4655-8deb-97d055ce9a10": {"definition": "The assignment of a unique object ID to each object so the Dolby Atmos Renderer can address it and pair its audio with the correct position metadata. A standard configuration provides 128 input channels total: a bed on the lowest channels (for example 1-10 for 7.1.2) and up to 118 objects numbered after it (for example IDs 11-128).", "plain_english": "It is the ID number each object gets so the system can tell them apart. A standard setup has 128 channels total, with the bed first and up to 118 objects numbered after it.", "purpose_function": "Unique IDs let the renderer keep every object separate and match each one with the right position data through mixing and delivery.", "practical_application": "A technician maps each object track to its object ID (with a 7.1.2 bed, objects start at ID 11) so the renderer receives them in the correct slots.", "category": "Object Authoring", "related_terms": ["Object enable", "Bed", "Object panning", "Object grouping", "Object monitoring mode"], "common_mistakes": ["Assigning two tracks to the same object ID, so one overwrites the other at the renderer.", "Forgetting the bed occupies the first channels, then mis-numbering objects into bed slots.", "Assuming there are 128 objects; with a 7.1.2 bed only 118 object channel paths remain."], "scenario_contexts": ["Mapping many object tracks to sequential object IDs during session setup.", "Troubleshooting a missing object by checking its ID assignment in the renderer's input view.", "Documenting object ID assignments so a mix can be recalled or handed off."]}, "5ca84196-cf5e-4fad-9335-e2d94194cc73": {"definition": "The placement and movement of an audio object anywhere within the three-dimensional Dolby Atmos listening space using X (left-right), Y (front-back), and Z (height) coordinates carried as metadata, independent of the physical speaker layout, so the renderer reproduces the intended position on whatever system is present.", "plain_english": "It is moving a sound to any spot in the room, left or right, front or back, low or high. The position travels as data, so it plays back correctly on big and small systems alike.", "purpose_function": "It lets sounds be positioned by location rather than by speaker, so the same mix adapts to different rooms and speaker counts.", "practical_application": "A mixer drags an object across the top-view and rear-view panners, or automates its X/Y/Z path, to move a sound through the room in sync with the action.", "category": "Object Panning", "related_terms": ["Object divergence", "Object size", "Object elevation", "Object enable", "Bed"], "common_mistakes": ["Panning objects to extreme positions that only translate on full speaker layouts and collapse on smaller systems.", "Confusing object panning (metadata-based, layout-independent) with bed panning (fixed to channels).", "Over-automating object motion, which can distract from the mix rather than support it."], "scenario_contexts": ["Following an on-screen car as it drives from left to right and overhead.", "Placing individual instruments around the listener in a music mix.", "Automating a flyover effect from the front wall to the rear of the room."]}, "255a0a66-271a-403c-b15f-8f38e5279352": {"definition": "A per-object parameter that spreads an object's audio over a region of the room around its position, engaging additional active speakers based on the object's location, so the source is perceived as large and diffuse rather than as a single point. It is mutually exclusive with speaker snap, which instead forces the object to the nearest single speaker.", "plain_english": "It sets how big a sound feels in the room. A small size is a tight point; a large size spreads the sound out so it seems to come from a wide area.", "purpose_function": "It lets a mixer make an object feel large and enveloping or small and pinpoint, adding a sense of scale that simple positioning cannot.", "practical_application": "A technician increases size on an ambience or pad object to wrap it around the room, and keeps size small for effects that must localize sharply.", "category": "Object Panning", "related_terms": ["Object divergence", "Object panning", "Object elevation", "Speaker snap", "Object linking", "Object spread"], "common_mistakes": ["Confusing size with divergence; size sets how large the source area is, while divergence shapes the attenuation/spread curve along each axis.", "Expecting size to work while speaker snap is enabled; the two are mutually exclusive.", "Maxing out size on many objects, which blurs localization across the whole mix."], "scenario_contexts": ["Enlarging a crowd or ambience object to fill the room.", "Keeping a fast fly-by effect small so it localizes to a precise point.", "Growing a synth pad's size so it envelops the listener in a music mix."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"1ca3a65f-7e71-40b6-b92f-9ea55cbbed28": {"definition": "A per-object panning setting in object-based audio (e.g. Dolby Atmos) that routes an object's signal to the single nearest active loudspeaker at its position rather than rendering a phantom image across several speakers. Enabling snap forces discrete, speaker-locked reproduction and typically disables the object's spread/size control.", "plain_english": "Snap sends a sound straight to the one closest speaker instead of spreading it between several. It is like clipping a note onto a grid line so it lands right on a speaker.", "purpose_function": "It gives an object a tight, discrete point of origin that stays locked to real speakers, avoiding the level and timbre shifts that phantom imaging between speakers can introduce.", "practical_application": "A mixer enables snap on a spot effect or cue that must come cleanly from one location so it reproduces consistently regardless of how many speakers a playback room has.", "category": "Object panning", "related_terms": ["Audio object", "Object spread", "Object trajectory", "Bed", "Phantom image"], "common_mistakes": ["Assuming snap always improves localization; on a moving object it can cause abrupt jumps between speakers instead of smooth panning.", "Enabling snap and then trying to adjust the object's spread/size, which is deactivated while snap is active.", "Confusing snap with divergence: snap locks energy to one speaker, while divergence deliberately spreads it across several."], "scenario_contexts": ["Locking a doorbell or phone-ring effect to a specific surround speaker in a film mix.", "Placing a discrete percussion hit in a Dolby Atmos music mix so it always fires from one speaker.", "Anchoring a narration or dialog object to the screen-center loudspeaker."]}, "65b5770b-d3d3-4fe4-ae5f-9e5d674625ce": {"definition": "An object panning parameter that increases the perceived spatial size of an audio object by distributing its energy across multiple loudspeakers around its position, ranging from a compact point source to a wide, diffuse source. In the ITU-R BS.2076 Audio Definition Model it corresponds to width, height and depth extent; in Dolby tools it is the Size control.", "plain_english": "Spread makes a sound feel big and wide by sharing it across many speakers instead of one spot. Think of a spotlight you can widen from a tiny dot to a broad wash of light.", "purpose_function": "It lets an engineer set how large or enveloping an object sounds, so sources like pads, ambience or crowd noise can fill the room while spot sounds stay small and precise.", "practical_application": "A mixer raises spread/size on reverb returns or synth pads to wrap them around the audience, and lowers it to keep lead vocals or effects tight and localized.", "category": "Object panning", "related_terms": ["Audio object", "Object snap", "Divergence", "Object trajectory", "Bed"], "common_mistakes": ["Thinking spread simply raises level; it changes how many speakers reproduce the object, not its gain.", "Maxing out spread on every object, which smears imaging and removes contrast between wide and pinpoint sources.", "Expecting spread to work while Speaker Snap is enabled, which deactivates the spread control."], "scenario_contexts": ["Widening an ambient synth pad so it envelops the listener in a Dolby Atmos music mix.", "Spreading room and crowd ambience across the surround field in a live-concert immersive mix.", "Keeping a lead vocal narrow while pads are wide to build front-to-surround depth contrast."]}, "4c2b101f-e1f7-4a48-9ad4-1a14008554be": {"definition": "The time-varying path an audio object follows through three-dimensional space, defined by its position metadata (azimuth/elevation/distance or X/Y/Z) changing over time via panning automation. Renderers interpolate between successive positions to produce continuous movement on any speaker layout.", "plain_english": "A trajectory is the route a sound travels through the room over time, like the flight path of a plane moving overhead. The system draws smooth motion by joining the sound positions from moment to moment.", "purpose_function": "It makes sounds move convincingly in a scene (flying, circling or passing by) by storing position changes as metadata the renderer plays back correctly on whatever speakers are present.", "practical_application": "An engineer draws or automates an object's path, for example a helicopter circling the audience, so the movement renders correctly on a large cinema array, a soundbar or headphones.", "category": "Object panning", "related_terms": ["Audio object", "Panning automation", "Object snap", "Object spread", "Interpolation"], "common_mistakes": ["Automating position too abruptly, causing audible steps when the renderer interpolates or snaps between points.", "Confusing a trajectory (movement over time) with a single static object position.", "Forgetting that trajectory metadata is layout-independent, so a path tuned by ear in one room may translate differently elsewhere."], "scenario_contexts": ["Sending a sound effect flying from the front of the room to the rear during a film scene.", "Circling a synth line around the listener in a Dolby Atmos music mix.", "Automating a passing vehicle across the sound field for a game or VR scene."]}, "b0c55bdb-e144-4ffb-ac1f-e93f7a1af0bd": {"definition": "A level (gain) adjustment applied to an individual audio object in an object-based mix, offsetting the object's contribution up or down without changing its position or spatial metadata. It corresponds to the per-object gain parameter carried in the object's metadata; it is distinct from a renderer's Trim controls, which attenuate whole surround and height groups during automatic downmix.", "plain_english": "An object trim is a small volume tweak for one sound in the mix. It is like nudging a single fader up or down so that one part sits right, without moving where the sound comes from.", "purpose_function": "It lets an engineer balance the loudness of each object relative to the rest of the mix while the object's position and movement stay untouched.", "practical_application": "A mixer trims an object's level to bring a vocal or effect forward or back in an immersive mix, or to match its loudness across different sections of a piece.", "category": "Object authoring", "related_terms": ["Audio object", "Bed", "Object spread", "Object-based music mix", "Re-render"], "common_mistakes": ["Confusing an object trim (a per-object level offset) with the renderer's Trim controls, which lower surround and height groups during downmix.", "Assuming trimming an object changes its position or spread; it only changes level.", "Leaning on large trims late in the mix instead of setting proper gain structure earlier, causing rebalancing headaches."], "scenario_contexts": ["Nudging a lead-vocal object up a decibel so it sits above the bed in a Dolby Atmos music mix.", "Trimming an effect object down so it does not overpower dialogue in a film scene.", "Matching object levels between verse and chorus sections of an immersive song."]}, "00b13fd4-d2dc-4e5b-ae96-8b1a20d8bc5a": {"definition": "A music mix authored as audio objects (individual sound elements each carrying positional and level metadata) rather than as fixed channels, so a renderer places each object in three-dimensional space for whatever playback layout is present, usually alongside a channel-based bed. Dolby Atmos Music, delivered as an ADM master, is a common form.", "plain_english": "It is a song mixed as separate sounds that each know where they belong in the room, instead of being locked to set speakers. The playback system then places each sound to fit whatever speakers or headphones you have.", "purpose_function": "It delivers immersive, layout-independent music that adapts from cinema arrays to soundbars to headphones while preserving the mixer's spatial intent.", "practical_application": "An engineer assigns instruments and vocals to objects (and a bed for ambience), positions and moves them in a renderer, and exports an ADM master for immersive streaming services.", "category": "Immersive mixing", "related_terms": ["Audio object", "Bed", "Object trajectory", "Object spread", "Dolby Atmos"], "common_mistakes": ["Thinking object-based mixing is just spreading a stereo mix wider; it requires assigning discrete elements to objects with intentional placement.", "Putting everything into objects and neglecting the bed, wasting object count and complicating the mix.", "Ignoring the binaural/headphone and downmix renders, so the mix translates poorly outside a full speaker array."], "scenario_contexts": ["Producing a Dolby Atmos Music version of a song for an immersive streaming service.", "Placing backing vocals and effects around the listener while keeping drums and bass in the bed.", "Delivering an ADM BWF master alongside a stereo mix for a new album release."]}, "f46f7363-20eb-46d3-912d-1eaa39b14766": {"definition": "Monitoring the 5.1 surround downmix (fold-down) that a renderer derives from an immersive mix, to check how the mix translates to a standard 5.1 system. The fold-down sums the immersive bed channels and objects into the five ear-level channels plus LFE using defined downmix coefficients.", "plain_english": "Listening to the 5.1 surround version that the system makes from a full 3D mix. It lets you hear how the mix will sound for people who only have a normal surround setup.", "purpose_function": "It exists so engineers can confirm the immersive mix still sounds balanced when collapsed to 5.1, since many listeners and broadcast paths use 5.1 rather than full immersive playback.", "practical_application": "A technician switches monitoring to the 5.1 fold-down to check that dialogue, balance and levels hold up before delivery, catching problems that only appear when the height and extra channels collapse.", "category": "Monitoring", "related_terms": ["Downmix monitoring", "5.1.4 monitoring", "7.1.4 monitoring", "Binaural monitoring mode", "Center speaker", "Atmos monitoring layout"], "common_mistakes": ["Assuming the 5.1 fold-down sounds identical to the immersive mix, so skipping the check.", "Forgetting that overhead (height) content collapses into the ear-level channels in the fold-down.", "Setting final levels only on the immersive layout and never verifying the 5.1 downmix."], "scenario_contexts": ["Checking that a Dolby Atmos music mix folds down cleanly to 5.1 before delivery.", "Verifying dialogue clarity in the 5.1 downmix of a film mix.", "Comparing the immersive mix and its 5.1 fold-down to judge translation."]}, "1a41d994-434e-4c58-80f9-697037a41f60": {"definition": "Monitoring an immersive mix on a 5.1.4 loudspeaker layout: five ear-level channels (left, center, right, left surround, right surround), one LFE channel, and four overhead height speakers. It is a common compact immersive monitoring configuration for Dolby Atmos and similar formats.", "plain_english": "Listening to a 3D mix over a set of speakers: five around you at ear level, one for deep bass, and four above you. It is a common smaller setup for immersive sound.", "purpose_function": "A 5.1.4 layout gives engineers a real height-capable monitoring system that follows the ITU-R and Dolby channel plan, so they can judge overhead and surround placement without needing a large room.", "practical_application": "A technician mixing or checking Dolby Atmos in a compact room uses a 5.1.4 rig to audition object height moves and surround balance.", "category": "Monitoring", "related_terms": ["7.1.4 monitoring", "9.1.4 monitoring", "Atmos monitoring layout", "Center speaker", "5.1 fold-down monitoring", "Downmix monitoring"], "common_mistakes": ["Reading the .4 as extra surround speakers instead of four overhead height speakers.", "Assuming a 5.1.4 mix will sound the same on a larger 7.1.4 or 9.1.6 system without checking.", "Placing the overhead speakers by guess rather than at the specified angles and heights."], "scenario_contexts": ["Setting up a small Dolby Atmos music room on a 5.1.4 layout.", "Checking overhead panning in a 5.1.4 monitoring rig.", "Calibrating the four height speakers and the surrounds in a 5.1.4 studio."]}, "0876d09c-181a-4e46-85ac-beb47ee6fac3": {"definition": "Monitoring an immersive mix on a 7.1.4 loudspeaker layout: seven ear-level channels (left, center, right, left/right side surround, left/right rear surround), one LFE channel, and four overhead height speakers. It is a widely used reference layout for Dolby Atmos production.", "plain_english": "Listening to a 3D mix over seven speakers around you, one for deep bass, and four above you. The two rear speakers add a fuller sense of sound coming from behind the listener.", "purpose_function": "The 7.1.4 layout is a common professional reference because its side and rear surrounds plus four heights let engineers hear surround and overhead detail the way many home immersive systems reproduce it.", "practical_application": "A technician mixes and calibrates Dolby Atmos on a 7.1.4 rig, using the rear surrounds to check sounds that move from the sides to behind the listener.", "category": "Monitoring", "related_terms": ["5.1.4 monitoring", "9.1.4 monitoring", "Atmos monitoring layout", "Center speaker", "Downmix monitoring", "5.1 fold-down monitoring"], "common_mistakes": ["Confusing side surrounds with rear surrounds when wiring or calibrating the seven ear-level channels.", "Reading the .4 as surround speakers rather than four overhead heights.", "Assuming a 7.1.4 mix folds down to 5.1 or stereo without checking."], "scenario_contexts": ["Using a 7.1.4 room as the reference for a Dolby Atmos film or music mix.", "Checking a sound move from side surround to rear surround on 7.1.4.", "Calibrating the four overhead speakers of a 7.1.4 studio to reference level."]}, "ae761615-f23f-42d4-bc57-91ab727b7680": {"definition": "Monitoring an immersive mix on a 9.1.4 loudspeaker layout, which adds a pair of front wide speakers to the seven ear-level channels of 7.1.4, giving nine ear-level channels plus one LFE channel and four overhead height speakers. The front wides fill the gap between the front speakers and the side surrounds.", "plain_english": "Listening to a 3D mix over nine ear-level speakers, one for deep bass, and four above you. Two extra front speakers fill the gap between the front and the sides, so sounds move more smoothly across the front.", "purpose_function": "The front wide pair widens and smooths the frontal image, so panning between the front speakers and the side surrounds sounds more continuous than it does on a 7.1.4 layout.", "practical_application": "A technician working in a larger immersive room uses 9.1.4 to check that sounds sweeping across the front stay smooth, then confirms the mix still translates to smaller layouts.", "category": "Monitoring", "related_terms": ["7.1.4 monitoring", "5.1.4 monitoring", "Atmos monitoring layout", "Center speaker", "Downmix monitoring", "5.1 fold-down monitoring"], "common_mistakes": ["Confusing the front wide speakers with the side surrounds.", "Assuming every playback system has front wides; most home systems do not.", "Reading the .4 as surround channels instead of four overhead heights."], "scenario_contexts": ["Monitoring a large-format Dolby Atmos mix on a 9.1.4 rig with front wides.", "Checking that front-stage panning stays smooth across a 9.1.4 layout.", "Confirming a 9.1.4 mix folds down correctly to 7.1.4 and 5.1."]}, "e12bde80-ce6b-43b5-b166-9b8b323af4c9": {"definition": "The physical arrangement and channel plan of loudspeakers used to monitor a Dolby Atmos mix, defined by ear-level, LFE and overhead positions at Dolby-specified angles and heights (for example 5.1.4, 7.1.4 or 9.1.6). It follows Dolby's placement guidance and the ITU-R base surround geometry.", "plain_english": "The set of speakers, and where each one goes, used to listen to a Dolby Atmos mix. Dolby gives exact positions and angles so every studio hears the mix the same way.", "purpose_function": "A defined monitoring layout ensures the mix is judged on a known, repeatable speaker geometry, so decisions made in one room translate to other Atmos rooms and to home systems.", "practical_application": "A technician sets up and calibrates speakers to the chosen Atmos layout, checking each position's angle, height and level against Dolby's specification before mixing.", "category": "Speaker layout", "related_terms": ["5.1.4 monitoring", "7.1.4 monitoring", "9.1.4 monitoring", "Center speaker", "Downmix monitoring", "Binaural monitoring mode"], "common_mistakes": ["Placing overhead or surround speakers by eye instead of at the specified angles and heights.", "Assuming any speaker positions will do as long as the channel count is right.", "Skipping calibration of level and distance for each speaker in the layout."], "scenario_contexts": ["Building a new Dolby Atmos room to a 7.1.4 monitoring layout.", "Aligning speaker angles and heights to Dolby's specification before a mix.", "Choosing between 5.1.4 and 9.1.6 monitoring layouts for a studio."]}, "59baa346-3abf-467b-b3d2-16b04b7a70a7": {"definition": "A monitoring mode in which the immersive mix is rendered to a two-channel binaural signal for headphones, using head-related transfer functions so that surround and height positions are perceived over stereo headphones. In the Dolby Atmos Renderer, each object can be given a binaural distance setting (Off, Near, Mid or Far) that controls its spatial treatment.", "plain_english": "A way to hear a 3D mix on ordinary headphones, where the system fakes the sense of sound coming from around and above you. It uses a model of how our ears judge direction to place each sound.", "purpose_function": "Binaural monitoring lets engineers check an immersive mix on headphones when no speaker array is available, and it previews how listeners will hear the mix on phones and earbuds.", "practical_application": "A technician switches to binaural monitoring to work on Atmos over headphones and to set each object's Near, Mid or Far binaural distance for the headphone render.", "category": "Monitoring", "related_terms": ["Binaural render check", "Downmix monitoring", "5.1 fold-down monitoring", "Atmos monitoring layout", "Center speaker", "7.1.4 monitoring"], "common_mistakes": ["Treating the binaural headphone render as identical to the speaker mix and making final calls only on headphones.", "Leaving every object's binaural distance at default instead of setting Off, Near, Mid or Far by ear.", "Expecting binaural cues to work well on loudspeakers, where they are meant for headphones."], "scenario_contexts": ["Mixing Dolby Atmos on headphones when no speaker room is available.", "Setting per-object binaural distance to shape the headphone render.", "Previewing how an Atmos mix will sound to streaming listeners on earbuds."]}, "d5c30083-b5b8-489c-9496-e68ec393e0c1": {"definition": "A quality-control step in which the engineer auditions the binaural (headphone) render of an immersive mix to confirm it translates well to headphones, adjusting each object's binaural distance setting (Off, Near, Mid, Far) as needed. It verifies the two-channel headphone version that many end listeners receive.", "plain_english": "Listening to the headphone version of a 3D mix to make sure it still sounds right on headphones. You check each sound and adjust how near or far it feels.", "purpose_function": "Because a large share of listeners hear immersive music on headphones, the check catches problems such as a weak center image or masked detail that only show up in the binaural render.", "practical_application": "A technician runs a binaural render check near the end of a mix, soloing objects and setting their Near, Mid or Far distance so the headphone version matches the intent of the speaker mix.", "category": "Monitoring", "related_terms": ["Binaural monitoring mode", "Downmix monitoring", "5.1 fold-down monitoring", "Atmos monitoring layout", "Center speaker", "7.1.4 monitoring"], "common_mistakes": ["Skipping the binaural check even though most streaming listeners hear the headphone render.", "Leaving all objects on the default binaural distance instead of setting them by ear.", "Assuming a mix that sounds good on speakers automatically works on headphones."], "scenario_contexts": ["Checking the binaural render of a Dolby Atmos music mix before delivery.", "Setting object binaural distances so the headphone version keeps its depth.", "Comparing the speaker mix and its binaural render to spot translation problems."]}, "7855b64e-4301-4989-aea6-8a08cca5cbb6": {"definition": "The loudspeaker positioned directly in front of the listener at ear level (0 degrees azimuth, the M+000 position), reproducing the center channel. In surround and immersive layouts it anchors the frontal image, most importantly dialogue and lead vocals, to the screen or front of the room.", "plain_english": "The speaker straight ahead of you at ear level. It holds sounds that should stay front and center, like dialogue or the lead singer, so they seem to come from the screen.", "purpose_function": "The center speaker fixes central sounds to one solid point instead of relying on a phantom image between the left and right speakers, keeping dialogue clear and stable for listeners sitting off to one side.", "practical_application": "A technician routes dialogue or a lead vocal to the center speaker and calibrates its level and distance so the front image locks to the screen.", "category": "Loudspeaker", "related_terms": ["Atmos monitoring layout", "5.1.4 monitoring", "7.1.4 monitoring", "Downmix monitoring", "5.1 fold-down monitoring", "9.1.4 monitoring"], "common_mistakes": ["Assuming a phantom center from the left and right speakers is as stable as a real center speaker.", "Setting the center speaker at the wrong height or level, so dialogue pulls away from the screen.", "Ignoring the center channel and mixing dialogue only into left and right."], "scenario_contexts": ["Anchoring film dialogue to the center speaker in a surround or Atmos mix.", "Calibrating the center channel level to match the left and right speakers.", "Placing a lead vocal in the center channel of an immersive music mix."]}, "b0b22e43-3d0e-4dcb-9619-a81580145160": {"definition": "Monitoring the reduced-channel downmixes (for example 5.1 or 2.0 stereo) that a renderer derives from an immersive mix, to verify how it translates to smaller playback formats. The renderer sums the immersive bed channels and objects into the target format using defined downmix coefficients.", "plain_english": "Listening to the smaller versions, like 5.1 or stereo, that the system makes from a full 3D mix. It checks the mix still sounds right for people without immersive speakers.", "purpose_function": "Most listeners hear stereo or 5.1, so downmix monitoring lets engineers confirm the mix stays balanced and mono-compatible in those formats before delivery.", "practical_application": "A technician cycles through the stereo and 5.1 downmixes while mixing, checking levels, balance and phase so problems do not appear only on smaller systems.", "category": "Monitoring", "related_terms": ["5.1 fold-down monitoring", "Binaural monitoring mode", "Atmos monitoring layout", "Center speaker", "5.1.4 monitoring", "7.1.4 monitoring"], "common_mistakes": ["Delivering an immersive mix without ever checking its stereo and 5.1 downmixes.", "Assuming the downmix keeps the immersive balance, when levels and phase can shift.", "Forgetting to check mono compatibility, so elements cancel in the folded-down stereo."], "scenario_contexts": ["Checking the stereo and 5.1 downmixes of a Dolby Atmos master before delivery.", "Testing mono compatibility of the stereo downmix.", "Comparing the immersive mix with its downmixes to judge translation."]}, "0b180e2e-f1c6-4b08-a422-8c08c42924c1": {"definition": "A binaural (headphone) monitoring method in which head-position sensors continuously update the head-related transfer function (HRTF) processing so the rendered immersive sound field stays anchored to the screen or device instead of rotating with the listener's head. It lets an engineer preview how spatial-audio playback behaves on head-tracked consumer devices.", "plain_english": "This is headphone listening that follows your head. When you turn your head, the sound stays fixed in place, like real speakers in a room, instead of moving with your ears.", "purpose_function": "It exists so engineers can check how an immersive mix will behave on consumer head-tracked playback, where sensors keep sources locked to the visual scene as the head moves.", "practical_application": "A technician enables head tracking on a binaural monitor path to confirm that objects stay stable and correctly placed as the listener's head moves before approving a spatial-audio deliverable.", "category": "Immersive Monitoring", "related_terms": ["Headphone-rendered monitoring", "Binaural rendering", "HRTF", "Immersive monitoring system", "Object-based audio"], "common_mistakes": ["Assuming a head-tracked binaural render sounds identical to the loudspeaker mix", "Making tonal or level decisions on head-tracked headphones instead of a calibrated speaker array", "Forgetting that head tracking is referenced to a device or screen origin, not to the headphones themselves"], "scenario_contexts": ["Previewing a spatial-audio release on earbuds with dynamic head tracking", "Checking object stability during head movement before final QC", "Demonstrating immersive playback to a client on headphones"]}, "47e42201-bf17-4c60-9281-81863ad8a863": {"definition": "Monitoring an immersive channel- and object-based mix over headphones by folding the multichannel/object signal into a two-channel binaural signal using HRTF-based processing, so overhead and surround positions are simulated for two ears. In the Dolby Atmos Renderer this is set per object with Off/Near/Mid/Far distance modes.", "plain_english": "This is checking a surround-sound mix using normal headphones. Special processing fakes the sound of speakers all around you and above you, using just the two earcups.", "purpose_function": "It lets engineers audition and approve an immersive mix without a full speaker array, and shows how the mix will translate to the headphone listeners who make up much of the audience.", "practical_application": "A technician switches the renderer to binaural, sets per-object near/mid/far distances to judge depth, and checks the fold-down before delivering the binaural version.", "category": "Immersive Monitoring", "related_terms": ["Head-tracked monitoring", "Binaural rendering", "HRTF", "Downmix", "Immersive monitoring system", "Object-based audio"], "common_mistakes": ["Making final tonal or panning decisions only on binaural headphones instead of a calibrated loudspeaker array", "Assuming every listener hears the same binaural result, when HRTFs vary between people", "Ignoring the per-object distance (near/mid/far) setting when judging depth"], "scenario_contexts": ["Mixing an immersive project in a room without overhead speakers", "Auditioning the binaural deliverable that ships to streaming services", "Spot-checking a mix on headphones while away from the studio"]}, "2dee66d0-e809-4015-bd13-85209b0ef926": {"definition": "A loudspeaker in the upper layer of an immersive array, mounted above the listener's ear-height (horizontal) plane to reproduce overhead and elevated content. In ITU-R BS.2051 these are the upper-layer (\"U\") loudspeakers; in Dolby Atmos home layouts they are the \"top\" surround speakers (the \".4\" or \".6\" in 7.1.4 or 9.1.6), which Dolby specifies at a minimum height of 2.4 m at the mix position with defined elevation angles.", "plain_english": "This is a speaker placed up high, near the ceiling. It plays sounds that should come from above you, like rain or a helicopter, which normal ear-level speakers cannot reproduce.", "purpose_function": "Height speakers add the vertical dimension that separates immersive audio from flat surround, letting sounds be placed and moved overhead.", "practical_application": "A technician mounts and aligns the top/height speakers at the specified elevation, then sets their level and delay during calibration so overhead pans track smoothly.", "category": "Immersive Playback", "related_terms": ["Immersive monitoring system", "Immersive delay calibration", "Immersive level calibration", "Bed", "Surround speaker", "Object-based audio"], "common_mistakes": ["Confusing height/top speakers with ordinary surround speakers on the ear-level plane", "Mounting height speakers too low or at the wrong elevation angle, collapsing the overhead image", "UNSAFE: Rigging or flying overhead speakers without rated mounting hardware, a secondary safety attachment, and the manufacturer's specified suspension practice"], "scenario_contexts": ["Installing a 7.1.4 room where four top speakers form the height layer", "Calibrating overhead pans in an immersive mix", "Troubleshooting a collapsed vertical image caused by misplaced height speakers"]}, "c5788623-18df-43c0-8ee3-5593b99413e0": {"definition": "The alignment step that sets a time delay (and matching level trim) for each loudspeaker in an immersive array so signals from speakers at unequal distances arrive at the mix position together. Dolby applies delay and amplitude compensation for distance differences up to a maximum of 10 ms, and the Dolby Atmos Renderer provides global and per-speaker delay controls.", "plain_english": "This lines up the timing of every speaker. Closer speakers get a tiny delay added so sound from near and far speakers reaches your seat at the same moment.", "purpose_function": "It preserves accurate imaging and object localization by removing arrival-time errors between speakers set at different distances from the listener.", "practical_application": "A technician measures each speaker's distance to the mix position and enters the delay (or lets the processor compute it) so pans and phantom images stay stable and centered.", "category": "Immersive Calibration", "related_terms": ["Immersive level calibration", "Immersive monitoring system", "Height speaker", "Mix position", "Bass management", "Reference level"], "common_mistakes": ["Calibrating levels but skipping delay, leaving overhead and surround images smeared", "Measuring distances from the wrong reference point instead of the defined mix position", "Placing speakers at very unequal distances so the required compensation exceeds the system limit"], "scenario_contexts": ["Aligning a 7.1.4 room where the surrounds sit closer than the fronts", "Setting per-speaker delay in the Dolby Atmos Renderer", "Re-checking alignment after moving a speaker"]}, "898e64a8-bdae-4d56-80ff-0b0697bd3371": {"definition": "Setting each loudspeaker in an immersive array to a defined sound-pressure level so the reproduced field matches a reference. Band-limited pink noise is measured on the SPL meter's slow setting and all full-range channels are aligned to the same level (Dolby near-field/home reference is 79-85 dBC), with the LFE/subwoofer set 10 dB higher in-band per Dolby/SMPTE practice.", "plain_english": "This makes every speaker equally loud from your seat. You play a steady test noise and adjust each speaker to hit the same meter reading, with the sub set a bit louder.", "purpose_function": "Equal, referenced levels let pans move smoothly around the room and help the mix translate to other calibrated rooms and consumer systems.", "practical_application": "A technician routes pink noise to one speaker at a time and trims each to the target SPL with a calibrated meter, then adds the LFE offset.", "category": "Immersive Calibration", "related_terms": ["Immersive delay calibration", "Reference level", "Pink noise", "LFE", "Bass management", "Immersive monitoring system"], "common_mistakes": ["Using an uncalibrated or phone SPL meter, or the wrong weighting or time setting", "Forgetting the +10 dB in-band offset for the LFE/subwoofer", "UNSAFE: Running loud calibration tones or mixing at high SPL for long periods without attention to occupational noise-exposure limits and hearing protection"], "scenario_contexts": ["Aligning all channels of a 7.1.4 room to reference level", "Trimming a replaced speaker back to match the array", "Verifying reference level before a mastering session"]}, "d44eb525-fc4e-437b-9736-80f52c0f9b19": {"definition": "A hardware or software device in the immersive monitoring chain that takes the many rendered speaker feeds and provides central control of monitor level, mute/solo, speaker and downmix selection, bass management, and often room correction, feeding the loudspeaker array from the renderer or DAW. In Dolby-certified rooms it sits between the rendering/mastering workstation and the speakers, providing overall level control and a separate 5.1/7.1 bypass path.", "plain_english": "This is the master volume and switching box for a room full of speakers. It sets one level for all of them at once and lets you mute, solo, or switch between speaker setups.", "purpose_function": "It gives one trusted point of gain and routing control over a large speaker count, so the engineer can change monitor level and configuration without touching the mix.", "practical_application": "A technician uses the monitor controller to dim, solo a single height speaker, or switch to a 5.1 fold-down while checking an immersive mix.", "category": "Monitor Control", "related_terms": ["Immersive monitoring system", "Immersive routing layout", "Bass management", "Immersive level calibration", "Downmix", "Reference level"], "common_mistakes": ["Confusing a monitor controller with an audio interface — it controls monitoring, not conversion of the mix", "Forgetting that room correction or bass management applied in the controller is active during critical listening", "Leaving trims or offsets in the controller that break the calibrated reference level"], "scenario_contexts": ["Switching between 7.1.4 and stereo to check translation", "Soloing individual speakers during calibration", "Setting a repeatable reference monitoring level for a session"]}, "6e374706-d888-4705-acbf-54f8adae7fb1": {"definition": "The structured checking of an immersive mix or deliverable by auditioning it on a calibrated monitoring system: verifying speaker assignments and routing, levels and loudness, object placement and overhead content, the downmix and binaural fold-downs, and the metadata against the target specification before delivery.", "plain_english": "This is the final listening check of a surround mix. You play it back on trusted, calibrated speakers to catch wrong routing, bad levels, or missing overhead sounds before you send it out.", "purpose_function": "It catches routing, level, metadata, and fold-down errors that would otherwise reach the listener, protecting the integrity of the immersive deliverable.", "practical_application": "A technician plays the finished mix and its downmixes on the calibrated array, confirms every channel maps to the right speaker and levels match reference, and logs any faults for correction.", "category": "Quality Control", "related_terms": ["Immersive monitoring system", "Immersive routing layout", "Downmix", "Immersive level calibration", "Reference level", "Binaural rendering"], "common_mistakes": ["Doing QC only in binaural or on headphones and missing loudspeaker-only problems", "Checking the immersive mix but never auditioning the stereo and 5.1 fold-downs", "Skipping verification that channels are routed to the correct physical speakers"], "scenario_contexts": ["Final QC of an immersive music master before upload", "Verifying a broadcast immersive deliverable against a spec", "Confirming fold-downs and metadata after a re-render"]}, "a9e94ee2-d197-4321-825e-66ec099dd610": {"definition": "The complete calibrated playback rig used to audition immersive audio, comprising the loudspeaker array in the horizontal and upper (height) layers plus subwoofer(s), the renderer/monitor controller and amplification, and the room, set up and calibrated to a defined layout such as 7.1.4 or 9.1.6 per Dolby and ITU-R BS.2051 practice.", "plain_english": "This is the whole speaker setup used to listen to surround-with-height mixes. It includes the speakers around and above you, the sub, and the gear and room that make them play back right.", "purpose_function": "It provides a trustworthy, reference reproduction of channel- and object-based audio so mix and calibration decisions translate to other rooms and to consumer systems.", "practical_application": "A technician installs, aligns, and calibrates the array and controller so the room meets a standard layout and reference level before any mixing begins.", "category": "Immersive Monitoring", "related_terms": ["Height speaker", "Immersive monitor controller", "Immersive level calibration", "Immersive delay calibration", "Immersive routing layout", "Bass management"], "common_mistakes": ["Adding height speakers but never calibrating level and delay for the full array", "Using mismatched speaker models around the array, causing timbre shifts as objects pan", "Treating the room and its acoustics as unimportant to an immersive system"], "scenario_contexts": ["Commissioning a new 7.1.4 mix room", "Comparing a mix across two certified immersive rooms", "Upgrading a 5.1 room to immersive by adding a height layer"]}, "67fa5212-2c2a-4e26-ba31-272d6ef504fb": {"definition": "The defined mapping of an immersive program's channels and rendered outputs to physical loudspeaker feeds (and DAW/renderer output buses) for a given layout, so each bed channel and object render lands on the correct speaker — for example, assigning the twelve feeds of a 7.1.4 layout to their outputs in the specified channel order.", "plain_english": "This is the plan for which output goes to which speaker. It makes sure the left-height signal reaches the left-height speaker and nothing gets crossed.", "purpose_function": "A correct routing layout guarantees that the renderer's speaker feeds arrive at their intended physical positions, without which imaging, calibration, and QC are meaningless.", "practical_application": "A technician patches the renderer/DAW outputs to interface and amplifier channels following the layout's channel order, then verifies each with a test signal.", "category": "Signal Routing", "related_terms": ["Immersive monitoring system", "Immersive monitor controller", "Height speaker", "Bed", "Immersive monitor quality control", "Object-based audio"], "common_mistakes": ["Swapping surround and height feeds because the channel order was assumed instead of checked", "Confusing the Dolby channel order or label with the DAW or interface output numbering", "Not verifying each output with a test tone after patching"], "scenario_contexts": ["Patching a 7.1.4 renderer to an audio interface and amplifiers", "Reconfiguring routing when moving from 7.1.4 to 9.1.6", "Diagnosing a mix where overhead content plays from the wrong speaker"]}, "3f168b77-15f5-4737-898f-7a6a2e7cd867": {"definition": "The loudspeaker, typically a subwoofer, that reproduces the dedicated low-frequency effects (LFE) channel, the '.1' in formats such as 5.1, 7.1 and 7.1.4. It carries band-limited deep bass, nominally 20 to 120 Hz, reproduced with roughly 10 dB of additional in-band headroom relative to a single main channel, and is a discrete effects channel rather than a substitute for bass in the full-range channels.", "plain_english": "It is the subwoofer that plays the special deep-bass channel in a surround mix, often called the point-one. It carries the low rumble, like the boom of an explosion, so the other speakers do not have to.", "purpose_function": "It reproduces the discrete LFE channel so high-level, low-frequency effects can be delivered with extra headroom without overloading the main and height speakers.", "practical_application": "A technician routes and calibrates the LFE channel to the subwoofer, setting its upper band limit around 120 Hz and its in-band level about 10 dB above a single main channel.", "category": "Monitor loudspeaker", "related_terms": ["Bass management", "Subwoofer", "Reference level", "Renderer calibration", "Overhead speaker", "Multichannel monitor controller"], "common_mistakes": ["Treating the LFE channel as a general bass channel and routing all low end to it, when it is meant only for added effects.", "Confusing the LFE channel with bass management; redirected bass from full-range speakers is not the same as the LFE signal.", "Forgetting the 10 dB in-band offset, so the LFE plays too quietly or too loudly against the mains.", "UNSAFE: Running sustained high-SPL bass during subwoofer calibration without limiting exposure time or wearing hearing protection, risking noise-induced hearing loss."], "scenario_contexts": ["Calibrating the subwoofer so the LFE channel sits about 10 dB above a main channel in-band.", "Routing the LFE track of a 7.1.4 Atmos mix to the dedicated subwoofer output.", "Checking that deep effects such as explosions reach the LFE speaker without clipping."]}, "a052db32-b402-4082-b44a-145b9b45f6a7": {"definition": "A hardware or software device that manages monitoring for multichannel and immersive playback, providing source selection, calibrated level control across all speaker feeds, per-channel trim and delay, bass management, downmix or fold-down monitoring, and solo/mute of individual speakers. It sits between the mix outputs and the monitor amplifiers or speakers so an engineer can audition surround and immersive formats such as 7.1.4.", "plain_english": "A control box that lets an engineer switch sources and set the volume for a whole room of speakers at once. It can also mute or solo one speaker, or fold the mix down to fewer speakers to check it.", "purpose_function": "It gives one calibrated, repeatable point of control over many speaker feeds so the engineer can hold a reference level, compare sources, and check fold-downs without re-patching.", "practical_application": "A technician uses it to select the renderer output, set the room to reference level, trim and delay each speaker, and solo a channel to trace a problem.", "category": "Monitoring hardware", "related_terms": ["Reference level", "Bass management", "Downmix", "Renderer speaker mapping", "Renderer calibration", "Immersive monitor controller"], "common_mistakes": ["Assuming the controller's volume knob changes the mix; it sets only the monitoring level, not the recorded signal.", "Forgetting that per-speaker trim and delay in the controller are separate from the renderer's own calibration.", "Leaving a downmix or a soloed speaker engaged and mixing against a wrong picture of the sound field."], "scenario_contexts": ["Switching between the Atmos renderer output and a stereo reference on the same speakers.", "Setting the whole immersive rig to a calibrated reference SPL before a mix session.", "Soloing the top-front speaker to check a suspected wiring or level error."]}, "abbf665d-df53-4913-a20c-42e821365bff": {"definition": "A loudspeaker mounted above the listening position to reproduce the height (top) channels of an immersive layout, providing the vertical dimension that distinguishes immersive audio from horizontal surround. In ITU-R BS.2051 layouts these are the top loudspeakers, such as TpFL, TpFR, TpSiL, TpSiR, TpBL and TpBR, typically at roughly +30 to +45 degrees elevation.", "plain_english": "A speaker placed in the ceiling or high on a wall so sound can come from above you. It adds the up-and-down layer that makes a mix feel like it wraps around you in three dimensions, not just at ear level.", "purpose_function": "It delivers the elevation cues and overhead content that create a sense of height, letting formats such as 7.1.4 place sounds above the listener.", "practical_application": "A technician installs, aligns and calibrates overhead speakers at the correct elevation angle, then confirms the renderer maps the top channels to them.", "category": "Monitor loudspeaker", "related_terms": ["Side surround speaker", "Rear surround speaker", "Renderer speaker mapping", "Renderer calibration", "Height speaker", "Low-frequency effects speaker"], "common_mistakes": ["Placing overhead speakers too far forward or back, so the height image does not sit above the listener.", "Confusing top-front and top-back positions when wiring, which reverses the overhead image.", "Assuming any ceiling speaker will do; overhead speakers should timbre-match the main monitors.", "UNSAFE: Hanging overhead speakers without rated mounts and a secondary safety attachment, risking a fall that can injure people below."], "scenario_contexts": ["Mounting four overhead speakers for a 7.1.4 monitoring setup.", "Calibrating the top channels so overhead pans track smoothly across the ceiling.", "Verifying that an effect authored overhead actually plays from the top speakers."]}, "f2c9368e-304e-4285-be1b-ad909d778f83": {"definition": "A loudspeaker positioned behind the listening position to reproduce the rear (back) surround channels of a 7.1-based or immersive layout. In ITU-R BS.2051 these are the left and right rear surround (Lrs, Rrs) at roughly plus or minus 120 to 150 degrees azimuth and ear level (0 degrees elevation), distinct from the side surround speakers.", "plain_english": "A speaker set behind you that plays sounds coming from the back of the room. It fills the space directly behind the listener, which the side speakers cannot cover on their own.", "purpose_function": "It provides discrete rear imaging so sounds can be placed and moved behind the listener, completing the horizontal surround field in 7.1 and larger layouts.", "practical_application": "A technician places the rear surrounds behind the seat at the correct angle, wires them to the rear channels, and calibrates their level and delay to match the array.", "category": "Monitor loudspeaker", "related_terms": ["Side surround speaker", "Overhead speaker", "Low-frequency effects speaker", "Renderer speaker mapping", "Renderer calibration", "Multichannel monitor controller"], "common_mistakes": ["Confusing rear surrounds with side surrounds and wiring them to the wrong channels.", "Placing rear surrounds too close together or too wide, collapsing or over-spreading the back image.", "Assuming a 5.1 room has rear surrounds; 5.1 uses only a single surround pair, not separate rears."], "scenario_contexts": ["Adding rear surround speakers to expand a 5.1 room to 7.1.", "Calibrating the rear pair so a sound panned front to back stays centered.", "Checking that the renderer routes the rear surround channels to the correct outputs."]}, "87c33102-7157-4e70-a5af-601cac862fbb": {"definition": "The process of configuring and aligning an object-audio renderer to a specific room and speaker layout so its output is correct and consistent: defining the speaker configuration and setting per-speaker trim (level), distance and delay, bass-management crossovers, and a defined monitoring reference SPL. It ensures the rendered mix is judged on an accurate system and translates to other calibrated rooms.", "plain_english": "Setting up the renderer so it plays back correctly in your exact room and speakers. You tell it where the speakers are, match their volumes and timing, and set a standard loudness so your mix sounds right and matches other rooms.", "purpose_function": "It makes the renderer's output match a known reference so mixes are made on an accurate, repeatable system and translate to other calibrated rooms.", "practical_application": "A technician sets each speaker to reference level with test noise, enters speaker distances so the renderer applies correct delays, and sets crossovers before any mixing begins.", "category": "Calibration", "related_terms": ["Renderer speaker mapping", "Reference level", "Bass management", "Multichannel monitor controller", "Room-rendered monitoring", "Low-frequency effects speaker"], "common_mistakes": ["Skipping distance or delay entry, so speakers arrive out of time and the image smears.", "Calibrating to the wrong reference SPL for the room, making the mix too loud or too soft.", "Forgetting to recalibrate after moving a speaker or changing the layout.", "Confusing calibration with speaker mapping; mapping sets routing, calibration sets levels and timing."], "scenario_contexts": ["Setting each channel to reference level with pink noise before a mix.", "Entering speaker distances so the renderer applies correct per-speaker delays.", "Recalibrating after swapping a monitor or adding overhead speakers."]}, "bda23d7d-456b-4b05-8d0a-2309d92ea5fc": {"definition": "The processing delay introduced by a real-time object-audio renderer between its input (the bed and object feeds from the DAW) and its monitored or recorded output. Because the renderer and the audio driver buffer and process audio, this latency must be handled by delay compensation so monitoring and any recorded re-renders stay time-aligned with the session.", "plain_english": "The small delay a renderer adds while it turns the mix into speaker or headphone sound. If you do not account for it, what you hear or record can drift out of time with the rest of the session.", "purpose_function": "Knowing the renderer's latency lets the system apply delay compensation so what you hear and what you record line up with the DAW timeline.", "practical_application": "A technician keeps delay compensation active and matches buffer settings so the renderer's return signal and re-renders sync with the picture and tracks.", "category": "Signal timing", "related_terms": ["Renderer speaker mapping", "Renderer calibration", "Room-rendered monitoring", "Multichannel monitor controller", "Re-render", "Buffer size"], "common_mistakes": ["Disabling automatic delay compensation, then wondering why the return is out of sync.", "Assuming an external renderer adds no delay and printing re-renders that drift against picture.", "Setting a very large audio buffer for stability while ignoring the extra latency it adds."], "scenario_contexts": ["Aligning a recorded re-render from the renderer back to the timeline.", "Troubleshooting sync drift between picture and an Atmos monitor feed.", "Choosing a buffer size that balances stability against added latency."]}, "e1cb17b5-6971-406b-8cf5-e5e224c87015": {"definition": "The assignment of a renderer's internal output channels (the speakers defined in its room setup, such as L, R, C, LFE, side and rear surrounds, and the top channels) to the physical outputs of the audio interface that feed each monitor. It is set in the renderer's room or output configuration and determines which speaker each rendered channel drives.", "plain_english": "Telling the renderer which real speaker jack each of its channels should go to. It is like labeling the wires so a left-top sound actually comes out of the left-top speaker.", "purpose_function": "It routes each rendered channel to the correct physical speaker so the immersive layout plays back as intended, with no swapped or misrouted channels.", "practical_application": "A technician sets the speaker layout, maps each channel to an interface output, and plays test noise per channel to confirm the right speaker responds.", "category": "Signal routing", "related_terms": ["Renderer calibration", "Room-rendered monitoring", "Multichannel monitor controller", "Overhead speaker", "Rear surround speaker", "Side surround speaker"], "common_mistakes": ["Mapping channels to the wrong outputs, so sounds come from the wrong speakers.", "Confusing speaker mapping with calibration; mapping is routing, calibration is levels and delays.", "Forgetting to re-check the map after changing the interface or its output order."], "scenario_contexts": ["Assigning the renderer's 7.1.4 channels to interface outputs one through twelve.", "Running per-channel test noise to verify each speaker is mapped correctly.", "Re-mapping outputs after adding a second interface for more speakers."]}, "a880e67e-78d6-4c0d-9e61-4f5fa1b40212": {"definition": "Monitoring in which the object-based mix is rendered in real time to the actual loudspeaker layout installed in the room, so the engineer hears it on the physical speakers rather than through binaural headphone rendering or a fixed downmix. What is heard depends on the room's speaker configuration and its calibration.", "plain_english": "Listening to an immersive mix on the real speakers in your room, with the renderer feeding sound to each one live. It is different from checking on headphones, where the space is faked for your ears.", "purpose_function": "It lets the engineer judge the mix on the true speaker layout it is made for, revealing imaging, level and translation issues that headphone monitoring can hide.", "practical_application": "A technician monitors on the room speakers through the renderer during a mix, switching to binaural only to spot-check the headphone experience.", "category": "Monitoring", "related_terms": ["Renderer calibration", "Renderer speaker mapping", "Multichannel monitor controller", "Renderer latency", "Downmix", "Overhead speaker"], "common_mistakes": ["Judging a mix mainly on binaural headphones, then finding it does not translate to the speaker layout.", "Monitoring on the room speakers before calibration, so level and timing errors are mistaken for mix problems.", "Assuming room-rendered monitoring sounds the same across studios; each room's layout and calibration differ."], "scenario_contexts": ["Mixing an Atmos session on a 7.1.4 room through the renderer.", "Comparing the room-speaker render against a binaural check before delivery.", "Diagnosing whether an imaging problem is in the mix or the room by listening on the calibrated speakers."]}, "0b3cd382-35a5-4aaa-9c45-9c926bcaf711": {"definition": "A loudspeaker positioned to the side of the listening position, roughly abreast of the listener, to reproduce the side surround channels of a 7.1-based or immersive layout. In ITU-R BS.2051 these are the left and right side surround (Lss, Rss) at roughly plus or minus 85 to 110 degrees azimuth and ear level (0 degrees elevation), distinct from the rear surround speakers.", "plain_english": "A speaker placed beside you, level with your ears, that plays sounds coming from your left or right side. It handles the sound that should feel right next to you, between the front and the back.", "purpose_function": "It provides discrete side imaging so sounds can be placed and panned along the listener's sides, filling the gap between the front speakers and the rear surrounds.", "practical_application": "A technician mounts the side surrounds at ear height beside the seat, wires them to the side channels, and calibrates their level and delay with the array.", "category": "Monitor loudspeaker", "related_terms": ["Rear surround speaker", "Overhead speaker", "Low-frequency effects speaker", "Renderer speaker mapping", "Renderer calibration", "Multichannel monitor controller"], "common_mistakes": ["Confusing side surrounds with rear surrounds and wiring them to the wrong channels.", "Placing side surrounds too far forward or behind the listener instead of to the side.", "Assuming a 5.1 setup has separate side and rear surrounds; 5.1 has only one surround pair."], "scenario_contexts": ["Placing the side surrounds at the listener's sides when expanding a room to 7.1.", "Calibrating the side pair so a left-to-right pan stays smooth.", "Verifying the renderer maps the side surround channels to the correct speakers."]}, "105a6d0d-ec53-4ddd-9495-ac6c4e7c1fd4": {"definition": "A test signal, typically a tone or band-limited pink noise, routed to one loudspeaker output at a time during system setup so the installer can confirm which physical speaker corresponds to which channel and that its wiring, polarity, and routing are correct.", "plain_english": "A test sound sent to one speaker at a time. It lets you hear which speaker is which and check that each one is wired to the right channel.", "purpose_function": "It verifies channel-to-speaker mapping and correct wiring before calibration, preventing swapped or miswired speakers in a multichannel immersive layout.", "practical_application": "During commissioning a technician sends the signal to each output in turn, walking the room to confirm the correct speaker plays and is in phase before running level and distance calibration.", "category": "Calibration & Setup", "related_terms": ["Speaker remapping", "Speaker-trim calibration", "Speaker-distance compensation", "Speaker-rendered monitoring", "Pink noise"], "common_mistakes": ["Assuming the physical speaker order matches the amplifier or interface output order without testing each one.", "Ignoring polarity, so a reversed speaker passes the identification check by sound alone.", "UNSAFE: Setting a very high signal level to hear a distant speaker, risking hearing damage and driver damage when the tone plays close by."], "scenario_contexts": ["Commissioning a 7.1.4 monitor room and confirming each ceiling speaker plays on its assigned channel.", "Troubleshooting a swapped surround pair reported by a mixer.", "Verifying wiring after re-patching an immersive amplifier rack."]}, "0c2d7803-bdf8-4477-9068-95f326ebc129": {"definition": "The reassignment of rendered output channels to different physical loudspeaker outputs, or the re-rendering of an immersive mix to a different loudspeaker layout, so program material plays on the intended speakers of the target system.", "plain_english": "Sending each audio channel to a different speaker output, or reshaping the mix for a different set of speakers. It makes sure sounds come out of the right speakers.", "purpose_function": "It matches the renderer's output to the actual hardware wiring or to an alternate playback layout, allowing one mix to be monitored on different speaker configurations.", "practical_application": "A technician remaps outputs when the interface patch differs from the default order, or re-renders a 7.1.4 master to a 5.1.4 room for monitoring.", "category": "Signal Routing", "related_terms": ["Speaker identification signal", "Speaker-rendered monitoring", "Speaker-relative placement", "Top speaker", "Wide speaker"], "common_mistakes": ["Confusing remapping outputs with changing the creative mix; remapping only reroutes or re-renders playback.", "Forgetting to update the map after changing the audio interface's output patch, sending channels to the wrong speakers.", "Assuming a re-render to a smaller layout preserves every overhead cue exactly."], "scenario_contexts": ["Matching renderer outputs to a non-standard interface output order.", "Re-rendering a 9.1.6 master down to a 7.1.4 monitor room.", "Adapting a mix for a room whose speakers are wired in a different sequence."]}, "912134de-0928-4c2f-af6c-52ee6dc87821": {"definition": "The application of a per-loudspeaker time delay based on each speaker's distance to the reference listening position, so signals from all speakers arrive at the listener simultaneously despite unequal path lengths.", "plain_english": "Adding a tiny delay to closer speakers so sound from every speaker reaches your ears at the same time. Think of a staggered start in a race so all runners finish together.", "purpose_function": "It time-aligns the array at the listening position, preserving accurate imaging, phantom images, and object localization that unequal distances would otherwise smear.", "practical_application": "A technician measures each speaker's distance to the mix position and enters it, or runs auto-calibration, so the renderer or processor delays nearer speakers accordingly.", "category": "Calibration & Setup", "related_terms": ["Speaker-trim calibration", "Speaker identification signal", "Speaker-rendered monitoring", "Top speaker", "Wide speaker"], "common_mistakes": ["Measuring to the speaker cabinet face but forgetting the extra path for in-ceiling overheads.", "Setting one global delay instead of a correct per-speaker distance.", "Confusing distance/time compensation with level trim, which correct different problems."], "scenario_contexts": ["Aligning near-field fronts with more distant surround and ceiling speakers.", "Compensating for overhead speakers mounted well above the listener.", "Restoring imaging after moving the mix position in a room."]}, "89d1c1ec-b577-423f-86ad-d51ea0942645": {"definition": "A positioning approach in which an audio signal's location is defined with reference to actual loudspeaker positions, each signal tied to a specific speaker or interpolated between named speakers, rather than to absolute room coordinates or a listener-centred angular grid.", "plain_english": "Placing sound by pointing it at the actual speakers, instead of at a spot in the room. Each channel is tied to a real speaker.", "purpose_function": "It ties reproduction directly to the physical layout, which keeps channel-based material predictable but locks the result to that exact speaker arrangement.", "practical_application": "A technician relies on speaker-relative routing when feeding fixed bed channels or test signals straight to named outputs, as opposed to object audio placed in room coordinates.", "category": "Spatial Rendering", "related_terms": ["Speaker remapping", "Speaker-rendered monitoring", "Speaker identification signal", "Top speaker", "Wide speaker"], "common_mistakes": ["Assuming speaker-relative channels translate perfectly to a layout with different speaker angles.", "Confusing speaker-relative (channel-anchored) placement with room-based object placement.", "Expecting a phantom image between two speakers to hold for listeners well off the sweet spot."], "scenario_contexts": ["Routing a 7.1.4 bed where each channel maps to one speaker.", "Comparing channel-based beds against object-based, room-positioned sources.", "Explaining why a hard-panned channel moves with the speaker layout, not the room."]}, "d68e0b74-accf-4b21-af8a-ae7c486214ad": {"definition": "Monitoring an immersive mix by rendering its bed channels and audio objects to a physical multichannel loudspeaker array in the room, as opposed to binaural rendering over headphones.", "plain_english": "Listening to an immersive mix through real speakers all around the room, not through headphones. The renderer decides how much of each sound goes to each speaker.", "purpose_function": "It reproduces the mix over the actual speaker layout so the engineer hears true spatial imaging, level, and timing at the listening position.", "practical_application": "An engineer uses speaker-rendered monitoring on a calibrated 7.1.4 system to make spatial and tonal decisions, switching to binaural only to check the headphone experience.", "category": "Monitoring", "related_terms": ["Speaker-trim calibration", "Speaker-distance compensation", "Speaker remapping", "Speaker-relative placement", "Top speaker", "Room-rendered monitoring"], "common_mistakes": ["Trusting spatial decisions on an uncalibrated array where levels and distances are wrong.", "Assuming speaker-rendered and binaural monitoring sound the same.", "Judging overhead content on a system missing or misplaced top speakers."], "scenario_contexts": ["Mixing Dolby Atmos on a calibrated in-room speaker array.", "Checking object movement across the surround and ceiling speakers.", "Comparing the loudspeaker render with a binaural headphone render."]}, "d0e33f33-174a-419d-89e2-e0526089b3f5": {"definition": "The process of adjusting each loudspeaker's playback gain (trim) so every speaker produces a matched sound-pressure level at the reference listening position, referenced to a defined target; for example, driving each channel with -20 dBFS RMS pink noise to reach roughly 79-82 dB SPL(C) in a Dolby Atmos near-field room.", "plain_english": "Setting each speaker volume so they all sound equally loud at the mixing spot. You play a steady test noise through one speaker at a time and adjust it to hit the target level.", "purpose_function": "It equalizes per-speaker level so the balance heard at the mix position is accurate and repeatable, which is essential for consistent immersive mixes across rooms.", "practical_application": "Using an SPL meter at the listening position, a technician sends reference pink noise to each speaker and trims its gain until all channels read the same target level.", "category": "Calibration & Setup", "related_terms": ["Speaker-distance compensation", "Speaker identification signal", "Speaker-rendered monitoring", "Pink noise", "Top speaker"], "common_mistakes": ["Level-matching by ear instead of a calibrated SPL meter and defined pink-noise reference.", "Using a different pink-noise level or meter weighting than the target specifies, so trims come out wrong.", "UNSAFE: Calibrating to full theatrical reference in a small room, producing sustained levels that can exceed safe hearing-exposure limits (OSHA 29 CFR 1910.95)."], "scenario_contexts": ["Calibrating a new immersive monitor room to a house reference level.", "Re-trimming a speaker after replacing its amplifier or driver.", "Matching two rooms so mixes translate between them."]}, "62067e15-1139-4fe1-90e1-e978b448bd0d": {"definition": "A loudspeaker in the upper (height) layer of an immersive layout, mounted above the listening plane, typically overhead at an elevation of about +30 to +45 degrees, used to reproduce height channels and elevated audio objects.", "plain_english": "A speaker mounted above you, usually on or near the ceiling. It plays sounds that should seem to come from overhead, like rain or a passing plane.", "purpose_function": "It adds the vertical dimension that distinguishes immersive audio from surround, letting sounds be placed and moved overhead.", "practical_application": "A technician installs top speakers, such as top front and top rear pairs in 7.1.4, at the specified elevation and includes them in distance and trim calibration.", "category": "Speaker Layout", "related_terms": ["Wide speaker", "Speaker-distance compensation", "Speaker-trim calibration", "Speaker-rendered monitoring", "Speaker-relative placement"], "common_mistakes": ["Mounting top speakers too shallow so overhead sounds seem to come from the front wall.", "Forgetting the extra ceiling-to-listener path when setting overhead distance.", "Spacing or aiming overhead pairs inconsistently between left and right."], "scenario_contexts": ["Installing the four overhead speakers of a 7.1.4 monitor room.", "Setting overhead elevation to about 45 degrees per the layout spec.", "Checking that an object panned upward images correctly overhead."]}, "785b5663-b20e-4c3f-a048-ca1eb16f3fb5": {"definition": "A front loudspeaker positioned at a wider azimuth than the main front left/right speakers, between the fronts and the side/surround speakers, used in extended immersive layouts (such as 9.1.x) to fill the frontal gap and broaden the front sound stage.", "plain_english": "An extra front speaker placed out to the side of the main left and right speakers. It widens the sound across the front so there is no gap between the front and side speakers.", "purpose_function": "It smooths panning and imaging between the front and surround speakers, widening the frontal image in layouts that go beyond the standard front trio.", "practical_application": "A technician adds left/right wide speakers between the fronts and sides in a 9.1.x room, then includes them in identification, distance, and trim calibration.", "category": "Speaker Layout", "related_terms": ["Top speaker", "Speaker-relative placement", "Speaker-distance compensation", "Speaker-trim calibration", "Speaker-rendered monitoring"], "common_mistakes": ["Placing wide speakers too close to the front left/right, so they add little width.", "Assuming every immersive layout includes wide speakers; many, like 7.1.4, do not.", "Confusing front wide speakers with side surround speakers."], "scenario_contexts": ["Expanding a 7.1.4 room to a 9.1.4 layout with front wides.", "Filling the imaging gap between front and side speakers.", "Calibrating the added wide pair into an existing immersive system."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"63e6e0d0-6516-43f4-8ecc-67df3cc0f37d": {"definition": "The dedicated workroom and workstation environment equipped for dialogue editing, typically comprising a DAW such as Pro Tools, calibrated near-field monitoring, and synchronized picture playback, in which the dialogue editor conforms, cleans, and organizes production sound and ADR into edited tracks for the re-recording mix.", "plain_english": "It is the workroom where an editor cleans up spoken lines in a film and lines them up to the picture.", "purpose_function": "It gives the dialogue editor a controlled listening space and the editing tools to conform, clean, and split dialogue and ADR, so the re-recording mixer receives organized, intelligible, ready-to-mix tracks.", "practical_application": "A dialogue editor works in the suite to sync ADR to picture, remove clicks and noises, smooth cuts with matching room tone, and split lines across tracks before handing the session to the dub stage.", "category": "Dialogue Editing", "related_terms": ["Dialogue mixing", "ADR", "Room tone", "Re-recording mixing", "Conform", "Edit decision list"], "common_mistakes": ["Assuming the final balance against music and effects is done in the dialogue-editing suite; that blending happens later on the dub stage during the re-recording mix.", "Confusing the dialogue-editing suite with the picture-editorial cutting room; they are separate stages with different roles and deliverables.", "Editing dialogue in an untreated, uncalibrated room, so noise and coloration in the space hide problems that only surface later on the dub stage.", "UNSAFE: monitoring at excessive SPL through long editing sessions can cause noise-induced hearing loss; keep exposure within OSHA permissible limits and take breaks."], "scenario_contexts": ["A dialogue editor conforms production sound to the locked picture and prepares split, labeled tracks before the re-recording mix.", "ADR takes are imported into the suite and edited so the recorded lines match the actor's on-screen lip movements and original performance.", "The editor uses room tone captured on set to fill gaps between lines and smooth over audible cuts between takes.", "Clicks, mouth noises, and camera or set noise are removed from the production dialogue before the tracks are handed off to the dub stage."]}, "2b25a96b-07c5-45d3-b715-78c5e3e5ee34": {"definition": "A small, sound-isolated recording enclosure used to re-record dialogue in sync to picture during ADR (automated dialogue replacement, or looping); it is acoustically treated for a dry, low-reverberation signal and fitted with a picture monitor, microphone, and headphone cue/talkback feed so an actor can match new lines to the original performance. It is the compact counterpart to a full ADR stage, common in television, animation, games, and voice-over facilities.", "plain_english": "A small, soundproof room where an actor re-records their movie lines while watching the scene on a screen. It is built to sound very dead, so the new voice is clean and can be blended into the film later.", "purpose_function": "It provides an isolated, acoustically neutral space so replacement lines are captured cleanly and can later be matched or processed to fit the on-screen environment, without room reflections coloring the recording.", "practical_application": "A technician sets up the booth mic, feeds the actor the original guide track and picture with sync beeps or streamers over headphones, and records take after take until the timing and lip-sync match the picture.", "category": "Post-production facility", "related_terms": ["ADR stage", "Looping", "Lip sync", "Guide track", "Streamer", "Foley stage"], "common_mistakes": ["Assuming any small vocal booth is ready for ADR; the space still needs a synchronized picture feed and a cueing system, not just sound isolation.", "Recording ADR in a booth with audible reverb, which colors the take and makes it impossible to match to different scene environments later.", "Expecting a booth to substitute for a full ADR stage when the scene needs a large, boomed, theatrical-scale performance.", "UNSAFE: driving actor headphone cue levels too high across a long looping session, risking hearing damage."], "scenario_contexts": ["Re-recording an actor's lines for an animated series in a compact isolation booth.", "Looping a single line ruined by set noise, matched to the lip movement on the monitor.", "Recording video-game character dialogue to picture or timecode in a voice booth."]}, "f6ac616c-ab13-4aad-bdb4-72da57f73146": {"definition": "A large, acoustically controlled recording studio dedicated to automated dialogue replacement (ADR, or looping), equipped with a big projection screen or monitor, a recording microphone (often on a boom), an adjacent control room, and sync/cueing systems such as streamers, wipes, and beeps so actors can re-perform and lip-sync dialogue to picture. Its acoustics are kept neutral and low in reverberation so recorded lines can be matched or processed to any on-screen environment.", "plain_english": "A big, quiet studio with a movie screen where actors re-record their lines to match the picture. The room is made to sound very dead, so the new voice can be shaped to fit any scene.", "purpose_function": "It exists to give actors a theatrical-scale space with picture playback for re-performing dialogue in sync, while its neutral, dry acoustics keep the recordings clean enough to blend seamlessly with production dialogue in the final mix.", "practical_application": "The recording mixer plays the scene on the large screen with cue beeps and streamers, records the actor at the boom mic through multiple takes, and the ADR editor later aligns the chosen take precisely to picture.", "category": "Post-production facility", "related_terms": ["ADR booth", "Looping", "Lip sync", "Streamer", "Guide track", "Foley stage"], "common_mistakes": ["Confusing an ADR stage with a dubbing/mix stage; the ADR stage is where replacement lines are recorded, while balancing and mixing happen on the dubbing stage.", "Assuming a live, reverberant room is acceptable; ADR stages are kept acoustically dead so lines can be matched to any scene's environment.", "Forgetting that the actor needs accurate sync cues (beeps and streamers) to hit lip-sync, not just picture playback.", "UNSAFE: setting actor cue/monitor or headphone levels too high over a long session, risking hearing damage."], "scenario_contexts": ["Re-recording dialogue for a feature film scene whose location sound was unusable.", "Bringing an actor in to change or clean up a line for a broadcast or airline edit, performed to the big screen.", "Recording loop-group (walla) crowd dialogue to picture on the stage."]}, "8a135eb7-c0f7-4ad2-b63a-55ed2a087d7b": {"definition": "A large, acoustically controlled mixing theatre in which the final re-recording (the 'dub') of a film or television programme is performed, combining the dialogue, music and sound-effects premixes into the finished soundtrack. It is aligned to a cinema monitoring reference (the wide-range 'X-curve' B-chain response of SMPTE ST 202 / ISO 2969) so the mix translates to release venues, and it is used to build both the original mix and the music-and-effects (M&E) stem that localized-language versions are dubbed against.", "plain_english": "A big, sound-treated theatre where a movie final soundtrack is mixed. Here the speech, music, and effects are blended into one track. The speakers are set to a cinema standard so the mix sounds right in real theatres.", "purpose_function": "It provides a calibrated, cinema-like listening environment where re-recording mixers balance every sound element into a final mix that plays back consistently across theatres and home systems, and it produces the M&E stem needed for foreign-language dubbing.", "practical_application": "A re-recording mixer works at a large console in the dubbing stage, mixing dialogue, music and effects to picture while checking the mix against the room's reference alignment; a localization team later reuses the stage's M&E stem when recording and mixing dubbed dialogue.", "category": "Post-production facility", "related_terms": ["Re-recording mixer", "M&E stem", "X-curve", "ADR", "Localization studio", "Final mix"], "common_mistakes": ["Confusing the dubbing stage (the mixing theatre) with a voice booth where dialogue is recorded; the stage is for mixing, not tracking.", "Assuming 'dubbing' here means language replacement; on a dubbing stage it refers to the final re-recording mix.", "Treating any large room as a dubbing stage even though it is not aligned to the cinema monitoring reference (X-curve), so the mix will not translate to release venues.", "UNSAFE: Monitoring at excessive SPL for long mixing sessions without level limits or hearing breaks, risking noise-induced hearing loss."], "scenario_contexts": ["Performing the final re-recording mix of a feature film, blending the dialogue, music and effects premixes.", "Creating and checking the M&E stem that overseas dubbing houses will mix localized dialogue against.", "Aligning the room's B-chain to the X-curve before a mixing session.", "Reviewing a completed mix in the calibrated theatre to confirm it translates to release cinemas."]}, "048f7884-2391-4c15-8d22-309e478c0e1b": {"definition": "A sound-isolated recording booth, within a dubbing or localization facility, in which voice talent records target-language dialogue to picture so it can replace the original-language performance. It provides acoustic isolation and a synchronized picture/audio reference feed so the actor can watch the scene and match timing and lip-sync while a director and engineer monitor from the control room.", "plain_english": "A small, soundproof room where voice actors record lines in another language while watching the film. It keeps outside noise out so their voice can cleanly replace the original speech.", "purpose_function": "It exists to capture clean, isolated dialogue in the target language, free of room noise and spill, that will be edited and mixed in place of the original dialogue during localization.", "practical_application": "An engineer sets up a large-diaphragm mic, headphone monitoring and a video feed in the booth, then records the voice actor line by line to picture, watching levels and lip-sync while keeping the booth quiet between takes.", "category": "Post-production facility", "related_terms": ["Localization studio", "Dubbing stage", "ADR", "Lip-sync", "M&E stem", "Voice actor"], "common_mistakes": ["Treating the localization booth like a mixing room; it is for recording clean dialogue, not for the final mix.", "Ignoring lip-sync and timing against the picture, so recorded lines do not fit the on-screen mouth movements.", "Allowing headphone bleed or booth noise into the take, contaminating dialogue that must sit cleanly over the M&E stem."], "scenario_contexts": ["Recording an actor's target-language lines to picture for a dubbed film.", "Re-recording an actor's own dialogue (ADR) to replace noisy or unusable production sound.", "Capturing isolated voice-over narration for a localized version of a documentary."]}, "d6f9eadc-987d-4207-8308-882eb5a4bd09": {"definition": "A post-production facility that adapts audiovisual content for other languages and markets, carrying out dubbing, voice-over and often subtitling work; it typically houses recording booths for target-language dialogue and mixing rooms where that dialogue is combined with the programme's supplied music-and-effects (M&E) stem to produce the localized soundtrack.", "plain_english": "A studio that adapts films and shows for other countries. It records new speech in different languages. Then it mixes that speech with the original music and sound effects to make a local version.", "purpose_function": "It exists to turn a finished programme into versions for other languages and regions, providing the rooms, tools and staff to record localized dialogue and remix it with the supplied M&E stem so the new soundtrack matches the original.", "practical_application": "A technician at a localization studio ingests the M&E stem and reference mix, records target-language dialogue in the booth, then edits and mixes it to picture to deliver a broadcast- or cinema-ready localized soundtrack.", "category": "Post-production facility", "related_terms": ["Localization booth", "Dubbing stage", "M&E stem", "ADR", "Subtitling", "Voice-over"], "common_mistakes": ["Confusing a localization studio with the original dubbing stage; the localization studio remixes against the delivered M&E stem rather than the original premixes.", "Assuming localization is only translation, when it also requires recording, editing and mixing dialogue to picture.", "Delivering a localized mix that ignores the loudness and format specs (such as the target market's broadcast loudness targets) required for delivery."], "scenario_contexts": ["Producing foreign-language dubbed versions of a streaming series from the supplied M&E stem.", "Recording and mixing localized voice-over for a documentary or corporate release.", "Preparing multiple language versions of a film for international theatrical or broadcast distribution."]}, "6b8d5c30-caa4-4997-bc00-d951af0faa98": {"definition": "A recessed section built into a Foley stage floor and filled with a specific walking-surface material—such as gravel, sand, dirt, concrete, wood, tile, or water—so a Foley artist can perform footsteps and other movement sounds directly on that surface. A stage normally has several pits holding different materials side by side.", "plain_english": "A sunken box built into the floor of a Foley studio and filled with a surface like gravel, sand, or wood. A Foley artist steps into it to make footstep sounds that match the picture on screen.", "purpose_function": "Foley pits let an artist reproduce footsteps and movement on the many surfaces seen on screen without leaving the stage, supplying the mixer with authentic, picture-synced surface sounds that replace or reinforce the production recording.", "practical_application": "A Foley artist selects the pit whose material best matches the on-screen surface—gravel for an outdoor path, wood for a porch—and performs the footsteps in sync while watching the picture and monitoring the recorded take.", "category": "Foley stage", "related_terms": ["Foley surface", "Foley prop area", "Foley stage", "Foley artist", "Footsteps (Foley)", "Spotting"], "common_mistakes": ["Treating the pit's material as fixed rather than choosing or dressing it to match the exact on-screen surface.", "Ignoring how loose material like gravel or sand migrates during a session, changing the sound and requiring reset between takes.", "Miking the pit at a fixed spot instead of adjusting distance and angle to capture the character of that particular surface."], "scenario_contexts": ["Performing a character's walk along a gravel road using the stage's gravel pit.", "Switching from the wood pit to the concrete pit as a scene moves from a porch to a sidewalk.", "Using the water pit to create splashing and wet footstep sounds for a rain sequence."]}, "285341f7-9f62-4967-9ad9-02599858584a": {"definition": "The dedicated storage and staging space on or beside a Foley stage where the props used to create sound effects—shoes, cloth, dishes, doors, hardware, keys, and countless found objects—are organized and kept within reach of the performer. It keeps the working collection sorted so props can be selected quickly during a session.", "plain_english": "The spot on a Foley stage where all the props are kept, like shoes, dishes, and doors. The artist grabs objects from here to make the sounds a scene needs.", "purpose_function": "It organizes the large, varied collection of sound-making objects a Foley artist needs so the right prop can be found and performed quickly, keeping the session efficient and matched to the picture.", "practical_application": "A Foley artist and editor stage the props a cue will need from the prop area before rolling, then return and re-sort them afterward so the collection stays usable for the next session.", "category": "Foley stage", "related_terms": ["Foley pit", "Foley surface", "Foley stage", "Foley artist", "Props (Foley)", "Spotting"], "common_mistakes": ["Leaving props scattered instead of returning them, so time is lost hunting for objects mid-session.", "Assuming a real-world object always sounds correct on screen rather than testing several props to find the convincing one.", "UNSAFE: storing sharp tools, broken glass, or heavy metal props loosely in the prop area, creating cut and crush hazards for performers reaching for objects."], "scenario_contexts": ["Pulling several pairs of shoes from the prop area to match different characters' footsteps.", "Selecting cloth and leather from the prop area to perform clothing movement (cloth pass) for a scene.", "Gathering dishes, cutlery, and glassware from the prop area to cover a kitchen sequence."]}, "c0a1024b-2cbd-41d2-9f02-96d5b838b61e": {"definition": "The specific material an artist walks or moves on to generate a Foley sound—for example wood, tile, marble, concrete, gravel, sand, grass, carpet, or metal—chosen to match the surface depicted on screen. Foley surfaces are held in the stage's pits or laid out as loose panels and materials for the performer.", "plain_english": "The material a Foley artist walks or moves on to make a sound, such as tile, wood, or grass. It is picked to match the floor you see on screen so the footsteps sound right.", "purpose_function": "The surface determines the timbre and character of footstep and movement sounds, so matching it to the on-screen material is what makes the Foley read as believable and locked to the picture.", "practical_application": "A Foley artist auditions and swaps surfaces—laying a tile panel over a pit or moving to the gravel pit—until the recorded footsteps match the on-screen floor in tone, weight, and rhythm.", "category": "Foley stage", "related_terms": ["Foley pit", "Foley prop area", "Foley stage", "Foley artist", "Footsteps (Foley)", "Sync"], "common_mistakes": ["Choosing a surface by name alone rather than by how it actually sounds under a given shoe and performance.", "Overlooking how a performer's shoe, weight, and walking rhythm interact with the surface to shape the final sound.", "Forgetting that a hard surface's brightness and reflections change with mic distance, so surface choice and mic placement must be set together."], "scenario_contexts": ["Laying a hardwood panel over a pit to match footsteps on a wooden floor.", "Choosing a marble or tile surface to give a character's steps a hard, ringing quality in a lobby scene.", "Performing on grass or leaf litter to match a character walking through a park."]}, "5c3233b8-f14d-44f3-9d4c-68586b841c80": {"definition": "A dedicated workspace equipped for game-audio implementation, the task of integrating audio assets into a game so they respond to gameplay. It typically runs the game engine (such as Unreal or Unity) alongside audio middleware (such as Audiokinetic Wwise or Firelight FMOD Studio) with calibrated monitoring, so a technician can author events, real-time parameters, states, and switches and audition the audio in-engine.", "plain_english": "A room set up to put game sounds into a game. An audio person runs the game next to a tool like Wwise or FMOD, links each sound to what happens in play, and then tests it.", "purpose_function": "It gives the person responsible for implementation the tools and monitoring needed to connect sound and music to game logic and to verify that behavior in the running build, rather than only mixing linear files.", "practical_application": "A technician works here to import assets into Wwise or FMOD, wire events and RTPCs to game parameters, build and profile SoundBanks, and audition the result in the live engine to catch missing triggers or mix problems before a build ships.", "category": "Game-audio facility", "related_terms": ["Game-audio suite", "Interactive-audio lab", "Audio middleware", "Real-Time Parameter Control (RTPC)", "SoundBank", "Game engine"], "common_mistakes": ["Treating implementation as simply exporting mixed files, rather than authoring the events, parameters, states, and switches that make audio respond to gameplay.", "Monitoring only on the room's studio speakers and never checking the mix on target playback such as TV speakers, headphones, or a phone.", "Forgetting to rebuild and profile SoundBanks after asset changes, so the running game loads outdated or missing audio.", "UNSAFE: auditioning game effects at high SPL for long implementation sessions without managing monitoring level, risking noise-induced hearing loss."], "scenario_contexts": ["Integrating a new weapon's sound set into the engine and mapping its firing, reload, and impact events.", "Setting up an RTPC so an engine loop's pitch tracks vehicle speed, then testing it while driving in-game.", "Profiling a level's audio in the running build to find voices that exceed the platform's voice limit."]}, "feb4f691-45a1-43ce-a580-12fa47b0d135": {"definition": "A complex of connected rooms configured as a complete game-audio production facility, typically covering recording and editing, sound design, implementation, and mixing for interactive projects. It groups the spaces and shared systems a game-audio team needs under one roof, as distinct from a single-purpose room.", "plain_english": "A set of connected rooms that together make all the sound for games. One space might record sounds, another designs them, and another puts them into the game.", "purpose_function": "It brings the full game-audio workflow—capture, design, implementation, and mixing—into one coordinated facility so a team can move a project through every stage without leaving the building.", "practical_application": "A studio books its game-audio suite for a project, using its recording room for source capture, its design and edit rooms for asset creation, and its implementation room to integrate and mix the audio in-engine.", "category": "Game-audio facility", "related_terms": ["Game-audio implementation room", "Interactive-audio lab", "Audio middleware", "Sound design", "Control room", "SoundBank"], "common_mistakes": ["Confusing a game-audio suite with a music studio, overlooking that it must also support in-engine implementation and interactive testing, not just linear recording and mixing.", "Assuming every room shares one calibrated reference, when target-platform monitoring and workstation setups differ between spaces.", "Neglecting a shared middleware project and asset server, so rooms in the suite drift onto different builds and versions.", "UNSAFE: running long high-level monitoring or repeated loud SFX passes across rooms without hearing-conservation practices, risking cumulative noise exposure."], "scenario_contexts": ["A game-audio team moving a title from field recording through design, implementation, and final mix within one facility.", "Scheduling different rooms of the suite for parallel work, such as dialogue editing in one and implementation in another.", "Setting up a shared asset server and middleware project so all rooms in the suite work from the same build."]}, "c195826c-db2c-4658-89f9-a8a6b12147c2": {"definition": "A workspace outfitted for developing and testing interactive (adaptive) audio—sound and music that changes in real time in response to game state and player input. It combines a game engine, audio middleware, and monitoring so that non-linear audio systems can be prototyped, implemented, and evaluated; the term is common in educational, research, and development settings.", "plain_english": "A room set up to build and test game sound that changes as you play. People try out music and effects that react to what the player does and check if they work in the game.", "purpose_function": "It provides a controlled space to prototype and evaluate adaptive audio behavior—transitions, layering, and parameter-driven changes—so systems can be refined before they go into a shipping game.", "practical_application": "Students or developers use the lab to build middleware projects, hook audio events and parameters to game logic, and audition how music and effects adapt while play conditions change.", "category": "Game-audio facility", "related_terms": ["Game-audio implementation room", "Game-audio suite", "Adaptive music", "Audio middleware", "Real-Time Parameter Control (RTPC)", "Interactive audio"], "common_mistakes": ["Thinking interactive audio is just looping a background track, rather than systems whose transitions and layers are driven by game parameters and state.", "Testing adaptive behavior only in the middleware's preview or soundcaster tool and never in the actual running game, where timing and state changes differ.", "Setting music transitions without defined sync points, so cues switch abruptly instead of on musically appropriate beats or bars.", "UNSAFE: prototyping with sustained high monitoring levels during long lab sessions, risking noise-induced hearing loss."], "scenario_contexts": ["Building a vertical-layering music system whose intensity follows a combat parameter and testing it in-engine.", "Prototyping a horizontal re-sequencing transition between exploration and danger music.", "A class exercise implementing footstep switches that change with the surface the player walks on."]}, "59a8a49e-6512-4f95-aeb2-496c08eb59ad": {"definition": "The deliberate level and dynamic contrast between a low-level ambient soundscape and a sudden high-level scare cue, engineered so the loudness jump maximizes the guest's startle response. It exploits relative loudness perception: a quiet bed lowers the listener's reference so the scare event is perceived as far more intense than its absolute level alone would suggest.", "plain_english": "It is the big jump from a soft background sound to a loud scare. The quiet part makes the loud part feel even louder and more shocking.", "purpose_function": "It exists to make scares effective through contrast rather than sheer volume, so designers can startle guests reliably while keeping average sound levels comfortable and within hearing-safe limits.", "practical_application": "A technician sets the ambient bed several decibels below the scare cue and checks both the scare's peak level and the average exposure so the effect lands hard yet stays safe for guests and staff.", "category": "Scare Sound Design", "related_terms": ["Jump-Scare Audio", "Continuous Haunt Playback", "Distant Scream", "Decoy Sound"], "common_mistakes": ["Raising the whole soundscape's level to make scares hit harder, which flattens the contrast and just fatigues guests", "Confusing loudness contrast with absolute volume, so the scare relies on brute level instead of the quiet-to-loud jump", "UNSAFE: Pushing scare-cue peaks above 140 dB peak sound pressure level or letting staff average exposure exceed OSHA limits, risking hearing damage"], "scenario_contexts": ["A quiet fog-filled hallway with faint drips is broken by a loud chainsaw stinger as an actor lunges", "Tuning a room so its ambient bed sits well below the triggered scare so the contrast reads clearly", "Lowering baseline bed level in a long queue to protect staff hearing while keeping scare impact"]}, "0b8c0b5a-9d8d-4e33-a265-81de94478b8f": {"definition": "Pre-recorded narrative or environmental audio that conveys the fictional history, lore, or context of a themed space or character, delivered through the sound system to immerse guests in the story rather than to scare them directly.", "plain_english": "Sound that tells the story behind a scene, like a recorded voice or eerie details that explain what happened there. It sets the mood before anything jumps out.", "purpose_function": "It exists to build narrative context and atmosphere so guests understand and feel the setting, supporting the story arc that scares punctuate.", "practical_application": "A technician levels and places backstory tracks such as a whispered legend or distant broadcast on looped or ambient playback so they read clearly without masking scare cues or dialogue.", "category": "Narrative Audio", "related_terms": ["Found-Recording Audio", "Character Voice Track", "Continuous Haunt Playback", "Creature Vocal Track"], "common_mistakes": ["Mixing backstory dialogue too quietly or too loudly, so it is unintelligible or overpowers scare cues", "Looping a spoken backstory track so short that guests notice the repeat and break immersion", "Treating backstory audio as a scare cue and triggering it abruptly instead of blending it into the bed"], "scenario_contexts": ["A recorded radio bulletin explaining an outbreak plays softly in an infected-lab room", "A whispered legend loops in a queue to set up the haunt's story", "Environmental sounds of a working asylum establish a scene's history before actors appear"]}, "e2bcac33-9db2-444d-a9e1-d63c37e68cf5": {"definition": "A pre-recorded (or live) vocal recording for a specific scripted character or animatronic figure, played back and often synchronized to mouth movement, action, or a show-control cue so the figure appears to speak.", "plain_english": "A recorded voice for one character or animatronic figure. It is played back, often timed to the figure's mouth so it looks like the character is really talking.", "purpose_function": "It exists to give a character a consistent, repeatable voice performance that plays on cue, freeing a live performer and ensuring the same delivery every show.", "practical_application": "A technician loads the character track into the playback or show-control system and aligns it with animatronic movement or lighting so voice and action stay in sync.", "category": "Voice Content", "related_terms": ["Creature Vocal Track", "Backstory Audio", "Continuous Haunt Playback", "Found-Recording Audio"], "common_mistakes": ["Letting the voice track drift out of sync with the figure's mouth or gestures", "Recording the track at a level or tone that does not cut through the room's ambient bed", "Failing to match playback loudness across zones, so the same character sounds different from room to room"], "scenario_contexts": ["An animatronic fortune teller delivers a scripted spiel from a looped voice track", "A talking portrait's lines are triggered when a guest enters the room", "Syncing a character's recorded dialogue to servo-driven jaw movement"]}, "cbb128b7-edd2-4f5d-adb3-9a83d32aab0f": {"definition": "An audio playback mode in which ambient beds, room tone, or music loop and play without interruption throughout operating hours, as distinct from momentary cues triggered by sensors or operators.", "plain_english": "Sound that keeps playing on a loop the whole time the haunt is open, like background atmosphere. It runs on its own instead of waiting to be set off.", "purpose_function": "It exists to maintain a constant atmosphere and mask outside noise so the environment stays immersive in the gaps between triggered scares.", "practical_application": "A technician sets ambient tracks to seamless loop on a playback device or show-control system and confirms they restart cleanly and hold a consistent level for a full night.", "category": "Show Playback", "related_terms": ["Backstory Audio", "Ambient-to-Scare Contrast", "Jump-Scare Audio", "Character Voice Track"], "common_mistakes": ["Using a loop with an audible seam or click that reveals the repeat", "Running continuous beds so loud that they mask triggered scare cues or fatigue guests and staff", "Assuming a continuous file will play all night without checking the player for dropouts or restarts"], "scenario_contexts": ["A low wind-and-drone bed loops through a graveyard maze all evening", "Room tone plays continuously to hide HVAC and crowd noise between scares", "A music loop maintains dread in a waiting queue"]}, "9269b34a-eedb-4810-9ad9-57942c6f11f9": {"definition": "A pre-recorded set of non-human vocalizations such as growls, screeches, and roars, designed for a monster, creature, or animatronic and played back on cue to voice the creature's presence or attack.", "plain_english": "Recorded monster sounds like growls and roars made for a creature or animatronic. They are played on cue so the creature seems alive and threatening.", "purpose_function": "It exists to give a non-human character a believable, repeatable voice, letting designers craft sounds no live performer could safely sustain and trigger them on demand.", "practical_application": "A technician loads creature vocals into the playback or trigger system and levels them so growls and roars sit menacingly in the mix without exceeding safe peaks.", "category": "Voice Content", "related_terms": ["Character Voice Track", "Jump-Scare Audio", "Distant Scream", "Backstory Audio"], "common_mistakes": ["Reusing the same short growl so often that guests recognize the loop", "Mixing creature vocals so low they lose menace or so high they mask other cues", "UNSAFE: Setting a triggered roar's peak level so high near guests or actors that it approaches unsafe sound pressure levels"], "scenario_contexts": ["A hidden speaker growls as an animatronic beast lunges from the dark", "Layered screeches play when a swarm effect is triggered", "A distant roar sets up a creature the guest will meet later"]}, "796888b0-2d36-4234-91ac-0ba654bb9b02": {"definition": "A sound cue deliberately placed to draw a guest's attention and gaze toward one location so an actor or effect can surprise them from a different direction, exploiting auditory localization and the reflex to orient toward a sound.", "plain_english": "A sound used to trick you into looking one way, so the real scare can come from another. It works because people turn toward a sound.", "purpose_function": "It exists to misdirect attention, setting up a stronger surprise by controlling where the guest looks in the moment just before the actual scare.", "practical_application": "A technician positions the decoy on a speaker away from the real scare and times it a beat before the reveal so guests turn the wrong way.", "category": "Scare Sound Design", "related_terms": ["Jump-Scare Audio", "Ambient-to-Scare Contrast", "Distant Scream", "Continuous Haunt Playback", "Misdirection Audio"], "common_mistakes": ["Placing the decoy on the same speaker as the real scare, so it gives the location away instead of misdirecting", "Making the decoy so loud or long that it becomes the main event instead of a setup", "Mistiming the decoy so guests have already turned back before the real scare hits"], "scenario_contexts": ["A crash on the left speaker pulls guests' eyes as an actor emerges on the right", "A whisper behind guests turns them around into a drop-panel scare", "A distant sound baits guests down a hallway toward a hidden trigger"]}, "0ec75386-1c78-4e6d-8d09-e37b19d9a399": {"definition": "A scream sound effect mixed and processed to be perceived as far away, using lower level, greater reverberation relative to the direct sound, and reduced high-frequency content, which are the acoustic cues the ear uses to judge source distance.", "plain_english": "A scream made to sound like it is coming from far off. Lowering its volume, adding echo, and dulling the highs make our ears place it in the distance.", "purpose_function": "It exists to expand a scene's sense of space and dread, suggesting off-scene danger or a larger world beyond what the guest can see.", "practical_application": "A technician lowers the level, adds reverberation, and rolls off the highs on a scream, then plays it from a far or hidden speaker so it reads as distant.", "category": "Scare Sound Design", "related_terms": ["Ambient-to-Scare Contrast", "Jump-Scare Audio", "Continuous Haunt Playback", "Decoy Sound"], "common_mistakes": ["Only lowering the volume without adding reverberation or dulling the highs, so it sounds close but quiet rather than far", "Placing a distant scream on a near speaker so its location contradicts the intended distance", "Adding so much reverberation that the scream turns to mush and loses its emotional read"], "scenario_contexts": ["A faint scream echoes from deep in a maze to imply another victim", "A distant cry lures guests forward toward the next scene", "Layering a far-off scream under an ambient bed to enlarge a room's implied space"]}, "066b4c76-6df0-4b94-be30-c2028174169e": {"definition": "Diegetic audio presented as a discovered artifact within the story, such as a recovered tape, voicemail, radio transmission, or log, usually given lo-fi, degraded processing to sell it as a real recording found in the environment.", "plain_english": "Sound made to seem like a real recording the characters found, such as an old tape or phone message. It is roughened up so it feels discovered, not staged.", "purpose_function": "It exists to deliver story and clues in the fiction's own voice, deepening immersion by making guests feel they are uncovering evidence.", "practical_application": "A technician applies band-limiting, added noise, and distortion to sell the format, then places it on a prop speaker or looped bed where guests encounter the recording.", "category": "Narrative Audio", "related_terms": ["Backstory Audio", "Character Voice Track", "Continuous Haunt Playback", "Creature Vocal Track"], "common_mistakes": ["Leaving the recording too clean, so it sounds like studio audio rather than a found artifact", "Degrading it so heavily that the words become unintelligible", "Looping a short found recording so obviously that the illusion of a real captured moment breaks"], "scenario_contexts": ["A victim's last voicemail plays from a prop phone in a crime-scene room", "A degraded reel-to-reel confession loops in a researcher's office", "A staticky radio distress call sets up a scene's backstory"]}, "eb170a35-971d-43ba-bf77-5dbf7ff9b6be": {"definition": "A sudden, high-level, fast-attack sound cue (a stinger) timed to coincide with a visual reveal to trigger the acoustic startle reflex, the involuntary defensive response the auditory system produces to an abrupt, intense sound onset.", "plain_english": "A sudden loud sound timed with a scare to make you flinch. Fast, sharp sounds set off the body's built-in startle reflex, which is why they make you jump.", "purpose_function": "It exists to produce an immediate, reliable startle at the moment of a reveal, using rapid onset and high contrast rather than sustained volume.", "practical_application": "A technician aligns the stinger tightly with the visual trigger and sets its peak for maximum startle while keeping peaks and average exposure within hearing-safe limits.", "category": "Scare Sound Design", "related_terms": ["Ambient-to-Scare Contrast", "Continuous Haunt Playback", "Decoy Sound", "Creature Vocal Track"], "common_mistakes": ["Chasing startle with sheer volume instead of a fast onset and quiet-to-loud contrast", "Mistiming the stinger so it lands before or after the visual reveal and loses its punch", "UNSAFE: Letting stinger peaks exceed 140 dB peak sound pressure level or letting cumulative exposure exceed OSHA limits, risking hearing damage to guests and staff"], "scenario_contexts": ["A sharp stinger fires as an animatronic drops from the ceiling", "A silent room is broken by a sudden screech synced to a strobe", "A fast transient hit is paired with an actor's lunge at a corner"]}, "5dc2dece-28f1-4afe-906f-d8b7bc60a724": {"definition": "A sound cue or source deliberately timed, placed, or localized in a themed or haunted attraction to draw guests' attention toward one location—or away from another—so a scare, reveal, or effect can be sprung where they are not looking. It applies the theatrical principle of misdirection to the audio channel, exploiting sound localization to steer the guest's focus.", "plain_english": "A sound used to pull your eyes and ears one way, so a scare can hit from another. It works like a magician who gets you to watch one hand while the trick happens in the other.", "purpose_function": "It exists to control where guests look and listen so a scare, reveal, or effect can be sprung from an unexpected direction, making the payoff land harder. Steering attention with sound also helps guide groups along the intended path through a walkthrough.", "practical_application": "A technician aims or triggers a localized sound—via a placed loudspeaker or a show-control cue—to pull a group's focus one way, then fires the real scare or gag from the opposite side a beat later.", "category": "Scare Technique", "related_terms": ["Decoy Sound", "Jump-Scare Audio", "Ambient-to-Scare Contrast", "Distant Scream", "Sound Localization", "Show Control"], "common_mistakes": ["Making the misdirection cue so loud or obvious that guests realize they are being steered, which kills the surprise.", "Placing the decoy sound and the real scare on the same side, so attention is never actually pulled away.", "Ignoring the timing gap between the misdirection cue and the payoff, so the two events overlap and neither reads clearly."], "scenario_contexts": ["A growl triggers from a speaker on the left of a haunted hallway so the group turns that way, and an actor emerges from an opening on the right.", "In a dark maze, a distant scream pulls guests toward one doorway while a pneumatic prop fires behind them.", "A show-control cue plays a phone ringing in an empty room to draw a small group inside before a startle effect activates."]}, "909d7e13-04f7-4bff-a232-a8d032166f08": {"definition": "The audio program presented in the pre-show—the space or segment guests experience immediately before the main attraction—typically combining narration, music, ambience, and any safety or instructional content. It is usually delivered through a fixed, zoned playback system under show control to set the story and pace groups before they enter.", "plain_english": "The sound played in the room or space guests pass through just before the main ride or show. It sets the mood and often tells the story or gives safety notes before they go in.", "purpose_function": "It sets the story, mood, and any safety or instructional information before guests enter the main attraction, and it helps batch and pace groups to match the ride or show's load cycle. This primes guests emotionally so the main experience lands as intended.", "practical_application": "A technician loads and triggers the preshow program through show control, balancing narration against music and ambience so the story and safety cues are clearly heard throughout the space.", "category": "Attraction Zone Audio", "related_terms": ["Queue-Line Audio", "Backstory Audio", "Show Control", "Distributed Sound System", "Character Voice Track", "Ambient Audio"], "common_mistakes": ["Treating the preshow as background filler instead of pacing it to batch and hold guests for the main attraction's load cycle.", "Mixing narration so low it is buried under music and ambience, so guests miss the story or safety information.", "UNSAFE: running preshow playback at high continuous levels in a small enclosed room, exposing guests and nearby staff to noise doses that can exceed OSHA permissible exposure limits over a shift."], "scenario_contexts": ["A themed briefing room plays recorded character narration and a safety spiel while the previous group finishes the ride.", "A pre-show video's synchronized audio sets up the backstory before doors open into the main attraction.", "Atmospheric sound and low music hold and pace a waiting group in an antechamber before they are batched into the show."]}, "23a6430d-7172-482b-9164-d7c4b11fe9ec": {"definition": "The atmospheric and thematic audio program played in an attraction's queue (waiting line) area, delivered through distributed loudspeakers to theme the wait, build anticipation, and mask ambient crowd and mechanical noise. It is commonly zoned and looped so content stays coherent as guests move along the line.", "plain_english": "The background sound played in the waiting line for a ride or show. It themes the wait, builds excitement, and helps cover the noise of the crowd.", "purpose_function": "It extends the attraction's themed world into the waiting line to build anticipation, mask crowd and mechanical noise, and make the wait feel shorter and part of the story. Zoning the content keeps it fresh as guests move along the queue.", "practical_application": "A technician designs and tunes zoned, looping playback along the queue through distributed loudspeakers, setting levels per section so the theming reads without becoming fatiguing over a long wait.", "category": "Attraction Zone Audio", "related_terms": ["Preshow Audio", "Ambient Audio", "Backstory Audio", "Distributed Sound System", "Show Control", "Background Music"], "common_mistakes": ["Looping a short music or ambience clip so tightly that the repetition becomes obvious and annoying over a long wait.", "Setting one level for the whole queue instead of zoning it, so some sections are too loud and others are drowned out by crowd noise.", "UNSAFE: mounting queue-line loudspeakers overhead without rated hardware and a secondary safety attachment, risking a fall onto guests below."], "scenario_contexts": ["Themed ambience and music loop through distributed speakers along a switchback queue to theme the wait.", "A haunt's outdoor line uses low, ominous soundscapes to build dread before guests reach the entrance.", "Zoned queue audio shifts content as guests move from the outer line toward the loading area."]}, "9dab4ff6-adbe-4b8d-a1a3-4fc8b80e02f7": {"definition": "Metadata that records the technical and management information needed to store, maintain, and preserve a digital object over time, including its technical characteristics (format, encoding, and file properties), rights and access conditions, and preservation history. In digital preservation it is commonly subdivided into technical, rights, and preservation (digital provenance) metadata, as distinct from descriptive and structural metadata.", "plain_english": "Administrative metadata is the record-keeping data about a file, not about what the sound is. It notes things like the file format, who may use it, and every change made to it over time.", "purpose_function": "It gives systems and staff the operational information needed to manage, protect, and preserve a file, tracking format, rights, and every preservation action so the object stays usable and trustworthy across its life.", "practical_application": "An audio archivist captures administrative metadata (format, sample rate, bit depth, checksum, capture chain, and each processing step) at ingest so future staff know exactly how a file was made and handled.", "category": "Metadata", "related_terms": ["Descriptive metadata", "Structural metadata", "Preservation metadata", "Archival information package", "Chain of custody", "Fixity"], "common_mistakes": ["Confusing administrative metadata (how a file is managed and preserved) with descriptive metadata (what the recording is about).", "Recording administrative metadata once at ingest and never updating it as preservation actions occur.", "Treating the checksum or technical format details as optional rather than core preservation information."], "scenario_contexts": ["Documenting format, sample rate, bit depth, and capture chain when ingesting a digitized tape into a repository.", "Recording each normalization, migration, or re-checksum event in a file's preservation history.", "Storing rights and access restrictions alongside a broadcast recording so future users know usage conditions."]}, "7e20fe06-97c6-469a-8983-48802ac23261": {"definition": "In the OAIS reference model (ISO 14721), the Archival Information Package (AIP) is the information package that a repository actually stores and preserves for the long term. It consists of the Content Information (the target digital object plus its Representation Information) together with the complete Preservation Description Information (Reference, Provenance, Context, Fixity, and Access Rights information) needed to preserve and interpret that content.", "plain_english": "An archival information package is the keeper version of a file that the archive holds for the long term. It bundles the audio with all the extra data needed to prove what it is, where it came from, and that it has not changed.", "purpose_function": "It defines a complete, self-describing unit for long-term storage so that content and everything needed to preserve, authenticate, and interpret it stay together, independent of the systems that created it.", "practical_application": "When ingesting a submission (SIP), an archivist turns it into an AIP by adding preservation metadata, fixity checksums, and identifiers before committing it to archival storage.", "category": "OAIS Framework", "related_terms": ["Submission information package", "Dissemination information package", "OAIS reference model", "Preservation metadata", "Administrative metadata", "Fixity"], "common_mistakes": ["Confusing the AIP (the stored preservation version) with the SIP submitted at ingest or the DIP delivered to users.", "Thinking the AIP is only the audio file, when it must also carry its Preservation Description Information.", "Assuming an AIP never changes; its content is preserved, but its metadata (for example new fixity or provenance) may be updated."], "scenario_contexts": ["Packaging a digitized field recording with its checksums, provenance, and identifiers for deposit in a preservation repository.", "Auditing a repository to confirm each AIP still contains complete Preservation Description Information.", "Generating a dissemination copy (DIP) from a stored AIP to give a researcher access."]}, "8eb52360-4c35-4226-935d-dcb8073e479a": {"definition": "A unique number or code assigned to a group of materials at the point it is acquired (accessioned) by a repository, used to identify that acquisition and to link the materials to their associated accession and management records. It is often structured as a year plus a running sequence.", "plain_english": "An accession number is the unique ID an archive gives a batch of material when it first arrives. It works like a claim ticket that ties the items to their paperwork.", "purpose_function": "It establishes intellectual and physical control at the moment of acquisition, giving each accession a persistent identifier so materials can be tracked, located, and tied to their documentation throughout their life in the repository.", "practical_application": "When a collection of tapes arrives, the archivist assigns an accession number and records it on the containers and in the accession register so every later action references it.", "category": "Archival Control", "related_terms": ["Chain of custody", "Administrative metadata", "Archive lifecycle management", "Archival information package", "Provenance"], "common_mistakes": ["Confusing the accession number (identifies an acquisition) with a catalog or call number used for description and retrieval.", "Reusing or reassigning accession numbers, which breaks the link between materials and their records.", "Assigning a single accession number to unrelated acquisitions received at different times."], "scenario_contexts": ["Logging a donated reel-to-reel collection into the accession register with a new accession number.", "Tracing a specific tape back to its acquisition paperwork using its accession number.", "Cross-referencing digitized files to the original accession number so provenance is preserved."]}, "b3828c65-8198-4584-a156-4bb277bc76cf": {"definition": "The process of confirming that an archived object is what it purports to be and has not been altered in an undocumented way, established through fixity information (checksums), documented provenance and chain of custody, and other integrity evidence maintained over the object's life.", "plain_english": "This is how you prove that a stored recording is genuine and has not been changed. You check that its checksum still matches and that there is a clear record of who handled it.", "purpose_function": "It protects trust in the archive by demonstrating that content is genuine and unmodified, which is essential for the legal, historical, and evidentiary use of recordings.", "practical_application": "Before releasing an archived recording as evidence or as a master, a technician verifies its checksum against the recorded value and reviews its provenance and chain-of-custody records.", "category": "Authenticity & Integrity", "related_terms": ["Fixity", "Chain of custody", "Archive integrity audit", "Administrative metadata", "Checksum", "Provenance"], "common_mistakes": ["Treating a successful file open or playback as proof of authenticity, rather than verifying fixity and provenance.", "Relying on MD5 alone where tampering is a concern; it detects accidental errors but is cryptographically compromised.", "Assuming authenticity without an unbroken, documented chain of custody."], "scenario_contexts": ["Confirming a forensic audio recording is unaltered before it is submitted as evidence.", "Validating a preservation master's checksum and provenance before creating derivative copies.", "Verifying the authenticity of files received from another institution during an exchange."]}, "bc08e0fb-4f66-4002-83de-aca9b89cc310": {"definition": "A systematic check of stored archival objects to confirm their bit-level integrity, typically by recalculating fixity values (checksums) across holdings and comparing them against the recorded values to detect data corruption, loss, or undocumented change.", "plain_english": "An integrity audit is a regular checkup that scans stored files to make sure none have gone bad. It re-checks each file's checksum and flags any that no longer match.", "purpose_function": "It detects bit rot, storage errors, and undocumented changes early so a damaged file can be restored from a verified copy before all copies are affected.", "practical_application": "A repository runs scheduled integrity audits that recompute checksums across storage and report mismatches, letting staff replace corrupted files from verified backups.", "category": "Authenticity & Integrity", "related_terms": ["Fixity", "Checksum", "Archive authenticity verification", "Archive refresh cycle", "Administrative metadata"], "common_mistakes": ["Assuming one copy passing a checksum check is enough; integrity auditing needs verified redundant copies to repair from.", "Running audits so rarely that corruption is found only after every copy is affected.", "Confusing an integrity audit (bit-level fixity) with authenticity verification (genuineness and provenance)."], "scenario_contexts": ["Scheduling periodic fixity checks across a digital audio repository to catch silent data corruption.", "Investigating a checksum mismatch flagged during a routine audit and restoring from backup.", "Reporting audit results as evidence of ongoing integrity for a trusted-repository assessment."]}, "a55b1b07-5563-41ad-8476-6d737082017a": {"definition": "The coordinated management of archival materials through all stages of their existence, from acquisition and accession, ingest, and description, through storage and active preservation (fixity checking, refreshment, and migration), access, and eventual disposition or continued retention, governed by defined policies.", "plain_english": "This means caring for stored material at every stage, from the day it arrives to its long-term storage. It is like servicing a car on a set schedule instead of waiting for it to break down.", "purpose_function": "It ensures preservation actions happen at the right time under consistent policy, so materials stay authentic, accessible, and usable across changing formats and technologies rather than degrading through neglect.", "practical_application": "An archive follows lifecycle policies that trigger ingest workflows, scheduled fixity audits, media refresh, and format migration so each object is actively maintained rather than left static.", "category": "Archival Management", "related_terms": ["Archive refresh cycle", "Archive integrity audit", "Archival information package", "Administrative metadata", "Archive accession number", "Chain of custody"], "common_mistakes": ["Treating archiving as a one-time deposit rather than an ongoing cycle of active preservation.", "Deferring migration and refresh until media or formats are already obsolete.", "Managing storage in isolation from accession, description, and access policies."], "scenario_contexts": ["Setting policy that schedules fixity audits, media refresh, and format migration at defined intervals.", "Planning a workflow from tape accession through digitization, storage, and researcher access.", "Reviewing at-risk formats to prioritize migration within the preservation lifecycle."]}, "bca0e812-4e11-4d29-acad-ae70ac12467a": {"definition": "The scheduled recurring process of copying archived data onto new storage media of the same type (media refreshment) without changing the bitstream, performed to counter physical media degradation and reach media before it fails; it is distinct from migration, which moves content to a new format or a different media type.", "plain_english": "A refresh cycle means copying stored files onto new media on a regular schedule, before the old media wears out. The files stay exactly the same; only the thing they sit on is renewed.", "purpose_function": "It counters the limited and uncertain lifespan of storage media by moving bit-for-bit copies onto new carriers on a planned schedule, so files are never left on aging or failing media.", "practical_application": "A repository refreshes its LTO tape or disk holdings on a set cycle, copying data to new carriers and verifying checksums after each copy to confirm nothing changed.", "category": "Storage & Media", "related_terms": ["Archive integrity audit", "Fixity", "Data migration", "Archive lifecycle management", "Archival information package"], "common_mistakes": ["Confusing refresh (a bit-identical copy to new media of the same type) with migration (a change of format or media type).", "Refreshing without verifying checksums, so a copy error goes undetected.", "Setting the cycle longer than the media's reliable life, so carriers fail before they are refreshed."], "scenario_contexts": ["Copying an LTO tape library to new-generation tape before the old stock exceeds its rated life.", "Copying disk-based masters to fresh drives on a scheduled refresh and re-verifying fixity.", "Planning refresh intervals as part of a repository's storage maintenance policy."]}, "df9deca5-4be8-4d3d-8514-7e9e3a013505": {"definition": "A planned test in which archived data is actually restored from backup or preservation copies to confirm that recovery procedures work and that the restored content is complete and valid; it is a disaster-recovery exercise that verifies recoverability rather than assuming it.", "plain_english": "A restoration drill is a practice run of recovering files from backup to prove it really works. It is like a fire drill: you test the plan before a real emergency, not during one.", "purpose_function": "It verifies that backups are usable and that recovery steps are correct, catching failed or unreadable backups and procedural gaps before a real loss makes them critical.", "practical_application": "An archive periodically restores a sample of AIPs from its backup system, checks their fixity against recorded values, and times the process to confirm recovery targets are met.", "category": "Disaster Recovery", "related_terms": ["Archive integrity audit", "Fixity", "Archival information package", "Archive lifecycle management", "Chain of custody"], "common_mistakes": ["Assuming backups are good because the backup job completes, without ever test-restoring them.", "Restoring files but never verifying their fixity to confirm the copy is intact.", "Drilling only on small files and never on the large media files that matter most."], "scenario_contexts": ["Test-restoring a set of preservation masters from off-site backup and verifying checksums.", "Timing a full recovery to confirm the archive meets its recovery-time objective.", "Discovering an unreadable backup tape during a drill and correcting the backup process."]}, "6ae0ef0c-a9b6-49d6-a93c-43ca0f8bfd07": {"definition": "The documented, unbroken succession of the persons or offices that have held and controlled materials from the moment of their creation onward. In archives it is a key support for authenticity, because content whose custody is fully documented can be shown to have remained under continuous, accountable control.", "plain_english": "Chain of custody is a complete record of everyone who has held an item, from the moment it was made. An unbroken record helps prove the recording is genuine and was not tampered with.", "purpose_function": "It supports authenticity and trust by showing continuous, accountable control of an object, so any gap that could allow undetected alteration is visible and can be judged.", "practical_application": "When accepting a recording as evidence or for preservation, a technician logs each transfer of custody, who handed it over, who received it, when, and any actions taken, to keep the chain unbroken.", "category": "Authenticity & Integrity", "related_terms": ["Provenance", "Archive authenticity verification", "Administrative metadata", "Archive accession number", "Fixity"], "common_mistakes": ["Confusing chain of custody (who controlled the item) with provenance of the intellectual content or with descriptive metadata.", "Leaving gaps in the custody record and assuming authenticity anyway.", "Failing to log routine handling and transfers, so the chain cannot be reconstructed later."], "scenario_contexts": ["Documenting every handoff of a recording intended for use as legal evidence.", "Recording custody transfers as tapes move from a donor through processing to storage.", "Reviewing custody records to assess the authenticity of a recording of uncertain origin."]}, "7332c99c-f000-4622-8d54-a82c6ec04440": {"definition": "A checksum audit is the scheduled, repeated recalculation of a file's checksum (a fixed-length value derived from its bitstream by an algorithm such as MD5 or SHA-256) and comparison against a stored reference value, performed to detect bit-level corruption, incomplete transfers, or tampering in archived audio files over time.", "plain_english": "A checksum is a short code worked out from a file's exact data. An audit means the archive works out that code again over time and checks it still matches, so it can catch any file that has gone bad.", "purpose_function": "It provides ongoing evidence of fixity—assurance that stored files remain bit-for-bit unchanged—so an archive can catch silent data corruption, failed copies, or unauthorized changes and restore from a good copy before the damage spreads.", "practical_application": "An archivist runs fixity software on ingest and then on a set schedule (for example every six months for disk and yearly for tape) to compare each file's current checksum with its recorded value, then investigates and repairs any mismatch from a verified backup.", "category": "Fixity & integrity", "related_terms": ["Fixity", "Checksum", "Bit rot", "Digital fingerprinting", "Digital preservation policy", "Disaster-recovery exercise"], "common_mistakes": ["Assuming a single checksum check at ingest is enough, when integrity must be re-verified on a schedule for the life of the file", "Believing a checksum can locate or repair corruption—it only signals that the file has changed, not where or how", "Treating MD5 as tamper-proof; it detects accidental errors but can be deliberately defeated, so SHA-256 is preferred where malicious change is a concern", "UNSAFE: overwriting the last remaining good copy after a failed check instead of restoring from a verified backup, which can destroy the only recoverable version"], "scenario_contexts": ["Verifying that a batch of newly digitized tapes transferred to preservation storage without corruption before deleting the working copies", "Running a scheduled integrity sweep across a tape or disk repository and flagging files whose checksums no longer match", "Confirming a file retrieved from a dark or deep archive is identical to the original before delivering an access copy"]}, "2556628d-1bc5-463b-b2cb-b126965ca3ed": {"definition": "A codec migration strategy is a documented plan for moving archived audio out of an encoding or codec that is becoming obsolete, unsupported, or at risk and into a current, well-supported preservation format, while preserving the essential information and metadata of the original. In audio archiving the preferred target is uncompressed linear PCM in a WAVE/BWF container, and lossy perceptual codecs are avoided for preservation masters.", "plain_english": "A codec is the method used to store audio in a file. Some codecs stop being supported over time. So this is a written plan to move the recordings into a newer, safer format before the old one dies out.", "purpose_function": "It guards against technical obsolescence—the point where software or hardware can no longer decode a format—by planning migrations in advance so that content stays accessible and playable across changing generations of technology.", "practical_application": "An archive monitors format viability, and when a codec is flagged as at risk it batch-transcodes affected files to the current preservation target (typically linear PCM WAV/BWF), verifies each result with checksums and quality checks, and records the action in preservation metadata.", "category": "Preservation strategy", "related_terms": ["Linear PCM", "Broadcast Wave Format", "Preservation master", "Descriptive metadata", "Digital preservation policy", "Checksum audit"], "common_mistakes": ["Migrating to another lossy or proprietary codec, which risks generation loss and simply repeats the obsolescence problem", "Waiting until a format is already unreadable instead of migrating while working decoders still exist", "Discarding the original file immediately after migration rather than validating the new copy first", "Failing to carry embedded and external metadata across the transcode, breaking provenance"], "scenario_contexts": ["Transcoding a legacy collection stored in an outdated proprietary codec to linear PCM WAV before decoder support disappears", "Scheduling periodic reviews of format viability as part of a preservation policy", "Migrating perceptually coded access copies while keeping the uncompressed preservation masters untouched"]}, "3d247d63-244f-4a67-ab9e-58a150c8f991": {"definition": "A cold archive is a storage tier for digital objects that are accessed very rarely, held on low-cost, high-latency media such as offline data tape or a deep cloud storage class, where retrieval is slower and may incur delay or cost in exchange for low ongoing storage cost and, for offline media, isolation from live systems.", "plain_english": "A cold archive is where files that are almost never opened are kept. They sit on cheap, slow storage such as offline tape, so getting a file back takes longer, but it costs very little and stays safe.", "purpose_function": "It lets archives retain large volumes of infrequently used content affordably for the long term, and—when the media is kept offline—adds a safety barrier so that errors, ransomware, or accidental deletions on live systems cannot reach the stored copy.", "practical_application": "A technician places seldom-requested preservation copies onto tape or a cold cloud tier, keeps faster online copies for daily access, and builds retrieval lead time into any workflow that needs to pull material back from the cold tier.", "category": "Archival storage", "related_terms": ["Deep archive", "Dark archive", "Offline storage", "Data tape", "Digital preservation policy", "Checksum audit"], "common_mistakes": ["Confusing cold storage (about how fast and cheap access is) with a dark archive (about who is allowed access)", "Expecting instant retrieval and not budgeting the delay or cost of pulling files from cold media", "Keeping only a cold copy and no verified second copy, leaving no recovery option if the media fails", "Skipping fixity checks on cold media because it is assumed 'safe', allowing undetected bit rot"], "scenario_contexts": ["Storing rarely requested digitized recordings on offline tape to cut storage costs", "Moving completed projects out of expensive online storage into a cold cloud tier", "Retrieving a decades-old master from cold storage for a reissue, allowing for retrieval lead time"]}, "2f774a38-5a75-43e0-b83d-7ca1b8e70918": {"definition": "A dark archive is a repository whose holdings are stored and actively preserved but are not openly accessible—available only to its custodian (and sometimes designated depositors)—typically maintained as a secure preservation or fail-safe copy that is 'opened' and made accessible only under defined trigger conditions.", "plain_english": "A dark archive is a collection that is kept safe but is not open to the public. Only the people who look after it can reach the files, which are held as a backup that is opened only if something goes wrong.", "purpose_function": "It exists to guarantee long-term survival and disaster recovery of important content without providing routine public access, so a trusted preservation copy remains available even if the primary, publicly accessible ('light') copy is lost.", "practical_application": "Publishers, libraries, and studios deposit content into a dark archive—such as a CLOCKSS-style repository or an internal preservation vault—that stays closed until a trigger event, like a provider ceasing operations, makes designated content accessible.", "category": "Archival storage", "related_terms": ["Light archive", "Cold archive", "Deep archive", "Digital preservation policy", "Disaster-recovery exercise", "Checksum audit"], "common_mistakes": ["Confusing 'dark' (an access policy — closed to the public) with 'cold' or 'deep' (about storage speed and cost)", "Assuming a dark archive is merely a backup, when it is a fully preserved, actively managed and integrity-checked copy", "Believing content stays dark forever; once it is released under a trigger it is no longer considered dark"], "scenario_contexts": ["Depositing e-journal or catalog content into a dark archive that is released only if the publisher fails", "Keeping a closed preservation master of sensitive session recordings that is not available for routine access", "Holding a fail-safe copy of a public collection so it can be restored after data loss"]}, "97e3f6fb-f082-4034-9541-c2fc32271e01": {"definition": "A deep archive is the most dormant, long-retention tier of preservation storage—typically offline data tape held for low cost and high safety—storing preservation copies that are expected to be retained indefinitely and retrieved only rarely, with the longest access latency of any storage tier.", "plain_english": "A deep archive is the deepest, most out-of-the-way place an archive keeps its files. The copies here, often on offline tape, are meant to be held for the very long term and are hardly ever taken out.", "purpose_function": "It provides a low-cost, highly durable resting place for preservation copies that must survive for the long term, keeping a protected master safely separated from the online systems used for everyday access.", "practical_application": "An archive writes a preservation master to tape held in a deep archive as one of several geographically separated copies, expecting to touch it only for migration, audits, or recovery rather than daily use.", "category": "Archival storage", "related_terms": ["Cold archive", "Dark archive", "Offline storage", "Data tape", "Preservation master", "Digital preservation policy"], "common_mistakes": ["Treating a deep-archive copy as a live backup for quick restores, when its retrieval is deliberately slow", "Confusing deep archive (storage latency and cost) with dark archive (who may access it)", "Relying on a single deep-archive copy without additional geographically separated copies", "Skipping periodic fixity checks and tape migration, letting media silently degrade"], "scenario_contexts": ["Writing preservation masters to LTO tape held offline as the deepest copy in a multi-copy strategy", "Storing content that must be kept indefinitely but is almost never requested", "Pulling a file from the deep archive during a scheduled media-migration cycle"]}, "635b55ed-cea1-45ec-bbfa-0a3f470517da": {"definition": "Descriptive metadata is metadata that describes the intellectual content of a resource—such as title, creator or performer, date, subject, and description—to support its discovery, identification, and retrieval. It is one of the standard metadata categories, alongside administrative, structural, technical, and preservation metadata, and is commonly expressed in schemes such as Dublin Core, MODS, or MARC.", "plain_english": "Descriptive metadata is the information that tells you what a recording is, such as its title, who made it, and when. It works like a library catalog card that helps people find the right file.", "purpose_function": "It enables users and systems to search, browse, identify, and select the correct resource from a collection, providing the intellectual access layer that raw files and technical data alone cannot.", "practical_application": "When cataloging a digitized recording, an archivist records fields such as title, artist, date, and subject in a schema like Dublin Core or MODS so the item can be found and correctly identified later.", "category": "Metadata", "related_terms": ["Administrative metadata", "Structural metadata", "Technical metadata", "Preservation metadata", "Dublin Core", "PREMIS"], "common_mistakes": ["Confusing descriptive metadata (what the content is) with technical or preservation metadata (file format, checksums, actions taken)", "Entering data inconsistently instead of following a controlled schema and vocabulary, which breaks searching", "Assuming embedded file tags are enough and not maintaining catalog-level descriptive records"], "scenario_contexts": ["Cataloging an oral-history recording with title, interviewee, date, and subject terms", "Populating a digital asset management system so users can search a music archive", "Mapping fields from an old catalog into Dublin Core during a metadata migration"]}, "f80e6ea8-d9fa-41da-bd41-80a52ecf8a5d": {"definition": "Digital (acoustic) fingerprinting is the computation of a compact, content-based signature derived from the perceptual features of an audio signal, so that a recording can be identified or matched by its actual sound regardless of file format, encoding, or minor distortion. Unlike a cryptographic checksum, which changes if any single bit changes, a fingerprint is designed to remain stable across format conversion and moderate processing while still discriminating between different recordings.", "plain_english": "A digital fingerprint is a small summary made from what a recording sounds like. It lets a computer spot the same song even after the file has been changed or saved in a new format. A checksum cannot do this, because it breaks if even one bit changes.", "purpose_function": "It allows content-based identification and matching of audio when metadata is missing or wrong, supporting deduplication, catalog matching, rights and broadcast monitoring, and linking unlabeled or format-converted files to a known recording.", "practical_application": "An archivist or automated system runs unlabeled or duplicate-suspect files through a fingerprinting service to identify the recording, detect duplicates across formats, or match a transfer against a reference database, without relying on filenames or tags.", "category": "Content identification", "related_terms": ["Checksum", "Descriptive metadata", "Deduplication", "Watermarking", "Digital preservation policy", "Checksum audit"], "common_mistakes": ["Confusing a fingerprint (identifies content by its sound, tolerant of format changes) with a checksum (verifies exact bits and breaks on any change)", "Expecting a fingerprint to prove a file is bit-for-bit intact—it confirms identity, not integrity", "Assuming a fingerprint match guarantees identical audio quality, when it only means the recordings are the same content"], "scenario_contexts": ["Identifying untitled recordings in a backlog by matching them against a reference database", "Finding duplicate copies of the same performance stored in different formats", "Matching a digitized transfer to a known commercial release for cataloging"]}}$j$::jsonb)) d
WHERE g.id = d.id;
COMMIT;
